local _, RM = ...
if RM.LOCALE ~= "ruRU" then return end
local L = RM.L

L["Ruinen von Ahn'Qiraj"] = "Руины Ан'Киража"
L["Kurinnaxx"] = "Куриннакс"
L["- Tödliche Wunde: stapelnder Debuff auf dem Tank, reduziert erhaltene Heilung -> Tankwechsel bei hohen Stapeln."] = "- Смертельная рана: стакающийся дебафф на танке, снижает получаемое исцеление -> смена танков на высоких стаках."
L["- Sandfalle: erscheint unter einem Spieler und lässt ihn bei Auslösen verfehlen -> sofort herauslaufen."] = "- Песчаная ловушка: появляется под игроком, при срабатывании он промахивается -> сразу выбегать."
L["- Raserei bei ca. 30 %: deutlich mehr Schaden -> Heiler auf die Tanks, Schaden hochfahren."] = "- Бешенство на ок. 30 %: урон сильно растет -> хилы на танков, разгоняем урон."
L["Taktik: Zwei Tanks wechseln sich ab, Raid verteilt hinter dem Boss, Sandfallen sofort verlassen."] = "Тактика: Два танка меняются, рейд рассредоточен за боссом, из Песчаных ловушек сразу выходить."
L["KURINNAXX: Tankwechsel bei Tödlicher Wunde! Raus aus der Sandfalle!"] = "КУРИННАКС: Смена танков на Смертельной ране! Выйти из Песчаной ловушки!"
L["Ab 30 % Raserei: Heiler auf die Tanks, alles auf den Boss."] = "С 30 % Бешенство: хилы на танков, все в босса."
L["General Rajaxx + Wellen der Qiraji (mit Generalleutnant Andorov)"] = "Генерал Раджакс + волны киражи (с генерал-лейтенантом Андоровым)"
L["- Wellen: mehrere Wellen Qiraji-Krieger mit je einem Hauptmann greifen nacheinander an -> Hauptmann und Adds sauber abarbeiten."] = "- Волны: несколько волн воинов-киражи, в каждой капитан, атакуют по очереди -> чисто разбираем капитана и аддов."
L["- Andorov: NPC-Verbündeter mit Aura und Händler -> am Leben halten, er hilft bei den Wellen."] = "- Андоров: союзный NPC с аурой и торговцем -> держать в живых, он помогает с волнами."
L["- Donnerkrachen (Rajaxx): halbiert das aktuelle Leben aller Spieler in der Nähe -> Raid hoch halten, Abstand für Fernkampf."] = "- Раскат грома (Раджакс): снимает половину текущего здоровья у всех игроков рядом -> держать рейд в фулл ХП, РДД на дистанции."
L["- Entwaffnen/Ansturm-Fähigkeiten der Hauptleute: Tankschaden schwankt -> Heiler aufmerksam."] = "- Обезоруживание/рывки капитанов: урон по танку скачет -> хилы внимательно."
L["Taktik: Wellen am Startpunkt tanken und mit Flächenschaden töten, zwischen den Wellen regenerieren. Zum Schluss Rajaxx tanken und mit allem töten."] = "Тактика: Волны танкуем на точке старта и убиваем АоЕ, между волнами восстанавливаемся. В конце танкуем Раджакса и убиваем всем, что есть."
L["RAJAXX: Wellen sauber abarbeiten, Andorov am Leben halten!"] = "РАДЖАКС: Чисто разбираем волны, держим Андорова в живых!"
L["Donnerkrachen halbiert Leben: Raid immer voll heilen."] = "Раскат грома снимает половину ХП: рейд всегда отхиливать в фулл."
L["Moam + Manadämonen"] = "Моам + демоны маны"
L["- Mana entziehen: Moam saugt Mana der Spieler; bei vollem Mana Arkanausbruch auf den ganzen Raid -> sein Mana leer halten (Mana verbrennen, Vipernbiss, Mana entziehen)."] = "- Похищение маны: Моам вытягивает ману игроков; при полной мане Чародейское извержение по всему рейду -> держать его ману на нуле (Сожжение маны, Укус гадюки, Похищение маны)."
L["- Versteinern: Moam wird zu Stein und ruft Manadämonen -> Dämonen verbannen bzw. tanken und töten."] = "- Окаменение: Моам превращается в камень и призывает демонов маны -> демонов изгнать или танковать и убить."
L["- Manadämonen: Arkanschaden und Spalten -> nicht frei laufen lassen."] = "- Демоны маны: тайный урон и Рассекающий удар -> не давать им бегать свободно."
L["Taktik: Schnell Schaden machen, Jäger/Priester/Hexer halten sein Mana unten. Bei Versteinerung Hexer auf die Manadämonen einteilen."] = "Тактика: Быстро наносим урон, охотники/жрецы/чернокнижники держат его ману на нуле. При окаменении распределить локов на демонов маны."
L["MOAM: Sein Mana leer halten! Bei Stein: Manadämonen verbannen!"] = "МОАМ: Держать его ману на нуле! При камне: изгнать демонов маны!"
L["Jäger Vipernbiss, Priester Mana verbrennen, Hexer Mana entziehen."] = "Охотники Укус гадюки, жрецы Сожжение маны, локи Похищение маны."
L["Moam (Dämonen)"] = "Моам (демоны)"
L["Jeder Manadämon ein Symbol, je ein Hexer verbannt sein zugewiesenes Symbol."] = "Каждому демону маны своя метка, каждый лок изгоняет свою назначенную метку."
L["Buru der Verschlinger + Eier"] = "Буру Ненасытный + яйца"
L["- Fixieren: Buru verfolgt einen zufälligen Spieler -> diesen Spieler Buru in ein Ei ziehen lassen."] = "- Сосредоточение: Буру преследует случайного игрока -> этот игрок ведет Буру в яйцо."
L["- Eier: zerstörte Eier explodieren und verletzen Buru (und Spieler in der Nähe), es schlüpfen Brutlinge -> Eier nur zerschlagen, wenn Buru danebensteht, Abstand halten."] = "- Яйца: разбитые яйца взрываются и ранят Буру (и игроков рядом), вылупляются личинки -> бить яйца только когда Буру рядом, держать дистанцию."
L["- Phase 2 (ca. 20 %): Buru verliert Panzer, kriechende Seuche verursacht steigenden Raidschaden -> alles auf den Boss."] = "- Фаза 2 (ок. 20 %): Буру теряет броню, Ползучая чума наносит растущий урон рейду -> все в босса."
L["Taktik: Raid zerschlägt Eier gezielt, wenn Buru den fixierten Spieler durch ein Ei verfolgt; Brutlinge schnell töten. Ab 20 % voller Schaden."] = "Тактика: Рейд прицельно разбивает яйца, когда Буру гонится за целью через яйцо; личинок быстро убивать. С 20 % полный урон."
L["BURU: Fixierten Spieler -> Buru durch die Eier ziehen! Abstand zur Explosion!"] = "БУРУ: Цель фиксации -> вести Буру через яйца! Дистанция от взрыва!"
L["Bei 20 % alles auf Buru, Heiler Raid hoch halten."] = "На 20 % все в Буру, хилы держат рейд в фулл."
L["Ayamiss der Jäger + Larven/Wespen"] = "Айамисса Охотница + личинки/осы"
L["- Phase 1 in der Luft: nur Fernkampf erreicht sie -> Fernkampf auf den Boss, Nahkampf auf Adds."] = "- Фаза 1 в воздухе: достают только РДД -> РДД в босса, мили на аддов."
L["- Lähmen: ein Spieler wird auf den Altar gebracht, eine Larve läuft hin -> Larve sofort töten, sonst stirbt der Spieler."] = "- Паралич: игрока уносит на алтарь, к нему ползет личинка -> личинку убить сразу, иначе игрок умрет."
L["- Giftstachelsalve: Naturschaden auf viele Spieler -> Gift entfernen, Naturwiderstand hilft."] = "- Залп ядовитых жал: урон от сил природы по многим игрокам -> снимать яд, помогает сопротивление силам природы."
L["- Phase 2 (ca. 70 %): landet und wird getankt, ruft weiter Wespen -> Tank übernimmt, Adds mit Flächenschaden töten."] = "- Фаза 2 (ок. 70 %): приземляется и танкуется, продолжает призывать ос -> танк забирает, аддов убивать АоЕ."
L["Taktik: Fernkampf schießt den Boss herunter, Nahkampf kümmert sich um Larven und Wespen. Nach der Landung normal tanken."] = "Тактика: РДД сбивают босса, мили занимаются личинками и осами. После приземления обычный танкинг."
L["AYAMISS: Larve zum Altar sofort töten! Fernkampf auf den Boss!"] = "АЙАМИССА: Личинку у алтаря сразу убить! РДД в босса!"
L["Gift entfernen. Ab 70 % landet sie: Tank bereit."] = "Снимать яд. С 70 % она садится: танк готов."
L["Ossirian der Narbenlose"] = "Оссириан Неуязвимый"
L["- Stärke des Ossirian: ohne Schwäche fast unverwundbar und tödlich -> immer zu einem Kristall ziehen."] = "- Сила Оссириана: без слабости почти неуязвим и смертоносен -> всегда тянуть к кристаллу."
L["- Kristalle: Aktivieren gibt ihm eine Zauberschwäche für ca. 45 Sek. -> rechtzeitig nächsten Kristall aktivieren und Boss dorthin tanken."] = "- Кристаллы: активация дает ему слабость к школе магии на ок. 45 сек. -> вовремя активировать следующий кристалл и тянуть босса туда."
L["- Wirbelstürme: wandern durch den Raum -> ausweichen."] = "- Смерчи: гуляют по залу -> уворачиваться."
L["- Fluch der Sprachen/Umhüllende Winde/Kriegsdonner: Raidkontrolle -> entfluchen, Abstand halten."] = "- Проклятие языков/Обволакивающие ветра/Громовая поступь: контроль рейда -> декурс, держать дистанцию."
L["Taktik: Tank kitet Ossirian von Kristall zu Kristall, ein Spieler aktiviert den nächsten vor Ablauf der Schwäche. Schaden passend zur Schwäche-Schule."] = "Тактика: Танк кайтит Оссириана от кристалла к кристаллу, один игрок активирует следующий до окончания слабости. Урон по школе слабости."
L["OSSIRIAN: Nächsten Kristall rechtzeitig aktivieren! Schwäche nie ablaufen lassen!"] = "ОССИРИАН: Вовремя активировать следующий кристалл! Не давать слабости спасть!"
L["Wirbelstürmen ausweichen, Flüche entfernen."] = "Уворачиваться от смерчей, снимать проклятия."
L["Tempel von Ahn'Qiraj"] = "Храм Ан'Киража"
L["Der Prophet Skeram + 2 Abbilder"] = "Пророк Скерам + 2 копии"
L["- Arkane Explosion: hoher Flächenschaden -> unterbrechen, Nahkampf vorsichtig."] = "- Чародейский взрыв: сильный АоЕ урон -> сбивать, мили осторожно."
L["- Wahre Erfüllung: Gedankenkontrolle -> Spieler kontrollieren (Verwandlung, Furcht), nicht töten."] = "- Истинное исполнение: контроль разума -> контролить игроков (Превращение, Страх), не убивать."
L["- Teleport: Skeram springt auf eine andere Plattform und setzt die Bedrohung zurück -> auf jeder Plattform ein Tank."] = "- Телепорт: Скерам прыгает на другую платформу и сбрасывает угрозу -> на каждой платформе по танку."
L["- Abbilder bei 75/50/25 %: zwei Kopien erscheinen -> Kopien tanken, echten Skeram finden und töten."] = "- Копии на 75/50/25 %: появляются две копии -> копии танковать, найти и убить настоящего Скерама."
L["Taktik: Drei Tanks auf drei Positionen verteilen, Unterbrecher fest einteilen. Bei Abbildern echten Skeram markieren und zuerst töten."] = "Тактика: Три танка на трех позициях, кикеров распределить заранее. При копиях пометить настоящего Скерама и убить первым."
L["SKERAM: Arkane Explosion unterbrechen! Gedankenkontrolle kontrollieren, nicht töten!"] = "СКЕРАМ: Сбивать Чародейский взрыв! Законтроленных контролить, не убивать!"
L["Bei Abbildern nur auf den echten Skeram (Totenkopf)."] = "При копиях только по настоящему Скераму (Череп)."
L["Skeram"] = "Скерам"
L["Totenkopf auf den echten Skeram, Kreuz und Viereck auf die Abbilder."] = "Череп на настоящего Скерама, Крест и Квадрат на копии."
L["Adel der Silithiden: Lord Kri, Prinzessin Yauj, Vem"] = "Королевская семья силитидов: лорд Кри, принцесса Яудж, Вем"
L["- Lord Kri: Giftwolke und bei Tod eine Giftwolke -> nicht darin stehen, Gift entfernen."] = "- Лорд Кри: ядовитое облако, и при смерти тоже ядовитое облако -> не стоять в нем, снимать яд."
L["- Prinzessin Yauj: Große Heilung und Furcht -> Heilung unterbrechen, Furcht beachten; bei Tod erscheinen Käfer -> Flächenschaden."] = "- Принцесса Яудж: Великое исцеление и Страх -> сбивать хил, следить за страхом; при смерти появляются жуки -> АоЕ."
L["- Vem: Ansturm und Rückstoß, wird stärker, wenn die anderen sterben -> stabil tanken."] = "- Вем: Рывок и отбрасывание, усиливается, когда умирают остальные -> стабильно танковать."
L["- Wer zuletzt stirbt, bestimmt die Beute -> Reihenfolge vorher absprechen."] = "- Кто умирает последним, определяет добычу -> порядок обговорить заранее."
L["Taktik: Alle drei getrennt tanken, Unterbrecher auf Yauj, Kill-Reihenfolge nach Absprache (der letzte Boss bestimmt die Beute)."] = "Тактика: Всех троих танковать раздельно, кикеры на Яудж, порядок убийства по договоренности (последний босс определяет добычу)."
L["SILITHIDEN: Kill-Reihenfolge laut Symbolen! Yauj-Heilung unterbrechen!"] = "СИЛИТИДЫ: Порядок убийства по меткам! Сбивать хил Яудж!"
L["Giftwolken meiden. Käfer nach Yauj mit Flächenschaden töten."] = "Избегать ядовитых облаков. Жуков после Яудж убивать АоЕ."
L["Adel der Silithiden"] = "Королевская семья силитидов"
L["Totenkopf zuerst, dann Kreuz, Viereck zuletzt (bestimmt die Beute)."] = "Череп первым, затем Крест, Квадрат последним (определяет добычу)."
L["Schlachtwache Sartura + 3 Königliche Wachen"] = "Боевой страж Сартура + 3 королевских стража"
L["- Wirbelwind: Sartura und Wachen wirbeln und laufen durch den Raid -> Abstand halten, Nahkampf raus."] = "- Вихрь: Сартура и стражи крутятся и бегают по рейду -> держать дистанцию, мили выйти."
L["- Wachen: verursachen viel Schaden -> mit Betäubungsrotation kontrollieren und zuerst töten."] = "- Стражи: наносят много урона -> контролить ротацией оглушений и убивать первыми."
L["- Wutanfall bei ca. 20 % und hartes Zeitlimit -> zügig Schaden machen."] = "- Исступление на ок. 20 % и жесткий лимит времени -> быстро наносить урон."
L["Taktik: Wachen einzeln tanken und nacheinander töten, Betäubungen fest einteilen. Danach Sartura, Raid verteilt."] = "Тактика: Стражей танковать по одному и убивать по очереди, оглушения распределить заранее. Затем Сартура, рейд рассредоточен."
L["SARTURA: Wachen zuerst! Betäubungen rotieren, bei Wirbelwind weg!"] = "САРТУРА: Сначала стражи! Ротация станов, при вихре отбегаем!"
L["Raid verteilt stehen. Ab 20 % Wutanfall: Heiler auf Tank."] = "Рейд рассредоточен. С 20 % Исступление: хилы на танка."
L["Sartura"] = "Сартура"
L["Totenkopf, Kreuz, Viereck auf die drei Wachen in Tötungsreihenfolge."] = "Череп, Крест, Квадрат на трех стражей в порядке убийства."
L["Fankriss der Unnachgiebige + Brut/Jungtiere"] = "Фанкрисс Неумолимый + отродья/детеныши"
L["- Tödliche Wunde: stapelnder Heilungsreduktions-Debuff -> Tankwechsel."] = "- Смертельная рана: стакающийся дебафф на снижение исцеления -> смена танков."
L["- Brut des Fankriss: wird nach kurzer Zeit wütend -> sofort töten."] = "- Отродье Фанкрисса: вскоре впадает в ярость -> убить сразу."
L["- Vekniss-Jungtiere: kommen aus den Tunneln -> Offtank sammelt sie, Flächenschaden."] = "- Детеныши векнисс: лезут из туннелей -> офф-танк собирает, АоЕ."
L["- Umschlingen: Spieler werden in die Tunnel versetzt -> zurücklaufen, Adds dort nicht ignorieren."] = "- Опутывание: игроков переносит в туннели -> бежать назад, аддов там не игнорировать."
L["Taktik: Zwei bis drei Tanks wechseln auf dem Boss, Fernkampf tötet Brut sofort. Schnell Schaden machen, bevor Adds überhandnehmen."] = "Тактика: Два-три танка меняются на боссе, РДД сразу убивают отродий. Быстро наносить урон, пока адды не задавили."
L["FANKRISS: Brut sofort töten! Tankwechsel bei Tödlicher Wunde!"] = "ФАНКРИСС: Отродий сразу убивать! Смена танков на Смертельной ране!"
L["Jungtiere zum Offtank, Flächenschaden."] = "Детенышей к офф-танку, АоЕ."
L["Viscidus"] = "Висцидус"
L["- Gefrieren: Viscidus muss mit Frostschaden eingefroren werden (Frostblitz, Frost-Zauberstäbe, Frostöl) -> alle Frostschaden."] = "- Заморозка: Висцидуса надо заморозить уроном от магии льда (Ледяная стрела, ледяные жезлы, ледяное масло) -> все бьют льдом."
L["- Zerschlagen: eingefroren mit Nahkampf zerschlagen -> er zerfällt in Kugeln."] = "- Раскалывание: замороженного разбивать в ближнем бою -> он распадается на капли."
L["- Kugeln: laufen zur Mitte zurück und heilen ihn -> alle Kugeln töten."] = "- Капли: ползут обратно в центр и лечат его -> убить все капли."
L["- Giftblitzsalve und Giftwolken: Naturschaden -> Naturwiderstand, Gift entfernen."] = "- Залп отравленных стрел и ядовитые облака: урон от сил природы -> сопротивление силам природы, снимать яд."
L["Taktik: Frost-Phase mit allem Fernkampf, Zerschlagen mit Nahkampf, danach Kugeln mit Flächenschaden. Wiederholen bis er tot ist."] = "Тактика: Фаза льда всеми РДД, раскалывание мили, затем капли АоЕ. Повторять, пока не умрет."
L["VISCIDUS: Alles Frostschaden! Gefroren -> Nahkampf zerschlagen!"] = "ВИСЦИДУС: Все бьют льдом! Заморожен -> мили разбивают!"
L["Alle Kugeln töten, bevor sie die Mitte erreichen."] = "Убить все капли до того, как они доползут до центра."
L["Prinzessin Huhuran"] = "Принцесса Хухуран"
L["- Raserei: deutlich mehr Schaden -> Jäger mit Einlullender Schuss sofort entfernen."] = "- Бешенство: урон сильно растет -> охотники сразу снимают Усмиряющим выстрелом."
L["- Wyverngift: Schlaf auf Spielern, beim Bannen Schaden -> gezielt bannen."] = "- Яд виверны: сон на игроках, при диспеле урон -> диспелить выборочно."
L["- Giftblitzsalve: trifft die nächsten Spieler -> Naturwiderstand-Gruppe nahe am Boss."] = "- Залп отравленных стрел: бьет ближайших игроков -> группа с сопротивлением силам природы вплотную к боссу."
L["- Säurespucke: Stapel-Debuff auf Tank; ab 30 % Berserker -> Burn-Phase, Heiler voll."] = "- Кислотный плевок: стакающийся дебафф на танке; с 30 % берсерк -> фаза бурста, хилы на полную."
L["Taktik: Naturwiderstand bei Nahkampf und Tank, Jäger-Rotation für Einlullender Schuss. Ab 30 % alles zünden und Raid hoch halten."] = "Тактика: Сопротивление силам природы у мили и танка, ротация охотников на Усмиряющий выстрел. С 30 % жмем все КД и держим рейд в фулл."
L["HUHURAN: Raserei sofort einlullen! Ab 30 % Burn!"] = "ХУХУРАН: Бешенство сразу усмирять! С 30 % бурст!"
L["Naturwiderstand nahe am Boss, Wyverngift gezielt bannen."] = "Сопротивление природе вплотную к боссу, Яд виверны диспелить выборочно."
L["Zwillingsimperatoren: Vek'lor + Vek'nilash"] = "Императоры-близнецы: Век'лор + Век'нилаш"
L["- Vek'lor: immun gegen körperlichen Schaden, Schattenblitz, Blizzard, Arkane Explosion -> von einem Hexer (Schattenschutz) getankt."] = "- Век'лор: невосприимчив к физическому урону, Стрела Тьмы, Снежная буря, Чародейский взрыв -> танкует лок (Защита от темной магии)."
L["- Vek'nilash: immun gegen Magie, Aufwärtshaken -> von Kriegern getankt, nur Nahkampf."] = "- Век'нилаш: невосприимчив к магии, Апперкот -> танкуют воины, только мили."
L["- Bruder heilen: sind sie nah beieinander, heilen sie sich -> immer weit auseinander halten."] = "- Исцеление брата: если стоят рядом, лечат друг друга -> всегда держать далеко друг от друга."
L["- Teleport: tauschen regelmäßig die Plätze -> Tanks an beiden Seiten bereit, Bedrohung neu aufbauen; Käfer explodieren/mutieren -> töten."] = "- Телепорт: регулярно меняются местами -> танки готовы с обеих сторон, заново набирать угрозу; жуки взрываются/мутируют -> убивать."
L["Taktik: Zwei Tankgruppen an beiden Enden, Hexer auf Vek'lor, Krieger auf Vek'nilash. Nach jedem Teleport sofort übernehmen."] = "Тактика: Две группы танков на обоих концах, локи на Век'лора, воины на Век'нилаша. После каждого телепорта сразу подхватывать."
L["ZWILLINGE: Brüder auseinander halten! Nach Teleport Tanks sofort übernehmen!"] = "БЛИЗНЕЦЫ: Держать братьев раздельно! После телепорта танки сразу подхватывают!"
L["Nahkampf nur Vek'nilash, Magie nur Vek'lor. Käfer töten."] = "Мили только Век'нилаш, магия только Век'лор. Жуков убивать."
L["Ouro + Skarabäen"] = "Оуро + скарабеи"
L["- Fegen: Rückstoß und Betäubung im Umkreis -> Tanks rotieren."] = "- Размах: отбрасывание и оглушение вокруг -> ротация танков."
L["- Sandstoß: großer Frontalkegel -> nur Tanks vor Ouro."] = "- Песчаный взрыв: большой фронтальный конус -> перед Оуро только танки."
L["- Untertauchen: Erdhügel verfolgen Spieler, Skarabäen erscheinen -> weglaufen, Skarabäen töten."] = "- Зарывание: земляные холмики преследуют игроков, появляются скарабеи -> убегать, скарабеев убивать."
L["- Ist niemand in Nahkampfreichweite, wirft er Felsbrocken; ab 20 % Berserker -> Burn."] = "- Если в радиусе ближнего боя никого нет, кидает валуны; с 20 % берсерк -> бурст."
L["Taktik: Mehrere Tanks halten Ouro im Nahkampf, Raid seitlich. Beim Untertauchen verteilen und Skarabäen töten."] = "Тактика: Несколько танков держат Оуро в мили, рейд сбоку. При зарывании рассредоточиться и убить скарабеев."
L["OURO: Nicht vor den Boss! Untertauchen: verteilen, Skarabäen töten!"] = "ОУРО: Не стоять перед боссом! Зарывание: разбежаться, убить скарабеев!"
L["Immer ein Tank im Nahkampf, sonst Felsbrocken."] = "Всегда один танк в мили, иначе валуны."
L["C'Thun + Tentakel"] = "К'Тун + щупальца"
L["- Augenstrahl: springt auf Spieler in der Nähe -> Raid im Kreis mit Abstand verteilen."] = "- Луч глаза: перескакивает на игроков рядом -> рейд по кругу с дистанцией."
L["- Dunkles Starren: rotierender Todesstrahl -> sofort zur Seite."] = "- Темный взгляд: вращающийся луч смерти -> сразу в сторону."
L["- Tentakel: Augen- und Klauententakel erscheinen -> schnell töten."] = "- Щупальца: появляются глазастые и когтистые щупальца -> быстро убивать."
L["- Phase 2: Spieler werden verschlungen; im Magen Fleischtentakel töten, um C'Thun zu schwächen -> nur in der Schwächephase Schaden."] = "- Фаза 2: игроков проглатывают; в желудке убивать мясистые щупальца, чтобы ослабить К'Туна -> урон только в фазе слабости."
L["Taktik: Feste Kreisaufstellung mit Abstand, Tentakel sofort weg. In Phase 2 Magen-Team tötet die Fleischtentakel, Raid zündet in der Schwächephase."] = "Тактика: Фиксированная расстановка по кругу с дистанцией, щупальца сразу убирать. В фазе 2 команда желудка убивает мясистые щупальца, рейд бурстит в фазе слабости."
L["C'THUN: Abstand halten! Dunkles Starren ausweichen, Tentakel sofort töten!"] = "К'ТУН: Держать дистанцию! Уходить от Темного взгляда, щупальца сразу убивать!"
L["Phase 2: Magen-Team auf Fleischtentakel, Schaden in Schwäche."] = "Фаза 2: команда желудка на мясистые щупальца, урон в слабость."
L["Pechschwingenhort"] = "Логово Крыла Тьмы"
L["Razorgore der Ungezähmte + Adds der Schwarzen Drachenbrut"] = "Бритвосмерт Неукротимый + адды из черных драконов"
L["- Phase 1: Ein Spieler kontrolliert Razorgore über die Kugel und zerstört mit ihm die Eier."] = "- Фаза 1: игрок контролирует Бритвосмерта через сферу и разбивает им яйца."
L["- Adds: Drachenbrut, Drachkin und Magier strömen aus den Eingängen -> an den Eingängen tanken und töten."] = "- Адды: дракончики, драконоиды и маги лезут из входов -> танковать и убивать у входов."
L["- Kugel-Kontrolle: Kontrolleur nicht unterbrechen, Bedrohung für Phase 2 beachten."] = "- Контроль сферы: контролера не прерывать, следить за угрозой на фазу 2."
L["- Phase 2: Razorgore wird frei, Feuerballsalve und Eroberung -> Tank bereit, Raid verteilt."] = "- Фаза 2: Бритвосмерт освобождается, Залп огненных шаров и Покорение -> танк готов, рейд рассредоточен."
L["Taktik: Gruppen an den Eingängen halten die Adds, der Kontrolleur zerstört alle Eier. Phase 2: Tank übernimmt Razorgore sofort."] = "Тактика: Группы у входов держат аддов, контролер разбивает все яйца. Фаза 2: танк сразу забирает Бритвосмерта."
L["RAZORGORE: Eier zerstören, Adds an den Eingängen halten!"] = "БРИТВОСМЕРТ: Разбивать яйца, держать аддов у входов!"
L["Kugel-Kontrolleur nicht unterbrechen. Phase 2: Tank bereit."] = "Контролера сферы не прерывать. Фаза 2: танк готов."
L["Vaelastrasz der Verdorbene"] = "Валестраз Порочный"
L["- Essenz des Roten: alle Spieler haben unbegrenzt Mana/Wut/Energie -> durchgehend Vollgas."] = "- Сущность Красного: у всех игроков бесконечная мана/ярость/энергия -> жмем на полную без остановки."
L["- Brennendes Adrenalin: Spieler explodiert nach kurzer Zeit und stirbt -> sofort aus dem Raid laufen; auf dem Tank -> Tankwechsel."] = "- Пылающий адреналин: игрок вскоре взрывается и умирает -> сразу выбежать из рейда; на танке -> смена танков."
L["- Flammenatem/Schwanzfeger: vorne und hinten gefährlich -> nur Tank vorne, Raid seitlich."] = "- Огненное дыхание/Удар хвостом: опасно спереди и сзади -> спереди только танк, рейд сбоку."
L["Taktik: Tank-Reihenfolge festlegen, Raid seitlich am Boss. Vael startet bei 30 % Leben: schnell töten, bevor zu viele Spieler sterben."] = "Тактика: Определить очередь танков, рейд сбоку от босса. Вейл начинает с 30 % здоровья: убить быстро, пока не умерло слишком много игроков."
L["VAELASTRASZ: Brennendes Adrenalin -> sofort raus aus dem Raid!"] = "ВАЛЕСТРАЗ: Пылающий адреналин -> сразу выбежать из рейда!"
L["Nur seitlich stehen. Tank-Reihenfolge einhalten, Vollgas!"] = "Стоять только сбоку. Соблюдать очередь танков, на полную!"
L["Brutwächter Dreschbringer"] = "Предводитель драконов Разящий Бич"
L["- Tödlicher Stoß: senkt die Heilung auf dem Tank -> Heiler aufmerksam, Tank mit Abklingzeiten."] = "- Смертельный удар: снижает исцеление на танке -> хилы внимательно, танк с КД."
L["- Druckwelle: Feuerschaden im Umkreis -> Nahkampf heilen, Fernkampf auf Abstand."] = "- Взрывная волна: урон от огня вокруг -> хилить мили, РДД на дистанции."
L["- Wegschlagen: senkt Bedrohung und wirft den Tank weg -> Tank mit dem Rücken zur Wand, Zweittank hoch in der Bedrohung."] = "- Отбрасывание: снижает угрозу и отбрасывает танка -> танк спиной к стене, второй танк высоко по угрозе."
L["Taktik: Vorher den Unterdrückungsraum säubern. Boss mit dem Rücken des Tanks zur Wand tanken, Zweittank als Ersatz bereit."] = "Тактика: Заранее зачистить комнату подавления. Танковать босса спиной танка к стене, второй танк на замену."
L["BRUTWÄCHTER: Tank an die Wand! Zweittank Bedrohung hoch halten!"] = "РАЗЯЩИЙ БИЧ: Танк к стене! Второй танк держит высокую угрозу!"
L["Tödlicher Stoß: Tank stark heilen. Fernkampf auf Abstand."] = "Смертельный удар: танка сильно хилить. РДД на дистанции."
L["Feuerschwinge"] = "Огнечрев"
L["- Flammenpuffer: stapelnder Feuer-Debuff auf allen in Sichtlinie -> hinter Säulen Stapel abbauen."] = "- Огненный буфер: стакающийся огненный дебафф на всех в зоне видимости -> сбрасывать стаки за колоннами."
L["- Flügelstoß: senkt Bedrohung, wirft zurück -> Tankwechsel einplanen."] = "- Взмах крыльев: снижает угрозу, отбрасывает -> планировать смену танков."
L["- Schattenflamme: Frontalkegel -> Onyxiaschuppenumhang tragen, nur Tank vorne."] = "- Пламя Тьмы: фронтальный конус -> носить Плащ из чешуи Ониксии, спереди только танк."
L["Taktik: Zwei Tanks wechseln bei Flügelstoß, Fernkampf und Heiler pendeln zwischen Sichtlinie und Säule, um Stapel abzubauen."] = "Тактика: Два танка меняются при Взмахе крыльев, РДД и хилы ходят между зоной видимости и колонной, чтобы сбрасывать стаки."
L["FEUERSCHWINGE: Stapel hinter der Säule abbauen! Umhang an!"] = "ОГНЕЧРЕВ: Сбрасывать стаки за колонной! Плащ надеть!"
L["Tankwechsel bei Flügelstoß. Nur Tank vorne."] = "Смена танков при Взмахе крыльев. Спереди только танк."
L["Schattenschwinge"] = "Черноскал"
L["- Schatten von Schattenschwinge: Debuff auf dem Tank, jeder Treffer heilt den Boss -> sofort Tankwechsel."] = "- Тень Черноскала: дебафф на танке, каждый удар лечит босса -> сразу смена танков."
L["- Flügelstoß: senkt Bedrohung -> Zweittank bereit."] = "- Взмах крыльев: снижает угрозу -> второй танк готов."
L["Taktik: Zwei Tanks wechseln bei jedem Schatten-Debuff, Raid seitlich. Mit Umhängen ist der Kampf ruhig."] = "Тактика: Два танка меняются на каждом дебаффе Тени, рейд сбоку. С плащами бой спокойный."
L["SCHATTENSCHWINGE: Tankwechsel bei Schatten-Debuff! Umhang an!"] = "ЧЕРНОСКАЛ: Смена танков при дебаффе Тени! Плащ надеть!"
L["Nur Tank vorne, Raid seitlich am Boss."] = "Спереди только танк, рейд сбоку от босса."
L["Flammenmaul"] = "Пламегор"
L["- Raserei: mehr Schaden auf den Tank -> Jäger mit Einlullender Schuss sofort entfernen."] = "- Бешенство: больше урона по танку -> охотники сразу снимают Усмиряющим выстрелом."
L["- Feuernova: Feuerschaden auf den ganzen Raid -> Heiler aufmerksam, Feuerwiderstand hilft."] = "- Кольцо огня: урон от огня по всему рейду -> хилы внимательно, помогает сопротивление огню."
L["- Flügelstoß und Schattenflamme: Bedrohungsverlust und Frontalkegel -> Tankwechsel, Umhang, nur Tank vorne."] = "- Взмах крыльев и Пламя Тьмы: потеря угрозы и фронтальный конус -> смена танков, плащ, спереди только танк."
L["Taktik: Zwei Tanks, Jäger-Rotation für Einlullender Schuss, Raid seitlich und verteilt."] = "Тактика: Два танка, ротация охотников на Усмиряющий выстрел, рейд сбоку и рассредоточен."
L["FLAMMENMAUL: Raserei sofort einlullen! Umhang an!"] = "ПЛАМЕГОР: Бешенство сразу усмирять! Плащ надеть!"
L["Tankwechsel bei Flügelstoß, Feuernova gegenheilen."] = "Смена танков при Взмахе крыльев, отхиливать Кольцо огня."
L["Schattenschwinge und Flammenmaul (gemeinsame Begegnung)"] = "Черноскал и Пламегор (совместный бой)"
L["- Gemeinsamer Kampf: beide Drachen gleichzeitig -> getrennt tanken, Fernkampf zwischen beiden aufteilen."] = "- Совместный бой: оба дракона одновременно -> танковать раздельно, РДД делить между обоими."
L["- Schatten von Schattenschwinge: Treffer auf dem betroffenen Tank heilen den Drachen -> sofort Tankwechsel."] = "- Тень Черноскала: удары по танку с дебаффом лечат дракона -> сразу смена танков."
L["- Raserei (Flammenmaul): sofort mit Einlullender Schuss entfernen."] = "- Бешенство (Пламегор): сразу снимать Усмиряющим выстрелом."
L["- Schattenflamme und Flügelstoß: Frontalkegel und Bedrohungsverlust -> Umhang, nur Tanks vorne."] = "- Пламя Тьмы и Взмах крыльев: фронтальный конус и потеря угрозы -> плащ, спереди только танки."
L["Taktik: Je zwei Tanks pro Drache, Drachen voneinander weg und seitlich zum Raid ausrichten. Ein Drache nach dem anderen fokussieren."] = "Тактика: По два танка на дракона, драконов развести друг от друга и развернуть боком к рейду. Фокусить драконов по одному."
L["Nur in Classic-Versionen, in denen beide Drachen gemeinsam bekämpft werden."] = "Только в Classic-версиях, где оба дракона сражаются вместе."
L["DRACHEN: Getrennt tanken! Tankwechsel bei Schatten, Raserei einlullen!"] = "ДРАКОНЫ: Танковать раздельно! Смена танков на Тени, Бешенство усмирять!"
L["Umhang an, nur Tanks vorne. Fokus laut Symbol."] = "Плащ надеть, спереди только танки. Фокус по метке."
L["Schattenschwinge/Flammenmaul"] = "Черноскал/Пламегор"
L["Totenkopf auf den Drachen, der zuerst stirbt, Kreuz auf den zweiten."] = "Череп на дракона, который умирает первым, Крест на второго."
L["Chromaggus"] = "Хромаггус"
L["- Atem: zwei von fünf Atemarten pro ID (z. B. Verbrennen, Ätzende Säure, Frostbrand, Zeitraffer, Fleisch entzünden) -> hinter die Wand in Deckung gehen."] = "- Дыхание: два из пяти видов дыхания на ID (напр. Испепеление, Едкая кислота, Ледяной ожог, Искажение времени, Воспламенение плоти) -> прятаться за стену."
L["- Brutgebrechen: fünf farbige Debuffs; Bronze nur mit Sand des Stundenglases entfernbar -> bannen, entfluchen, Gift/Krankheit heilen."] = "- Недуги стаи: пять цветных дебаффов; бронзовый снимается только Песком из песочных часов -> диспел, декурс, снимать яд/болезнь."
L["- Raserei: Jäger mit Einlullender Schuss; ab 20 % Wutanfall -> Burn."] = "- Бешенство: охотники Усмиряющим выстрелом; с 20 % Исступление -> бурст."
L["- Wechselnde Verwundbarkeit: Chromaggus wird gegen eine Schule anfällig -> passende Zauber nutzen."] = "- Смена уязвимости: Хромаггус становится уязвим к одной школе -> использовать подходящие заклинания."
L["Taktik: Tank zieht Chromaggus an den Eingang, Raid steht für die Atemangriffe hinter der Mauer in Deckung. Debuffs sofort entfernen."] = "Тактика: Танк тянет Хромаггуса ко входу, рейд стоит в укрытии за стеной от дыханий. Дебаффы снимать сразу."
L["CHROMAGGUS: Bei Atem hinter die Wand! Brutgebrechen sofort entfernen!"] = "ХРОМАГГУС: При дыхании за стену! Недуги стаи снимать сразу!"
L["Raserei einlullen, Sand für Bronze bereithalten. Ab 20 % Burn."] = "Бешенство усмирять, держать Песок для бронзы. С 20 % бурст."
L["Nefarian + Drakoniden"] = "Нефариан + дракониды"
L["- Phase 1: Drakoniden zweier Farben aus beiden Seiten -> an beiden Seiten tanken und töten, bis Nefarian landet."] = "- Фаза 1: дракониды двух цветов с обеих сторон -> танковать и убивать с обеих сторон, пока Нефариан не приземлится."
L["- Dröhnendes Gebrüll: Furcht auf alle -> Furchtschutz, Tremorstotem, Tanks mit Berserkerwut."] = "- Гулкий рев: страх на всех -> Защита от страха, Тотем трепета, танки с Яростью берсерка."
L["- Klassenrufe: Klassen erhalten negative Effekte -> je nach Ruf reagieren (z. B. Krieger Haltung, Priester nicht heilen)."] = "- Классовые вызовы: классы получают негативные эффекты -> реагировать по вызову (напр. воины стойка, жрецы не хилят)."
L["- Schleier der Schatten/Schattenflamme: Heilungsreduktion und Frontalkegel -> entfluchen, Umhang, nur Tank vorne."] = "- Покров тьмы/Пламя Тьмы: снижение исцеления и фронтальный конус -> декурс, плащ, спереди только танк."
L["- Phase 3 bei 20 %: tote Drakoniden erstehen als Skelette -> Offtanks sammeln, Fokus Nefarian."] = "- Фаза 3 на 20 %: мертвые дракониды встают скелетами -> офф-танки собирают, фокус Нефариан."
L["Taktik: Zwei Gruppen halten in Phase 1 die Drakoniden. Phase 2 Nefarian mit Rücken zur Wand tanken, Raid seitlich, auf Klassenrufe achten."] = "Тактика: Две группы держат драконидов в фазе 1. Фаза 2: Нефариана танковать спиной к стене, рейд сбоку, следить за классовыми вызовами."
L["NEFARIAN: Furchtschutz bereit! Auf Klassenrufe reagieren!"] = "НЕФАРИАН: Защита от страха готова! Реагировать на классовые вызовы!"
L["Nur Tank vorne, Umhang an. Phase 3: Skelette sammeln, Fokus Nef."] = "Спереди только танк, плащ надеть. Фаза 3: собрать скелетов, фокус Неф."
L["Naxxramas"] = "Наксрамас"
L["Anub'Rekhan + Gruftwächter"] = "Ануб'Рекан + стражи склепа"
L["- Heuschreckenschwarm: Anub'Rekhan wird schneller und verursacht viel Schaden -> Tank kitet ihn durch den Raum."] = "- Нашествие саранчи: Ануб'Рекан ускоряется и наносит много урона -> танк кайтит его по залу."
L["- Aufspießen: Linie mit Hochschleudern -> nicht in einer Linie mit dem Boss stehen."] = "- Прокалывание: линия с подбрасыванием -> не стоять на одной линии с боссом."
L["- Gruftwächter: kommen zu Beginn und während des Kampfes -> Offtank übernimmt, zuerst töten."] = "- Стражи склепа: приходят в начале и во время боя -> офф-танк забирает, убивать первыми."
L["- Leichenskarabäen: aus getöteten Spielern/Adds -> mit Flächenschaden töten."] = "- Трупные скарабеи: из убитых игроков/аддов -> убивать АоЕ."
L["Taktik: Wächter zuerst töten, Raid verteilt seitlich. Beim Heuschreckenschwarm kitet der Tank Anub'Rekhan im großen Kreis durch den Raum."] = "Тактика: Стражей убивать первыми, рейд рассредоточен сбоку. При Нашествии саранчи танк кайтит Ануб'Рекана по большому кругу по залу."
L["ANUB'REKHAN: Heuschreckenschwarm -> Tank kitet, Raid ausweichen!"] = "АНУБ'РЕКАН: Нашествие саранчи -> танк кайтит, рейд уходит!"
L["Gruftwächter zuerst. Nicht in Linie für Aufspießen."] = "Стражи склепа первыми. Не стоять в линию под Прокалывание."
L["Großwitwe Faerlina + Anhänger und Verehrer"] = "Великая вдова Фарлина + последователи и почитатели"
L["- Raserei: hoher Tankschaden -> Verehrer in ihrer Nähe sterben lassen (Umarmung der Witwe), Raserei endet."] = "- Бешенство: сильный урон по танку -> дать почитателю умереть рядом с ней (Объятие вдовы), Бешенство спадает."
L["- Feuerregen: Feuerzone -> sofort verlassen."] = "- Огненный ливень: огненная зона -> сразу выйти."
L["- Giftblitzsalve: Naturschaden auf Gruppen -> Gift entfernen, Naturwiderstand hilft."] = "- Залп отравленных стрел: урон от сил природы по группам -> снимать яд, помогает сопротивление силам природы."
L["- Anhänger: Ansturm und Stille -> zuerst töten."] = "- Последователи: рывок и немота -> убивать первыми."
L["Taktik: Anhänger zuerst töten, Verehrer per Gedankenkontrolle der Priester aufsparen und bei Raserei neben Faerlina opfern."] = "Тактика: Последователей убивать первыми, почитателей сохранить через контроль разума жрецов и при Бешенстве жертвовать рядом с Фарлиной."
L["FAERLINA: Anhänger zuerst! Verehrer für Raserei aufheben!"] = "ФАРЛИНА: Последователи первыми! Почитателей беречь под Бешенство!"
L["Raus aus dem Feuerregen, Gift entfernen."] = "Выйти из Огненного ливня, снимать яд."
L["Faerlina"] = "Фарлина"
L["Totenkopf/Kreuz auf die Anhänger (zuerst töten), Stern bis Dreieck auf die Verehrer für die Priester."] = "Череп/Крест на последователей (убивать первыми), от Звезды до Треугольника на почитателей для жрецов."
L["Maexxna + Spinnenjunge"] = "Мексна + паучата"
L["- Netzspray: betäubt den ganzen Raid ca. 8 Sek. -> vorher Tank voll heilen, HoTs drauf."] = "- Распыление паутины: оглушает весь рейд на ок. 8 сек. -> заранее отхилить танка в фулл, накинуть ХоТы."
L["- Netzwirbel: Spieler werden an die Wand gesponnen -> Fernkampf befreit sie sofort."] = "- Кокон: игроков приклеивает к стене -> РДД сразу освобождают."
L["- Nekrotisches Gift: senkt Heilung auf dem Tank -> Gift sofort entfernen."] = "- Некротический яд: снижает исцеление на танке -> яд снимать сразу."
L["- Spinnenjunge: werden regelmäßig ausgespuckt -> Flächenschaden; ab 30 % Raserei -> Burn."] = "- Паучата: регулярно выплевываются -> АоЕ; с 30 % Бешенство -> бурст."
L["Taktik: Tank in der Mitte, Fernkampf befreit Eingesponnene, Heiler bereiten jedes Netzspray mit Vorheilung vor."] = "Тактика: Танк в центре, РДД освобождают из коконов, хилы готовят каждое Распыление паутины прехилом."
L["MAEXXNA: Vor Netzspray Tank voll heilen! Eingesponnene sofort befreien!"] = "МЕКСНА: Перед Распылением паутины танка в фулл! Коконы сразу освобождать!"
L["Nekrotisches Gift entfernen, Spinnenjunge per Flächenschaden."] = "Снимать Некротический яд, паучат АоЕ."
L["Noth der Seuchenfürst + Seuchenkrieger"] = "Нот Чумной + чумные воины"
L["- Fluch des Seuchenfürsten: bei Ablauf Schaden auf Spieler und Umgebung -> sofort entfluchen."] = "- Проклятие Чумного: по окончании урон по игроку и окружающим -> сразу декурс."
L["- Blinzeln: Noth teleportiert und setzt Bedrohung zurück -> Tanks schnell übernehmen."] = "- Скачок: Нот телепортируется и сбрасывает угрозу -> танки быстро подхватывают."
L["- Balkon-Phase: Noth teleportiert sich weg, Wellen von Skeletten -> Offtanks sammeln, Flächenschaden."] = "- Фаза балкона: Нот телепортируется прочь, волны скелетов -> офф-танки собирают, АоЕ."
L["Taktik: Entfluchen fest einteilen, Tanks in den Ecken bereit. Adds in den Balkon-Phasen sammeln und schnell töten."] = "Тактика: Декурс распределить заранее, танки готовы по углам. Аддов в фазах балкона собирать и быстро убивать."
L["NOTH: Flüche sofort entfernen! Nach Blinzeln Tank übernehmen!"] = "НОТ: Проклятия снимать сразу! После Скачка танк подхватывает!"
L["Balkon-Phase: Adds sammeln und mit Flächenschaden töten."] = "Фаза балкона: собрать аддов и убить АоЕ."
L["Heigan der Unreine"] = "Хейган Нечестивый"
L["- Ausbruch: der Boden bricht in Zonen nacheinander aus -> im Takt die Zonen wechseln (Tanzen)."] = "- Извержение: пол по зонам извергается по очереди -> менять зоны в ритме (танец)."
L["- Zauberunterbrechung/Manabrand: in der Nähe Zauberverlangsamung -> Fernkampf auf der Plattform weg."] = "- Прерывание заклинаний/Ожог маны: рядом замедление чтения заклинаний -> РДД уходят на платформу."
L["- Fieberhafte Krankheit: Krankheits-Debuff, senkt Leben -> Krankheit heilen."] = "- Лихорадочная болезнь: дебафф-болезнь, снижает здоровье -> снимать болезнь."
L["- Tanz-Phase: Heigan teleportiert auf die Plattform, schnellere Ausbrüche -> alle tanzen mit."] = "- Фаза танца: Хейган телепортируется на платформу, извержения быстрее -> все танцуют."
L["Taktik: Tank führt Heigan im Takt durch die Zonen, Fernkampf auf der Plattform. In der Tanz-Phase alle zusammen der Zonenreihenfolge folgen."] = "Тактика: Танк ведет Хейгана по зонам в ритме, РДД на платформе. В фазе танца все вместе идут по порядку зон."
L["HEIGAN: Im Takt die Zonen wechseln! Nicht im Ausbruch stehen!"] = "ХЕЙГАН: Менять зоны в ритме! Не стоять в Извержении!"
L["Krankheit heilen. Tanz-Phase: alle zusammen dem Tank folgen."] = "Снимать болезнь. Фаза танца: все вместе за танком."
L["Loatheb + Sporen"] = "Лотхиб + споры"
L["- Verderbter Geist: Heiler können nur ca. einmal pro Minute heilen -> feste Heilrotation."] = "- Мертвящая аура: хилы могут лечить ок. одного раза в минуту -> фиксированная ротация хилов."
L["- Unausweichliches Schicksal: hoher Schattenschaden nach kurzer Zeit -> Schattenschutz-Tränke, rechtzeitig heilen."] = "- Неминуемый рок: сильный урон от темной магии через короткое время -> зелья защиты от темной магии, вовремя хилить."
L["- Sporen: getötete Spore gibt nahen Spielern kritische Treffer -> Gruppen nacheinander in die Spore."] = "- Споры: убитая спора дает игрокам рядом критические удары -> группы по очереди в спору."
L["Taktik: Strikte Heilrotation, Schattenschutz-Tränke vorher. Sporen gruppenweise für Kritbonus nutzen und Schaden maximieren."] = "Тактика: Строгая ротация хилов, зелья защиты от темной магии заранее. Споры использовать по группам ради бонуса к криту и выжимать максимум урона."
L["LOATHEB: Heilrotation einhalten! Schattenschutz-Trank nutzen!"] = "ЛОТХИБ: Соблюдать ротацию хилов! Пить зелье защиты от темной магии!"
L["Sporen gruppenweise nutzen für kritische Treffer."] = "Споры брать по группам ради критов."
L["Instrukteur Razuvious + 4 Todesritter-Reservisten"] = "Инструктор Разувий + 4 рыцаря смерти-резервиста"
L["- Schwere Nahkampfschläge: töten normale Tanks fast sofort -> nur gedankenkontrollierte Reservisten tanken ihn."] = "- Тяжелые удары в ближнем бою: обычных танков убивают почти сразу -> его танкуют только законтроленные резервисты."
L["- Störender Schrei: Manabrand und Schaden im Umkreis -> Abstand halten."] = "- Разрушительный крик: сжигание маны и урон вокруг -> держать дистанцию."
L["- Gedankenkontrolle: Priester steuern die Reservisten (Schildwall, Spott) -> Kontrolle rechtzeitig wechseln."] = "- Контроль разума: жрецы управляют резервистами (Глухая оборона, Провокация) -> вовремя менять контроль."
L["Taktik: Priester übernehmen je einen Reservisten und wechseln die Rolle als Tank, Fernkampf auf Distanz, Nahkampf am Boss."] = "Тактика: Жрецы берут по резервисту и меняются ролью танка, РДД на дистанции, мили у босса."
L["RAZUVIOUS: Nur Reservisten tanken! Priester Kontrolle rechtzeitig wechseln!"] = "РАЗУВИЙ: Танкуют только резервисты! Жрецы вовремя меняют контроль!"
L["Abstand wegen Störender Schrei."] = "Дистанция из-за Разрушительного крика."
L["Razuvious (Reservisten)"] = "Разувий (резервисты)"
L["Jeder Reservist ein Symbol, jeder Priester übernimmt sein zugewiesenes Symbol."] = "Каждому резервисту своя метка, каждый жрец берет свою назначенную метку."
L["Gothik der Seelenjäger + Lebende und Untote"] = "Готик Жнец + живые и нежить"
L["- Zwei Seiten: Raid aufgeteilt in lebende und tote Seite -> beide Seiten gleich stark besetzen."] = "- Две стороны: рейд разделен на сторону живых и сторону мертвых -> обе стороны укомплектовать одинаково."
L["- Lebende Adds: sterben sie, erscheinen sie als Geister auf der toten Seite -> tote Seite muss mithalten."] = "- Живые адды: умирая, появляются духами на стороне мертвых -> сторона мертвых должна успевать."
L["- Tor: öffnet nach einiger Zeit, dann kommt Gothik herunter -> Adds vorher unter Kontrolle haben."] = "- Ворота: открываются через некоторое время, затем спускается Готик -> к этому моменту адды под контролем."
L["- Seele ernten: stapelnder Debuff -> zügig töten."] = "- Жатва душ: стакающийся дебафф -> убивать быстро."
L["Taktik: Raid in zwei Hälften, jede Seite tötet ihre Wellen. Nach Öffnen des Tores Gothik tanken und schnell töten."] = "Тактика: Рейд на две половины, каждая сторона убивает свои волны. После открытия ворот танкуем Готика и быстро убиваем."
L["GOTHIK: Beide Seiten halten! Tote Seite auf Geister vorbereiten!"] = "ГОТИК: Держать обе стороны! Сторона мертвых, готовьтесь к духам!"
L["Nach dem Tor: Gothik schnell töten."] = "После ворот: Готика быстро убить."
L["Die Vier Reiter: Thane Korth'azz, Lady Blaumeux, Hochlord Mograine, Sir Zeliek"] = "Четыре всадника: тан Корт'азз, леди Бломе, верховный лорд Могрейн, сэр Зелиек"
L["- Male: jeder Reiter stapelt sein Mal, hohe Stapel töten -> Tanks rotieren zwischen den Reitern."] = "- Метки: каждый всадник стакает свою метку, высокие стаки убивают -> танки ротируются между всадниками."
L["- Meteor (Korth'azz): Schaden geteilt auf getroffene Spieler -> bei ihm zusammenstehen."] = "- Метеор (Корт'азз): урон делится между задетыми игроками -> стоять у него вместе."
L["- Leerezone (Blaumeux): Schattenfläche -> herauslaufen."] = "- Зона пустоты (Бломе): лужа тьмы -> выходить."
L["- Heiliger Zorn (Zeliek): springt zwischen Spielern -> verteilt stehen."] = "- Гнев небес (Зелиек): прыгает между игроками -> стоять рассредоточенно."
L["Taktik: Reiter in die vier Ecken ziehen, Tanks und Heiler rotieren nach festem Plan, um Mal-Stapel abzubauen. Zwei Reiter nacheinander fokussieren."] = "Тактика: Всадников растащить по четырем углам, танки и хилы ротируются по фиксированному плану, чтобы сбрасывать стаки меток. Фокусить двух всадников по очереди."
L["VIER REITER: Rotation einhalten! Male nicht zu hoch stapeln!"] = "ЧЕТЫРЕ ВСАДНИКА: Соблюдать ротацию! Не набирать много стаков меток!"
L["Meteor: zusammen. Zeliek: verteilt. Leerezone verlassen."] = "Метеор: вместе. Зелиек: рассредоточиться. Из Зоны пустоты выйти."
L["Flickwerk"] = "Лоскутик"
L["- Hasserfüllter Schlag: trifft den Nahkampf-Spieler mit dem meisten Leben (nicht den Haupttank) -> drei Offtanks mit voller Gesundheit soaken."] = "- Удар ненависти: бьет игрока в мили с наибольшим здоровьем (не главного танка) -> три офф-танка с фулл ХП соакают."
L["- Berserker nach ca. 7 Minuten: Raid stirbt -> Schaden maximieren."] = "- Берсерк через ок. 7 минут: рейд умирает -> выжимать максимум урона."
L["- Raserei ab 5 %: mehr Schaden -> Heiler voll auf die Tanks."] = "- Исступление с 5 %: больше урона -> хилы полностью на танков."
L["Taktik: Haupttank plus drei Offtanks mit hohem Leben im Nahkampf, Heiler fest auf die Tanks eingeteilt, alle anderen maximaler Schaden."] = "Тактика: Мейн-танк плюс три офф-танка с большим запасом ХП в мили, хилы закреплены за танками, все остальные максимальный урон."
L["FLICKWERK: Offtanks mit vollem Leben im Nahkampf! Volles DPS!"] = "ЛОСКУТИК: Офф-танки с фулл ХП в мили! Полный ДПС!"
L["Heiler nur auf die Tanks. Berserker-Timer beachten."] = "Хилы только на танков. Следить за таймером берсерка."
L["Grobbulus + Brühschleime"] = "Гроббулус + жижи"
L["- Mutierende Injektion: Spieler explodiert nach Ablauf mit Giftwolke -> an den Rand laufen, erst dort bannen/ablaufen lassen."] = "- Мутагенная инъекция: по окончании игрок взрывается ядовитым облаком -> бежать к краю, только там диспел/дать спасть."
L["- Schleimspray: Kegel vor dem Boss, ruft Brühschleime -> Raid nicht vorne, Schleime töten."] = "- Слизистая струя: конус перед боссом, призывает жиж -> рейд не спереди, жиж убивать."
L["- Giftwolken: bleiben liegen -> Tank zieht Grobbulus langsam am Rand entlang."] = "- Ядовитые облака: остаются на полу -> танк медленно ведет Гроббулуса вдоль края."
L["Taktik: Tank kitet Grobbulus langsam um den Raum, Raid hinten/seitlich, betroffene Spieler laufen mit Injektion an die Seite."] = "Тактика: Танк медленно кайтит Гроббулуса по залу, рейд сзади/сбоку, игроки с инъекцией отбегают в сторону."
L["GROBBULUS: Injektion -> an den Rand laufen! Nicht vor den Boss!"] = "ГРОББУЛУС: Инъекция -> бежать к краю! Не стоять перед боссом!"
L["Schleime töten, Giftwolken meiden, Tank kitet am Rand."] = "Жиж убивать, ядовитые облака обходить, танк кайтит по краю."
L["Gluth + Zombies"] = "Глут + зомби"
L["- Tödliche Wunde: Heilungsreduktions-Stapel -> Tankwechsel."] = "- Смертельная рана: стаки снижения исцеления -> смена танков."
L["- Dezimieren: bringt alle auf ca. 5 % Leben, Zombies laufen zu Gluth und heilen ihn -> Zombies kiten und mit Flächenschaden töten."] = "- Истребление: опускает всех до ок. 5 % здоровья, зомби бегут к Глуту и лечат его -> зомби кайтить и убивать АоЕ."
L["- Raserei: Jäger mit Einlullender Schuss."] = "- Бешенство: охотники Усмиряющим выстрелом."
L["- Schreckliches Gebrüll: Furcht -> Furchtschutz für Tanks."] = "- Ужасающий рев: страх -> Защита от страха на танков."
L["Taktik: Zwei Tanks wechseln, ein Kiter mit Fallen hält die Zombies vom Boss weg. Nach Dezimieren Zombies sofort mit Flächenschaden töten."] = "Тактика: Два танка меняются, кайтер с ловушками держит зомби подальше от босса. После Истребления зомби сразу убивать АоЕ."
L["GLUTH: Zombies kiten und töten! Raserei einlullen!"] = "ГЛУТ: Зомби кайтить и убивать! Бешенство усмирять!"
L["Tankwechsel bei Tödlicher Wunde. Nach Dezimieren hochheilen."] = "Смена танков на Смертельной ране. После Истребления отхилить."
L["Thaddius + Stalagg und Feugen"] = "Таддиус + Сталагг и Фойген"
L["- Phase 1: Stalagg und Feugen auf zwei Plattformen -> beide gleichzeitig töten (kurzes Zeitfenster), sonst erwacht der andere wieder."] = "- Фаза 1: Сталагг и Фойген на двух платформах -> убить обоих одновременно (короткое окно), иначе другой оживает."
L["- Magnetzug: tauscht die Tanks zwischen den Plattformen -> Tanks bereit halten."] = "- Магнитное притяжение: меняет танков местами между платформами -> танки наготове."
L["- Polaritätsverschiebung: Plus- oder Minus-Ladung -> zur Gruppe mit gleicher Ladung laufen."] = "- Сдвиг полярности: плюс- или минус-заряд -> бежать к группе с тем же зарядом."
L["- Kettenblitz und Berserker nach ca. 5 Minuten -> verteilt und schnell."] = "- Цепная молния и берсерк через ок. 5 минут -> рассредоточенно и быстро."
L["Taktik: Phase 1 beide Adds gleichzeitig herunterbringen. Phase 2 feste Plus- und Minus-Seite, bei Polaritätswechsel sofort Seite wechseln."] = "Тактика: Фаза 1: обоих аддов опускать одновременно. Фаза 2: фиксированная сторона плюса и минуса, при смене полярности сразу менять сторону."
L["THADDIUS: Plus links, Minus rechts! Bei Polaritätswechsel Seite wechseln!"] = "ТАДДИУС: Плюс слева, минус справа! При смене полярности менять сторону!"
L["Phase 1: Stalagg und Feugen gleichzeitig töten."] = "Фаза 1: Сталагга и Фойгена убить одновременно."
L["Saphiron"] = "Сапфирон"
L["- Frostaura: dauerhafter Frostschaden -> Frostwiderstand für alle."] = "- Аура холода: постоянный урон от магии льда -> сопротивление льду у всех."
L["- Lebensentzug: Fluch auf Spielern -> sofort entfluchen."] = "- Похищение жизни: проклятие на игроках -> сразу декурс."
L["- Flugphase: Eisblitz friert Spieler zu Eisblöcken -> danach hinter einem Eisblock vor Frostatem verstecken."] = "- Фаза полета: Ледяная стрела превращает игроков в глыбы льда -> потом прятаться за ледяной глыбой от Ледяного дыхания."
L["- Blizzard: wandernde Frostzonen -> ausweichen."] = "- Снежная буря: блуждающие ледяные зоны -> уворачиваться."
L["Taktik: Frostwiderstand-Ausrüstung pflicht. Tank hält Saphiron mit Kopf weg vom Raid, in der Flugphase alle verteilt und dann hinter Eisblock."] = "Тактика: Экипировка на сопротивление льду обязательна. Танк держит Сапфирона головой от рейда, в фазе полета все рассредоточены, затем за ледяную глыбу."
L["SAPHIRON: Hinter Eisblock bei Frostatem! Flüche sofort entfernen!"] = "САПФИРОН: За глыбу при Ледяном дыхании! Проклятия снимать сразу!"
L["Frostwiderstand an. Blizzard ausweichen."] = "Сопротивление льду надеть. Уворачиваться от Снежной бури."
L["Kel'Thuzad + Adds"] = "Кел'Тузад + адды"
L["- Phase 1: Skelette, Abscheulichkeiten und Seelenweber -> am Rand der Nischen töten."] = "- Фаза 1: скелеты, поганища и ткачи душ -> убивать у края ниш."
L["- Frostblitz: sehr hoher Schaden -> unterbrechen."] = "- Ледяная стрела: очень сильный урон -> сбивать."
L["- Frostschlag/Detonieren von Mana/Schattenspalt: Frost-Wurzeln, Manaexplosion und Bodenflächen -> heilen, Manaspieler raus, Spalt verlassen."] = "- Ледяной взрыв/Детонация маны/Расщелина тьмы: ледяные корни, взрыв маны и зоны на полу -> хилить, манаюзеры наружу, из расщелины выйти."
L["- Ketten von Kel'Thuzad: Gedankenkontrolle -> Spieler kontrollieren."] = "- Цепи Кел'Тузада: контроль разума -> контролить игроков."
L["- Phase 3 (45 %): Wächter von Eiskrone -> Priester fesseln die Untoten."] = "- Фаза 3 (45 %): стражи Ледяной Короны -> жрецы сковывают нежить."
L["Taktik: Raid verteilt in den Nischen, Unterbrecher-Rotation auf Frostblitz. Phase 3: Wächter per Untote fesseln binden."] = "Тактика: Рейд рассредоточен по нишам, ротация кикеров на Ледяную стрелу. Фаза 3: стражей связывать Сковыванием нежити."
L["KEL'THUZAD: Frostblitz unterbrechen! Schattenspalt sofort verlassen!"] = "КЕЛ'ТУЗАД: Сбивать Ледяную стрелу! Из Расщелины тьмы сразу выйти!"
L["Gedankenkontrollierte kontrollieren. Phase 3: Wächter fesseln."] = "Законтроленных контролить. Фаза 3: стражей сковать."
L["Kel'Thuzad (Wächter)"] = "Кел'Тузад (стражи)"
L["Jeder Wächter von Eiskrone ein Symbol, Priester fesseln ihr zugewiesenes Symbol (Stern zuerst)."] = "Каждому стражу Ледяной Короны своя метка, жрецы сковывают свою назначенную метку (Звезда первой)."
L["Onyxias Hort"] = "Логово Ониксии"
L["Onyxia + Welpen und Wachen"] = "Ониксия + дракончики и стражи"
L["- Phase 2 (65 %): fliegt, Feuerbälle und Tiefer Atem -> aus der Atemlinie laufen, Welpen aus den Höhlen töten."] = "- Фаза 2 (65 %): летает, огненные шары и Глубокий вдох -> выбегать из линии дыхания, убивать дракончиков из пещер."
L["- Phase 3 (40 %): landet, Furcht (Gebrüll) und Bodenausbrüche -> Furchtschutz, Tremorstotem."] = "- Фаза 3 (40 %): приземляется, страх (рев) и извержения из пола -> Защита от страха, Тотем трепета."
L["- Flügelstoß: senkt Bedrohung -> Tank behält vorsichtig Aggro."] = "- Взмах крыльев: снижает угрозу -> танк аккуратно держит агро."
L["Taktik: Phase 1 Onyxia mit Kopf zur Wand, Raid seitlich. Phase 2 verteilt, Welpen mit Flächenschaden. Phase 3 Tank übernimmt, Furcht beachten."] = "Тактика: Фаза 1: Ониксия головой к стене, рейд сбоку. Фаза 2: рассредоточиться, дракончиков АоЕ. Фаза 3: танк забирает, следить за страхом."
L["ONYXIA: Nicht vor oder hinter den Drachen! Tiefer Atem: aus der Linie!"] = "ОНИКСИЯ: Не стоять перед или за драконом! Глубокий вдох: уйти с линии!"
L["Welpen sofort töten. Phase 3: Furchtschutz bereit."] = "Дракончиков сразу убивать. Фаза 3: Защита от страха наготове."
L["Zul'Gurub"] = "Зул'Гуруб"
L["Hohepriesterin Jeklik + Fledermäuse"] = "Верховная жрица Джеклик + летучие мыши"
L["- Phase 1 (Fledermausform): Ansturm, Schallexplosion (Stille), Fledermausschwärme -> Fernkampf verteilt, Fledermäuse töten."] = "- Фаза 1 (облик летучей мыши): рывок, Звуковой взрыв (немота), стаи мышей -> РДД рассредоточены, мышей убивать."
L["- Phase 2 (50 %): Trollform, Große Heilung -> unterbrechen!"] = "- Фаза 2 (50 %): облик тролля, Великое исцеление -> сбивать!"
L["- Gedankenschinden/Schattenwort: Schmerz: Schattenschaden -> bannen, heilen."] = "- Пытка разума/Слово Тьмы: Боль: урон от темной магии -> диспел, хил."
L["- Feuer-Fledermäuse: werfen Feuerbomben -> aus den Flammen laufen."] = "- Огненные мыши: кидают огненные бомбы -> выбегать из огня."
L["Taktik: Tank hält Jeklik, Nahkampf auf Schallexplosion achten. Phase 2: Unterbrecher fest einteilen, aus dem Feuer bleiben."] = "Тактика: Танк держит Джеклик, мили следят за Звуковым взрывом. Фаза 2: кикеров распределить заранее, не стоять в огне."
L["JEKLIK: Große Heilung unterbrechen! Raus aus dem Feuer!"] = "ДЖЕКЛИК: Сбивать Великое исцеление! Выйти из огня!"
L["Fledermäuse töten, Fernkampf verteilt gegen Ansturm."] = "Мышей убивать, РДД рассредоточены от рывка."
L["Hohepriester Venoxis + 4 Schlangen"] = "Верховный жрец Веноксис + 4 змеи"
L["- Schlangen: vier Adds -> zuerst töten."] = "- Змеи: четыре адда -> убивать первыми."
L["- Heiliges Feuer/Erneuerung: Priesterform heilt und verursacht Schaden -> unterbrechen und bannen."] = "- Священный огонь/Обновление: в облике жреца лечит и наносит урон -> сбивать и диспелить."
L["- Heiliger Zorn: springt zwischen Spielern -> Abstand halten."] = "- Гнев небес: прыгает между игроками -> держать дистанцию."
L["- Schlangenform (50 %): Giftwolken und Gift -> aus Wolken laufen, Gift entfernen."] = "- Облик змеи (50 %): ядовитые облака и яд -> выходить из облаков, снимать яд."
L["Taktik: Schlangen zuerst, dann Venoxis mit Unterbrechern. In Schlangenform Giftwolken meiden und Gift entfernen."] = "Тактика: Сначала змеи, затем Веноксис с кикерами. В облике змеи обходить ядовитые облака и снимать яд."
L["VENOXIS: Schlangen zuerst! Heilige Zauber unterbrechen!"] = "ВЕНОКСИС: Змеи первыми! Сбивать заклинания Света!"
L["Abstand für Heiliger Zorn. Giftwolken meiden."] = "Дистанция от Гнева небес. Обходить ядовитые облака."
L["Venoxis"] = "Веноксис"
L["Totenkopf, Kreuz, Viereck, Mond auf die Schlangen in Tötungsreihenfolge."] = "Череп, Крест, Квадрат, Луна на змей в порядке убийства."
L["Hohepriesterin Mar'li + Spinnenjunge"] = "Верховная жрица Мар'ли + паучата"
L["- Spinnenjunge: wachsen mit der Zeit -> sofort töten."] = "- Паучата: растут со временем -> убивать сразу."
L["- Giftblitzsalve: Naturschaden im Umkreis -> Gift entfernen."] = "- Залп отравленных стрел: урон от сил природы вокруг -> снимать яд."
L["- Spinnenform: umhüllende Netze und Bedrohungsverlust -> zweiter Tank bereit."] = "- Облик паука: опутывающая паутина и потеря угрозы -> второй танк наготове."
L["- Leben entziehen: heilt Mar'li -> bannen bzw. unterbrechen."] = "- Похищение жизни: лечит Мар'ли -> диспел или сбивать."
L["Taktik: Spinnenjunge sofort töten, Gift entfernen. Zwei Tanks wegen Bedrohungsverlust in Spinnenform."] = "Тактика: Паучат убивать сразу, снимать яд. Два танка из-за потери угрозы в облике паука."
L["MAR'LI: Spinnenjunge sofort töten! Gift entfernen!"] = "МАР'ЛИ: Паучат сразу убивать! Снимать яд!"
L["Zweittank bereit bei Spinnenform."] = "Второй танк готов к облику паука."
L["Blutfürst Mandokir + Ohgan"] = "Мандокир Повелитель Крови + Оган"
L["- Bedrohlicher Blick: Mandokir starrt einen Spieler an -> dieser macht nichts (kein Angriff, Zauber, Bewegung), sonst Ansturm und Tod."] = "- Угрожающий взгляд: Мандокир смотрит на игрока -> тот ничего не делает (ни атак, ни заклинаний, ни движения), иначе рывок и смерть."
L["- Wirbelwind: hoher Schaden im Umkreis -> Nahkampf kurz raus."] = "- Вихрь: сильный урон вокруг -> мили ненадолго выходят."
L["- Geister: tote Spieler können wiederbelebt werden; Mandokir steigt bei Kills im Level -> Tode vermeiden."] = "- Духи: мертвых игроков можно воскресить; Мандокир повышает уровень за убийства -> избегать смертей."
L["- Ohgan: Raptor -> von einem zweiten Tank halten."] = "- Оган: ящер -> держит второй танк."
L["Taktik: Ohgan separat tanken, Mandokir mit Rücken zum Raid. Angestarrte Spieler hören sofort auf zu handeln."] = "Тактика: Огана танковать отдельно, Мандокира спиной к рейду. Игроки под взглядом сразу прекращают любые действия."
L["MANDOKIR: Angestarrt? NICHTS tun! Wirbelwind -> Nahkampf raus!"] = "МАНДОКИР: Под взглядом? НИЧЕГО не делать! Вихрь -> мили наружу!"
L["Ohgan separat tanken, Tode vermeiden."] = "Огана танковать отдельно, избегать смертей."
L["Rand des Wahnsinns: Gri'lek, Hazza'rah, Renataki oder Wushoolay"] = "Грань Безумия: Гри'лек, Хазза'рах, Ренатаки или Вушулай"
L["- Wechselnder Boss: einer von vier Bossen, je nach Rotation -> vorher klären, welcher aktiv ist."] = "- Сменяющийся босс: один из четырех боссов, по ротации -> заранее выяснить, кто активен."
L["- Gri'lek: verfolgt Spieler -> Weglaufen; Hazza'rah: Illusionen -> töten; Renataki: Verschwinden/Bedrohungsreset -> Tank bereit."] = "- Гри'лек: преследует игроков -> убегать; Хазза'рах: иллюзии -> убивать; Ренатаки: исчезновение/сброс угрозы -> танк наготове."
L["- Wushoolay: Kettenblitz -> verteilt stehen."] = "- Вушулай: Цепная молния -> стоять рассредоточенно."
L["Taktik: Je nach Boss Raid verteilen oder Illusionen schnell töten, ansonsten einfacher Tank-und-Schaden-Kampf."] = "Тактика: В зависимости от босса рассредоточить рейд или быстро убивать иллюзии, в остальном простой бой «танк и урон»."
L["Optionaler Boss, wird über die Gurubashi-Wahnsinnsmechanik beschworen."] = "Необязательный босс, призывается через механику безумия Гурубаши."
L["RAND DES WAHNSINNS: Boss-Mechanik beachten! Verteilt stehen!"] = "ГРАНЬ БЕЗУМИЯ: Следить за механикой босса! Стоять рассредоточенно!"
L["Illusionen/Adds schnell töten, Tank bei Bedrohungsreset bereit."] = "Иллюзий/аддов быстро убивать, танк готов к сбросу угрозы."
L["Gahz'ranka"] = "Газ'ранка"
L["- Frostatem: Frontalkegel mit Manaentzug -> nur Tank vorne."] = "- Ледяное дыхание: фронтальный конус с вытягиванием маны -> спереди только танк."
L["- Gewaltiger Geysir: schleudert Spieler hoch -> Fallschaden, Heiler aufmerksam."] = "- Мощный гейзер: подбрасывает игроков -> урон от падения, хилы внимательно."
L["- Zerschmettern: Rückstoß auf den Tank -> Tank stabil positionieren."] = "- Сокрушение: отбрасывание танка -> танку встать устойчиво."
L["Taktik: Tank hält Gahz'ranka mit Kopf weg vom Raid, Raid seitlich. Einfacher Kampf, Fallschaden gegenheilen."] = "Тактика: Танк держит Газ'ранку головой от рейда, рейд сбоку. Простой бой, отхиливать урон от падения."
L["Optionaler Boss, wird mit einem Schlammstinkerköder am Teich geangelt."] = "Необязательный босс, вылавливается у пруда на приманку из грязнопузых пучеглазок."
L["GAHZ'RANKA: Nur Tank vorne! Geysir-Fallschaden gegenheilen!"] = "ГАЗ'РАНКА: Спереди только танк! Отхиливать урон от падения после гейзера!"
L["Raid seitlich, Heiler auf Rückstoß achten."] = "Рейд сбоку, хилы следят за отбрасыванием."
L["Hohepriester Thekal + Zelot Lor'Khan und Zelot Zath"] = "Верховный жрец Текал + фанатик Лор'Кхан и фанатик Зат"
L["- Phase 1: Thekal, Lor'Khan und Zath -> alle drei fast gleichzeitig töten, sonst stehen sie wieder auf."] = "- Фаза 1: Текал, Лор'Кхан и Зат -> убить всех троих почти одновременно, иначе они встают снова."
L["- Lor'Khan: heilt -> unterbrechen; Zath: Blenden/Verschwinden -> Tank bereit."] = "- Лор'Кхан: лечит -> сбивать; Зат: Ослепление/Исчезновение -> танк наготове."
L["- Phase 2 (Tigerform): Kraftschlag mit Rückstoß, Tiger-Adds, Raserei -> Tank an die Wand, Adds töten, Raserei einlullen."] = "- Фаза 2 (облик тигра): Мощный удар с отбрасыванием, тигры-адды, Бешенство -> танк к стене, аддов убивать, Бешенство усмирять."
L["Taktik: Drei Tanks, alle drei Ziele gleichmäßig herunterbringen und im Zeitfenster töten. Phase 2: Tank mit Rücken zur Wand."] = "Тактика: Три танка, всех троих опускать равномерно и убить в окно. Фаза 2: танк спиной к стене."
L["THEKAL: Alle drei gleichzeitig töten! Lor'Khan unterbrechen!"] = "ТЕКАЛ: Убить всех троих одновременно! Сбивать Лор'Кхана!"
L["Phase 2: Tiger töten, Raserei einlullen."] = "Фаза 2: тигров убивать, Бешенство усмирять."
L["Thekal"] = "Текал"
L["Totenkopf Thekal, Kreuz Lor'Khan, Viereck Zath – gleichmäßig herunterbringen."] = "Череп Текал, Крест Лор'Кхан, Квадрат Зат – опускать равномерно."
L["Hohepriesterin Arlokk + Panther"] = "Верховная жрица Арлокк + пантеры"
L["- Mal der Arlokk: Panther greifen den markierten Spieler an -> Spieler zum Tank laufen, Panther abfangen."] = "- Метка Арлокк: пантеры атакуют помеченного игрока -> игрок бежит к танку, пантер перехватывать."
L["- Verschwinden: Arlokk wird unsichtbar, viele Panther kommen -> Offtanks sammeln, Flächenschaden."] = "- Исчезновение: Арлокк становится невидимой, приходит много пантер -> офф-танки собирают, АоЕ."
L["- Solarplexus/Wirbelwind: Tank wird betäubt -> Zweittank bereit."] = "- Солнечное сплетение/Вихрь: танк оглушен -> второй танк наготове."
L["Taktik: Raid in der Mitte zusammen, Offtanks fangen Panther ab, Flächenschaden auf Panther. Arlokk nach Erscheinen sofort übernehmen."] = "Тактика: Рейд вместе в центре, офф-танки перехватывают пантер, АоЕ по пантерам. Арлокк после появления сразу забирать."
L["ARLOKK: Markierter Spieler -> zu den Tanks laufen! Panther sammeln!"] = "АРЛОКК: Помеченный игрок -> бежать к танкам! Собирать пантер!"
L["Bei Verschwinden: Flächenschaden auf Panther, Tank bereit."] = "При Исчезновении: АоЕ по пантерам, танк наготове."
L["Jin'do der Verhexer + Totems und Skelette"] = "Джин'до Проклинатель + тотемы и скелеты"
L["- Mächtiger Heilungszauberschutz: heilt Jin'do -> sofort zerstören."] = "- Мощный тотем исцеления: лечит Джин'до -> сразу уничтожить."
L["- Gehirnwäsche-Totem: Gedankenkontrolle -> sofort zerstören."] = "- Тотем промывания мозгов: контроль разума -> сразу уничтожить."
L["- Verhexung: Tank verwandelt -> magisch bannen."] = "- Сглаз: танк превращен -> снять магию диспелом."
L["- Wahnvorstellungen: Fluch, Schatten sehen -> entfluchen, Schatten töten; Teleport in die Grube -> Skelette töten und herauskommen."] = "- Бред: проклятие, видны тени -> декурс, тени убивать; телепорт в яму -> убить скелетов и выбраться."
L["Taktik: Fernkampf zerstört sofort alle Totems, Banner/Entflucher fest einteilen. Spieler in der Grube kämpfen sich frei."] = "Тактика: РДД сразу уничтожают все тотемы, диспелеров/декурсеров распределить заранее. Игроки в яме пробиваются наружу."
L["JIN'DO: Totems sofort zerstören! Verhexung bannen!"] = "ДЖИН'ДО: Тотемы сразу уничтожать! Сглаз диспелить!"
L["Wahnvorstellungen entfluchen, Schatten töten."] = "Бред декурсить, тени убивать."
L["Hakkar der Seelenschinder + Söhne des Hakkar"] = "Хаккар Свежеватель Душ + сыны Хаккара"
L["- Blutsauger: regelmäßig Lebensentzug auf den Raid -> vorher Gift (Giftiges Blut) von Söhnen des Hakkar holen, dann schadet er sich selbst."] = "- Кровопийца: регулярно вытягивает жизнь у рейда -> заранее взять яд (Ядовитая кровь) от сынов Хаккара, тогда он ранит сам себя."
L["- Verderbtes Blut: springt zwischen Spielern -> verteilt stehen."] = "- Порченая кровь: прыгает между игроками -> стоять рассредоточенно."
L["- Wahnsinn verursachen: Gedankenkontrolle des Tanks -> Zweittank übernimmt."] = "- Вызов безумия: контроль разума над танком -> второй танк забирает."
L["- Aspekte: lebende Hohepriester geben Hakkar zusätzliche Fähigkeiten -> vorher alle Priester töten."] = "- Аспекты: живые верховные жрецы дают Хаккару дополнительные способности -> заранее убить всех жрецов."
L["Taktik: Alle Priester vor Hakkar töten. Vor jedem Blutsauger Söhne töten, damit der Raid vergiftet ist, ansonsten verteilt stehen."] = "Тактика: Всех жрецов убить до Хаккара. Перед каждым Кровопийцей убивать сынов, чтобы рейд был отравлен, в остальное время стоять рассредоточенно."
L["HAKKAR: Vor Blutsauger ins Gift von Sohn des Hakkar!"] = "ХАККАР: Перед Кровопийцей в яд сына Хаккара!"
L["Verteilt stehen, Zweittank bei Gedankenkontrolle bereit."] = "Стоять рассредоточенно, второй танк готов к контролю разума."
L["Der Schwarze Tempel"] = "Черный храм"
L["Oberster Kriegsfürst Naj'entus"] = "Верховный полководец Надж'ентус"
L["- Nadelstachel: Schaden auf zufällige Spieler und Umstehende -> Fernkampf und Heiler verteilt stehen."] = "- Игольчатый шип: урон по случайным игрокам и стоящим рядом -> РДД и хилы стоят рассредоточенно."
L["- Aufspießender Stachel: Spieler wird aufgespießt und erleidet Schaden -> ein anderer Spieler zieht den Stachel per Klick heraus und behält ihn."] = "- Прокалывающий шип: игрока протыкает, он получает урон -> другой игрок кликом вытаскивает шип и оставляет у себя."
L["- Gezeitenschild: Boss wird unverwundbar -> mit dem gesammelten Stachel auf den Boss werfen, um den Schild zu brechen."] = "- Приливный щит: босс становится неуязвимым -> бросить собранный шип в босса, чтобы сломать щит."
L["- Gezeitenschlag beim Brechen des Schilds: Schaden am ganzen Raid -> Raid vorher voll heilen."] = "- Приливный взрыв при разрушении щита: урон по всему рейду -> заранее отхилить рейд в фулл."
L["- Hartes Enrage nach ca. 8 Min. -> konstanter Schaden nötig."] = "- Жесткий энрейдж через ок. 8 мин. -> нужен стабильный урон."
L["Taktik: Boss in der Mitte tanken, alle anderen verteilt; feste Spieler zum Ziehen der Stacheln und zum Brechen des Schilds einteilen."] = "Тактика: Босса танковать в центре, все остальные рассредоточены; закрепить игроков, которые вытаскивают шипы и ломают щит."
L["NAJ'ENTUS: Verteilt stehen! Stacheln sofort ziehen und für den Schild aufheben!"] = "НАДЖ'ЕНТУС: Стоять рассредоточенно! Шипы вытаскивать сразу и беречь для щита!"
L["Schild brechen nur mit vollem Leben im Raid."] = "Ломать щит только при фулл ХП у рейда."
L["Supremus"] = "Супремус"
L["- Hasserfüllter Stoß (Tankphase): trifft den Nahkämpfer mit der höchsten Bedrohung neben dem Haupttank -> 2-3 Tanks/Spieler mit viel Leben im Nahkampf, Bedrohung aufbauen."] = "- Удар ненависти (фаза танка): бьет мили с наибольшей угрозой помимо мейн-танка -> 2-3 танка/игрока с большим ХП в мили, набирать угрозу."
L["- Geschmolzene Flammen/Feuerspur am Boden -> sofort aus dem Feuer gehen."] = "- Расплавленное пламя/огненный след на полу -> сразу выходить из огня."
L["- Vulkanausbrüche: Geysire auf dem Boden -> umgehen."] = "- Извержения вулканов: гейзеры на полу -> обходить."
L["- Jagdphase (wechselt jede Minute): Supremus fixiert einen zufälligen Spieler und wird schneller -> Ziel läuft weg, Raid weicht aus."] = "- Фаза охоты (меняется каждую минуту): Супремус фиксируется на случайном игроке и ускоряется -> цель убегает, рейд уворачивается."
L["- Hartes Enrage nach 15 Min."] = "- Жесткий энрейдж через 15 мин."
L["Taktik: In der Tankphase Haupttank plus Hasserfüllter-Stoß-Abfänger heilen; in der Jagdphase laufen, Feuer meiden und weiter Schaden machen."] = "Тактика: В фазе танка хилить мейн-танка и принимающих Удар ненависти; в фазе охоты бегать, обходить огонь и продолжать бить."
L["SUPREMUS: Jagdphase - Ziel rennt! Aus Feuer und Vulkanen raus!"] = "СУПРЕМУС: Фаза охоты - цель бежит! Выйти из огня и вулканов!"
L["Tankphase: Stoß-Abfänger im Nahkampf voll heilen."] = "Фаза танка: принимающих удар в мили отхиливать в фулл."
L["Akamas Schemen"] = "Тень Акамы"
L["Akamas Schemen + Kanalisierer und Adds der Aschenzungen"] = "Тень Акамы + чаротворцы и адды Пеплоустов"
L["- Kanalisierer der Aschenzungen: 6 Adds halten den Schemen gebannt -> alle Kanalisierer töten, dann wird der Schemen angreifbar."] = "- Чаротворцы из клана Пеплоустов: 6 аддов удерживают Тень -> убить всех чаротворцев, тогда Тень становится уязвимой."
L["- Zauberer der Aschenzungen: kommen aus den Seitentüren und kanalisieren ebenfalls -> sofort töten."] = "- Колдуны из клана Пеплоустов: выходят из боковых дверей и тоже поддерживают канал -> убивать сразу."
L["- Weitere Adds (Verteidiger, Elementaristen, Geistbinder) aus den Seitentüren -> an den Türen abfangen und tanken."] = "- Другие адды (защитники, элементалисты, духовные узы) из боковых дверей -> перехватывать и танковать у дверей."
L["- Akama darf nicht sterben -> Schemen nach dem Freikommen schnell übernehmen und töten."] = "- Акама не должен умереть -> после освобождения Тень быстро забрать и убить."
L["Taktik: Zwei Gruppen an den Seitentüren fangen Adds ab, der Rest tötet die Kanalisierer; danach alles auf den Schemen, Akama hilft mit."] = "Тактика: Две группы у боковых дверей перехватывают аддов, остальные убивают чаротворцев; затем все в Тень, Акама помогает."
L["SCHEMEN: Kanalisierer und Zauberer zuerst! Türgruppen Adds abfangen!"] = "ТЕНЬ: Сначала чаротворцы и колдуны! Группы у дверей перехватывают аддов!"
L["Akama am Leben halten. Danach alles auf den Schemen."] = "Держать Акаму в живых. Потом все в Тень."
L["Teron Blutschatten"] = "Терон Кровожад"
L["Teron Blutschatten + Schattenhafte Konstrukte"] = "Терон Кровожад + призрачные конструкты"
L["- Schatten des Todes: Spieler stirbt nach kurzer Zeit und wird zum Geist -> als Geist mit den Geisterfähigkeiten die Konstrukte verlangsamen und töten."] = "- Тень смерти: игрок через короткое время умирает и становится духом -> духом замедлять и убивать конструктов способностями духа."
L["- Schattenhafte Konstrukte: greifen den Raid an -> von Geistern binden, verlangsamen und töten lassen, nicht zum Raid laufen lassen."] = "- Призрачные конструкты: атакуют рейд -> духи связывают, замедляют и убивают их, не пускать к рейду."
L["- Verbrennen: Magie-Debuff mit Feuerschaden -> bannen."] = "- Испепеление: магический дебафф с уроном от огня -> диспелить."
L["- Zermalmende Schatten: Schattenschaden auf mehrere Spieler -> Heiler reagieren schnell."] = "- Сокрушающие тени: урон от темной магии по нескольким игрокам -> хилы быстро реагируют."
L["- Schicksalsblüten: schießen Schattenblitze -> Schaden heilen."] = "- Цветы рока: пускают стрелы Тьмы -> отхиливать урон."
L["Taktik: Teron am Rand tanken; Spieler mit Schatten des Todes stellen sich vor dem Tod an die Konstrukt-Position und erledigen die Adds als Geist."] = "Тактика: Терона танковать у края; игроки с Тенью смерти перед смертью встают на позицию конструктов и добивают аддов духом."
L["TERON: Schatten des Todes - zu den Konstrukten gehen! Als Geist Adds töten!"] = "ТЕРОН: Тень смерти - идти к конструктам! Духом убивать аддов!"
L["Verbrennen bannen. Konstrukte vom Raid fernhalten."] = "Испепеление диспелить. Конструктов держать подальше от рейда."
L["Gurtogg Siedeblut"] = "Гуртогг Кипящая Кровь"
L["- Blutsieden: trifft die 5 entferntesten Spieler, Debuff stapelt -> 3 Fernkampfgruppen im Wechsel hinten stehen."] = "- Кипение крови: бьет 5 самых дальних игроков, дебафф стакается -> 3 группы РДД по очереди стоят сзади."
L["- Teufelssäure / Säurewunde: stapelnde Rüstungsreduktion am Tank -> Tankwechsel."] = "- Скверная кислота / Кислотная рана: стакающееся снижение брони на танке -> смена танков."
L["- Rauswerfen: Rückstoß mit Bedrohungsverlust -> zweiter Tank sofort übernehmen."] = "- Вышвыривание: отбрасывание с потерей угрозы -> второй танк сразу забирает."
L["- Teufelswut (Phase 2): fixiert einen zufälligen Spieler, der viel Leben und Rüstung bekommt -> diesen Spieler stark heilen, Raid weiter auf Boss."] = "- Ярость Скверны (фаза 2): фиксируется на случайном игроке, который получает много здоровья и брони -> этого игрока сильно хилить, рейд дальше в босса."
L["- Teufelsgeysir: Schaden um den Fixierten -> nicht zu nah stehen."] = "- Гейзер Скверны: урон вокруг цели фиксации -> не стоять слишком близко."
L["Taktik: Zwei Tanks wechseln wegen der Säure, Fernkampf in Gruppen für Blutsieden rotieren; in Teufelswut den Fixierten hochheilen."] = "Тактика: Два танка меняются из-за кислоты, РДД ротируются группами под Кипение крови; в Ярости Скверны отхиливать цель фиксации."
L["GURTOGG: Blutsieden-Gruppen rotieren! Tankwechsel bei Säurestapeln!"] = "ГУРТОГГ: Группы под Кипение крови ротируются! Смена танков на стаках кислоты!"
L["Teufelswut: Fixiertes Ziel voll heilen, nicht wegrennen."] = "Ярость Скверны: цель фиксации хилить в фулл, не убегать."
L["Reliquiar der Seelen"] = "Реликварий Душ"
L["Reliquiar der Seelen (Essenz des Leidens, der Begierde, des Zorns)"] = "Реликварий Душ (Сущность Страдания, Желания, Гнева)"
L["- Essenz des Leidens: Aura senkt Heilung massiv, fixiert den nächsten Spieler -> Nahkämpfer mit hohem Leben vorne, schnell töten."] = "- Сущность Страдания: аура сильно снижает исцеление, фиксируется на ближайшем игроке -> мили с большим ХП впереди, быстро убить."
L["- Gefangene Seelen zwischen den Phasen: Adds -> schnell töten."] = "- Плененные души между фазами: адды -> быстро убивать."
L["- Essenz der Begierde: Aura reflektiert Schaden auf den Angreifer und senkt Mana -> Schaden dosieren; Runenschild bannen, Abstumpfen und Geistschock unterbrechen."] = "- Сущность Желания: аура отражает урон на атакующего и снижает ману -> дозировать урон; Руническую защиту диспелить, Притупление и Удар духа сбивать."
L["- Essenz des Zorns: Bosheit auf mehrere Spieler -> heilen; Seelenschrei entzieht Mana -> Mana sparen."] = "- Сущность Гнева: Злоба на нескольких игроках -> хилить; Крик души вытягивает ману -> экономить ману."
L["- Zorn steigert sich bei Tankwechsel -> nur einen Tank verwenden."] = "- Гнев усиливается при смене танка -> использовать только одного танка."
L["Taktik: Drei Phasen nacheinander: Leiden schnell töten, Begierde kontrolliert mit Unterbrechern, Zorn mit vollem Raid-Schaden."] = "Тактика: Три фазы подряд: Страдание быстро убить, Желание под контролем кикеров, Гнев полным уроном рейда."
L["RELIQUIAR: Phase 2 Reflexion beachten! Unterbrecher bereit!"] = "РЕЛИКВАРИЙ: Фаза 2 следить за отражением! Кикеры наготове!"
L["Phase 1: Wenig Heilung, schnell töten. Adds zwischen den Phasen weg."] = "Фаза 1: мало хила, быстро убить. Аддов между фазами убрать."
L["Mutter Shahraz"] = "Матушка Шахраз"
L["- Unheilvoller, Übler, Gemeiner, Sündiger Strahl: Schattenschaden und Debuffs -> Raid mit Schattenwiderstand."] = "- Зловещий, Злобный, Порочный, Греховный луч: урон от темной магии и дебаффы -> рейд в сопротивлении темной магии."
L["- Tödliche Anziehung: 3 Spieler werden zusammen teleportiert und schaden sich gegenseitig -> sofort auseinander laufen."] = "- Роковое влечение: 3 игрока телепортируются вместе и наносят урон друг другу -> сразу разбегаться."
L["- Säbelpeitsche: Schaden wird auf Umstehende aufgeteilt -> Nahkampf und Tanks zusammen am Boss."] = "- Сабельный удар: урон делится между стоящими рядом -> мили и танки вместе у босса."
L["- Prismatische Aura: wechselnde Widerstände -> keine Gegenmaßnahme nötig."] = "- Призматическая аура: меняющиеся сопротивления -> контрмеры не нужны."
L["- Raserei bei ca. 10% -> Cooldowns aufheben."] = "- Исступление на ок. 10% -> КД приберечь."
L["Taktik: Boss mittig tanken, Nahkampf zum Teilen der Säbelpeitsche stapeln, Raid mit Schattenwiderstand-Ausrüstung verteilt."] = "Тактика: Босса танковать в центре, мили стакаются для разделения Сабельного удара, рейд в экипировке на сопротивление темной магии рассредоточен."
L["SHAHRAZ: Bei Anziehung SOFORT auseinander laufen!"] = "ШАХРАЗ: При Влечении СРАЗУ разбегаться!"
L["Nahkampf am Boss für Säbelpeitsche. Schattenwiderstand an."] = "Мили у босса под Сабельный удар. Сопротивление темной магии надеть."
L["Rat der Illidari"] = "Совет Иллидари"
L["Rat der Illidari (Gathios, Malande, Zerevor, Veras)"] = "Совет Иллидари (Гатиос, Маланда, Зеревор, Верас)"
L["- Gemeinsamer Lebenspool: alle vier teilen sich das Leben -> Schaden verteilen ist egal, alle sterben zusammen."] = "- Общий запас здоровья: у всех четырех одно здоровье на всех -> распределение урона неважно, умирают все вместе."
L["- Gathios der Zerschmetterer: Weihe und Segen/Auren -> Segen und Schutz stehlen/reinigen, von Weihe weg tanken."] = "- Гатиос Раскольщик: Освящение и благословения/ауры -> красть/снимать благословения и защиту, танковать вне Освящения."
L["- Lady Malande: Gebet der Heilung, Göttlicher Zorn, Reflexionsschild -> Heilzauber unterbrechen, Schild beachten."] = "- Леди Маланда: Молитва исцеления, Божественный гнев, отражающий щит -> сбивать хил, следить за щитом."
L["- Hochnethermant Zerevor: Arkane Explosion, Blizzard, Flammenstoß -> auf Distanz halten (Magier/Hexer-Tank), aus Flächenschaden raus."] = "- Верховный пустомант Зеревор: Чародейский взрыв, Снежная буря, Огненный столб -> держать на дистанции (танк маг/лок), выходить из АоЕ."
L["- Veras Dunkelschatten: Verschwinden und tödliches Gift -> Gift entfernen, Ziel heilen."] = "- Верас Темная Тень: Исчезновение и смертельный яд -> снимать яд, хилить цель."
L["Taktik: Jedes Ratsmitglied eigener Tank an eigener Position, Zerevor auf Distanz; Malandes Heilungen konsequent unterbrechen."] = "Тактика: У каждого члена совета свой танк на своей позиции, Зеревор на дистанции; хил Маланды сбивать без пропусков."
L["RAT: Malande unterbrechen! Zerevor-AoE meiden!"] = "СОВЕТ: Сбивать Маланду! Обходить АоЕ Зеревора!"
L["Gift von Veras entfernen. Segen von Gathios stehlen/reinigen."] = "Снимать яд Вераса. Благословения Гатиоса красть/снимать."
L["Rat (Tanks)"] = "Совет (танки)"
L["Ein Symbol pro Ratsmitglied für die Tankzuteilung: Totenkopf Gathios, Kreuz Malande, Viereck Zerevor, Mond Veras."] = "По метке на каждого члена совета для распределения танков: Череп Гатиос, Крест Маланда, Квадрат Зеревор, Луна Верас."
L["Illidan Sturmgrimm"] = "Иллидан Ярость Бури"
L["Illidan Sturmgrimm + Flammen von Azzinoth und Schattendämonen"] = "Иллидан Ярость Бури + Пламя Аззинота и демоны Тьмы"
L["- Scheren: senkt das max. Leben des Tanks stark -> Tank nutzt Verteidigungs-CDs, Heiler bereit."] = "- Рассечение: сильно снижает максимальное здоровье танка -> танк жмет защитные КД, хилы наготове."
L["- Parasitärer Schattenteufel: Spieler bekommt Debuff, Adds schlüpfen -> Adds sofort töten."] = "- Паразитический теневой демон: игрок получает дебафф, вылупляются адды -> аддов сразу убивать."
L["- Phase 2 (Flammen von Azzinoth): zwei Elementare -> mit Feuerwiderstand-Tanks getrennt tanken, nicht zu nah an die Gleven ziehen."] = "- Фаза 2 (Пламя Аззинота): два элементаля -> танковать раздельно танками в сопротивлении огню, не подводить близко к глефам."
L["- Augenstrahl / Feuerbälle: Linie aus Feuer am Boden -> ausweichen."] = "- Луч глаз / огненные шары: линия огня на полу -> уворачиваться."
L["- Dämonenform: Schattendämonen fixieren Spieler -> sofort töten; Fernkampf verteilt (Flammenexplosion)."] = "- Облик демона: демоны Тьмы фиксируются на игроках -> сразу убивать; РДД рассредоточены (Огненный взрыв)."
L["- Maiev (ab ca. 30%): legt Käfigfallen -> Illidan in die Falle ziehen."] = "- Майев (с ок. 30%): ставит ловушки-клетки -> тянуть Иллидана в ловушку."
L["Taktik: Phasen 1-5: Tankphase, Flammenphase mit Feuerwiderstands-Tanks, wieder Tank, Dämonenform mit Hexer-Tank, Maiev-Phase mit Fallen."] = "Тактика: Фазы 1-5: фаза танка, фаза пламени с танками в сопротивлении огню, снова танк, облик демона с лок-танком, фаза Майев с ловушками."
L["ILLIDAN: Scheren - Tank-CDs! Schattenteufel und Dämonen sofort töten!"] = "ИЛЛИДАН: Рассечение - КД танка! Демонов и паразитов сразу убивать!"
L["Flammen getrennt tanken, Augenstrahl ausweichen. Maiev: Falle nutzen."] = "Пламя танковать раздельно, уворачиваться от Луча глаз. Майев: использовать ловушку."
L["Illidan"] = "Иллидан"
L["Totenkopf und Kreuz auf die beiden Flammen von Azzinoth (je ein Tank)."] = "Череп и Крест на оба Пламени Аззинота (по танку на каждое)."
L["Gruuls Unterschlupf"] = "Логово Груула"
L["Hochkönig Maulgar"] = "Король Молгар"
L["Hochkönig Maulgar + Krosh, Olm, Kiggler, Blindauge"] = "Король Молгар + Крош, Олм, Киглер, Слепоглаз"
L["- Blindauge der Seher (Priester): Heilung und Schild -> unterbrechen, als Erstes töten."] = "- Слепоглаз Провидец (жрец): исцеление и щит -> сбивать, убить первым."
L["- Olm der Beschwörer: beschwört Teufelsjäger -> Hexer tanken/binden, als Zweites töten."] = "- Олм Призыватель: призывает охотников Скверны -> локи танкуют/контролят, убить вторым."
L["- Kiggler der Verrückte: Verwandlung und Rückstoß -> auf Distanz von Jägern/Druiden tanken."] = "- Киглер Безумный: превращение и отбрасывание -> танковать на дистанции охотниками/друидами."
L["- Krosh Feuerhand: starke Feuerzauber -> Magier tankt mit Zauberraub auf Kroshs Zauberschild."] = "- Крош Огненная Рука: сильные огненные заклинания -> танкует маг Похищением заклинания щита Кроша."
L["- Maulgar: Wirbelwind und Ansturm, ab 50% Raserei -> Nahkampf bei Wirbelwind raus."] = "- Молгар: Вихрь и рывок, с 50% Исступление -> мили выходят при Вихре."
L["Taktik: Jedes Add eigener Tank an eigener Stelle; Reihenfolge Blindauge, Olm, Kiggler, Krosh, zuletzt Maulgar."] = "Тактика: У каждого адда свой танк на своем месте; порядок Слепоглаз, Олм, Киглер, Крош, последним Молгар."
L["MAULGAR: Blindauge zuerst und unterbrechen! Dann Olm, Kiggler, Krosh!"] = "МОЛГАР: Слепоглаз первым и сбивать! Потом Олм, Киглер, Крош!"
L["Krosh nur der Magier-Tank. Wirbelwind: Nahkampf raus."] = "Крош только на маге-танке. Вихрь: мили наружу."
L["Maulgar"] = "Молгар"
L["Totenkopf Blindauge, Kreuz Olm, Viereck Kiggler, Mond Krosh, Dreieck Maulgar."] = "Череп Слепоглаз, Крест Олм, Квадрат Киглер, Луна Крош, Треугольник Молгар."
L["Gruul der Drachenschlächter"] = "Груул Драконобой"
L["- Wachstum: Gruul wird alle 30 Sek. größer und stärker -> weiches Enrage, schnell töten."] = "- Рост: Груул каждые 30 сек. становится больше и сильнее -> мягкий энрейдж, быстро убить."
L["- Verletzender Schlag: trifft den Nahkämpfer mit zweithöchster Bedrohung -> zweiter Tank/Plattenträger direkt hinter dem Haupttank."] = "- Обидный удар: бьет мили со второй по величине угрозой -> второй танк/латник прямо за мейн-танком."
L["- Bodenschlag + Zerschmettern: Raid wird herangezogen und versteinert, danach Schaden je nach Nähe -> sofort auseinanderlaufen."] = "- Дрожь земли + Раскол: рейд притягивает и обращает в камень, затем урон в зависимости от близости -> сразу разбегаться."
L["- Höhleneinsturz: Steinschlag am Boden -> sofort raus."] = "- Обвал пещеры: камнепад на полу -> сразу выйти."
L["- Widerhall: Stille in der Nähe -> Heiler auf Abstand."] = "- Отголосок: немота рядом -> хилы на дистанции."
L["Taktik: Fernkampf und Heiler verteilt mit genug Abstand, nach jedem Bodenschlag sofort auseinander; volle Schadensphase gegen das Wachstum."] = "Тактика: РДД и хилы рассредоточены с запасом дистанции, после каждой Дрожи земли сразу разбегаться; полный урон против Роста."
L["GRUUL: Nach Bodenschlag SOFORT verteilen! Raus aus dem Einsturz!"] = "ГРУУЛ: После Дрожи земли СРАЗУ рассредоточиться! Выйти из обвала!"
L["Zweiter Tank für Verletzenden Schlag bereit. Volle DPS gegen Wachstum."] = "Второй танк готов к Обидному удару. Полный ДПС против Роста."
L["Hyjalgipfel"] = "Битва за гору Хиджал"
L["Furor Winterfrost"] = "Лютый Хлад"
L["Furor Winterfrost (nach 8 Trash-Wellen)"] = "Лютый Хлад (после 8 волн трэша)"
L["- Tod und Verfall: Schaden in einem Bereich -> sofort herausgehen."] = "- Смерть и разложение: урон в области -> сразу выходить."
L["- Eisblitz: Frostschaden und Betäubung auf zufälligen Spieler -> heilen."] = "- Ледяная стрела: урон от магии льда и оглушение на случайном игроке -> хилить."
L["- Frostnova: friert Spieler in der Nähe fest -> nicht zu viele Spieler eng stehen."] = "- Кольцо льда: замораживает игроков рядом -> не стоять толпой."
L["- Frostrüstung: verlangsamt Angreifer -> Nahkampf kurz aushalten."] = "- Ледяной доспех: замедляет атакующих -> мили потерпеть."
L["Taktik: Vorher die Trash-Wellen im Lager abfangen; Boss an Ort und Stelle tanken, Raid aus Tod und Verfall raus."] = "Тактика: Заранее отбить волны трэша в лагере; босса танковать на месте, рейд выходит из Смерти и разложения."
L["FUROR: Raus aus Tod und Verfall!"] = "ЛЮТЫЙ ХЛАД: Выйти из Смерти и разложения!"
L["Eisblitz-Ziele heilen. Trash-Wellen vorher sauber abfangen."] = "Цели Ледяной стрелы хилить. Волны трэша заранее чисто отбить."
L["Anetheron"] = "Анетерон"
L["Anetheron + Höllenbestien"] = "Анетерон + инферналы"
L["- Aasschwarm: Schaden im Kegel und Heilung reduziert -> Boss vom Raid weggedreht tanken."] = "- Рой стервятников: урон конусом и сниженное исцеление -> босса танковать отвернутым от рейда."
L["- Schlaf: mehrere Spieler schlafen -> Magie bannen."] = "- Сон: несколько игроков засыпают -> диспелить магию."
L["- Vampiraura: Boss heilt sich bei Treffern -> Tank gut ausgerüstet halten."] = "- Вампирская аура: босс лечится от ударов -> танк хорошо одет."
L["- Inferno: Höllenbestie auf zufälligem Spieler -> von Offtank/Hexer wegtanken, Raid raus aus dem Feuer."] = "- Инферно: инфернал на случайного игрока -> офф-танк/лок уводит, рейд выходит из огня."
L["Taktik: Anetheron vom Raid weg drehen, Höllenbestien von einem Offtank aufnehmen und abseits halten."] = "Тактика: Анетерона отвернуть от рейда, инферналов забирает офф-танк и держит в стороне."
L["ANETHERON: Höllenbestien sofort abholen! Schlaf bannen!"] = "АНЕТЕРОН: Инферналов сразу забирать! Сон диспелить!"
L["Nicht vor den Boss stellen (Aasschwarm)."] = "Не стоять перед боссом (Рой стервятников)."
L["Kaz'rogal"] = "Каз'рогал"
L["- Mal von Kaz'rogal: entzieht allen Manaklassen Mana, bei 0 Mana Explosion mit hohem Schaden -> Mana tränken, bei leerem Mana raus aus dem Raid."] = "- Метка Каз'рогала: вытягивает ману у всех манаклассов, при 0 маны взрыв с большим уроном -> пить зелья маны, при пустой мане выбежать из рейда."
L["- Intervall des Mals wird immer kürzer -> schnell töten."] = "- Интервал метки все короче -> быстро убить."
L["- Kriegsdonner: Betäubung im Nahkampf -> Nahkampf kurz raus wenn möglich."] = "- Громовая поступь: оглушение в мили -> мили по возможности ненадолго выходят."
L["- Spalten: Frontalschaden -> Boss weg vom Raid drehen."] = "- Рассекающий удар: фронтальный урон -> развернуть босса от рейда."
L["Taktik: Boss weg vom Raid tanken; Manaklassen achten auf ihr Mana und laufen bei fast leerem Mana vom Raid weg."] = "Тактика: Босса танковать от рейда; манаклассы следят за маной и при почти пустой мане отбегают от рейда."
L["KAZ'ROGAL: Mana im Blick! Fast leer = weg vom Raid laufen!"] = "КАЗ'РОГАЛ: Следить за маной! Почти пусто = бежать от рейда!"
L["Mana-Tränke nutzen. Boss weg vom Raid gedreht."] = "Пить зелья маны. Босс развернут от рейда."
L["Azgalor"] = "Азгалор"
L["Azgalor + Geringe Verdammniswachen"] = "Азгалор + малые стражи ужаса"
L["- Feuerregen: Flächenschaden -> sofort raus."] = "- Огненный ливень: АоЕ урон -> сразу выйти."
L["- Verdammnis: Spieler stirbt nach Ablauf und erzeugt eine Verdammniswache -> zum Offtank laufen, Wache abseits tanken/töten."] = "- Рок: игрок по окончании умирает и создает стража ужаса -> бежать к офф-танку, стража танковать/убивать в стороне."
L["- Heulen von Azgalor: Stille im Umkreis -> Heiler auf Abstand."] = "- Вой Азгалора: немота вокруг -> хилы на дистанции."
L["Taktik: Boss weg vom Raid tanken, Verdammniswachen von Offtank abseits halten und töten; nie im Feuer stehen."] = "Тактика: Босса танковать от рейда, стражей ужаса офф-танк держит в стороне и убивает; никогда не стоять в огне."
L["AZGALOR: Raus aus dem Feuerregen! Verdammnis-Ziele zum Offtank!"] = "АЗГАЛОР: Выйти из Огненного ливня! Цели Рока к офф-танку!"
L["Verdammniswachen abseits tanken. Heiler auf Abstand (Stille)."] = "Стражей ужаса танковать в стороне. Хилы на дистанции (немота)."
L["Archimonde"] = "Архимонд"
L["- Luftstoß: schleudert Spieler hoch -> Tränen der Göttin nutzen, um nicht am Sturz zu sterben."] = "- Порыв ветра: подбрасывает игроков -> использовать Слезы Богини, чтобы не разбиться при падении."
L["- Verdammnisfeuer: Feuerspur folgt Spielern -> wegziehen, nicht durch das Feuer laufen."] = "- Огонь Рока: огненный след следует за игроками -> уводить, не бегать через огонь."
L["- Furcht: ganzer Raid -> Furchtschutz auf Tank, Totem des Erdstoßes."] = "- Страх: весь рейд -> Защита от страха на танка, Тотем трепета."
L["- Griff der Legion: Fluch -> entfluchen."] = "- Хватка Легиона: проклятие -> декурс."
L["- Seelenladung bei Spielertoden -> niemand sterben lassen."] = "- Заряд души при смертях игроков -> никому не давать умереть."
L["Taktik: Raid locker verteilt um den Boss, jeder hat Tränen der Göttin in der Leiste; Feuer sofort wegziehen."] = "Тактика: Рейд свободно рассредоточен вокруг босса, у каждого Слезы Богини на панели; огонь сразу уводить."
L["ARCHIMONDE: Tränen der Göttin bei Luftstoß nutzen!"] = "АРХИМОНД: При Порыве ветра жать Слезы Богини!"
L["Verdammnisfeuer wegziehen. Flüche entfernen, Furchtschutz auf Tank."] = "Огонь Рока уводить. Проклятия снимать, Защита от страха на танка."
L["Karazhan"] = "Каражан"
L["Attumen der Jäger"] = "Ловчий Аттумен"
L["Attumen der Jäger + Mittnacht"] = "Ловчий Аттумен + Полночь"
L["- Mittnacht: zuerst Pferd tanken, Attumen erscheint dazu -> zweiter Tank übernimmt Attumen."] = "- Полночь: сначала танкуем коня, к нему выходит Аттумен -> второй танк забирает Аттумена."
L["- Schattenspalten: Frontalschaden -> nur Tank vorne."] = "- Рассечение тени: фронтальный урон -> спереди только танк."
L["- Unkörperliche Präsenz: Fluch -> entfluchen."] = "- Бестелесное присутствие: проклятие -> декурс."
L["- Beritten (ab 25%): Ansturm auf entfernte Spieler -> Fernkampf verteilt in mittlerer Distanz."] = "- Верхом (с 25%): рывок на дальних игроков -> РДД рассредоточены на средней дистанции."
L["Taktik: Zwei Tanks: einer auf Mittnacht, einer auf Attumen; nach dem Aufsitzen Ansturm-Schaden heilen und durchziehen."] = "Тактика: Два танка: один на Полночи, один на Аттумене; после посадки на коня отхиливать урон от рывков и дожимать."
L["ATTUMEN: Nicht vor den Boss! Flüche entfernen!"] = "АТТУМЕН: Не стоять перед боссом! Проклятия снимать!"
L["Ab Aufsitzen: Fernkampf verteilt für Ansturm."] = "После посадки: РДД рассредоточены от рывка."
L["Moroes"] = "Мороуз"
L["Moroes + 4 Gäste"] = "Мороуз + 4 гостя"
L["- Solarplexus: betäubt den Tank -> zweiter Tank mit hoher Bedrohung übernimmt."] = "- Солнечное сплетение: оглушает танка -> забирает второй танк с высокой угрозой."
L["- Verschwinden + Erdrosseln: stapelnde Blutung auf zufälligem Spieler -> heilen (Eisblock/Gottesschild entfernen)."] = "- Исчезновение + Гаррота: стакающееся кровотечение на случайном игроке -> хилить (снимается Ледяной глыбой/Божественным щитом)."
L["- Gäste: Heiler-Adds (Priester/Paladine) zuerst töten, gefährliche Adds kontrollieren."] = "- Гости: адды-хилы (жрецы/паладины) убивать первыми, опасных аддов контролить."
L["- Raserei bei 30% -> Gäste vorher töten oder sicher kontrollieren."] = "- Исступление на 30% -> гостей убить раньше или надежно контролить."
L["Taktik: CC auf zwei Gäste (Kopfnuss, Fesseln, Verwandlung), zwei Gäste nacheinander töten, dann Moroes; Erdrosseln heilen."] = "Тактика: КК на двух гостей (Ошеломление, Сковывание, Превращение), двух гостей убить по очереди, затем Мороуз; Гарроту хилить."
L["MOROES: Heiler-Gäste zuerst! CC halten!"] = "МОРОУЗ: Гости-хилы первыми! Держать КК!"
L["Solarplexus: Zweiter Tank übernimmt. Erdrosseln-Ziele heilen."] = "Солнечное сплетение: второй танк забирает. Цели Гарроты хилить."
L["Totenkopf und Kreuz töten, Viereck und Mond CC, Stern auf Moroes."] = "Череп и Крест убивать, Квадрат и Луна КК, Звезда на Мороуза."
L["Tugendhafte Maid"] = "Благочестивая дева"
L["- Buße: lähmt alle Spieler, löst sich bei Schaden -> vorher alle hochheilen."] = "- Покаяние: парализует всех игроков, снимается уроном -> заранее отхилить всех."
L["- Heiliges Feuer: Magie-DoT -> bannen."] = "- Священный огонь: магический ДоТ -> диспелить."
L["- Heiliger Zorn: springt zwischen Spielern -> verteilt stehen."] = "- Гнев небес: прыгает между игроками -> стоять рассредоточенно."
L["- Geheiligter Boden: Stille um die Maid -> Heiler und Fernkampf außerhalb."] = "- Освященная земля: немота вокруг девы -> хилы и РДД снаружи."
L["Taktik: Fernkampf und Heiler verteilt am Rand des Raums außerhalb des geheiligten Bodens, Nahkampf am Boss."] = "Тактика: РДД и хилы рассредоточены по краю зала вне Освященной земли, мили у босса."
L["MAID: Verteilt am Rand! Vor Buße hochheilen!"] = "ДЕВА: Рассредоточиться по краю! Перед Покаянием отхилить!"
L["Heiliges Feuer bannen. Heiler nicht in den Geheiligten Boden."] = "Священный огонь диспелить. Хилам не заходить в Освященную землю."
L["Der große böse Wolf"] = "Злой и страшный серый волк"
L["Oper: Der große böse Wolf"] = "Опера: Злой и страшный серый волк"
L["- Rotkäppchen: Spieler wird verwandelt, verliert Rüstung und Widerstände -> im Kreis vom Wolf weglaufen."] = "- Красная Шапочка: игрок превращается, теряет броню и сопротивления -> бежать по кругу от волка."
L["- Schreckliches Heulen: Furcht -> Furchtschutz/Erdstoßtotem."] = "- Ужасающий вой: страх -> Защита от страха/Тотем трепета."
L["- Weiter Prankenhieb: Schaden vorne -> nur Tank vor dem Wolf."] = "- Широкий взмах: урон спереди -> перед волком только танк."
L["Taktik: Wolf mittig tanken; Rotkäppchen läuft im Kreis außen herum, Raid bleibt ruhig und macht weiter Schaden."] = "Тактика: Волка танковать в центре; Красная Шапочка бегает по внешнему кругу, рейд спокойно продолжает бить."
L["WOLF: Rotkäppchen im Kreis laufen!"] = "ВОЛК: Красная Шапочка, бежать по кругу!"
L["Nicht vor den Wolf stellen. Furchtschutz auf den Tank."] = "Не стоять перед волком. Защита от страха на танка."
L["Romulo und Julianne"] = "Ромуло и Джулианна"
L["Oper: Romulo und Julianne"] = "Опера: Ромуло и Джулианна"
L["- Julianne: Ewige Zuneigung (Heilung) -> unterbrechen; Hingabe-Buff -> reinigen/stehlen."] = "- Джулианна: Вечная привязанность (исцеление) -> сбивать; бафф Преданность -> снимать/красть."
L["- Romulo: Wagemut-Buff -> reinigen/stehlen; Gift -> entfernen."] = "- Ромуло: бафф Удаль -> снимать/красть; яд -> снимать."
L["- Mächtige Anziehung: Betäubung -> heilen."] = "- Мощное притяжение: оглушение -> хилить."
L["- Phase 3: beide stehen wieder auf und müssen innerhalb von 10 Sek. sterben -> Schaden gleichmäßig verteilen."] = "- Фаза 3: оба встают снова и должны умереть в течение 10 сек. -> урон распределять равномерно."
L["Taktik: Erst Julianne, dann Romulo, in Phase 3 beide getrennt tanken und gleichzeitig runterbringen."] = "Тактика: Сначала Джулианна, затем Ромуло, в фазе 3 обоих танковать раздельно и опускать одновременно."
L["ROMULO & JULIANNE: Heilung unterbrechen! Phase 3 gleichzeitig töten!"] = "РОМУЛО И ДЖУЛИАННА: Сбивать хил! Фаза 3 убить одновременно!"
L["Buffs reinigen/stehlen. Gift entfernen."] = "Баффы снимать/красть. Снимать яд."
L["Totenkopf Julianne, Kreuz Romulo."] = "Череп Джулианна, Крест Ромуло."
L["Der Zauberer von Oz"] = "Волшебник страны Оз"
L["Oper: Der Zauberer von Oz (Dorothee, Tito, Brüller, Strohmann, Blechkopf, Hexe)"] = "Опера: Волшебник страны Оз (Дороти, Тито, Хохотун, Балбес, Медноголовый, Ведьма)"
L["- Dorothee: nicht tankbar, Wasserblitze und Furcht, ruft Tito -> Fernkampf zuerst töten."] = "- Дороти: не танкуется, водяные стрелы и страх, призывает Тито -> РДД убивают первой."
L["- Brüller: Furcht -> schnell töten."] = "- Хохотун: страх -> быстро убить."
L["- Strohmann: anfällig für Feuer -> Feuerzauber betäuben ihn, Magier/Hexer übernehmen."] = "- Балбес: уязвим к огню -> огненные заклинания его оглушают, маги/локи берут на себя."
L["- Blechkopf: wird mit der Zeit rostig/langsam -> tanken oder kiten."] = "- Медноголовый: со временем ржавеет/замедляется -> танковать или кайтить."
L["- Hexe (am Ende): Wirbelstürme und Kettenblitz -> Wirbelstürmen ausweichen."] = "- Ведьма (в конце): смерчи и Цепная молния -> уворачиваться от смерчей."
L["Taktik: Adds zügig nacheinander töten, Strohmann mit Feuer kontrollieren; danach die Hexe, Wirbelstürme meiden."] = "Тактика: Аддов быстро убивать по очереди, Балбеса контролить огнем; затем Ведьма, обходить смерчи."
L["OZ: Dorothee zuerst! Strohmann mit Feuer!"] = "ОЗ: Дороти первой! Балбеса огнем!"
L["Hexe: Wirbelstürmen ausweichen."] = "Ведьма: уворачиваться от смерчей."
L["Oz"] = "Оз"
L["Totenkopf Dorothee, Kreuz Brüller, Viereck Strohmann, Mond Blechkopf."] = "Череп Дороти, Крест Хохотун, Квадрат Балбес, Луна Медноголовый."
L["Der Kurator"] = "Смотритель"
L["Der Kurator + Astrale Blitze"] = "Смотритель + астральные вспышки"
L["- Astrale Blitze: alle 10 Sek. ein Add mit Arkanschaden -> sofort töten (Nahkampf)."] = "- Астральные вспышки: каждые 10 сек. адд с тайным уроном -> сразу убивать (мили)."
L["- Hasserfüllter Blitz: trifft den Spieler mit dem meisten Leben (außer Tank) -> Spieler mit viel Leben voll heilen."] = "- Вспышка ненависти: бьет игрока с наибольшим здоровьем (кроме танка) -> игроков с большим ХП хилить в фулл."
L["- Hervorrufung: bei 0 Mana erleidet der Kurator +200% Schaden -> alles auf den Boss, Cooldowns nutzen."] = "- Прилив сил: при 0 маны Смотритель получает +200% урона -> все в босса, жать КД."
L["- Enrage bei 15%: keine Blitze mehr, Hasserfüllter Blitz öfter -> durchheilen und schnell töten."] = "- Энрейдж на 15%: вспышек больше нет, Вспышка ненависти чаще -> прохиливать и быстро убить."
L["Taktik: Fernkampf am Boss, Nahkampf auf die Blitze; in der Hervorrufung volle Cooldowns."] = "Тактика: РДД на боссе, мили на вспышках; в Приливе сил все КД."
L["KURATOR: Astrale Blitze sofort töten!"] = "СМОТРИТЕЛЬ: Астральные вспышки сразу убивать!"
L["Hervorrufung = alle CDs auf den Boss. Ab 15% durchheilen."] = "Прилив сил = все КД в босса. С 15% прохиливать."
L["Terestian Siechhuf"] = "Терестиан Больное Копыто"
L["Terestian Siechhuf + Kil'rek"] = "Терестиан Больное Копыто + Кил'рек"
L["- Opferung: Spieler in dämonische Ketten gelegt -> Ketten sofort töten."] = "- Жертвоприношение: игрока сковывают демонические цепи -> цепи сразу убивать."
L["- Kil'rek (Wichtel): beim Tod erleidet Terestian mehr Schaden -> Kil'rek töten, dann Boss."] = "- Кил'рек (бес): при его смерти Терестиан получает больше урона -> убить Кил'река, затем босса."
L["- Dämonische Portale: Wichtel strömen -> per AoE töten."] = "- Демонические порталы: лезут бесы -> убивать АоЕ."
L["- Schattenblitz auf den Tank -> heilen."] = "- Стрела Тьмы по танку -> хилить."
L["Taktik: Kil'rek zuerst töten, dann auf Terestian; Ketten haben höchste Priorität, Wichtel per AoE."] = "Тактика: Кил'река убить первым, затем Терестиан; у цепей высший приоритет, бесов АоЕ."
L["TERESTIAN: Ketten sofort töten! Kil'rek zuerst!"] = "ТЕРЕСТИАН: Цепи сразу убивать! Кил'рек первым!"
L["Wichtel mit AoE wegräumen."] = "Бесов убирать АоЕ."
L["Terestian"] = "Терестиан"
L["Totenkopf Ketten der Opferung, Kreuz Kil'rek."] = "Череп Цепи жертвоприношения, Крест Кил'рек."
L["Arans Schemen"] = "Тень Арана"
L["- Flammenkranz: Feuerkreise um Spieler -> nicht bewegen, sonst explodiert der Kreis."] = "- Венец пламени: огненные круги вокруг игроков -> не двигаться, иначе круг взрывается."
L["- Arkane Explosion: zieht Spieler in die Mitte -> sofort an den Rand laufen."] = "- Чародейский взрыв: стягивает игроков в центр -> сразу бежать к краю."
L["- Blizzard: wandert durch den Raum -> rausgehen."] = "- Снежная буря: ходит по залу -> выходить."
L["- Arkane/Feuer/Frost-Geschosse -> unterbrechen."] = "- Чародейские/Огненные/Ледяные стрелы -> сбивать."
L["- Wasserelementare bei 40%, Massenverwandlung + Trinken bei 0 Mana -> Elementare verbannen/furchten, beim Trinken volle DPS."] = "- Водные элементали на 40%, Массовое превращение + питье при 0 маны -> элементалей изгонять/фирить, во время питья полный ДПС."
L["Taktik: Raid verteilt am Rand, Unterbrecher fest einteilen; bei Flammenkranz stehenbleiben, bei Arkaner Explosion raus."] = "Тактика: Рейд рассредоточен по краю, кикеров распределить заранее; при Венце пламени стоять, при Чародейском взрыве выбегать."
L["ARAN: Flammenkranz - NICHT BEWEGEN!"] = "АРАН: Венец пламени - НЕ ДВИГАТЬСЯ!"
L["Arkane Explosion: an den Rand laufen. Zauber unterbrechen."] = "Чародейский взрыв: бежать к краю. Сбивать заклинания."
L["Nethergroll"] = "Гнев Пустоты"
L["- Roter Strahl (Beharrlichkeit): Tank stellt sich hinein -> Bedrohung und Leben, Boss greift diesen Spieler an."] = "- Красный луч (Упорство): танк встает в луч -> угроза и здоровье, босс атакует этого игрока."
L["- Grüner Strahl (Gelassenheit): Heiler stellt sich hinein -> mehr Heilung, weniger Mana."] = "- Зеленый луч (Безмятежность): хил встает в луч -> больше исцеления, меньше маны."
L["- Blauer Strahl (Dominanz): DPS stellt sich hinein -> mehr Schaden."] = "- Синий луч (Господство): ДД встает в луч -> больше урона."
L["- Erschöpfungs-Debuff -> in den Strahlen rotieren."] = "- Дебафф истощения -> ротироваться в лучах."
L["- Verbannphase: Netheratem und Leerezonen -> verteilt stehen, Leerezonen meiden."] = "- Фаза изгнания: Дыхание Пустоты и зоны пустоты -> стоять рассредоточенно, обходить зоны пустоты."
L["Taktik: Feste Spieler pro Strahl einteilen und rotieren; in der Verbannphase Abstand halten und Zonen meiden."] = "Тактика: Закрепить игроков за каждым лучом и ротировать; в фазе изгнания держать дистанцию и обходить зоны."
L["NETHERGROLL: Strahlen blocken und rotieren!"] = "ГНЕВ ПУСТОТЫ: Блокировать лучи и ротироваться!"
L["Verbannphase: Verteilen, aus Leerezonen raus."] = "Фаза изгнания: рассредоточиться, выйти из зон пустоты."
L["Schachspiel"] = "Шахматы"
L["Schachspiel (Medivhs Spiel)"] = "Шахматы (игра Медива)"
L["- Spieler steuern Figuren -> den gegnerischen König angreifen."] = "- Игроки управляют фигурами -> атаковать короля противника."
L["- Medivh schummelt: Feuer auf dem Brett und Buffs für Gegner -> Figuren aus dem Feuer ziehen."] = "- Медив жульничает: огонь на доске и баффы противнику -> уводить фигуры из огня."
L["- Fähigkeiten der Figuren aktiv nutzen -> König schützen."] = "- Активно использовать способности фигур -> защищать короля."
L["Taktik: Ein Spieler pro Figur, Fokus auf den gegnerischen König, eigene Figuren aus dem Feuer."] = "Тактика: Один игрок на фигуру, фокус на короле противника, свои фигуры уводить из огня."
L["SCHACH: Fokus auf den König! Aus dem Feuer ziehen!"] = "ШАХМАТЫ: Фокус на короля! Уводить из огня!"
L["Eigenen König schützen."] = "Защищать своего короля."
L["Prinz Malchezaar"] = "Принц Малчезар"
L["Prinz Malchezaar + Höllenbestien"] = "Принц Малчезар + инферналы"
L["- Entkräften: setzt 5 Spieler auf 1 Leben -> sofort vor der Schattennova weglaufen."] = "- Слабость: опускает 5 игроков до 1 ХП -> сразу убегать от Кольца Тьмы."
L["- Schattennova: Schaden um den Prinzen -> Raid in Abstand halten."] = "- Кольцо Тьмы: урон вокруг принца -> рейд держит дистанцию."
L["- Höllenbestien: fallen vom Himmel und machen Feuerschaden -> ausweichen."] = "- Инферналы: падают с неба и наносят урон от огня -> уворачиваться."
L["- Phase 2 (60%): Äxte, starke Nahkampftreffer -> Tank-CDs."] = "- Фаза 2 (60%): топоры, сильные удары в мили -> КД танка."
L["- Phase 3 (30%): fliegende Äxte und Schadensverstärkung -> Heiler aufmerksam."] = "- Фаза 3 (30%): летающие топоры и усиление урона -> хилы внимательно."
L["Taktik: Boss in eine Ecke ohne Höllenbestien tanken; Entkräftete laufen sofort raus, ab 30% alles in Schaden."] = "Тактика: Босса танковать в углу без инферналов; ослабленные сразу выбегают, с 30% все в урон."
L["PRINZ: Entkräftet = sofort raus! Höllenbestien meiden!"] = "ПРИНЦ: Ослаблен = сразу наружу! Обходить инферналов!"
L["Phase 2: Tank-CDs. Phase 3: Volle DPS."] = "Фаза 2: КД танка. Фаза 3: полный ДПС."
L["Schrecken der Nacht"] = "Ночная Погибель"
L["Schrecken der Nacht + Skelette"] = "Ночная Погибель + скелеты"
L["- Dröhnendes Gebrüll: Furcht -> Furchtschutz/Erdstoßtotem."] = "- Гулкий рев: страх -> Защита от страха/Тотем трепета."
L["- Schwanzfeger/Spalten -> seitlich stehen."] = "- Удар хвостом/Рассекающий удар -> стоять сбоку."
L["- Verkohlte Erde: Feuer am Boden -> raus."] = "- Обугленная земля: огонь на полу -> выходить."
L["- Luftphase (75/50/25%): Knochenregen ruft Skelette -> sofort töten; Rauchende Explosion auf Tank."] = "- Воздушная фаза (75/50/25%): Дождь из костей призывает скелетов -> сразу убивать; Дымящийся взрыв на танке."
L["Taktik: Boss seitlich tanken, Raid seitlich und verteilt; in der Luftphase Skelette per AoE töten."] = "Тактика: Босса танковать боком, рейд сбоку и рассредоточен; в воздушной фазе скелетов убивать АоЕ."
L["SCHRECKEN DER NACHT: Nicht vorne/hinten stehen! Feuer meiden!"] = "НОЧНАЯ ПОГИБЕЛЬ: Не стоять спереди/сзади! Обходить огонь!"
L["Luftphase: Skelette sofort töten."] = "Воздушная фаза: скелетов сразу убивать."
L["Magtheridons Kammer"] = "Логово Магтеридона"
L["Magtheridon"] = "Магтеридон"
L["Magtheridon + 5 Kanalisierer des Höllenfeuers"] = "Магтеридон + 5 чаротворцев Адского Пламени"
L["- Kanalisierer: Schattenblitzsalve, Dunkle Heilung -> unterbrechen, einzeln tanken und töten (sie stärken die anderen beim Tod)."] = "- Чаротворцы: Залп стрел Тьмы, Темное исцеление -> сбивать, танковать по одному и убивать (при смерти усиливают остальных)."
L["- Höllenbestien: fallen auf Spieler -> ausweichen."] = "- Инферналы: падают на игроков -> уворачиваться."
L["- Druckwellennova: Raidweiter Schaden -> 5 Spieler klicken gleichzeitig die Manticronwürfel, um sie zu unterbrechen."] = "- Кольцо взрывной волны: урон по всему рейду -> 5 игроков одновременно кликают кубы Мантикрона, чтобы прервать его."
L["- Debris-Einsturz (ab 30%): Steine fallen -> aus dem Bereich laufen."] = "- Обвал обломков (с 30%): падают камни -> выбегать из зоны."
L["Taktik: Kanalisierer schnell töten; 2 Gruppen à 5 Spieler für die Würfel einteilen und abwechseln (Debuff)."] = "Тактика: Чаротворцев быстро убить; распределить 2 группы по 5 игроков на кубы и чередовать (дебафф)."
L["MAGTHERIDON: Würfel gleichzeitig klicken bei Druckwellennova!"] = "МАГТЕРИДОН: Одновременно кликать кубы при Кольце взрывной волны!"
L["Phase 1: Kanalisierer unterbrechen und töten. Ab 30%: Debris meiden."] = "Фаза 1: чаротворцев сбивать и убивать. С 30%: обходить обломки."
L["Jeder Kanalisierer ein Symbol in Tötungsreihenfolge, Totenkopf zuerst."] = "Каждому чаротворцу метка в порядке убийства, Череп первым."
L["Höhle des Schlangenschreins"] = "Змеиное святилище"
L["Hydross der Unstete"] = "Гидросс Нестабильный"
L["Hydross der Unstete + Elementare"] = "Гидросс Нестабильный + элементали"
L["- Frost- und Naturform: wechselt beim Überschreiten der Linie -> Frost- und Naturwiderstand-Tank im Wechsel."] = "- Ледяной облик и облик природы: меняется при пересечении линии -> по очереди танки в сопротивлении льду и природе."
L["- Mal des Hydross / Mal der Verderbnis: stapelnde Schadenserhöhung -> Boss rechtzeitig über die Linie ziehen."] = "- Метка Гидросса / Метка порчи: стакающееся увеличение урона -> вовремя перетаскивать босса через линию."
L["- Elementare beim Formwechsel -> per AoE töten."] = "- Элементали при смене облика -> убивать АоЕ."
L["- Wassergrab / Schlamm-Effekte -> Betroffene heilen."] = "- Водяная могила / эффекты слизи -> хилить пострадавших."
L["Taktik: Zwei Tanks mit Widerstand, Formwechsel bei ca. 3-4 Stapeln; Fernkampf AoE auf die Elementare."] = "Тактика: Два танка в сопротивлении, смена облика на ок. 3-4 стаках; РДД АоЕ по элементалям."
L["HYDROSS: Formwechsel = Tankwechsel! Elementare mit AoE!"] = "ГИДРОСС: Смена облика = смена танков! Элементалей АоЕ!"
L["Nicht zu viele Mal-Stapel aufbauen."] = "Не набирать много стаков меток."
L["Das Grauen aus der Tiefe"] = "Скрытень из глубин"
L["Das Grauen aus der Tiefe + Adds"] = "Скрытень из глубин + адды"
L["- Speien: rotierender Wasserstrahl -> ins Wasser springen."] = "- Извержение: вращающаяся струя воды -> прыгать в воду."
L["- Wirbeln: Rückstoß im Nahkampf -> Nahkampf abseits wenn möglich."] = "- Водоворот: отбрасывание в мили -> мили по возможности в стороне."
L["- Geysir: schleudert Spieler hoch -> verteilt stehen."] = "- Гейзер: подбрасывает игроков -> стоять рассредоточенно."
L["- Abtauchen: Wachen und Hinterhältige auf Plattformen -> Adds töten."] = "- Погружение: стражи и засадники на платформах -> убивать аддов."
L["Taktik: Boss zu Beginn angeln, Raid auf den Plattformen verteilt; bei Speien sofort ins Wasser."] = "Тактика: Босса вначале выловить, рейд рассредоточен по платформам; при Извержении сразу в воду."
L["GRAUEN: Bei Speien ins Wasser springen!"] = "СКРЫТЕНЬ: При Извержении прыгать в воду!"
L["Abtauchen: Adds auf den Plattformen töten."] = "Погружение: убивать аддов на платформах."
L["Leotheras der Blinde"] = "Леотерас Слепец"
L["Leotheras der Blinde + Innere Dämonen"] = "Леотерас Слепец + внутренние демоны"
L["- Wirbelwind (Elfenform): Schaden um den Boss -> Nahkampf raus."] = "- Вихрь (облик эльфа): урон вокруг босса -> мили наружу."
L["- Dämonenform: Chaosstrahl -> Hexer tankt."] = "- Облик демона: Хаотический взрыв -> танкует лок."
L["- Innerer Dämon: jeder Spieler muss seinen eigenen Dämon töten."] = "- Внутренний демон: каждый игрок должен убить своего демона."
L["- Ab 15%: Elf und Schatten getrennt -> zwei Tanks bereit."] = "- С 15%: эльф и тень разделяются -> два танка наготове."
L["Taktik: Krieger-Tank in Elfenform, Hexer-Tank in Dämonenform; innere Dämonen sofort töten."] = "Тактика: Воин-танк в облике эльфа, лок-танк в облике демона; внутренних демонов убивать сразу."
L["LEOTHERAS: Innere Dämonen sofort töten!"] = "ЛЕОТЕРАС: Внутренних демонов сразу убивать!"
L["Wirbelwind: Nahkampf raus. Hexer-Tank bei Dämonenform."] = "Вихрь: мили наружу. Лок-танк на облике демона."
L["Tiefenlord Karathress"] = "Повелитель глубин Каратресс"
L["Tiefenlord Karathress + Sharkkis, Tidalvess, Caribdis"] = "Повелитель глубин Каратресс + Шарккис, Тайдалвесс, Карибдис"
L["- Caribdis (Heiler): heilt die anderen -> unterbrechen, zuerst töten."] = "- Карибдис (хил): лечит остальных -> сбивать, убивать первым."
L["- Tidalvess: Totems (Feuerspeier) -> Totems sofort zerstören."] = "- Тайдалвесс: тотемы (Плевок огнем) -> тотемы сразу уничтожать."
L["- Sharkkis: Mehrfachschuss und Tier -> Tier mittanken."] = "- Шарккис: Залп и питомец -> питомца тоже танковать."
L["- Karathress: übernimmt Fähigkeiten getöteter Adds -> Totems weiter zerstören."] = "- Каратресс: перенимает способности убитых аддов -> тотемы продолжать уничтожать."
L["Taktik: Jedes Add eigener Tank; übliche Reihenfolge Caribdis, Tidalvess, Sharkkis, dann Karathress."] = "Тактика: У каждого адда свой танк; обычный порядок Карибдис, Тайдалвесс, Шарккис, затем Каратресс."
L["KARATHRESS: Caribdis zuerst und unterbrechen!"] = "КАРАТРЕСС: Карибдис первым и сбивать!"
L["Totems sofort zerstören."] = "Тотемы сразу уничтожать."
L["Karathress"] = "Каратресс"
L["Totenkopf Caribdis, Kreuz Tidalvess, Viereck Sharkkis, Mond Karathress."] = "Череп Карибдис, Крест Тайдалвесс, Квадрат Шарккис, Луна Каратресс."
L["Morogrim Gezeitenwandler"] = "Морогрим Волноступ"
L["Morogrim Gezeitenwandler + Murlocs"] = "Морогрим Волноступ + мурлоки"
L["- Flutwelle: Frontalschaden -> Boss weg vom Raid drehen."] = "- Приливная волна: фронтальный урон -> развернуть босса от рейда."
L["- Wassergrab: Spieler werden in Wassergräber teleportiert -> heilen."] = "- Водяная могила: игроков телепортирует в водяные могилы -> хилить."
L["- Erdbeben: Murloc-Wellen -> per AoE töten."] = "- Землетрясение: волны мурлоков -> убивать АоЕ."
L["- Wasserkugeln ab 25%: folgen Spielern -> weglaufen/ausweichen."] = "- Водяные шары с 25%: следуют за игроками -> убегать/уворачиваться."
L["Taktik: Tank an der Wand, Murlocs per AoE; ab 25% Kugeln ausweichen."] = "Тактика: Танк у стены, мурлоков АоЕ; с 25% уворачиваться от шаров."
L["MOROGRIM: Murlocs mit AoE! Wassergrab-Spieler heilen!"] = "МОРОГРИМ: Мурлоков АоЕ! Хилить игроков в Водяной могиле!"
L["Ab 25%: Wasserkugeln ausweichen."] = "С 25%: уворачиваться от водяных шаров."
L["Lady Vashj"] = "Леди Вайш"
L["Lady Vashj + Elementare und Schreiter"] = "Леди Вайш + элементали и бегуны"
L["- Phase 1: Schockschlag auf Tank, Statische Aufladung -> verteilt stehen."] = "- Фаза 1: Шоковый удар по танку, Статический заряд -> стоять рассредоточенно."
L["- Phase 2: Besudelter Kern von besudelten Elementaren -> zu den Generatoren weitergeben."] = "- Фаза 2: Зараженное ядро от зараженных элементалей -> передавать к генераторам."
L["- Verzauberte Elementare -> töten, bevor sie Vashj erreichen."] = "- Зачарованные элементали -> убить, пока не дошли до Вайш."
L["- Echsenkrieger und Schreiter -> tanken/kiten."] = "- Наги-воины и бегуны -> танковать/кайтить."
L["- Phase 3: Sporensegler -> grüne Wolken meiden."] = "- Фаза 3: спороскаты -> обходить зеленые облака."
L["Taktik: Kernweitergabe mit festen Spielern; Generatoren zügig aktivieren; Phase 3 schnell töten."] = "Тактика: Передача ядер закрепленными игроками; генераторы активировать быстро; фазу 3 быстро добить."
L["VASHJ: Kerne weitergeben, Generatoren aktivieren!"] = "ВАЙШ: Передавать ядра, активировать генераторы!"
L["Elementare töten, bevor sie zu Vashj gelangen."] = "Элементалей убивать, пока не дошли до Вайш."
L["Sonnenbrunnenplateau"] = "Плато Солнечного Колодца"
L["Kalecgos"] = "Калесгос"
L["Kalecgos + Sathrovarr der Verderber (Dämonenreich)"] = "Калесгос + Сатроварр Осквернитель (царство демонов)"
L["- Spektrale Explosion: Spieler werden ins Dämonenreich zu Sathrovarr teleportiert -> dort Sathrovarr tanken und Kalec (Elfengestalt) schützen."] = "- Призрачный взрыв: игроков телепортирует в царство демонов к Сатроварру -> там танковать Сатроварра и защищать Калека (облик эльфа)."
L["- Spektrale Erschöpfung: nach Rückkehr ca. 1 Min. kein Zutritt -> Gruppen planen und rotieren."] = "- Призрачное изнеможение: после возвращения ок. 1 мин. нет входа -> планировать группы и ротировать."
L["- Fluch der grenzenlosen Qual (Sathrovarr): steigender Schaden -> nur gezielt entfernen."] = "- Проклятие безграничной агонии (Сатроварр): растущий урон -> снимать только выборочно."
L["- Arkanpuffer und Wilde Magie (Kalecgos): stapelnder Arkanschaden und zufällige Effekte -> heilen, Debuffs beachten."] = "- Чародейский буфер и Дикая магия (Калесгос): стакающийся тайный урон и случайные эффекты -> хилить, следить за дебаффами."
L["- Kalecgos und Sathrovarr möglichst gleichmäßig senken -> unter 10% Raserei, Sathrovarr muss sterben, Kalecgos wird befreit."] = "- Калесгоса и Сатроварра опускать как можно равномернее -> ниже 10% Исступление, Сатроварр должен умереть, Калесгос освобождается."
L["Taktik: Raid teilt sich auf: Hauptgruppe auf Kalecgos, Tanks und eine DPS-Gruppe rotieren ins Dämonenreich; Lebensbalken beider Bosse synchron halten."] = "Тактика: Рейд делится: основная группа на Калесгосе, танки и одна ДД-группа ротируются в царство демонов; полоски здоровья обоих боссов держать синхронно."
L["KALECGOS: Dämonenreich-Gruppen rotieren! Beide Bosse gleichmäßig senken!"] = "КАЛЕСГОС: Группы царства демонов ротируются! Обоих боссов опускать равномерно!"
L["Kalec im Dämonenreich am Leben halten. Sathrovarr muss sterben."] = "Держать Калека в живых в царстве демонов. Сатроварр должен умереть."
L["Brutallus"] = "Бруталл"
L["- Meteorschlag: Schaden im Frontalkegel, auf alle Getroffenen aufgeteilt, plus Debuff -> zwei Gruppen vor dem Boss im Wechsel."] = "- Удар метеора: урон во фронтальном конусе, делится на всех задетых, плюс дебафф -> две группы перед боссом по очереди."
L["- Brand: Feuer-DoT auf zufälligem Spieler, springt auf Umstehende -> nicht dicht stehen, durchheilen."] = "- Горение: огненный ДоТ на случайном игроке, перескакивает на стоящих рядом -> не стоять плотно, прохиливать."
L["- Stampfen: Tank wird zurückgestoßen und erleidet mehr Schaden -> Heiler reagieren, Tank sofort zurück."] = "- Топот: танка отбрасывает, он получает больше урона -> хилы реагируют, танк сразу назад."
L["- Hartes Enrage nach 6 Min. -> reiner DPS-Check."] = "- Жесткий энрейдж через 6 мин. -> чистая проверка ДПС."
L["Taktik: Tank plus Meteorgruppe vorne, zweite Gruppe wechselt, wenn der Debuff zu hoch ist; Rest seitlich verteilt, alle CDs früh."] = "Тактика: Танк плюс метеорная группа спереди, вторая группа сменяет, когда дебафф слишком высок; остальные рассредоточены сбоку, все КД сразу."
L["BRUTALLUS: Meteorgruppen wechseln! Brand: Abstand halten!"] = "БРУТАЛЛ: Метеорные группы меняются! Горение: держать дистанцию!"
L["6 Min. Enrage - alle Cooldowns nutzen."] = "Энрейдж 6 мин. - жать все КД."
L["Teufelsruch"] = "Сквернопар"
L["Teufelsruch + Unnachgiebige Tote"] = "Сквернопар + Неумолимые мертвецы"
L["- Einkapseln: Spieler wird angehoben und verursacht Schaden um sich -> sofort von ihm weg."] = "- Заключение в кокон: игрока поднимает, он наносит урон вокруг -> сразу отойти от него."
L["- Ätzen: Tank-Debuff -> Tank heilen."] = "- Разъедание: дебафф на танке -> хилить танка."
L["- Gasnova: Schaden auf den Raid -> heilen."] = "- Газовое кольцо: урон по рейду -> хилить."
L["- Luftphase: Dämonischer Dunst folgt Spielern und lässt Skelette entstehen -> Dunst wegziehen, Skelette per AoE töten."] = "- Воздушная фаза: Демонический пар следует за игроками и порождает скелетов -> уводить пар, скелетов убивать АоЕ."
L["- Nebel der Verderbnis: Atemangriff in Bahnen, Getroffene werden gedankenkontrolliert -> aus der Bahn des Atems gehen."] = "- Туман порчи: дыхание полосами, задетые попадают под контроль разума -> уходить с полосы дыхания."
L["Taktik: Raid verteilt, Nahkampf seitlich; in der Luftphase Dunst vom Raid wegziehen und vor dem Atem die Bahnen räumen."] = "Тактика: Рейд рассредоточен, мили сбоку; в воздушной фазе уводить пар от рейда и перед дыханием освобождать полосы."
L["TEUFELSRUCH: Atem-Bahnen räumen! Einkapseln-Ziel meiden!"] = "СКВЕРНОПАР: Освобождать полосы дыхания! Обходить цель кокона!"
L["Dämonischen Dunst wegziehen, Skelette mit AoE töten."] = "Демонический пар уводить, скелетов убивать АоЕ."
L["Eredarzwillinge"] = "Эредарские близнецы"
L["Eredarzwillinge (Lady Sacrolash und Großhexenmeisterin Alythess)"] = "Эредарские близнецы (леди Сакролаш и великая чернокнижница Алитесса)"
L["- Lady Sacrolash: Schattenklingen und Schattenbilder -> Nahkampftank, Schattenbilder per AoE töten."] = "- Леди Сакролаш: Клинки тьмы и теневые образы -> танк в мили, образы убивать АоЕ."
L["- Großhexenmeisterin Alythess: Feuerzauber -> auf Distanz von Hexern tanken; Pyrogenik-Buff stehlen/reinigen."] = "- Великая чернокнижница Алитесса: огненные заклинания -> танкуют локи на дистанции; бафф Пирогеника красть/снимать."
L["- Feuersbrunst: Feuerschaden um ein Ziel -> verteilt stehen."] = "- Воспламенение: урон от огня вокруг цели -> стоять рассредоточенно."
L["- Schattennova -> Ziel und Umstehende heilen."] = "- Кольцо Тьмы -> хилить цель и стоящих рядом."
L["- Gegenseitige Debuff-Stapel (Dunkel/Flamme berührt) -> Stapel beobachten."] = "- Взаимные стаки дебаффов (Касание тьмы/пламени) -> следить за стаками."
L["Taktik: Beide getrennt tanken, meist zuerst Sacrolash; nach dem Tod eines Zwillings übernimmt der andere dessen Fähigkeiten."] = "Тактика: Обеих танковать раздельно, обычно первой Сакролаш; после смерти одной близняшки другая перенимает ее способности."
L["ZWILLINGE: Verteilt stehen! Pyrogenik stehlen/reinigen!"] = "БЛИЗНЕЦЫ: Стоять рассредоточенно! Пирогенику красть/снимать!"
L["Schattenbilder schnell töten. Debuff-Stapel beachten."] = "Теневые образы быстро убивать. Следить за стаками дебаффов."
L["M'uru"] = "М'ару"
L["M'uru + Leerenwächter und Schattenschwert-Adds / Entropius"] = "М'ару + стражи Бездны и адды Темного Клинка / Энтропий"
L["- Dunkelheit: Leerezone unter Spielern -> sofort raus."] = "- Тьма: зона пустоты под игроками -> сразу выйти."
L["- Negative Energie: springt zwischen Spielern -> verteilt stehen."] = "- Отрицательная энергия: прыгает между игроками -> стоять рассредоточенно."
L["- Leerenwächter: erscheinen aus der Dunkelheit -> tanken und töten."] = "- Стражи Бездны: появляются из Тьмы -> танковать и убивать."
L["- Schattenschwert-Berserker und Teufelsmagier aus den Türen -> abfangen, unterbrechen, töten."] = "- Берсерки Темного Клинка и маги Скверны из дверей -> перехватывать, сбивать, убивать."
L["- Phase 2 Entropius: Singularität (schwarzes Loch) und Dunkelheit -> ausweichen, volle DPS."] = "- Фаза 2 Энтропий: Сингулярность (черная дыра) и Тьма -> уворачиваться, полный ДПС."
L["Taktik: Zwei Teams an den Türen für die Adds, Rest auf M'uru und Leerenwächter; Entropius schnell töten."] = "Тактика: Две команды у дверей на аддов, остальные на М'ару и стражей Бездны; Энтропия быстро убить."
L["M'URU: Adds an den Türen abfangen! Raus aus der Dunkelheit!"] = "М'АРУ: Перехватывать аддов у дверей! Выйти из Тьмы!"
L["Entropius: Singularitäten ausweichen, volle DPS."] = "Энтропий: уворачиваться от сингулярностей, полный ДПС."
L["Kil'jaeden"] = "Кил'джеден"
L["Kil'jaeden + Hände des Betrügers"] = "Кил'джеден + Руки Обманщика"
L["- Hände des Betrügers: kanalisieren Kil'jaeden herbei -> zuerst töten."] = "- Руки Обманщика: призывают Кил'джедена каналом -> убивать первыми."
L["- Feuerblüte: Debuff mit Schaden an Umstehenden -> verteilt stehen."] = "- Огненный цветок: дебафф с уроном по стоящим рядом -> стоять рассредоточенно."
L["- Finstere Reflexionen: Kopien von Spielern -> schnell töten."] = "- Зловещие отражения: копии игроков -> быстро убивать."
L["- Dunkelheit der tausend Seelen: tödlicher Raidschaden -> Kugeln der blauen Drachen für den Schild nutzen."] = "- Тьма тысячи душ: смертельный урон по рейду -> использовать сферы синих драконов для щита."
L["- Armageddon: Meteore fallen -> Einschläge meiden."] = "- Армагеддон: падают метеоры -> обходить места падения."
L["Taktik: Raid verteilt; feste Spieler für die Kugeln; Reflexionen schnell beseitigen."] = "Тактика: Рейд рассредоточен; закрепленные игроки на сферах; отражения быстро убирать."
L["KIL'JAEDEN: Dunkelheit = Schild der Blauen!"] = "КИЛ'ДЖЕДЕН: Тьма = щит синих!"
L["Feuerblüte: verteilen. Reflexionen töten, Armageddon meiden."] = "Огненный цветок: рассредоточиться. Отражения убивать, обходить Армагеддон."
L["Festung der Stürme"] = "Крепость Бурь"
L["Al'ar"] = "Ал'ар"
L["Al'ar + Glut von Al'ar"] = "Ал'ар + Угли Ал'ара"
L["- Flammenpuffer: Al'ar landet auf wechselnden Plattformen und trifft alle, wenn kein Tank in Nahkampfreichweite ist -> auf jeder Plattform ein Tank bereit."] = "- Огненный буфер: Ал'ар садится на разные платформы и бьет всех, если в радиусе мили нет танка -> на каждой платформе танк наготове."
L["- Flammenfedern: Al'ar fliegt in die Mitte und überzieht die Plattformen mit Feuer -> alle sofort nach unten in die Mitte."] = "- Огненные перья: Ал'ар летит в центр и заливает платформы огнем -> всем сразу вниз в центр."
L["- Wiedergeburt: nach Phase 1 ersteht Al'ar mit Schaden um sich herum neu -> nicht in der Mitte stehen."] = "- Возрождение: после фазы 1 Ал'ар возрождается с уроном вокруг себя -> не стоять в центре."
L["- Phase 2: Rüstung schmelzen auf dem Tank -> Tankwechsel; Flammenfelder am Boden -> raus."] = "- Фаза 2: Расплавление брони на танке -> смена танков; огненные зоны на полу -> выходить."
L["- Sturzflug: Al'ar stürzt auf einen Spieler, Glut von Al'ar erscheint -> Glut tanken und töten (kostet Al'ar Leben), Explosion meiden."] = "- Пикирование: Ал'ар пикирует на игрока, появляется Уголь Ал'ара -> уголь танковать и убить (отнимает здоровье у Ал'ара), обходить взрыв."
L["Taktik: Phase 1 Tanks auf den Plattformen, Raid unten mittig verteilt; Phase 2 zwei Tanks im Wechsel, Gluten von Offtanks aufnehmen und töten."] = "Тактика: Фаза 1: танки на платформах, рейд внизу рассредоточен по центру; фаза 2: два танка меняются, угли забирают офф-танки и убивают."
L["AL'AR: Flammenfedern - sofort runter! Tank auf jeder Plattform!"] = "АЛ'АР: Огненные перья - сразу вниз! Танк на каждой платформе!"
L["Phase 2: Tankwechsel bei Rüstung schmelzen. Gluten töten, Feuer meiden."] = "Фаза 2: смена танков на Расплавлении брони. Угли убивать, обходить огонь."
L["Leerhäscher"] = "Страж Бездны"
L["- Arkane Kugel: wird auf Fernkämpfer geworfen und explodiert am Zielort -> Fernkampf weit verteilt, Einschlagstelle verlassen."] = "- Чародейская сфера: кидается в РДД и взрывается в точке падения -> РДД широко рассредоточены, уходить из точки падения."
L["- Hämmern: Arkanschaden um den Boss -> Nahkampf und Tank heilen."] = "- Удары молота: тайный урон вокруг босса -> хилить мили и танка."
L["- Wegschlagen: Rückstoß und Bedrohungsverlust -> 2-3 Tanks mit ähnlicher Bedrohung."] = "- Отбрасывание: отбрасывание и потеря угрозы -> 2-3 танка с похожей угрозой."
L["- Enrage nach 10 Min. -> DPS-Check."] = "- Энрейдж через 10 мин. -> проверка ДПС."
L["Taktik: Boss mittig tanken, Fernkampf in großem Kreis verteilt und in Bewegung bei Kugeln; mehrere Tanks gegen Wegschlagen."] = "Тактика: Босса танковать в центре, РДД рассредоточены по большому кругу и двигаются при сферах; несколько танков против Отбрасывания."
L["LEERHÄSCHER: Fernkampf verteilt! Arkanen Kugeln ausweichen!"] = "СТРАЖ БЕЗДНЫ: РДД рассредоточены! Уворачиваться от Чародейских сфер!"
L["Tanks Bedrohung aufbauen (Wegschlagen). Enrage 10 Min."] = "Танкам набирать угрозу (Отбрасывание). Энрейдж 10 мин."
L["Hochastromantin Solarian"] = "Верховный звездочет Солариан"
L["Hochastromantin Solarian + Agenten und Priester des Solariums"] = "Верховный звездочет Солариан + агенты и жрецы Солнечной обсерватории"
L["- Zorn der Astromantin: nach kurzer Zeit Explosion um den Spieler -> Betroffener läuft sofort weg vom Raid."] = "- Гнев звездочета: через короткое время взрыв вокруг игрока -> пострадавший сразу убегает от рейда."
L["- Arkane Geschosse: Schaden auf zufällige Spieler -> heilen."] = "- Чародейские стрелы: урон по случайным игрокам -> хилить."
L["- Teilung: Solarian verschwindet, Agenten des Solariums erscheinen -> per AoE töten."] = "- Разделение: Солариан исчезает, появляются агенты Солнечной обсерватории -> убивать АоЕ."
L["- Priester des Solariums: heilen -> unterbrechen und töten."] = "- Жрецы Солнечной обсерватории: лечат -> сбивать и убивать."
L["- Leerenform (ab 20%): Psychischer Schrei (Furcht) -> Furchtschutz/Erdstoßtotem, volle DPS."] = "- Облик Бездны (с 20%): Ментальный крик (страх) -> Защита от страха/Тотем трепета, полный ДПС."
L["Taktik: Raid verteilt, Zorn-Ziele laufen zur Seite; in der Teilungsphase Agenten wegbomben und Priester unterbrechen."] = "Тактика: Рейд рассредоточен, цели Гнева отбегают в сторону; в фазе разделения выжигать агентов АоЕ и сбивать жрецов."
L["SOLARIAN: Zorn = sofort raus aus dem Raid!"] = "СОЛАРИАН: Гнев = сразу из рейда!"
L["Agenten per AoE, Priester unterbrechen. Ab 20%: Furcht."] = "Агентов АоЕ, жрецов сбивать. С 20%: страх."
L["Kael'thas Sonnenwanderer"] = "Кель'тас Солнечный Скиталец"
L["Kael'thas Sonnenwanderer + 4 Berater und 7 Waffen"] = "Кель'тас Солнечный Скиталец + 4 советника и 7 оружий"
L["- Phase 1: Berater kommen nacheinander -> Thaladred fixiert (wegkiten), Sanguinar fürchtet (Furchtschutz), Capernian auf Distanz tanken, Telonicus Bomben meiden."] = "- Фаза 1: советники выходят по очереди -> Таладред фиксируется (кайтить), Сангвинар пугает (Защита от страха), Каперниана танковать на дистанции, бомбы Телоникуса обходить."
L["- Phase 2: 7 legendäre Waffen -> töten, plündern und in Phase 3/4 benutzen."] = "- Фаза 2: 7 легендарных оружий -> убить, залутать и использовать в фазе 3/4."
L["- Phase 3: alle Berater stehen gleichzeitig wieder auf -> erneut tanken und töten."] = "- Фаза 3: все советники встают снова одновременно -> снова танковать и убивать."
L["- Phase 4: Feuerball, Flammenschlag, Phönix, Gedankenkontrolle -> unterbrechen, Feuer meiden, Phönix samt Ei töten, Gedankenkontrollierte CC."] = "- Фаза 4: Огненный шар, Огненный удар, феникс, контроль разума -> сбивать, обходить огонь, убивать феникса вместе с яйцом, законтроленных КК."
L["- Schockbarriere + Pyroschlag: Schild schnell brechen und Pyroschlag unterbrechen."] = "- Шоковый барьер + Огненная глыба: щит быстро сломать и Огненную глыбу сбить."
L["- Phase 5 (50%): Schwerkraftverlust -> schwebend verteilt bleiben, Netherdampf meiden."] = "- Фаза 5 (50%): потеря гравитации -> парить рассредоточенно, обходить пар Пустоты."
L["Taktik: Berater-Tanks fest einteilen und Waffen gezielt verteilen; in Phase 4/5 Unterbrecher-Rotation auf Kael."] = "Тактика: Танков на советников закрепить заранее и раздавать оружие прицельно; в фазах 4/5 ротация кикеров на Кель'таса."
L["Hinweis: Die Waffen sind nur im Kampf nutzbar; Waffen vorher fest an Spieler vergeben."] = "Примечание: оружие можно использовать только в бою; заранее закрепить оружие за игроками."
L["KAEL'THAS: Berater nacheinander! Waffen plündern und nutzen!"] = "КЕЛЬ'ТАС: Советники по очереди! Лутать и использовать оружие!"
L["Phase 4: Barriere brechen, Pyroschlag kicken. Phase 5: verteilt schweben."] = "Фаза 4: ломать барьер, кикать Огненную глыбу. Фаза 5: парить рассредоточенно."
L["Kael'thas (Berater)"] = "Кель'тас (советники)"
L["Totenkopf Thaladred, Kreuz Sanguinar, Viereck Capernian, Mond Telonicus."] = "Череп Таладред, Крест Сангвинар, Квадрат Каперниан, Луна Телоникус."
L["Zul'Aman"] = "Зул'Аман"
L["Nalorakk"] = "Налоракк"
L["Nalorakk (Bärengott)"] = "Налоракк (бог-медведь)"
L["- Brutaler Hieb (Trollform): Frontalschaden, auf alle Getroffenen aufgeteilt -> Nahkampf vor dem Boss teilt mit dem Tank."] = "- Жестокий удар (облик тролля): фронтальный урон, делится на всех задетых -> мили перед боссом делят урон с танком."
L["- Woge: stürmt auf den entferntesten Spieler -> 1-2 feste Spieler mit viel Leben weit weg."] = "- Бросок: рывок на самого дальнего игрока -> 1-2 закрепленных игрока с большим ХП стоят далеко."
L["- Zerfleischen / Rotte Fleisch (Bärenform): Blutungen auf dem Tank -> Tank stark heilen."] = "- Увечье / Рваная плоть (облик медведя): кровотечения на танке -> танка сильно хилить."
L["- Ohrenbetäubendes Gebrüll: Stille -> Heiler zuvor hochheilen."] = "- Оглушающий рев: немота -> хилам заранее отхилить."
L["- Formwechsel ca. alle 45 Sek. -> Tankwechsel."] = "- Смена облика ок. каждые 45 сек. -> смена танков."
L["Taktik: Zwei Tanks wechseln bei Formwechsel; feste Woge-Ziele hinten, Nahkampf teilt Brutalen Hieb."] = "Тактика: Два танка меняются при смене облика; закрепленные цели Броска сзади, мили делят Жестокий удар."
L["NALORAKK: Tankwechsel bei Formwechsel! Woge-Ziel weit weg!"] = "НАЛОРАКК: Смена танков при смене облика! Цель Броска далеко!"
L["Nahkampf teilt Brutalen Hieb. Gebrüll = Stille."] = "Мили делят Жестокий удар. Рев = немота."
L["Akil'zon"] = "Акил'зон"
L["Akil'zon + Adler"] = "Акил'зон + орлы"
L["- Elektrischer Sturm: ein Spieler wird angehoben, sein Umfeld ist sicher -> alle sammeln sich unter ihm."] = "- Электрическая буря: игрока поднимает в воздух, рядом с ним безопасно -> все собираются под ним."
L["- Statische Störung: Naturschaden an Ziel und Umstehenden -> außerhalb des Sturms verteilt stehen."] = "- Статический разряд: урон от сил природы по цели и стоящим рядом -> вне бури стоять рассредоточенно."
L["- Windbö: Spieler wird hochgeschleudert -> heilen."] = "- Порыв ветра: игрока подбрасывает -> хилить."
L["- Adler: Adds -> per AoE töten."] = "- Орлы: адды -> убивать АоЕ."
L["Taktik: Raid locker verteilt, bei Elektrischem Sturm sofort unter dem angehobenen Spieler sammeln; Naturwiderstand hilft."] = "Тактика: Рейд свободно рассредоточен, при Электрической буре сразу собираться под поднятым игроком; помогает сопротивление силам природы."
L["AKIL'ZON: Elektrischer Sturm - unter den Spieler stellen!"] = "АКИЛ'ЗОН: Электрическая буря - встать под игрока!"
L["Sonst verteilt stehen. Adler per AoE."] = "В остальное время стоять рассредоточенно. Орлов АоЕ."
L["Jan'alai"] = "Джан'алай"
L["Jan'alai + Brüter und Drachenfalken"] = "Джан'алай + наседки и дракондоры"
L["- Flammenatem: Feuerlinie -> nicht vor dem Boss stehen."] = "- Огненное дыхание: линия огня -> не стоять перед боссом."
L["- Feuerbomben: Bomben um den Boss -> Lücken suchen bzw. aus dem Bereich laufen."] = "- Огненные бомбы: бомбы вокруг босса -> искать просветы или выбегать из зоны."
L["- Brüter der Amani'shi: brüten Eier aus -> Brüter einer Seite töten, nur wenige Eier schlüpfen lassen."] = "- Наседки Амани'ши: высиживают яйца -> убить наседок с одной стороны, давать вылупиться лишь немногим яйцам."
L["- Ab 35%: alle Eier schlüpfen -> Eier vorher reduzieren und Drachenfalken per AoE töten."] = "- С 35%: вылупляются все яйца -> заранее сократить число яиц и убивать дракондоров АоЕ."
L["Taktik: Jan'alai mittig, Raid verteilt; eine Seite der Eier kontrolliert ausbrüten, Rest bei 35% per AoE."] = "Тактика: Джан'алай в центре, рейд рассредоточен; одну сторону яиц выводить контролируемо, остальное на 35% АоЕ."
L["JAN'ALAI: Feuerbomben meiden! Brüter töten!"] = "ДЖАН'АЛАЙ: Обходить огненные бомбы! Убивать наседок!"
L["Drachenfalken per AoE, ab 35% schlüpfen alle Eier."] = "Дракондоров АоЕ, с 35% вылупляются все яйца."
L["Halazzi"] = "Халаззи"
L["Halazzi + Luchsgeist"] = "Халаззи + дух рыси"
L["- Säbelpeitsche: Schaden auf alle Nahen aufgeteilt -> Nahkampf und Tanks zusammen am Boss."] = "- Сабельный удар: урон делится на всех рядом -> мили и танки вместе у босса."
L["- Teilung (75/50/25%): Troll und Luchsgeist trennen sich -> zwei Tanks."] = "- Разделение (75/50/25%): тролль и дух рыси разделяются -> два танка."
L["- Verderbtes Blitzschlagtotem -> sofort töten."] = "- Тотем порченой молнии -> сразу убить."
L["- Flammenschock: Feuer-DoT -> bannen."] = "- Огненный шок: огненный ДоТ -> диспелить."
L["Taktik: Halazzi und Luchsgeist getrennt tanken, Totems sofort zerstören; unter 25% volle DPS."] = "Тактика: Халаззи и духа рыси танковать раздельно, тотемы сразу уничтожать; ниже 25% полный ДПС."
L["HALAZZI: Totems sofort töten!"] = "ХАЛАЗЗИ: Тотемы сразу убивать!"
L["Teilung: Luchsgeist separat tanken. Flammenschock bannen."] = "Разделение: духа рыси танковать отдельно. Огненный шок диспелить."
L["Hexlord Malacrass"] = "Повелитель проклятий Малакрасс"
L["Hexlord Malacrass + 4 Adds"] = "Повелитель проклятий Малакрасс + 4 адда"
L["- Geistblitze: kanalisierter Schatten-AoE -> Heiler bereit, CDs."] = "- Стрелы духа: поддерживаемый теневой АоЕ -> хилы наготове, КД."
L["- Seele entziehen: übernimmt Klassenfähigkeiten eines Spielers -> darauf reagieren."] = "- Вытягивание души: перенимает классовые способности игрока -> реагировать на это."
L["- Kraft entziehen: stapelnder Debuff -> schnell töten."] = "- Вытягивание силы: стакающийся дебафф -> быстро убить."
L["- 4 zufällige Adds -> zuerst töten oder kontrollieren."] = "- 4 случайных адда -> убивать первыми или контролить."
L["Taktik: Adds zuerst, dann Malacrass; bei Geistblitzen heilen."] = "Тактика: Сначала адды, затем Малакрасс; при Стрелах духа хилить."
L["MALACRASS: Adds zuerst! Geistblitze heilen!"] = "МАЛАКРАСС: Адды первыми! Хилить Стрелы духа!"
L["Seele entziehen: Klassenfähigkeiten beachten."] = "Вытягивание души: следить за классовыми способностями."
L["Malacrass"] = "Малакрасс"
L["Ein Symbol pro Add, Totenkopf zuerst."] = "По метке на каждого адда, Череп первым."
L["Zul'jin"] = "Зул'джин"
L["- Trollform: Wirbelwind und Grausamer Wurf (Blutung bis volle Gesundheit) -> Nahkampf raus, Ziele voll heilen."] = "- Облик тролля: Вихрь и Жестокий бросок (кровотечение до полного здоровья) -> мили наружу, цели хилить в фулл."
L["- Bärenform (80%): Schleichende Paralyse -> bannen."] = "- Облик медведя (80%): Ползучий паралич -> диспелить."
L["- Adlerform (60%): Energiesturm (Zaubern verursacht Blitzschaden) und Wirbelstürme -> Wirbelstürmen ausweichen."] = "- Облик орла (60%): Энергетическая буря (произнесение заклинаний наносит урон от молнии) и смерчи -> уворачиваться от смерчей."
L["- Luchsform (40%): Klauenwut und Luchsstürmen -> Ziele heilen."] = "- Облик рыси (40%): Шквал когтей и Рысий рывок -> хилить цели."
L["- Drachenfalkenform (20%): Flammensäulen -> Säulen meiden."] = "- Облик дракондора (20%): огненные столбы -> обходить столбы."
L["Taktik: Phasen nacheinander mit festen Gegenmaßnahmen; Heiler auf Blutungen und Paralyse vorbereitet."] = "Тактика: Фазы по очереди с заранее отработанными контрмерами; хилы готовы к кровотечениям и параличу."
L["ZUL'JIN: Formwechsel beachten! Paralyse bannen!"] = "ЗУЛ'ДЖИН: Следить за сменой облика! Паралич диспелить!"
L["Adler: Wirbelstürme meiden. Drachenfalke: Flammensäulen meiden."] = "Орел: обходить смерчи. Дракондор: обходить огненные столбы."
L["Prüfung des Kreuzfahrers"] = "Испытание крестоносца"
L["Anub'arak"] = "Ануб'арак"
L["Anub'arak + Nerubische Bohrer und Schwärmerskarabäen"] = "Ануб'арак + нерубские зарыватели и скарабеи роя"
L["- Pfählen (Untergrundphase): ein Stachel verfolgt einen Spieler -> wegrennen und den Stachel über Permafrost (Eisfelder) führen, dort bricht er ab."] = "- Прокалывание (подземная фаза): шип преследует игрока -> убегать и провести шип по вечной мерзлоте (ледяные поля), там он обрывается."
L["- Frostsphären: schweben im Raum -> runterschießen, sie erzeugen den Permafrost, den der Raid für Pfählen und die Bohrer braucht."] = "- Ледяные сферы: парят в зале -> сбивать, они создают вечную мерзлоту, которая нужна рейду для Прокалывания и зарывателей."
L["- Nerubische Bohrer: graben sich ein und heilen sich -> auf Permafrost tanken (dort können sie nicht eingraben), Schattenschlag unterbrechen."] = "- Нерубские зарыватели: закапываются и лечатся -> танковать на вечной мерзлоте (там они не могут закопаться), прерывать Удар тьмы."
L["- Durchdringende Kälte: Frost-Debuff mit hohem Schaden -> Ziele gezielt heilen."] = "- Пронизывающий холод: ледяной дебафф с высоким уроном -> целенаправленно хилить цели."
L["- Phase 3 (30 %): Heuschreckenschwarm mit dauerhaftem Raidschaden, Boss gräbt sich nicht mehr ein -> alle Abklingzeiten, schnell töten."] = "- Фаза 3 (30 %): Рой саранчи с постоянным уроном по рейду, босс больше не закапывается -> все кулдауны, быстро убить."
L["Taktik: Boss in der Mitte tanken, Bohrer vom Offtank auf Permafrost sammeln und mit AoE töten. Pfählen-Ziel rennt zum Permafrost; ab 30 % Heldentum und alles auf den Boss."] = "Тактика: босса танковать в центре, зарывателей офф-танк собирает на вечной мерзлоте и их убивают АоЕ. Цель Прокалывания бежит к мерзлоте; с 30 % героизм и всё в босса."
L["Heroisch: Bohrer unbedingt unterbrechen und kontrollieren, Permafrost knapp halten (Frostsphären nicht zu früh verbrauchen)."] = "Героик: зарывателей обязательно прерывать и контролить, мерзлоту экономить (ледяные сферы не сбивать слишком рано)."
L["ANUB'ARAK: Pfählen-Ziel zum Permafrost rennen! Bohrer auf Eis tanken!"] = "АНУБ'АРАК: цель Прокалывания бежит к мерзлоте! Зарывателей танковать на льду!"
L["Frostsphären runterschießen. Bei 30 % Heldentum, alles auf den Boss."] = "Сбивать ледяные сферы. На 30 % героизм, всё в босса."
L["Fraktionschampions"] = "Чемпионы фракций"
L["Fraktionschampions (6 bzw. 10 gegnerische Spieler-Champions)"] = "Чемпионы фракций (6 или 10 вражеских чемпионов-игроков)"
L["- Heiler-Champions: heilen sich gegenseitig und bannen -> unterbrechen, kontrollieren und zuerst töten."] = "- Чемпионы-хилы: лечат друг друга и диспелят -> прерывать, контролить и убивать первыми."
L["- Schutzzauber (Gottesschild, Eisblock, Schilde, HoTs) -> bannen bzw. Massenbannung auf Gottesschild."] = "- Защитные заклинания (Божественный щит, Ледяная глыба, щиты, HoT'ы) -> диспелить, на Божественный щит — Массовое рассеивание."
L["- Kontrolleffekte (Furcht, Verwandlung, Betäubung) auf den Raid -> bannen, Freiheitsfähigkeiten nutzen, Heiler schützen."] = "- Контроль (страх, превращение, оглушение) на рейд -> диспелить, использовать способности освобождения, защищать хилов."
L["- Nahkampf-Champions springen auf Heiler und Stoffträger -> Offtanks und CC fangen sie ab."] = "- Чемпионы ближнего боя прыгают на хилов и тканевиков -> офф-танки и СС их перехватывают."
L["- Abnehmende Wirkung (Diminishing Returns) gilt -> CC-Ziele fest einteilen, nicht doppelt kontrollieren."] = "- Действует уменьшение длительности (Diminishing Returns) -> жёстко распределить цели СС, не контролить дважды."
L["Taktik: Raid steht kompakt auf einer Seite, alle Champions markieren. Fokus-Ziel strikt nach Symbol (meist Heiler zuerst), Rest per CC und Unterbrechungen kontrollieren."] = "Тактика: рейд стоит кучно с одной стороны, всех чемпионов пометить. Фокус строго по метке (обычно сначала хилы), остальных держать под СС и киками."
L["Heroisch: Champions verursachen mehr Schaden; saubere Unterbrechungsrotation und CC-Zuweisungen sind Pflicht."] = "Героик: чемпионы наносят больше урона; чёткая ротация киков и распределение СС обязательны."
L["FRAKTIONSCHAMPIONS: Totenkopf fokussieren! Heiler unterbrechen, CC halten!"] = "ЧЕМПИОНЫ ФРАКЦИЙ: фокус на Череп! Кикать хилов, держать СС!"
L["Gottesschild/Eisblock bannen. Raid zusammen, Kontrolleffekte bannen."] = "Диспелить Божественный щит/Ледяную глыбу. Рейд вместе, снимать контроль."
L["Totenkopf = erstes Ziel, Kreuz = zweites, restliche Symbole für die CC-Ziele (Verwandlung, Furcht, Fesseln)."] = "Череп = первая цель, Крест = вторая, остальные метки на цели СС (превращение, страх, оковы)."
L["Lord Jaraxxus"] = "Лорд Джараксус"
L["Lord Jaraxxus + Infernos und Herrin des Schmerzes"] = "Лорд Джараксус + инферналы и Госпожа боли"
L["- Teufelsfeuerball: starker Feuerzauber auf den Tank -> unterbrechen, verbliebenen Debuff bannen."] = "- Огненный шар Скверны: мощное огненное заклинание по танку -> прерывать, оставшийся дебафф диспелить."
L["- Legionsflamme: Spieler hinterlässt eine Feuerspur -> an den Rand laufen, Feuer nicht im Raid ablegen."] = "- Пламя Легиона: игрок оставляет огненный след -> бежать к краю, не оставлять огонь в рейде."
L["- Fleischeinäscherung: Heilabsorb auf einem Spieler -> sofort komplett wegheilen, sonst Raidschaden."] = "- Испепеление плоти: поглощение исцеления на игроке -> сразу полностью отхилить, иначе урон по рейду."
L["- Netherkraft: stapelbarer Magie-Buff auf dem Boss -> per Zauberraub/Magiebannung entfernen."] = "- Сила Пустоты: стакающийся магический бафф на боссе -> снимать Чарокрадством/диспелом магии."
L["- Netherportal / Infernalischer Vulkan: rufen Herrin des Schmerzes bzw. Infernos -> Herrin vom Offtank, Infernos per AoE."] = "- Портал Пустоты / Инфернальный вулкан: призывают Госпожу боли или инферналов -> Госпожу берёт офф-танк, инферналов АоЕ."
L["Taktik: Boss in der Mitte tanken, Herrin des Schmerzes und Infernos vom Boss weg holen und zuerst töten. Feuerspuren an den Rand legen, Feuerball konsequent unterbrechen."] = "Тактика: босса танковать в центре, Госпожу боли и инферналов отвести от босса и убить первыми. Огненные следы класть у края, Огненный шар стабильно прерывать."
L["Heroisch: Portale und Vulkane schnell zerstören, sonst kommen immer mehr Adds."] = "Героик: порталы и вулканы быстро уничтожать, иначе аддов становится всё больше."
L["JARAXXUS: Teufelsfeuerball unterbrechen! Legionsflamme an den Rand!"] = "ДЖАРАКСУС: кикать Огненный шар Скверны! Пламя Легиона к краю!"
L["Fleischeinäscherung wegheilen. Netherkraft stehlen/bannen, Adds zuerst."] = "Отхилить Испепеление плоти. Силу Пустоты красть/диспелить, сначала адды."
L["Bestien von Nordend"] = "Чудовища Нордскола"
L["Bestien von Nordend: Gormok der Pfähler, Säureschlund & Schreckensschuppe, Eisheuler"] = "Чудовища Нордскола: Гормок Пронзающий Бивень, Кислотная Утроба и Жуткая Чешуя, Ледяной Рев"
L["- Gormok: Pfählen stapelt Blutungs-Debuff auf dem Tank -> Tankwechsel; Schneebolde springen auf Spieler -> sofort töten."] = "- Гормок: Прокалывание стакает дебафф кровотечения на танке -> смена танков; снобольды прыгают на игроков -> сразу убивать."
L["- Säureschlund & Schreckensschuppe: Paralysegift und Brennende Galle -> vergiftete Spieler zu einem Galle-Ziel laufen, um die Paralyse aufzuheben."] = "- Кислотная Утроба и Жуткая Чешуя: Парализующий яд и Жгучая желчь -> отравленные бегут к цели с желчью, чтобы снять паралич."
L["- Würmer wechseln zwischen beweglich und stationär -> getrennt tanken, Giftpfützen meiden."] = "- Черви переключаются между подвижной и неподвижной формой -> танковать раздельно, избегать ядовитых луж."
L["- Eisheuler: Massiver Krach stößt den Raid um, danach Wilder Ansturm auf einen Spieler -> aus der Laufbahn gehen, Boss ist nach Wandaufprall betäubt."] = "- Ледяной Рев: Сокрушительный удар раскидывает рейд, затем Яростный рывок на игрока -> уйти с линии рывка, после удара о стену босс оглушён."
L["Taktik: Gormok am Eingang tanken und Schneebolde töten, Würmer möglichst gleichzeitig töten. Bei Eisheuler weit verteilen und dem Ansturm ausweichen, dann voller Schaden."] = "Тактика: Гормока танковать у входа и убивать снобольдов, червей по возможности убить одновременно. На Ледяном Реве широко рассредоточиться и уклоняться от рывка, затем полный урон."
L["Heroisch: Die nächste Bestie kommt nach Zeit, auch wenn die vorige noch lebt – Schaden zählt."] = "Героик: следующее чудовище выходит по таймеру, даже если предыдущее ещё живо — решает ДПС."
L["BESTIEN: Schneebolde töten! Gift-Spieler zu Brennende-Galle-Spielern!"] = "ЧУДОВИЩА: убивать снобольдов! Отравленные к игрокам с Жгучей желчью!"
L["Würmer gleichzeitig runter. Eisheuler: Ansturm ausweichen, dann Schaden."] = "Червей опустить одновременно. Ледяной Рев: уклоняться от рывка, затем урон."
L["Zwillingsval'kyr"] = "Валь'киры-близнецы"
L["Zwillingsval'kyr: Fjola (Licht) und Eydis (Dunkelheit)"] = "Валь'киры-близнецы: Фьола (Свет) и Эйдис (Тьма)"
L["- Licht-/Dunkelessenz: Spieler nehmen an den Portalen eine Farbe an -> Kugeln der eigenen Farbe einsammeln (Buff), Kugeln der Gegenfarbe meiden."] = "- Сущность Света/Тьмы: игроки берут цвет у порталов -> собирать сферы своего цвета (бафф), избегать сфер противоположного цвета."
L["- Wirbel (Licht oder Dunkel): großer Raidschaden -> vorher alle die Farbe des wirbelnden Bosses annehmen."] = "- Вихрь (Света или Тьмы): сильный урон по рейду -> заранее всем взять цвет босса, который кастует вихрь."
L["- Schild + Zwillingspakt: Boss heilt sich -> Schild mit der Gegenfarbe brechen und den Pakt unterbrechen."] = "- Щит + Договор близнецов: босс лечится -> пробить щит противоположным цветом и прервать Договор."
L["- Berührung des Lichts/der Dunkelheit (Heroisch): Debuff -> Spieler wechselt auf die passende Essenz."] = "- Касание Света/Тьмы (героик): дебафф -> игрок меняет сущность на соответствующую."
L["Taktik: Beide Valkyr getrennt tanken, Raid nach Ansage auf die passende Farbe. Gemeinsamer Lebenspool – auf einen Boss Schaden machen, Schilde und Pakt sofort brechen."] = "Тактика: обеих валь'кир танковать раздельно, рейд по команде берёт нужный цвет. Общий запас здоровья — бить одного босса, щиты и Договор сразу ломать."
L["ZWILLINGE: Farbe des Wirbels annehmen! Schild brechen, Pakt unterbrechen!"] = "БЛИЗНЕЦЫ: взять цвет вихря! Пробить щит, прервать Договор!"
L["Eigene Farbe Kugeln sammeln, fremde Kugeln meiden."] = "Собирать сферы своего цвета, чужие избегать."
L["Das Auge der Ewigkeit"] = "Око Вечности"
L["Malygos"] = "Малигос"
L["Malygos + Nexuslords, Funken der Macht, Ewigkeitsgeweihte"] = "Малигос + повелители Нексуса, искры энергии, потомки Вечности"
L["- Funke der Macht: fliegt zu Malygos und verstärkt ihn -> abfangen und von ihm weg töten, Spieler stehen in der Pfütze für Schadensbonus."] = "- Искра энергии: летит к Малигосу и усиливает его -> перехватить и убить подальше от него, игроки стоят в луже ради бонуса к урону."
L["- Arkaner Atem / Wirbel: Raid wird hochgewirbelt -> Heiler halten den Raid oben, danach wieder sammeln."] = "- Чародейское дыхание / Вихрь: рейд подбрасывает вверх -> хилы держат рейд, потом снова собраться."
L["- Phase 2: Arkane Schübe und Nexuslords/Ewigkeitsgeweihte auf Scheiben -> unter Schutzblasen stellen, Adds töten und deren Scheiben übernehmen."] = "- Фаза 2: Чародейские импульсы и повелители Нексуса/потомки Вечности на дисках -> вставать под защитные пузыри, убивать аддов и забирать их диски."
L["- Phase 3: Raid fliegt auf roten Drachen -> Schadens-, Schild- und Heilfähigkeiten der Drachen koordiniert nutzen, Statischen Feldern ausweichen."] = "- Фаза 3: рейд летит на красных драконах -> координированно использовать способности драконов на урон, щит и хил, уклоняться от Статических полей."
L["Taktik: P1 Boss am Rand tanken und Funken abfangen; P2 Adds per Fernkampf und Scheiben töten, Blasen nutzen; P3 Drachenfähigkeiten koordiniert einsetzen."] = "Тактика: Ф1 босса танковать у края и перехватывать искры; Ф2 аддов убивать ренжем и с дисков, использовать пузыри; Ф3 координированно использовать способности драконов."
L["MALYGOS: Funken abfangen und von ihm weg töten! In der Pfütze stehen!"] = "МАЛИГОС: перехватывать искры и убивать подальше от него! Стоять в луже!"
L["P2: Unter die Blase, Adds auf Scheiben töten. P3: Drachen-Combos nutzen."] = "Ф2: под пузырь, убивать аддов на дисках. Ф3: использовать комбо драконов."
L["Eiskronenzitadelle"] = "Цитадель Ледяной Короны"
L["Sindragosa"] = "Синдрагоса"
L["- Entfesselte Magie: Zauberer erleiden Schaden pro Zauber -> bei hohen Stapeln kurz nicht zaubern; Nahkampf achtet auf Frost-Stapel (Bis auf die Knochen)."] = "- Высвобожденная магия: кастеры получают урон за каждое заклинание -> при высоких стаках ненадолго прекратить каст; мили следят за ледяными стаками (Промерзание до костей)."
L["- Durchdringende Kälte (Blistering Cold): großer Schaden im Nahbereich nach Eisgriff -> sofort mindestens 25 m weg vom Boss."] = "- Обжигающий холод (Blistering Cold): сильный урон вблизи после Ледяной хватки -> сразу минимум 25 м от босса."
L["- Frostleuchtfeuer: Ziele werden zu Eisgräbern -> in festgelegter Formation stehen, Gräber zum Sichtschutz nutzen."] = "- Ледяная метка: цели превращаются в ледяные гробницы -> стоять в заданной формации, использовать гробницы как укрытие от обзора."
L["- Luftphase: Frostbomben -> hinter Eisgrab verstecken, danach Gräber freischlagen."] = "- Воздушная фаза: ледяные бомбы -> прятаться за ледяной гробницей, потом разбить гробницы."
L["- Phase 3 (35 %): Mysteriöse Energie stapelt auf Spielern -> per Sichtlinie hinter Eisgrab zurücksetzen."] = "- Фаза 3 (35 %): Магический удар стакается на игроках -> сбрасывать за ледяной гробницей через линию обзора."
L["Taktik: Boss seitlich tanken, Raid hinter ihr gestaffelt. Eisgräber nach Plan platzieren, in P3 Tankwechsel und Stapel per Grab-Sichtschutz abbauen."] = "Тактика: босса танковать боком, рейд эшелоном за ней. Ледяные гробницы ставить по плану, в Ф3 смена танков и сброс стаков за гробницей."
L["SINDRAGOSA: Nach Eisgriff sofort weg vom Boss! Frostbombe: hinter Eisgrab!"] = "СИНДРАГОСА: после Ледяной хватки сразу от босса! Ледяная бомба: за гробницу!"
L["Entfesselte Magie: weniger zaubern. P3 Stapel hinter Gräbern abbauen."] = "Высвобожденная магия: меньше кастовать. Ф3 сбрасывать стаки за гробницами."
L["Valithria Traumwandler"] = "Валитрия Сноходица"
L["Valithria Traumwandler + untote Adds aus den Portalen"] = "Валитрия Сноходица + нежить-адды из порталов"
L["- Ziel: Valithria auf 100 % heilen -> Heiler heilen nur sie, Schaden auf die Adds."] = "- Цель: отхилить Валитрию до 100 % -> хилы лечат только её, урон по аддам."
L["- Traumportale: Heiler fliegen in die Traumwelt und sammeln Nebelwolken -> starker Heilungsbonus."] = "- Порталы сна: хилы летят в мир снов и собирают облака -> сильный бонус к исцелению."
L["- Unterdrücker: reduzieren die Heilung auf Valithria -> schnell töten bzw. kontrollieren."] = "- Подавители: снижают исцеление на Валитрии -> быстро убивать или контролить."
L["- Brennende Skelette und Erzmagier: hoher Schaden/Raid-AoE -> sofort töten, Frostbomben-Zielen ausweichen."] = "- Пылающие скелеты и верховные маги: высокий урон/АоЕ по рейду -> сразу убивать, уклоняться от целей ледяных бомб."
L["- Verderbte Abscheulichkeiten/Zombies: verlangsamen bzw. explodieren -> von Tanks gehalten, außerhalb des Raids töten."] = "- Прожорливые поганища/зомби: замедляют или взрываются -> их держат танки, убивать вне рейда."
L["Taktik: Raid in zwei Gruppen an beiden Seiten für die Portale, Tanks sammeln die Adds. Heiler rotieren durch die Traumwelt, DPS fokussiert Unterdrücker und Skelette."] = "Тактика: рейд двумя группами с обеих сторон у порталов, танки собирают аддов. Хилы по очереди летают в мир снов, ДПС фокусит подавителей и скелетов."
L["VALITHRIA: Heiler nur auf Valithria! Unterdrücker und Skelette zuerst!"] = "ВАЛИТРИЯ: хилы только на Валитрию! Подавители и скелеты первыми!"
L["Heiler in die Portale, Nebel sammeln. Adds weg vom Raid tanken."] = "Хилы в порталы, собирать облака. Аддов танковать подальше от рейда."
L["Rat der Blutprinzen"] = "Совет принцев крови"
L["Rat der Blutprinzen: Valanar, Keleseth, Taldaram"] = "Совет принцев крови: Валанар, Келесет, Талдарам"
L["- Nur ein Prinz ist verstärkt und nimmt echten Schaden -> Ziel beim Wechsel umstellen."] = "- Усилен только один принц и только он получает реальный урон -> при смене переключать цель."
L["- Valanar: Schockwirbel, verstärkt als großer Raidwirbel -> verteilen und aus Wirbeln raus."] = "- Валанар: Шоковый вихрь, в усиленном виде — большой вихрь по рейду -> рассредоточиться и выйти из вихрей."
L["- Keleseth: Schattenlanze und Dunkle Kerne -> von einem Fernkampf-Tank (z. B. Hexer) gehalten, Kerne mitnehmen."] = "- Келесет: Теневое копьё и Тёмные ядра -> держит ренж-танк (напр. чернокнижник), ядра забирать на себя."
L["- Taldaram: Flammenkugel verfolgt einen Spieler -> Ziel zieht sie vom Raid weg."] = "- Талдарам: Огненный шар преследует игрока -> цель уводит его от рейда."
L["- Kinetische Bomben: fallen langsam -> durch Fernkampf in der Luft halten, nicht aufschlagen lassen."] = "- Кинетические бомбы: медленно падают -> ренж держит их в воздухе, не давать упасть."
L["Taktik: Valanar und Taldaram von Nahkampf-Tanks, Keleseth vom Fernkampf-Tank; nur den verstärkten Prinzen voll beschießen, Bomben oben halten, Flammenkugeln kiten."] = "Тактика: Валанара и Талдарама держат мили-танки, Келесета — ренж-танк; полностью бить только усиленного принца, бомбы держать наверху, огненные шары кайтить."
L["BLUTPRINZEN: Nur auf den verstärkten Prinzen! Kinetische Bomben oben halten!"] = "ПРИНЦЫ КРОВИ: только по усиленному принцу! Кинетические бомбы держать наверху!"
L["Flammenkugel wegziehen. Bei Valanar-Wirbel verteilen."] = "Огненный шар уводить. На вихре Валанара рассредоточиться."
L["Blutkönigin Lana'thel"] = "Королева Лана'тель"
L["- Essenz der Blutkönigin: gebissene Spieler müssen nach einiger Zeit einen anderen Spieler beißen -> feste Beißliste, sonst Gedankenkontrolle."] = "- Сущность Кровавой королевы: укушенные игроки через время должны укусить другого -> фиксированный список укусов, иначе контроль разума."
L["- Pakt der Dunkelgefallenen: verbundene Spieler nehmen Schaden -> sofort zueinander laufen."] = "- Договор Падших: связанные игроки получают урон -> сразу бежать друг к другу."
L["- Schwärmende Schatten: Ziel hinterlässt Schattenpfütze -> am Rand ablegen, nicht durch den Raid laufen."] = "- Роящиеся тени: цель оставляет теневую лужу -> класть у края, не бегать через рейд."
L["- Luftphase: Blutwirbel und Furcht -> verteilt stehen, Heiler bereit."] = "- Воздушная фаза: Вихрь кровавых стрел и страх -> стоять рассредоточенно, хилы наготове."
L["Taktik: Boss zentral tanken, Fernkampf locker verteilt, Schatten an den Rand. Beißreihenfolge vorher festlegen (Schaden zuerst), Pakt-Spieler treffen sich sofort."] = "Тактика: босса танковать в центре, ренж свободно рассредоточен, тени к краю. Порядок укусов заранее (сначала ДПС), игроки с Договором сразу сходятся."
L["LANA'THEL: Beißliste einhalten! Pakt-Ziele sofort zueinander!"] = "ЛАНА'ТЕЛЬ: соблюдать список укусов! Цели Договора сразу друг к другу!"
L["Schwärmende Schatten an den Rand legen. Luftphase verteilt stehen."] = "Роящиеся тени класть у края. В воздушной фазе стоять рассредоточенно."
L["Der Lichkönig"] = "Король-лич"
L["Der Lichkönig + Ghule, Schreckliche Schrecken, Val'kyr, Eissphären, Wütende Geister"] = "Король-лич + вурдалаки, шаркающие ужасы, валь'киры, ледяные сферы, буйные духи"
L["- Phase 1: Nekrotische Seuche springt beim Bannen -> auf einen Schrecklichen Schrecken bannen; Schrecken-Raserei per Einlullen beruhigen."] = "- Фаза 1: Мертвящая чума прыгает при диспеле -> диспелить на шаркающего ужаса; бешенство ужаса снимать Усмиряющим выстрелом."
L["- Zwischenphasen: Unbarmherziger Winter -> an den Rand, Eissphären und Wütende Geister töten bzw. ausweichen."] = "- Промежуточные фазы: Безжалостная зима -> к краю, ледяные сферы и буйных духов убивать или уклоняться."
L["- Phase 2: Val'kyr tragen Spieler zum Rand -> sofort töten bzw. verlangsamen; Entweihen -> aus dem Kreis raus, am Rand ablegen."] = "- Фаза 2: валь'киры уносят игроков к краю -> сразу убивать или замедлять; Осквернение -> выйти из круга, класть у края."
L["- Phase 3: Seele ernten zieht Spieler in Frostgram -> dort Geist töten/überleben; Üble Geister -> wegkiten, nicht berühren."] = "- Фаза 3: Сбор души затягивает игрока в Ледяную Скорбь -> там убить духа/выжить; Злобные духи -> кайтить, не касаться."
L["- Zersprengen (Infest): Raidweiter Schaden -> Raid über 90 % hochheilen."] = "- Заражение (Infest): урон по всему рейду -> отхиливать рейд выше 90 %."
L["Taktik: Boss am Rand vom Eingang tanken, Adds sauber töten. P2 Val'kyr fokussieren und Entweihen am Rand ablegen, P3 Geister kiten und Seele ernten mit Abklingzeiten überbrücken."] = "Тактика: босса танковать у края со стороны входа, аддов чисто убивать. Ф2 фокус на валь'кир и Осквернение класть у края, Ф3 кайтить духов и Сбор души перекрывать кулдаунами."
L["LICHKÖNIG: Val'kyr sofort töten! Entweihen am Rand ablegen!"] = "КОРОЛЬ-ЛИЧ: валь'кир убивать сразу! Осквернение класть у края!"
L["Seuche auf Schrecken bannen. Winter: an den Rand, Sphären/Geister töten."] = "Чуму диспелить на ужаса. Зима: к краю, убивать сферы/духов."
L["Val'kyr"] = "Валь'киры"
L["Totenkopf, Kreuz und Viereck auf die Val'kyr in Phase 2, in dieser Reihenfolge töten bzw. verlangsamen."] = "Череп, Крест и Квадрат на валь'кир во 2-й фазе, убивать или замедлять в этом порядке."
L["Todesbringer Saurfang"] = "Саурфанг Смертоносный"
L["Todesbringer Saurfang + Blutbestien"] = "Саурфанг Смертоносный + кровавые чудовища"
L["- Mal des gefallenen Champions: betroffener Spieler wird auf Dauer geschwächt, sein Tod heilt den Boss -> Spieler unbedingt am Leben halten."] = "- Метка павшего воителя: игрок надолго ослаблен, его смерть лечит босса -> обязательно держать игрока живым."
L["- Blutmacht: Boss gewinnt Macht durch erlittenen/verursachten Schaden -> Schaden an Spielern möglichst gering halten."] = "- Сила крови: босс набирает силу от полученного/нанесённого урона -> урон по игрокам держать как можно ниже."
L["- Blutbestien: erscheinen periodisch -> Fernkampf tötet sie schnell, verlangsamen und nicht zum Raid lassen."] = "- Кровавые чудовища: появляются периодически -> ренж быстро убивает, замедлять и не пускать к рейду."
L["- Kochendes Blut / Blutnova: Blutungs- und Flächenschaden -> Fernkampf verteilt, Heiler aufmerksam."] = "- Кипящая кровь / Кровавый взрыв: кровотечение и урон по площади -> ренж рассредоточен, хилы внимательны."
L["- Runenblut auf dem Tank -> Tankwechsel."] = "- Руна крови на танке -> смена танков."
L["Taktik: Boss in der Mitte tanken, Fernkampf in einem lockeren Halbkreis. Bestien sofort mit Verlangsamung und Fokus töten, so wenig Male wie möglich zulassen."] = "Тактика: босса танковать в центре, ренж свободным полукругом. Чудовищ сразу замедлять и убивать фокусом, допускать как можно меньше меток."
L["SAURFANG: Blutbestien sofort töten und verlangsamen! Male am Leben halten!"] = "САУРФАНГ: кровавых чудовищ сразу убивать и замедлять! Метки держать живыми!"
L["Fernkampf verteilt. Bei Runenblut Tankwechsel."] = "Ренж рассредоточен. На Руне крови смена танков."
L["Blutbestien"] = "Кровавые чудовища"
L["Totenkopf zuerst, dann Kreuz usw.; Jäger und Frostzauberer verlangsamen die Bestien."] = "Сначала Череп, потом Крест и т. д.; охотники и фрост-маги замедляют чудовищ."
L["Lady Todeswisper"] = "Леди Смертный Шёпот"
L["Lady Todeswisper + Kultfanatiker und Kultanhänger"] = "Леди Смертный Шёпот + фанатики и последователи культа"
L["- Manabarriere (Phase 1): Schaden geht auf ihr Mana -> Fernkampf auf den Boss, bis das Mana leer ist."] = "- Барьер маны (фаза 1): урон идёт в её ману -> ренж бьёт босса, пока мана не кончится."
L["- Kultisten-Wellen von den Seiten -> Fanatiker an Tanks, Anhänger per Fernkampf; wiederbelebte Kultisten zuerst."] = "- Волны культистов с боков -> фанатики на танков, последователи на ренж; воскрешённые культисты первыми."
L["- Tod und Verfall: Schattenfeld auf dem Boden -> sofort raus."] = "- Смерть и разложение: теневое поле на полу -> сразу выйти."
L["- Phase 2: Frostblitz und Frostblitzsalve -> unterbrechen; Berührung der Bedeutungslosigkeit stapelt -> Tankwechsel."] = "- Фаза 2: Ледяная стрела и Залп ледяных стрел -> прерывать; Прикосновение ничтожности стакается -> смена танков."
L["- Rachsüchtige Schatten: verfolgen einen Spieler -> weglaufen, Fernkampf tötet sie."] = "- Мстительные духи: преследуют игрока -> убегать, ренж их убивает."
L["Taktik: P1 Fernkampf baut Mana ab, Nahkampf und Tanks töten die Kultisten. P2 Boss in der Mitte tanken, Frostblitze unterbrechen und Schatten auskiten."] = "Тактика: Ф1 ренж сбивает ману, мили и танки убивают культистов. Ф2 босса танковать в центре, Ледяные стрелы прерывать и кайтить духов."
L["TODESWISPER: P1 Mana runter, Adds zuerst! Aus Tod und Verfall raus!"] = "СМЕРТНЫЙ ШЁПОТ: Ф1 сбить ману, сначала адды! Выйти из Смерти и разложения!"
L["P2: Frostblitz unterbrechen, Schatten wegkiten. Tankwechsel beachten."] = "Ф2: кикать Ледяную стрелу, кайтить духов. Следить за сменой танков."
L["Kultisten"] = "Культисты"
L["Pro Welle Adds markieren, Totenkopf/Kreuz zuerst; Fanatiker an Tanks, Anhänger per Fernkampf."] = "Каждую волну аддов метить, сначала Череп/Крест; фанатики на танков, последователи на ренж."
L["Luftschiffkampf"] = "Битва на кораблях"
L["Luftschiffkampf (Muradin Bronzebart bzw. Hochfürst Saurfang) + Entertrupps"] = "Битва на кораблях (Мурадин Бронзобород или верховный правитель Саурфанг) + абордажные отряды"
L["- Raketenrucksack: Entergruppe springt aufs feindliche Schiff -> Gewehrschützen/Axtwerfer und Mörser töten, Magier unterbrechen."] = "- Реактивный ранец: абордажная группа прыгает на вражеский корабль -> убить стрелков/метателей топоров и мортирщиков, прерывать мага."
L["- Feindlicher Kampfmagier friert die Kanonen ein -> Magier töten, damit die Kanonen wieder feuern."] = "- Вражеский боевой маг замораживает пушки -> убить мага, чтобы пушки снова стреляли."
L["- Kanonen: Spieler in den Kanonen schießen aufs Schiff -> Hitze beachten, Spezialschuss bei vollem Balken."] = "- Пушки: игроки в пушках стреляют по кораблю -> следить за перегревом, спецвыстрел при полной шкале."
L["- Enterer auf eigenem Schiff -> Tank holt sie, Raid tötet sie; Kommandant auf dem Gegnerschiff nur kurz tanken."] = "- Абордажники на своём корабле -> танк их берёт, рейд убивает; командира на вражеском корабле танковать недолго."
L["Taktik: Zwei Spieler in die Kanonen, Entergruppe (Tank + DPS) springt über, Rest verteidigt das eigene Schiff. Schaden aufs feindliche Schiff bis es zerstört ist."] = "Тактика: два игрока в пушки, абордажная группа (танк + ДПС) прыгает на врага, остальные защищают свой корабль. Урон по вражескому кораблю, пока он не уничтожен."
L["LUFTSCHIFF: Magier auf dem Gegnerschiff töten, Kanonen feuern!"] = "КОРАБЛИ: убить мага на вражеском корабле, пушки стреляют!"
L["Enterer auf eigenem Schiff töten, Entergruppe springt über."] = "Убивать абордажников на своём корабле, абордажная группа прыгает."
L["Lord Mark'gar"] = "Лорд Ребрад"
L["- Knochenstachel: spießt Spieler auf -> Stachel sofort zerstören."] = "- Костяной шип: насаживает игрока -> шип сразу уничтожить."
L["- Knochensturm: wirbelt durch den Raum mit hohem Schaden -> Abstand halten, Nahkampf kurz raus."] = "- Костяной вихрь: носится по залу с высоким уроном -> держать дистанцию, мили ненадолго выходят."
L["- Kalte Flamme: Feuerlinien vom Boss -> ausweichen, nicht drin stehen."] = "- Холодное пламя: огненные линии от босса -> уклоняться, не стоять в них."
L["- Säbelhieb: Schaden wird auf die nahen Ziele aufgeteilt -> zwei Tanks nebeneinander vorne."] = "- Удар саблей: урон делится между ближайшими целями -> два танка рядом спереди."
L["Taktik: Boss mittig tanken, Fernkampf locker verteilt. Knochenstacheln sofort zerstören, während Knochensturm verteilt stehen und Flammen ausweichen."] = "Тактика: босса танковать в центре, ренж свободно рассредоточен. Костяные шипы сразу уничтожать, во время Костяного вихря стоять раздельно и уклоняться от пламени."
L["MARK'GAR: Knochenstacheln sofort zerstören! Kalten Flammen ausweichen!"] = "РЕБРАД: костяные шипы сразу уничтожать! Уклоняться от Холодного пламени!"
L["Knochensturm: verteilt bleiben. Tanks nebeneinander für Säbelhieb."] = "Костяной вихрь: оставаться рассредоточенными. Танки рядом для Удара саблей."
L["Fauldarm"] = "Тухлопуз"
L["- Inhalierte Seuche: nach 3 Stapeln folgt Durchdringender Ausbruch mit sehr hohem Schaden -> vorher Impfung gestapelt haben, Abklingzeiten nutzen."] = "- Вдыхание гнили: после 3 стаков следует Едкая гниль с очень сильным уроном -> заранее набрать стаки Прививки, использовать кулдауны."
L["- Gasartige Sporen: auf mehreren Spielern -> Sporenträger in Gruppen platzieren, jeder bekommt Impfung."] = "- Газовые споры: на нескольких игроках -> носителей спор ставить в группы, каждый получает Прививку."
L["- Magenblähung: stapelt auf dem Tank -> Tankwechsel nach Absprache (vor 9 Stapeln)."] = "- Вздутие желудка: стакается на танке -> смена танков по договорённости (до 9 стаков)."
L["- Übles Gas: Fernkampf-Spieler erhalten Schaden -> Fernkampf in Abstand verteilt in kleinen Gruppen."] = "- Гнусный газ: ренж-игроки получают урон -> ренж рассредоточен небольшими группами на расстоянии."
L["Taktik: Boss in der Mitte tanken, Fernkampf in 2–3 Gruppen rundum. Sporen in die Gruppen verteilen, Tankwechsel nach Magenblähung, beim Ausbruch volle Heilung."] = "Тактика: босса танковать в центре, ренж в 2–3 группах вокруг. Споры распределить по группам, смена танков по Вздутию желудка, на Едкой гнили полный хил."
L["FAULDARM: Sporen-Gruppen bilden, Impfung stapeln! Tankwechsel beachten!"] = "ТУХЛОПУЗ: собраться в группы со спорами, набирать Прививку! Следить за сменой танков!"
L["3. Seuchen-Stapel: Abklingzeiten. Fernkampf verteilt."] = "3-й стак гнили: кулдауны. Ренж рассредоточен."
L["Professor Seuchenmord"] = "Профессор Мерзоцид"
L["Professor Seuchenmord + Schlamm und Gaswolke"] = "Профессор Мерзоцид + слизнюк и газовое облако"
L["- Instabiles Experiment: grüner Schlamm haftet an einem Spieler -> ganzer Raid stapelt auf dem Ziel, Schaden teilen."] = "- Нестабильный эксперимент: зелёный слизнюк цепляется к игроку -> весь рейд стакается на цели, делить урон."
L["- Orange Gaswolke: verfolgt einen Spieler -> Ziel kitet die Wolke, Rest verteilt sich; Schlamm/Wolke per Abscheulichkeit verlangsamen."] = "- Оранжевое газовое облако: преследует игрока -> цель кайтит облако, остальные рассредоточены; слизнюка/облако замедлять поганищем."
L["- Formbarer Schleim: wird auf Spieler geworfen -> ausweichen, stark verlangsamt."] = "- Податливая слизь: бросается в игроков -> уклоняться, сильно замедляет."
L["- Phase 3: Mutierte Seuche stapelt auf den Tanks -> Tankwechsel."] = "- Фаза 3: Мутировавшая чума стакается на танках -> смена танков."
L["- Unbändige Seuche (Heroisch): wandert zwischen Spielern -> sofort weitergeben."] = "- Неустойчивая чума (героик): переходит между игроками -> сразу передавать дальше."
L["Taktik: Boss tanken, ein Spieler steuert die Abscheulichkeit (verlangsamt Adds). Bei grünem Schlamm stapeln, bei oranger Wolke verteilen, P3 schnell mit Tankwechsel."] = "Тактика: босса танковать, один игрок управляет поганищем (замедляет аддов). На зелёном слизнюке стакаться, на оранжевом облаке рассредоточиться, Ф3 быстро со сменой танков."
L["SEUCHENMORD: Grüner Schlamm -> alle stapeln! Orange Wolke -> verteilen!"] = "МЕРЗОЦИД: зелёный слизнюк -> все в стак! Оранжевое облако -> рассредоточиться!"
L["Formbarem Schleim ausweichen. Phase 3: Tankwechsel nach Seuche."] = "Уклоняться от Податливой слизи. Фаза 3: смена танков по чуме."
L["Modermiene"] = "Гниломорд"
L["Modermiene + kleine und große Schlammbrocken"] = "Гниломорд + малые и большие слизнюки"
L["- Mutierte Infektion: Debuff -> Spieler läuft an den Rand und wird gebannt, dort entsteht ein kleiner Schlamm."] = "- Мутировавшая инфекция: дебафф -> игрок бежит к краю, его диспелят, там появляется малый слизнюк."
L["- Kleine Schlämme: verbinden sich zu großen -> Offtank sammelt kleine ein und führt den großen am Rand."] = "- Малые слизнюки: сливаются в больших -> офф-танк собирает малых и водит большого у края."
L["- Instabile Schlammexplosion: großer Schlamm explodiert bei 5 Stapeln -> Raid weit weg verteilen."] = "- Взрыв нестабильного слизнюка: большой слизнюк взрывается на 5 стаках -> рейд далеко рассредоточен."
L["- Schlammfontäne: Kegel vor dem Boss -> raus aus dem Kegel."] = "- Струя слизи: конус перед боссом -> выйти из конуса."
L["Taktik: Boss in der Mitte tanken, Offtank kitet die Schlämme am Rand. Infizierte Spieler gehen zum Offtank, Explosionen ausweichen."] = "Тактика: босса танковать в центре, офф-танк кайтит слизнюков у края. Заражённые идут к офф-танку, уклоняться от взрывов."
L["MODERMIENE: Infizierte zum Rand/Offtank! Explosion ausweichen!"] = "ГНИЛОМОРД: заражённые к краю/офф-танку! Уклоняться от взрыва!"
L["Schlammfontäne: aus dem Kegel. Fernkampf locker verteilt."] = "Струя слизи: выйти из конуса. Ренж свободно рассредоточен."
L["Anub'Rekhan"] = "Ануб'Рекан"
L["Anub'Rekhan + Gruftwachen und Gruftskarabäen"] = "Ануб'Рекан + стражи склепа и скарабеи-трупоеды"
L["- Heuschreckenschwarm: hoher Schaden um den Boss -> Tank kitet den Boss durch den Raum, Raid hält Abstand."] = "- Рой саранчи: сильный урон вокруг босса -> танк кайтит босса по залу, рейд держит дистанцию."
L["- Pfählen: Linie mit Wurf in die Luft -> ausweichen, Ziele heilen."] = "- Прокалывание: линия с подбрасыванием в воздух -> уклоняться, хилить цели."
L["- Gruftwachen: Add mit Spalten -> vom Offtank halten und töten."] = "- Стражи склепа: адд с рассекающим ударом -> держит и убивает офф-танк."
L["Taktik: Boss am Rand tanken, Gruftwachen vom Offtank. Beim Schwarm kitet der Tank um den Raum, Raid bleibt weit weg und wartet ab."] = "Тактика: босса танковать у края, стражей склепа берёт офф-танк. Во время роя танк кайтит по залу, рейд держится далеко и пережидает."
L["ANUB'REKHAN: Heuschreckenschwarm -> weg vom Boss! Tank kiten!"] = "АНУБ'РЕКАН: Рой саранчи -> от босса! Танк кайтит!"
L["Gruftwachen vom Offtank. Pfählen ausweichen."] = "Стражи склепа на офф-танке. Уклоняться от Прокалывания."
L["Großwitwe Faerlina"] = "Великая вдова Фарлина"
L["- Raserei: Boss teilt stark mehr Schaden aus -> einen Verehrer neben ihr töten (Witwenumarmung beendet die Raserei)."] = "- Бешенство: босс наносит намного больше урона -> убить почитателя рядом с ней (Объятия вдовы снимают бешенство)."
L["- Giftblitzsalve: Raidweites Gift -> heilen, Gift entfernen."] = "- Залп отравленных стрел: яд по всему рейду -> хилить, снимать яд."
L["Taktik: Anhänger zuerst töten, Verehrer für die Raserei aufheben. Boss zentral tanken, Feuerregen meiden."] = "Тактика: сначала убить последователей, почитателей оставить для бешенства. Босса танковать в центре, избегать Огненного ливня."
L["FAERLINA: Anhänger zuerst! Raserei -> Verehrer neben Boss töten!"] = "ФАРЛИНА: сначала последователи! Бешенство -> убить почитателя рядом с боссом!"
L["Feuerregen meiden. Gift entfernen."] = "Избегать Огненного ливня. Снимать яд."
L["Totenkopf/Kreuz auf die Anhänger (zuerst töten), Viereck/Mond auf die Verehrer für die Raserei."] = "Череп/Крест на последователей (убить первыми), Квадрат/Луна на почитателей для бешенства."
L["Maexxna"] = "Мексна"
L["- Netzwickel: Spieler hängen an der Wand -> Fernkampf befreit sie."] = "- Кокон: игроки висят на стене -> ренж их освобождает."
L["- Netzspray: Raid betäubt -> Heiler vorher HoTs und Tank vollheilen."] = "- Паутина: рейд оглушён -> хилы заранее HoT'ы и танка в фулл."
L["- Spinnenjunge: kleine Adds -> per AoE töten."] = "- Паучки: мелкие адды -> убивать АоЕ."
L["- Raserei bei 30 % -> Abklingzeiten auf Tank."] = "- Бешенство на 30 % -> кулдауны на танка."
L["Taktik: Boss mittig tanken, Fernkampf befreit Eingewickelte und tötet Junge. Vor dem Netzspray den Tank hochheilen."] = "Тактика: босса танковать в центре, ренж освобождает коконы и убивает паучков. Перед Паутиной отхилить танка."
L["MAEXXNA: Eingewickelte befreien! Vor Netzspray Tank voll heilen!"] = "МЕКСНА: освобождать коконы! Перед Паутиной танка в фулл!"
L["Spinnenjunge per AoE. Bei 30 % Raserei: Abklingzeiten."] = "Паучков АоЕ. На 30 % бешенство: кулдауны."
L["Gluth"] = "Глут"
L["Gluth + Zombie-Hunde"] = "Глут + зомби-собаки"
L["- Dezimieren: setzt alle auf 5 % -> Zombies kommen zum Boss und heilen ihn -> Zombies vorher kiten bzw. sofort töten."] = "- Истребление: снимает всем здоровье до 5 % -> зомби идут к боссу и лечат его -> зомби заранее кайтить или сразу убивать."
L["- Tödliche Wunde: Heilung auf Tank reduziert -> Tankwechsel."] = "- Смертельная рана: снижает исцеление на танке -> смена танков."
L["- Raserei -> Jäger beruhigen."] = "- Бешенство -> охотники снимают Усмиряющим выстрелом."
L["Taktik: Boss tanken mit zwei Tanks im Wechsel, Offtank/Kiter hält die Zombies. Nach Dezimieren AoE auf Zombies und Raid hochheilen."] = "Тактика: босса танковать двумя танками по очереди, офф-танк/кайтер держит зомби. После Истребления АоЕ по зомби и отхилить рейд."
L["GLUTH: Zombies kiten, nach Dezimieren töten! Raserei beruhigen!"] = "ГЛУТ: кайтить зомби, после Истребления убивать! Снимать бешенство!"
L["Tödliche Wunde: Tankwechsel."] = "Смертельная рана: смена танков."
L["Grobbulus"] = "Гроббулус"
L["Grobbulus + Schleime"] = "Гроббулус + слизни"
L["- Mutagene Injektion: Spieler hinterlässt Giftwolke -> an den Rand gehen."] = "- Мутагенная инъекция: игрок оставляет ядовитое облако -> уходить к краю."
L["- Schleimspray: Kegel vor dem Boss erzeugt Schleime -> Tank dreht Boss weg, Schleime töten."] = "- Струя слизи: конус перед боссом создаёт слизней -> танк отворачивает босса, слизней убить."
L["- Giftwolken: Boss hinterlässt Wolken -> Boss langsam durch den Raum ziehen."] = "- Ядовитые облака: босс оставляет облака -> медленно водить босса по залу."
L["Taktik: Tank zieht den Boss im Kreis am Rand, injizierte Spieler laufen außen weg. Schleime per AoE."] = "Тактика: танк водит босса по кругу у края, игроки с инъекцией отбегают наружу. Слизней АоЕ."
L["GROBBULUS: Injektion -> an den Rand! Wolken meiden!"] = "ГРОББУЛУС: инъекция -> к краю! Избегать облаков!"
L["Schleimspray weg vom Raid, Schleime töten."] = "Струю слизи от рейда, слизней убивать."
L["- Hasserfüllter Stoß: trifft das Ziel mit höchster Bedrohung im Nahkampf außer dem Haupttank -> 2–3 Tanks mit hoher Bedrohung."] = "- Удар ненависти: бьёт цель с наибольшей угрозой в ближнем бою, кроме мейн-танка -> 2–3 танка с высокой угрозой."
L["- Raserei bei 5 % -> Abklingzeiten."] = "- Бешенство на 5 % -> кулдауны."
L["- Berserker nach Zeitlimit -> reiner Schadenscheck."] = "- Берсерк по таймеру -> чистая проверка ДПС."
L["Taktik: Haupttank und Stoß-Tanks vorne, Heiler fest auf Tanks. Alle Schaden, Heldentum nach Bedarf."] = "Тактика: мейн-танк и танки под удар спереди, хилы закреплены за танками. Все в урон, героизм по необходимости."
L["FLICKWERK: Schaden, Schaden, Schaden! Heiler auf die Stoß-Tanks!"] = "ЛОСКУТИК: урон, урон, урон! Хилы на танков под удар!"
L["Bei 5 % Raserei: Abklingzeiten."] = "На 5 % бешенство: кулдауны."
L["Thaddius"] = "Таддиус"
L["- Stalagg & Feugen (Phase 1): gleichzeitig töten, sonst Wiederbelebung."] = "- Сталагг и Фойген (фаза 1): убить одновременно, иначе воскрешение."
L["- Polaritätsverschiebung: Plus/Minus -> Plus links, Minus rechts; gleiche Ladung zusammen stehen."] = "- Сдвиг полярности: плюс/минус -> плюс налево, минус направо; с одинаковым зарядом стоять вместе."
L["- Kettenblitz: Schaden springt -> verteilt stehen."] = "- Цепная молния: урон перескакивает -> стоять рассредоточенно."
L["Taktik: P1 beide Adds gleichmäßig runter. P2 Raid nach Ladung aufgeteilt, bei jeder Polaritätsverschiebung sofort Seite wechseln."] = "Тактика: Ф1 обоих аддов опускать равномерно. Ф2 рейд разделён по заряду, при каждом Сдвиге полярности сразу менять сторону."
L["THADDIUS: Plus links, Minus rechts! Bei Wechsel sofort umstellen!"] = "ТАДДИУС: плюс налево, минус направо! При смене сразу перебегать!"
L["P1: Stalagg und Feugen gleichzeitig töten."] = "Ф1: Сталагга и Фойгена убить одновременно."
L["Kel'Thuzad"] = "Кел'Тузад"
L["Kel'Thuzad + Skelette, Seelenfresser, Abscheulichkeiten, Wächter von Eiskrone"] = "Кел'Тузад + скелеты, пожиратели душ, поганища, стражи Ледяной Короны"
L["- Phase 1: Adds strömen aus den Nischen -> abfangen, nicht in die Nischen laufen."] = "- Фаза 1: адды выходят из ниш -> перехватывать, не забегать в ниши."
L["- Frostblitz: starker Zauber auf den Tank -> unterbrechen."] = "- Ледяная стрела: мощное заклинание по танку -> прерывать."
L["- Manadetonation: Ziel explodiert -> weg vom Raid."] = "- Детонация маны: цель взрывается -> от рейда."
L["- Frostschlag: friert Spieler ein -> heilen; Schattenspalt -> raus."] = "- Ледяной удар: замораживает игрока -> хилить; Расщелина тьмы -> выйти."
L["- Phase 3: Wächter von Eiskrone -> fesseln (Priester) oder tanken."] = "- Фаза 3: стражи Ледяной Короны -> сковывать (жрецы) или танковать."
L["Taktik: P1 Adds im Zentrum abfangen, P2 Boss zentral tanken und Frostblitz unterbrechen, P3 Wächter fesseln."] = "Тактика: Ф1 перехватывать аддов в центре, Ф2 босса танковать в центре и прерывать Ледяную стрелу, Ф3 сковывать стражей."
L["KEL'THUZAD: Frostblitz unterbrechen! Detonation weg vom Raid!"] = "КЕЛ'ТУЗАД: кикать Ледяную стрелу! Детонация — от рейда!"
L["P3: Wächter fesseln. Schattenspalt raus."] = "Ф3: сковывать стражей. Из Расщелины тьмы выйти."
L["Symbole auf die Wächter von Eiskrone in P3; jeder Priester fesselt sein Symbol."] = "Метки на стражей Ледяной Короны в Ф3; каждый жрец сковывает свою метку."
L["- Frostaura: dauerhafter Raidschaden -> Frostschutz, Heiler fest."] = "- Аура холода: постоянный урон по рейду -> защита от магии льда, хилы закреплены."
L["- Lebensentzug: Fluch -> entfluchen."] = "- Похищение жизни: проклятие -> снимать проклятия."
L["- Luftphase: Eisblock-Ziele -> hinter Eisblock verstecken vor Frostatem."] = "- Воздушная фаза: цели ледяных глыб -> прятаться за глыбой от Ледяного дыхания."
L["- Blizzard: Bodenfläche -> raus."] = "- Снежная буря: зона на полу -> выйти."
L["Taktik: Boss vorne tanken, Raid verteilt. Flüche entfernen, in der Luftphase hinter Eisblöcken verstecken."] = "Тактика: босса танковать спереди, рейд рассредоточен. Снимать проклятия, в воздушной фазе прятаться за ледяными глыбами."
L["SAPHIRON: Luftphase -> hinter Eisblock! Flüche entfernen!"] = "САПФИРОН: воздушная фаза -> за глыбу! Снимать проклятия!"
L["Blizzard meiden, Frostschutz."] = "Избегать Снежной бури, защита от льда."
L["Gothik der Ernter"] = "Готик Жнец"
L["Gothik der Ernter + lebende und tote Adds"] = "Готик Жнец + живые и мёртвые адды"
L["- Adds erscheinen auf der lebenden Seite; getötete erscheinen als Geister auf der toten Seite -> beide Seiten besetzen."] = "- Адды появляются на живой стороне; убитые появляются духами на мёртвой стороне -> занять обе стороны."
L["- Tor öffnet nach Zeit -> Adds strömen über, AoE."] = "- Ворота открываются по таймеру -> адды перебегают, АоЕ."
L["- Boss teleportiert zwischen den Seiten -> beide Seiten Schaden."] = "- Босс телепортируется между сторонами -> урон с обеих сторон."
L["Taktik: Raid auf zwei Seiten aufteilen, Tanks auf beiden Seiten. Nach Toröffnung Adds sammeln und töten."] = "Тактика: рейд разделить на две стороны, танки на обеих. После открытия ворот собрать аддов и убить."
L["GOTHIK: Beide Seiten halten! Tote-Seite-Adds sofort töten!"] = "ГОТИК: держать обе стороны! Аддов мёртвой стороны сразу убивать!"
L["Tor offen -> Adds sammeln, AoE."] = "Ворота открыты -> собрать аддов, АоЕ."
L["Die Vier Reiter"] = "Четыре всадника"
L["Die Vier Reiter: Korth'azz, Rivendare, Blaumeux, Zeliek"] = "Четыре всадника: Кортазз, Ривендер, Бломе, Зелиек"
L["- Male: stapeln sich auf Spielern in Reichweite -> Tankwechsel zwischen den Ecken."] = "- Метки: стакаются на игроках в радиусе -> смена танков между углами."
L["- Meteor (Korth'azz): Schaden aufgeteilt -> Nahkampf zusammen."] = "- Метеор (Кортазз): урон делится -> мили вместе."
L["- Leerzone (Blaumeux): -> raus."] = "- Зона пустоты (Бломе): -> выйти."
L["- Heiliger Zorn (Zeliek): -> Zeliek abseits tanken."] = "- Священный гнев (Зелиек): -> Зелиека танковать в стороне."
L["Taktik: Reiter in Ecken tanken, Fernkampf auf Blaumeux/Zeliek, Nahkampf auf Korth'azz/Rivendare. Tankwechsel nach Male."] = "Тактика: всадников танковать в углах, ренж на Бломе/Зелиека, мили на Кортазза/Ривендера. Смена танков по меткам."
L["VIER REITER: Male beachten, Tankwechsel! Leerzone raus!"] = "ЧЕТЫРЕ ВСАДНИКА: следить за метками, смена танков! Из Зоны пустоты выйти!"
L["Nahkampf auf Korth'azz/Rivendare, Fernkampf auf Blaumeux/Zeliek."] = "Мили на Кортазза/Ривендера, ренж на Бломе/Зелиека."
L["Vier Reiter"] = "Четыре всадника"
L["Jeder Reiter ein Symbol, Totenkopf zuerst; Tanks nach Symbol eingeteilt."] = "Каждому всаднику своя метка, Череп первым; танки распределены по меткам."
L["Instrukteur Razuvious"] = "Инструктор Разувий"
L["Instrukteur Razuvious + Todesritter-Reservisten"] = "Инструктор Разувий + ученики-рыцари смерти"
L["- Unterbrechungsruf: hoher Schaden auf Spieler in der Nähe -> Abstand halten, Heiler und Zauberer weit weg."] = "- Разрушительный крик: сильный урон по игрокам рядом -> держать дистанцию, хилы и кастеры далеко."
L["- Reservisten: werden über die Kristalle per Gedankenkontrolle übernommen -> tanken den Boss abwechselnd mit Knochenbarriere und Spott."] = "- Ученики: берутся под контроль разума через кристаллы -> по очереди танкуют босса с Костяным барьером и Провокацией."
L["- Schwere Schläge auf den Reservisten-Tank -> rechtzeitig auf den nächsten Reservisten wechseln."] = "- Тяжёлые удары по ученику-танку -> вовремя переключиться на следующего ученика."
L["- Reservisten-Knochenbarriere/Spott: Fähigkeiten der kontrollierten Reservisten -> im Wechsel nutzen, Gedankenkontrolle rechtzeitig erneuern."] = "- Костяной барьер/Провокация учеников: способности контролируемых учеников -> использовать по очереди, вовремя обновлять контроль разума."
L["Taktik: Zwei Spieler steuern die Reservisten über die Kristalle und tanken den Boss im Wechsel, Raid macht Schaden auf Razuvious, nicht auf die Reservisten."] = "Тактика: два игрока управляют учениками через кристаллы и по очереди танкуют босса, рейд бьёт Разувия, а не учеников."
L["RAZUVIOUS: Nicht die Reservisten angreifen! Kontrolleure: Wechsel ansagen!"] = "РАЗУВИЙ: учеников не бить! Контролёры: объявлять смену!"
L["Abstand vom Boss halten, Unterbrechungsruf trifft die Nähe."] = "Держать дистанцию от босса, Разрушительный крик бьёт вблизи."
L["Razuvious"] = "Разувий"
L["Reservisten markieren, jeder Kontrolleur übernimmt sein Symbol."] = "Учеников пометить, каждый контролёр берёт свою метку."
L["- Eruption: die Bodenzonen explodieren der Reihe nach -> Raid tanzt gemeinsam in die jeweils sichere Zone."] = "- Извержение: зоны пола взрываются по очереди -> рейд вместе танцует в безопасную зону."
L["- Entkräftendes Fieber/Krankheiten: Schaden über Zeit -> Krankheiten heilen bzw. bannen."] = "- Изнуряющая лихорадка/болезни: урон со временем -> лечить или диспелить болезни."
L["- Plattformphase: Boss teleportiert und die Eruptionen werden schneller -> ganzer Raid tanzt in der hintersten Zone."] = "- Фаза на платформе: босс телепортируется, извержения ускоряются -> весь рейд танцует в самой дальней зоне."
L["- Manaentzug in Bossnähe -> Heiler und Zauberer etwas weiter weg."] = "- Похищение маны рядом с боссом -> хилы и кастеры чуть дальше."
L["Taktik: Tank hält den Boss in der ersten Zone, Raid tanzt als Gruppe. In der Plattformphase gemeinsam hin und her springen."] = "Тактика: танк держит босса в первой зоне, рейд танцует группой. В фазе на платформе вместе прыгать туда-сюда."
L["HEIGAN: Tanzen! Alle gemeinsam in die sichere Zone!"] = "ХЕЙГАН: танцуем! Все вместе в безопасную зону!"
L["Plattformphase: schneller tanzen, Krankheiten heilen."] = "Фаза на платформе: танцевать быстрее, лечить болезни."
L["Loatheb"] = "Лотхиб"
L["- Nekrotische Aura: verhindert die meiste Heilung -> Heiler nutzen die kurzen Heilfenster."] = "- Мертвящая аура: блокирует большую часть исцеления -> хилы используют короткие окна хила."
L["- Sporen: geben beim Tod einen Kritbuff in der Nähe -> gezielt in Nahkampf-/Fernkampfgruppen töten."] = "- Споры: при смерти дают бафф на крит рядом -> убивать прицельно в группах мили/ренжа."
L["- Unvermeidliches Verderben: Schattenschaden wird mit der Zeit immer schneller -> Schadensrennen, Tank hält durch."] = "- Неотвратимый рок: теневой урон со временем всё чаще -> гонка ДПС, танк выдерживает."
L["Taktik: Heilfenster koordinieren und Sporen nach Plan in die Gruppen ziehen und töten. Volles Burst, bevor Verderben zu oft kommt."] = "Тактика: координировать окна хила, споры по плану заводить в группы и убивать. Полный бурст, пока Рок не стал слишком частым."
L["LOATHEB: Heilfenster nutzen! Sporen in die Gruppen töten!"] = "ЛОТХИБ: использовать окна хила! Споры убивать в группах!"
L["Unvermeidliches Verderben steigt -> schnell töten."] = "Неотвратимый рок растёт -> быстро убить."
L["Noth der Seuchenfürst"] = "Нот Чумной"
L["Noth der Seuchenfürst + Skelette"] = "Нот Чумной + скелеты"
L["- Fluch des Seuchenfürsten: Flüche auf Spieler -> sofort entfluchen."] = "- Проклятие Чумного: проклятия на игроках -> сразу снимать."
L["- Blinzeln: Noth teleportiert und setzt Bedrohung zurück -> Tank holt ihn sofort wieder."] = "- Скачок: Нот телепортируется и сбрасывает угрозу -> танк сразу забирает его обратно."
L["- Balkonphase: Boss verschwindet, Skelettwellen erscheinen -> Tanks fangen sie ab, AoE."] = "- Фаза на балконе: босс исчезает, появляются волны скелетов -> танки перехватывают, АоЕ."
L["Taktik: Boss in der Mitte tanken, Flüche entfernen. In der Balkonphase Adds sammeln und töten."] = "Тактика: босса танковать в центре, снимать проклятия. В фазе на балконе собрать аддов и убить."
L["NOTH: Flüche entfernen! Balkonphase: Adds sammeln!"] = "НОТ: снимать проклятия! Фаза на балконе: собрать аддов!"
L["Blinzeln: Bedrohung neu aufbauen."] = "Скачок: заново набрать угрозу."
L["Das Obsidiansanktum"] = "Обсидиановое святилище"
L["Sartharion"] = "Сартарион"
L["Sartharion + Lavablitze, ggf. Tenebron, Shadron, Vesperon"] = "Сартарион + лавовые смерчи, при необходимости Тенеброн, Шадрон, Весперон"
L["- Flammentsunami: Lavawellen rollen über die Plattform -> durch die Lücke bzw. auf die sichere Seite laufen."] = "- Огненное цунами: волны лавы катятся по платформе -> бежать в просвет или на безопасную сторону."
L["- Feuerspalt / Lavablitz: Feuerzonen auf dem Boden und Lava-Adds -> raus aus dem Feuer, Adds vom Offtank töten."] = "- Огненная расщелина / лавовый смерч: огненные зоны на полу и лавовые адды -> выйти из огня, аддов убивать на офф-танке."
L["- Flammenatem: Kegel vor dem Boss -> nur der Tank steht vorne."] = "- Огненное дыхание: конус перед боссом -> спереди стоит только танк."
L["- Drachen bleiben am Leben (Sartharion +1/+2/+3): jeder Drache landet nach Zeit und verstärkt den Boss -> mehr Beute, aber deutlich schwerer."] = "- Драконы остаются живы (Сартарион +1/+2/+3): каждый дракон по таймеру приземляется и усиливает босса -> больше лута, но заметно сложнее."
L["Taktik: Boss mit dem Rücken zum Raid tanken, Raid verteilt und für den Tsunami bereit. Ohne Drachen vorher Tenebron, Shadron, Vesperon einzeln töten; mit Drachen Offtanks und Portalgruppen fest einteilen."] = "Тактика: босса танковать спиной к рейду, рейд рассредоточен и готов к цунами. Без драконов заранее убить Тенеброна, Шадрона, Весперона по одному; с драконами жёстко распределить офф-танков и группы портала."
L["Sartharion mit 3 Drachen ist die Herausforderung (Erfolg/Mount im 25er) – Drachen dabei nacheinander bei der Landung abfangen."] = "Сартарион с 3 драконами — это челлендж (достижение/маунт в 25-ке) – драконов при этом перехватывать по очереди при приземлении."
L["SARTHARION: Flammentsunami -> in die Lücke! Aus dem Feuer raus!"] = "САРТАРИОН: Огненное цунами -> в просвет! Выйти из огня!"
L["Lavablitze vom Offtank. Drachen nach Plan abholen."] = "Лавовые смерчи на офф-танке. Драконов забирать по плану."
L["Shadron"] = "Шадрон"
L["Shadron + Akolyth von Shadron (Zwielichtportal)"] = "Шадрон + послушник Шадрона (портал сумерек)"
L["- Zwielichtportal: Akolyth von Shadron erscheint im Zwielicht und macht den Drachen bzw. Sartharion fast immun -> Gruppe ins Portal, Akolyth töten."] = "- Портал сумерек: послушник Шадрона появляется в Сумраке и делает дракона или Сартариона почти неуязвимым -> группа в портал, убить послушника."
L["- Schattenfissur: dunkler Kreis auf dem Boden -> sofort raus."] = "- Теневая трещина: тёмный круг на полу -> сразу выйти."
L["- Schattenatem: Kegel vor dem Drachen -> nur der Tank steht vorne."] = "- Теневое дыхание: конус перед драконом -> спереди стоит только танк."
L["Taktik: Drachen vom Raid weg drehen, eine Portalgruppe tötet den Akolythen, danach Schaden auf Shadron."] = "Тактика: дракона отвернуть от рейда, группа портала убивает послушника, затем урон по Шадрону."
L["SHADRON: Portalgruppe -> Akolyth töten! Fissur raus!"] = "ШАДРОН: группа портала -> убить послушника! Из трещины выйти!"
L["Atem nur auf den Tank, Drachen weggedreht."] = "Дыхание только на танка, дракон отвёрнут."
L["Tenebron"] = "Тенеброн"
L["Tenebron + Zwielichtwelpen"] = "Тенеброн + сумеречные дракончики"
L["- Zwielichteier: im Zwielicht schlüpfen Welpen -> Eier im Portal zerstören oder die Welpen in der normalen Welt per AoE töten."] = "- Сумеречные яйца: в Сумраке вылупляются дракончики -> разбивать яйца в портале или убивать дракончиков в обычном мире АоЕ."
L["Taktik: Drachen vom Raid weg drehen, Welpen vom Offtank sammeln und per AoE töten, dann Schaden auf Tenebron."] = "Тактика: дракона отвернуть от рейда, дракончиков собирает офф-танк и их убивают АоЕ, затем урон по Тенеброну."
L["TENEBRON: Welpen sammeln und töten! Fissur raus!"] = "ТЕНЕБРОН: собрать дракончиков и убить! Из трещины выйти!"
L["Vesperon"] = "Весперон"
L["Vesperon + Akolyth von Vesperon (Zwielichtportal)"] = "Весперон + послушник Весперона (портал сумерек)"
L["- Zwielichtportal: Akolyth von Vesperon erscheint, solange er lebt erleidet der Raid Zwielichtqual (Schaden pro verursachtem Schaden) -> Gruppe ins Portal, schnell töten."] = "- Портал сумерек: появляется послушник Весперона, пока он жив, рейд получает Сумеречные муки (урон за нанесённый урон) -> группа в портал, быстро убить."
L["Taktik: Drachen vom Raid weg drehen, Portalgruppe tötet den Akolythen; währenddessen wenig Schaden machen, danach Vesperon töten."] = "Тактика: дракона отвернуть от рейда, группа портала убивает послушника; в это время мало урона, затем убить Весперона."
L["VESPERON: Akolyth schnell töten! Bis dahin Schaden zurückhalten!"] = "ВЕСПЕРОН: послушника быстро убить! До этого придержать урон!"
L["Fissur raus, Atem nur auf den Tank."] = "Из трещины выйти, дыхание только на танка."
L["Onyxia"] = "Ониксия"
L["Onyxia + Onyxiawelpen und Onyxische Wachen"] = "Ониксия + дракончики Ониксии и ониксийские стражи"
L["- Flammenatem und Schwanzfeger -> nur der Tank vorne, niemand hinter ihr; seitlich stehen."] = "- Огненное дыхание и Удар хвостом -> спереди только танк, сзади никого; стоять по бокам."
L["- Phase 2 (65 %): Onyxia fliegt, Feuerbälle auf Spieler und Tiefer Atem über den Raum -> verteilt stehen, aus der Atemlinie raus."] = "- Фаза 2 (65 %): Ониксия летает, огненные шары по игрокам и Глубокий вдох через зал -> стоять рассредоточенно, уйти с линии дыхания."
L["- Welpen und Onyxische Wachen aus den Höhlen -> Offtanks fangen ab, AoE auf Welpen."] = "- Дракончики и ониксийские стражи из пещер -> офф-танки перехватывают, АоЕ по дракончикам."
L["- Phase 3 (40 %): Massenfurcht und Lavaeruptionen aus dem Boden -> Furchtschutz/Totem nutzen, nicht über Risse laufen."] = "- Фаза 3 (40 %): массовый страх и извержения лавы из пола -> использовать Защиту от страха/тотем, не ходить по трещинам."
L["Taktik: P1 an der Nordwand tanken, Raid an den Seiten; P2 verteilt unter ihr, Welpen per AoE; P3 Tank holt sie sofort wieder, Furcht kontern."] = "Тактика: Ф1 танковать у северной стены, рейд по бокам; Ф2 рассредоточиться под ней, дракончиков АоЕ; Ф3 танк сразу забирает её, контрить страх."
L["ONYXIA: Nicht vor oder hinter sie! P2: Tiefer Atem -> aus der Linie!"] = "ОНИКСИЯ: не стоять спереди и сзади! Ф2: Глубокий вдох -> с линии!"
L["Welpen per AoE. P3: Furchtschutz, Lavarisse meiden."] = "Дракончиков АоЕ. Ф3: Защита от страха, избегать лавовых трещин."
L["Das Rubinsanktum"] = "Рубиновое святилище"
L["Baltharus der Kriegsjünger"] = "Балтар Рожденный в Битве"
L["Baltharus der Kriegsjünger + Abbild"] = "Балтар Рожденный в Битве + копия"
L["- Abbild: Boss spaltet sich bei bestimmten Lebenspunkten -> Offtank übernimmt das Abbild, beide gleichmäßig töten."] = "- Копия: босс раздваивается на определённом здоровье -> копию берёт офф-танк, обоих убивать равномерно."
L["- Klingentempest: Wirbelangriff um den Boss -> Nahkampf kurz raus."] = "- Буря клинков: вихревая атака вокруг босса -> мили ненадолго выходят."
L["- Entkräftendes Brandmal: Debuff auf Spielern verstärkt den Boss in der Nähe -> Betroffene weg vom Boss und voneinander."] = "- Изнуряющее клеймо: дебафф на игроках усиливает босса поблизости -> поражённые отходят от босса и друг от друга."
L["- Abstoßende Welle: stößt den Raid zurück -> nicht am Rand stehen."] = "- Отталкивающая волна: отбрасывает рейд -> не стоять у края."
L["Taktik: Boss und Abbild getrennt tanken, Brandmal-Spieler gehen weg, Nahkampf meidet den Wirbel."] = "Тактика: босса и копию танковать раздельно, игроки с клеймом отходят, мили избегают вихря."
L["BALTHARUS: Abbild vom Offtank! Brandmal-Ziele weg vom Boss!"] = "БАЛТАР: копию берёт офф-танк! Цели клейма — от босса!"
L["Klingentempest: Nahkampf raus."] = "Буря клинков: мили выйти."
L["Halion"] = "Халион"
L["Halion + Zwielichtreich (Halion im Zwielicht)"] = "Халион + Сумеречный мир (Халион в Сумраке)"
L["- Phase 1: Feuriger Brand (Debuff) -> Ziel sofort an den Rand laufen; Meteoritenschlag -> aus der Einschlagzone und den Flammen raus."] = "- Фаза 1: Пылающий огонь (дебафф) -> цель сразу бежит к краю; Падение метеора -> выйти из зоны удара и пламени."
L["- Phase 2 (75 %): Halion im Zwielicht, Seelenverzehrung (Debuff) -> Ziel zum Rand; rotierende Schattenkugeln -> den Lasern ausweichen."] = "- Фаза 2 (75 %): Халион в Сумраке, Пожирание души (дебафф) -> цель к краю; вращающиеся теневые сферы -> уклоняться от лазеров."
L["- Phase 3 (50 %): beide Reiche gleichzeitig -> Schaden gleichmäßig verteilen (Körperlichkeit), sonst wird ein Reich stärker."] = "- Фаза 3 (50 %): оба мира одновременно -> распределять урон равномерно (Материальность), иначе один мир усиливается."
L["- Atem und Schwanzfeger in beiden Reichen -> Boss vom Raid weg drehen."] = "- Дыхание и Удар хвостом в обоих мирах -> босса отвернуть от рейда."
L["Taktik: P1 Raid verteilt hinter Halion, Debuffs an den Rand. P2 alle ins Portal, Laserkugeln ausweichen. P3 Raid aufteilen und nach Körperlichkeit-Ansagen Schaden anpassen."] = "Тактика: Ф1 рейд рассредоточен позади Халиона, дебаффы к краю. Ф2 все в портал, уклоняться от лазерных сфер. Ф3 рейд разделить и подстраивать урон по колам Материальности."
L["Heroisch: Zusätzlich Kugeln/Meteore häufiger und der Schadensausgleich in P3 muss deutlich exakter sein."] = "Героик: дополнительно сферы/метеоры чаще, и баланс урона в Ф3 должен быть заметно точнее."
L["HALION: Feuriger Brand / Seelenverzehrung -> zum Rand! Meteor raus!"] = "ХАЛИОН: Пылающий огонь / Пожирание души -> к краю! Из метеора выйти!"
L["P2 Laser ausweichen. P3 Schaden auf beide Reiche gleichmäßig verteilen."] = "Ф2 уклоняться от лазеров. Ф3 урон равномерно по обоим мирам."
L["Saviana Wutfeuer"] = "Савиана Огненная Ярость"
L["- Raserei: Schaden steigt stark -> Wildtiere besänftigen/Raserei sofort entfernen."] = "- Бешенство: урон сильно растёт -> Умиротворение/сразу снимать бешенство."
L["- Flammenatem: Kegel -> nur der Tank vorne."] = "- Огненное дыхание: конус -> спереди только танк."
L["- Luftphase: Entflammen auf mehreren Spielern -> Betroffene weg vom Raid, nicht ineinander stehen."] = "- Воздушная фаза: Воспламенение на нескольких игроках -> поражённые от рейда, не стоять друг в друге."
L["Taktik: Boss seitlich tanken, Raserei konsequent entfernen. In der Luftphase verteilen und Entflammen-Ziele separieren."] = "Тактика: босса танковать боком, бешенство стабильно снимать. В воздушной фазе рассредоточиться и разводить цели Воспламенения."
L["SAVIANA: Raserei sofort entfernen! Entflammen-Ziele weg vom Raid!"] = "САВИАНА: бешенство сразу снимать! Цели Воспламенения — от рейда!"
L["Atem nur auf den Tank. Luftphase verteilen."] = "Дыхание только на танка. Воздушная фаза — рассредоточиться."
L["General Zarithrian"] = "Генерал Заритриан"
L["General Zarithrian + Onyx-Flammenrufer"] = "Генерал Заритриан + ониксовые заклинатели огня"
L["- Rüstung spalten: stapelt auf dem Tank -> Tankwechsel."] = "- Раскол брони: стакается на танке -> смена танков."
L["- Onyx-Flammenrufer: Adds aus den Seiten -> Offtank fängt ab, schnell töten, Feuerzauber unterbrechen."] = "- Ониксовые заклинатели огня: адды с боков -> офф-танк перехватывает, быстро убить, кикать огненные заклинания."
L["- Einschüchterndes Gebrüll: Furcht -> Furchtschutz/Totem nutzen."] = "- Устрашающий рёв: страх -> использовать Защиту от страха/тотем."
L["Taktik: Boss mit zwei Tanks im Wechsel, Adds vom Offtank abfangen und getrennt töten. Furcht kontern."] = "Тактика: босса держат два танка по очереди, аддов перехватывает офф-танк и их убивают отдельно. Контрить страх."
L["ZARITHRIAN: Flammenrufer abfangen und töten! Tankwechsel beachten!"] = "ЗАРИТРИАН: перехватить заклинателей огня и убить! Следить за сменой танков!"
L["Gebrüll: Furchtschutz bereit."] = "Рёв: Защита от страха наготове."
L["Ulduar"] = "Ульдуар"
L["Algalon der Beobachter"] = "Алгалон Наблюдатель"
L["Algalon der Beobachter + Kollabierende Sterne, Lebende Konstellationen"] = "Алгалон Наблюдатель + коллапсирующие звёзды, живые созвездия"
L["- Großer Knall: tödlicher Raidschaden -> vor Ende des Zaubers in ein Schwarzes Loch springen und danach wieder herauskommen."] = "- Большой взрыв: смертельный урон по рейду -> до конца каста прыгнуть в чёрную дыру и потом выйти обратно."
L["- Kollabierende Sterne: verlieren Leben und hinterlassen beim Tod ein Schwarzes Loch -> kontrolliert nahe am Raid töten."] = "- Коллапсирующие звёзды: теряют здоровье и при смерти оставляют чёрную дыру -> контролируемо убивать рядом с рейдом."
L["- Phasenschlag: stapelt auf dem Tank, bei 5 Stapeln wird er in eine andere Phase versetzt -> rechtzeitig Tankwechsel."] = "- Фазовый удар: стакается на танке, на 5 стаках его переносит в другую фазу -> вовремя смена танков."
L["- Kosmischer Schlag: markierte Einschläge auf Spielern -> aus dem Einschlag raus, Schaden nimmt mit Entfernung ab."] = "- Космический удар: помеченные места удара на игроках -> выйти из зоны, урон падает с расстоянием."
L["- Lebende Konstellationen: Adds -> in ein Schwarzes Loch ziehen, das schließt das Loch und tötet das Add."] = "- Живые созвездия: адды -> затянуть в чёрную дыру, это закрывает дыру и убивает адда."
L["- Unter 20 %: alle Löcher werden zu Dunkle-Materie-Adds -> Adds kontrollieren, Schadensrennen auf den Boss."] = "- Ниже 20 %: все дыры становятся аддами тёмной материи -> контролить аддов, гонка ДПС по боссу."
L["Taktik: Boss in der Mitte tanken, Sterne rechtzeitig für den Großen Knall töten und die Löcher freihalten. Tankwechsel nach Phasenschlag, Konstellationen gezielt in Löcher ziehen."] = "Тактика: босса танковать в центре, звёзды убивать вовремя к Большому взрыву и держать дыры свободными. Смена танков по Фазовому удару, созвездия целенаправленно заводить в дыры."
L["Zeitlimit: Nach dem ersten Pull bleibt eine Stunde für den Kill, danach verschwindet Algalon."] = "Лимит времени: после первого пулла есть один час на килл, затем Алгалон исчезает."
L["ALGALON: Großer Knall -> ins Schwarze Loch! Sterne rechtzeitig töten!"] = "АЛГАЛОН: Большой взрыв -> в чёрную дыру! Звёзды убивать вовремя!"
L["Phasenschlag: Tankwechsel. Kosmischer Schlag: raus."] = "Фазовый удар: смена танков. Космический удар: выйти."
L["Auriaya"] = "Ауриайя"
L["Auriaya + Wächter des Sanktums, Wildverteidiger"] = "Ауриайя + стражи святилища, дикие защитники"
L["- Schreckliches Kreischen: Furcht auf den Raid, danach kanalisiert sie Wächtersalve -> Furchtschutz/Totem, Salve sofort unterbrechen."] = "- Ужасающий вопль: страх на рейд, затем она кастует Залп стража -> Защита от страха/тотем, залп сразу кикать."
L["- Schallkreischen: Kegel vor ihr, Schaden wird geteilt -> Tank und möglichst viele Spieler vorne stapeln."] = "- Звуковой визг: конус перед ней, урон делится -> танк и как можно больше игроков стакаются спереди."
L["- Wildverteidiger: Add mit 9 Leben, jeder Tod hinterlässt eine Pfütze -> immer wieder töten, Pfütze verlassen."] = "- Дикий защитник: адд с 9 жизнями, каждая смерть оставляет лужу -> убивать снова и снова, выходить из лужи."
L["- Wächter des Sanktums: Rudel mit dem Boss gepullt -> per Offtank sammeln und zuerst töten."] = "- Стражи святилища: стая пуллится вместе с боссом -> собрать офф-танком и убить первыми."
L["Taktik: Wächter vom Boss getrennt tanken und zuerst töten, dann Boss; Kreischen-Kegel mit Stapel teilen, Salve konsequent unterbrechen."] = "Тактика: стражей танковать отдельно от босса и убить первыми, потом босс; конус визга делить стаком, залп стабильно кикать."
L["AURIAYA: Wächtersalve unterbrechen! Schallkreischen vorne teilen!"] = "АУРИАЙЯ: кикать Залп стража! Звуковой визг делить спереди!"
L["Wildverteidiger immer wieder töten, Pfützen verlassen."] = "Дикого защитника убивать снова и снова, выходить из луж."
L["Flammenleviathan"] = "Огненный Левиафан"
L["Flammenleviathan (Fahrzeugkampf: Belagerungsmaschinen, Demolierer, Motorräder)"] = "Огненный Левиафан (бой на технике: осадные машины, разрушители, мотоциклы)"
L["- Verfolgung: Boss jagt ein Fahrzeug -> verfolgtes Fahrzeug fährt weg, Motorräder legen Teer zum Verlangsamen."] = "- Преследование: босс гонится за машиной -> преследуемая машина уезжает, мотоциклы кладут смолу для замедления."
L["- Überladungskreislauf: Passagiere (aus dem Demolierer katapultiert) zerstören die Geschütze auf dem Boss -> Boss betäubt, volles Feuer."] = "- Перегрузка цепи: пассажиры (катапультированные из разрушителя) уничтожают турели на боссе -> босс оглушён, полный огонь."
L["- Pyrit: Fässer aus der Luft -> Motorräder/Belagerungsmaschinen sammeln für die Demolierer."] = "- Пирит: бочки с воздуха -> мотоциклы/осадные машины собирают для разрушителей."
L["- Flammenschlote: Flächenschaden um den Boss -> Fahrzeuge reparieren bzw. Abstand halten."] = "- Огненные выбросы: урон по площади вокруг босса -> чинить технику или держать дистанцию."
L["- Türme der Wächter: jeder stehen gelassene Turm verstärkt den Boss (Hardmode) -> nach Plan zerstören."] = "- Башни стражей: каждая оставленная башня усиливает босса (хардмод) -> уничтожать по плану."
L["Taktik: Fahrzeuge vor dem Pull fest einteilen: Belagerungsmaschinen rammen, Demolierer schießen von hinten, Motorräder verlangsamen und sammeln Pyrit; verfolgte Fahrzeuge kiten."] = "Тактика: технику жёстко распределить до пулла: осадные машины таранят, разрушители стреляют сзади, мотоциклы замедляют и собирают пирит; преследуемые машины кайтят."
L["LEVIATHAN: Verfolgtes Fahrzeug weg! Überladung -> volles Feuer!"] = "ЛЕВИАФАН: преследуемая машина — уезжай! Перегрузка -> полный огонь!"
L["Pyrit sammeln, Passagiere die Geschütze zerstören."] = "Собирать пирит, пассажиры уничтожают турели."
L["Freya"] = "Фрейя"
L["Freya + Ältester Bewahrer, Elementar-Trio, Explosive Peitscher"] = "Фрейя + Древний защитник, трио элементалей, взрывные плеточники"
L["- Elementar-Trio (Wassergeist, Sturmpeitscher, Schnappschling): müssen kurz nacheinander sterben -> gleichmäßig runter, zusammen töten."] = "- Трио элементалей (дух воды, плеточник бури, хваткий росток): должны умереть почти одновременно -> опускать равномерно, убить вместе."
L["- Ältester Bewahrer: Griff des Bewahrers -> unter die Gesunden Sporen (Pilze) stellen."] = "- Древний защитник: Хватка защитника -> вставать под Здоровые споры (грибы)."
L["- Explosive Peitscher: viele kleine Adds explodieren -> per AoE, aber nicht am Raid."] = "- Взрывные плеточники: много мелких аддов взрывается -> АоЕ, но не у рейда."
L["- Sonnenstrahl und Naturbomben -> sofort raus; Eisenwurzeln fesseln Spieler -> Wurzel töten."] = "- Солнечный луч и бомбы природы -> сразу выйти; Железные корни сковывают игроков -> убить корень."
L["- Eonars Geschenk heilt Freya -> sofort töten."] = "- Дар Эонара лечит Фрейю -> сразу убить."
L["Taktik: Phase 1: sechs Add-Wellen tanken und töten, Elementar-Trio zusammen. Phase 2: Freya selbst, Bodeneffekte meiden."] = "Тактика: фаза 1: танковать и убивать шесть волн аддов, трио элементалей вместе. Фаза 2: сама Фрейя, избегать эффектов на полу."
L["Hardmode: Älteste (Eisenzweig, Hellblatt, Steinrinde) bleiben am Leben und verstärken Freya."] = "Хардмод: древни (Железная Ветвь, Светлая Листва, Каменная Кора) остаются живы и усиливают Фрейю."
L["FREYA: Elementar-Trio gleichzeitig töten! Eonars Geschenk sofort!"] = "ФРЕЙЯ: трио элементалей убить одновременно! Дар Эонара — сразу!"
L["Sonnenstrahl/Naturbomben raus. Eisenwurzeln befreien."] = "Из Солнечного луча/бомб природы выйти. Освобождать от Железных корней."
L["General Vezax"] = "Генерал Везакс"
L["General Vezax (+ Saronitanimus im Hardmode)"] = "Генерал Везакс (+ Саронитовый враг в хардмоде)"
L["- Aura der Verzweiflung: keine Manaregeneration -> Saronitdampf (Wolke) gibt Mana, aber stapelnder Schaden; kurz rein, wieder raus."] = "- Аура отчаяния: нет реги маны -> саронитовые пары (облако) дают ману, но стакающийся урон; ненадолго зайти и снова выйти."
L["- Sengende Flammen: Zauber auf den Raid -> konsequent unterbrechen."] = "- Опаляющее пламя: заклинание по рейду -> стабильно кикать."
L["- Schattenkrachen: Geschoss auf einen Spieler -> verteilt stehen und ausweichen."] = "- Грохот тьмы: снаряд в игрока -> стоять рассредоточенно и уклоняться."
L["- Mal der Gesichtslosen: entzieht Leben aus der Umgebung -> Ziel geht weg vom Raid."] = "- Метка Безликого: вытягивает жизнь из окружающих -> цель отходит от рейда."
L["- Dunkelheitsschub: Boss teilt stark mehr Schaden aus -> Tank kitet bzw. Abklingzeiten."] = "- Всплеск тьмы: босс наносит намного больше урона -> танк кайтит или кулдауны."
L["Taktik: Raid locker verteilt, Unterbrechungsrotation für Sengende Flammen. Mana-Klassen nutzen die Saronitwolken vorsichtig, Tank kitet beim Schub."] = "Тактика: рейд свободно рассредоточен, ротация киков на Опаляющее пламя. Классы с маной осторожно используют саронитовые облака, танк кайтит во время Всплеска."
L["Hardmode: Saronitwolken nicht nutzen; sie verschmelzen zum Saronitanimus, der zuerst getötet wird."] = "Хардмод: саронитовые облака не использовать; они сливаются в Саронитового врага, которого убивают первым."
L["VEZAX: Sengende Flammen unterbrechen! Schattenkrachen ausweichen!"] = "ВЕЗАКС: кикать Опаляющее пламя! Уклоняться от Грохота тьмы!"
L["Mal-Ziel weg vom Raid. Dunkelheitsschub: Tank kitet."] = "Цель метки — от рейда. Всплеск тьмы: танк кайтит."
L["Hodir"] = "Ходир"
L["Hodir + eingefrorene NPC-Helfer"] = "Ходир + замороженные НИП-помощники"
L["- Beißende Kälte: stapelnder Frostschaden bei Stillstand -> regelmäßig bewegen bzw. springen."] = "- Трескучий мороз: стакающийся ледяной урон, если стоять на месте -> регулярно двигаться или прыгать."
L["- Blitzfrost: friert den Raid ein -> in den Schneehaufen der gefallenen Eiszapfen stehen."] = "- Ледяная вспышка: замораживает рейд -> стоять в сугробах от упавших сосулек."
L["- Eiszapfen: fallen auf Spieler -> aus dem Schatten raus."] = "- Сосульки: падают на игроков -> выйти из тени."
L["- Gefrorene Schläge: Boss stärker, Tank-Abklingzeiten; eingefrorene NPCs befreien -> Buffs (Feuer, Sternenlicht, Sturmkraft, Heilung)."] = "- Ледяные удары: босс сильнее, кулдауны танка; освобождать замороженных НИП -> баффы (огонь, звёздный свет, сила бури, хил)."
L["Taktik: Raid bewegt sich ständig, NPCs zuerst befreien und ihre Buffs nutzen. Bei Blitzfrost in die Schneehaufen."] = "Тактика: рейд постоянно двигается, сначала освобождать НИП и использовать их баффы. На Ледяной вспышке — в сугробы."
L["Hardmode: Hodir innerhalb von 3 Minuten töten (seltene Beutetruhe)."] = "Хардмод: убить Ходира за 3 минуты (редкий сундук с лутом)."
L["HODIR: Blitzfrost -> in die Schneehaufen! Bewegen gegen Kälte!"] = "ХОДИР: Ледяная вспышка -> в сугробы! Двигаться против мороза!"
L["NPCs befreien, Eiszapfen ausweichen."] = "Освобождать НИП, уклоняться от сосулек."
L["Ignis, Meister des Ofens"] = "Повелитель Горнов Игнис"
L["Ignis, Meister des Ofens + Eisenkonstrukte"] = "Повелитель Горнов Игнис + железные создания"
L["- Eisenkonstrukte: werden durch Sengen erhitzt -> Offtank zieht sie durchs Feuer, bei Geschmolzen ins Wasser, dort werden sie spröde."] = "- Железные создания: нагреваются от Опаления -> офф-танк проводит их через огонь, расплавленных — в воду, там они становятся хрупкими."
L["- Spröde Konstrukte: zerspringen bei starkem Schaden -> sofort hart treffen, Splitter-Schaden für den Raid beachten."] = "- Хрупкие создания: разбиваются от сильного удара -> сразу бить мощно, учитывать урон осколков по рейду."
L["- Schlackentopf: Spieler sitzt im Topf und erleidet hohen Schaden -> sofort hochheilen."] = "- Шлаковый ковш: игрок сидит в ковше и получает сильный урон -> сразу отхилить."
L["- Flammenstrahlen: Raidschaden und Zauberunterbrechung -> Zauber gut timen, Heiler bereit."] = "- Огненные струи: урон по рейду и прерывание кастов -> хорошо тайминговать касты, хилы наготове."
L["Taktik: Boss vom Wasser entfernt tanken, Konstrukte vom Offtank durchs Feuer ins Wasser ziehen und dort zerbrechen; Topf-Ziel sofort heilen."] = "Тактика: босса танковать подальше от воды, офф-танк ведёт создания через огонь в воду и там их разбивают; цель ковша сразу хилить."
L["IGNIS: Konstrukte ins Wasser und zerbrechen! Schlackentopf heilen!"] = "ИГНИС: создания в воду и разбивать! Хилить Шлаковый ковш!"
L["Sengen-Feuer meiden. Flammenstrahlen: Heiler bereit."] = "Избегать огня Опаления. Огненные струи: хилы наготове."
L["Die Versammlung des Eisens"] = "Железное собрание"
L["Die Versammlung des Eisens: Stahlbrecher, Runenmeister Molgeim, Sturmrufer Brundir"] = "Железное собрание: Сталелом, мастер рун Молгейм, буревестник Брундир"
L["- Jeder Tod verstärkt die verbleibenden Mitglieder -> Tötungsreihenfolge vorher festlegen (sie bestimmt Schwierigkeit und Beute)."] = "- Каждая смерть усиливает оставшихся -> порядок убийства определить заранее (от него зависят сложность и лут)."
L["- Brundir: Überladung (große Blitzexplosion) -> 30 m weg; Kettenblitz -> unterbrechen; Blitzranken verfolgen Spieler -> weglaufen."] = "- Брундир: Перегрузка (большой взрыв молний) -> 30 м прочь; Цепная молния -> кикать; Вихрь молний преследует игроков -> убегать."
L["- Molgeim: Rune der Macht -> Tanks ziehen die Bosse hinein, Raid steht drin; Rune des Todes -> sofort raus; Runenschild -> bannen/Zauberraub."] = "- Молгейм: Руна силы -> танки затягивают туда боссов, рейд стоит внутри; Руна смерти -> сразу выйти; Рунический щит -> диспел/Чарокрадство."
L["- Stahlbrecher: Fusionsschlag auf den Tank -> Debuff bannen; Hohe Spannung pulsiert Raidschaden -> Heiler stark gefordert."] = "- Сталелом: Удар синтеза по танку -> диспелить дебафф; Высокое напряжение пульсирует уроном по рейду -> большая нагрузка на хилов."
L["Taktik: Drei Tanks, Bosse getrennt voneinander halten. Leichter Modus: Stahlbrecher zuerst, dann Molgeim, Brundir zuletzt; Hardmode genau umgekehrt (Stahlbrecher zuletzt)."] = "Тактика: три танка, боссов держать отдельно друг от друга. Лёгкий режим: сначала Сталелом, потом Молгейм, Брундир последним; хардмод ровно наоборот (Сталелом последним)."
L["VERSAMMLUNG: Totenkopf zuerst! Überladung -> 30 m weg!"] = "СОБРАНИЕ: сначала Череп! Перегрузка -> 30 м прочь!"
L["Rune des Todes raus, Rune der Macht rein. Kettenblitz unterbrechen."] = "Из Руны смерти выйти, в Руну силы зайти. Кикать Цепную молнию."
L["Versammlung des Eisens"] = "Железное собрание"
L["Totenkopf = erstes, Kreuz = zweites, Viereck = drittes Ziel laut gewählter Tötungsreihenfolge."] = "Череп = первая, Крест = вторая, Квадрат = третья цель согласно выбранному порядку убийства."
L["Kologarn"] = "Кологарн"
L["Kologarn + Linker/Rechter Arm, Geröll-Adds"] = "Кологарн + левая/правая рука, адды-обломки"
L["- Steingriff (rechter Arm): packt Spieler -> genug Schaden auf den rechten Arm, um sie zu befreien."] = "- Каменная хватка (правая рука): хватает игроков -> достаточно урона по правой руке, чтобы их освободить."
L["- Fokussierter Augenstrahl: zwei Strahlen verfolgen ein Ziel -> Ziel läuft den Strahl vom Raid weg."] = "- Сосредоточенный взгляд: два луча преследуют цель -> цель уводит луч от рейда."
L["- Überkopfschlag / Rüstung zermalmen: starker Tankschaden, stapelnder Debuff -> Tankwechsel."] = "- Удар сверху / Сокрушение доспеха: сильный урон по танку, стакающийся дебафф -> смена танков."
L["- Geröll: Adds nach dem Tod eines Arms -> Offtank sammelt, AoE."] = "- Обломки: адды после смерти руки -> офф-танк собирает, АоЕ."
L["- Versteinernder Atem: wenn kein Nahkämpfer in Reichweite ist -> Tank immer in Reichweite halten."] = "- Каменное дыхание: если в радиусе нет мили -> танк всегда в радиусе."
L["Taktik: Kologarn steht fest, Tank und Nahkampf vorne, Fernkampf verteilt auf den Treppen. Arme nach Plan töten (Steingriff-Befreiung hat Vorrang), Augenstrahl kiten."] = "Тактика: Кологарн стоит на месте, танк и мили спереди, ренж рассредоточен на ступенях. Руки убивать по плану (освобождение из Каменной хватки в приоритете), луч кайтить."
L["KOLOGARN: Steingriff -> rechten Arm runter! Augenstrahl vom Raid weg!"] = "КОЛОГАРН: Каменная хватка -> опустить правую руку! Луч от рейда!"
L["Geröll per AoE. Tankwechsel bei Rüstung zermalmen."] = "Обломки АоЕ. Смена танков на Сокрушении доспеха."
L["Mimiron"] = "Мимирон"
L["Mimiron: Leviathan Mk II, VX-001, Luftkommandoeinheit, V-07-TR-0N"] = "Мимирон: Левиафан II, VX-001, Воздушное судно, V-07-TR-0N"
L["- Phase 1 (Leviathan Mk II): Schockschlag -> Nahkampf sofort raus; Annäherungsminen meiden; Napalmgranate trifft Fernkampf -> verteilt stehen."] = "- Фаза 1 (Левиафан II): Шоковый удар -> мили сразу выйти; избегать мин; Напалмовый снаряд бьёт ренж -> стоять рассредоточенно."
L["- Phase 2 (VX-001): Laserbarrage dreht sich -> hinter den Boss bzw. aus dem Strahl; Raketenschlag -> raus aus der Einschlagmarkierung."] = "- Фаза 2 (VX-001): лазерный обстрел вращается -> за босса или из луча; Ракетный удар -> выйти из метки удара."
L["- Phase 3 (Luftkommandoeinheit): fliegt -> Fernkampf/Heiler; Angriffsbots lassen Magnetkern fallen -> nutzen, um die Einheit runterzuholen; Bombenbots töten."] = "- Фаза 3 (Воздушное судно): летает -> ренж/хилы; штурмботы роняют Магнитное ядро -> использовать, чтобы опустить судно; бомботов убивать."
L["- Phase 4 (V-07-TR-0N): alle drei Teile wieder kombiniert -> alle Mechaniken gleichzeitig, Teile kurz nacheinander töten."] = "- Фаза 4 (V-07-TR-0N): все три части снова вместе -> все механики одновременно, части убить почти одновременно."
L["Taktik: Phasen nacheinander, Nahkampf achtet in P1 und P4 auf Schockschlag. In P4 alle drei Teile gleichmäßig runter und innerhalb weniger Sekunden töten."] = "Тактика: фазы по очереди, мили в Ф1 и Ф4 следят за Шоковым ударом. В Ф4 все три части опускать равномерно и убить в пределах нескольких секунд."
L["Hardmode: Großer Roter Knopf startet Selbstzerstörung mit Feuer im Raum und Zeitlimit."] = "Хардмод: Большая красная кнопка запускает самоуничтожение с огнём в зале и лимитом времени."
L["MIMIRON: Schockschlag -> Nahkampf raus! Laser und Raketen ausweichen!"] = "МИМИРОН: Шоковый удар -> мили выйти! Уклоняться от лазера и ракет!"
L["P3 Magnetkern nutzen. P4 alle drei Teile gleichzeitig töten."] = "Ф3 использовать Магнитное ядро. Ф4 все три части убить одновременно."
L["Klingenschuppe"] = "Острокрылая"
L["Klingenschuppe + Dunkelrunen-Adds (Wächter, Wachposten, Behüter)"] = "Острокрылая + адды Тёмной руны (стражи, часовые, хранители)"
L["- Luftphase: Zwerge bauen Harpunen -> Harpunen abschießen, um Klingenschuppe herunterzuholen."] = "- Воздушная фаза: дворфы строят гарпуны -> стрелять гарпунами, чтобы опустить Острокрылую."
L["- Dunkelrunen-Adds: kommen aus den Höhlen -> Offtanks, Behüter/Wachposten zuerst töten."] = "- Адды Тёмной руны: выходят из пещер -> офф-танки, хранителей/часовых убивать первыми."
L["- Verschlingende Flamme: Feuerkreise am Boden -> sofort raus."] = "- Пожирающее пламя: огненные круги на полу -> сразу выйти."
L["- Nach Harpunentreffer: Boss am Boden und betäubt -> volles Burst; Flammenatem beim Aufstehen -> nicht vorne."] = "- После попадания гарпунов: босс на земле и оглушён -> полный бурст; Огненное дыхание при подъёме -> не стоять спереди."
L["- Bodenphase (50 %): Rüstung schmelzen stapelt auf dem Tank -> Tankwechsel."] = "- Наземная фаза (50 %): Плавление брони стакается на танке -> смена танков."
L["Taktik: Adds abfangen, Zwerge schützen, Harpunen bedienen und am Boden alles auf den Boss. Ab 50 % bleibt sie unten: Tankwechsel und Flammen meiden."] = "Тактика: перехватывать аддов, защищать дворфов, стрелять гарпунами и на земле всё в босса. С 50 % она остаётся внизу: смена танков и избегать пламени."
L["KLINGENSCHUPPE: Harpunen abschießen, am Boden Burst! Flammen raus!"] = "ОСТРОКРЫЛАЯ: стрелять гарпунами, на земле бурст! Из пламени выйти!"
L["Adds vom Offtank. Ab 50 % Tankwechsel bei Rüstung schmelzen."] = "Адды на офф-танке. С 50 % смена танков на Плавлении брони."
L["Thorim"] = "Торим"
L["Thorim + Arena-Adds, Runenkoloss, Uralter Runenriese"] = "Торим + адды арены, рунический колосс, древний рунический великан"
L["- Arena (Phase 1): Adds strömen in die Arena, Thorim wirft Blitze -> Adds töten, Kettenblitz-Flächen meiden."] = "- Арена (фаза 1): адды заполняют арену, Торим бросает молнии -> убивать аддов, избегать зон цепной молнии."
L["- Gang: Gang-Team kämpft sich zu Thorim -> Runenkoloss (Ansturm-Bahnen ausweichen) und Uralter Runenriese töten."] = "- Коридор: команда коридора пробивается к Ториму -> убить рунического колосса (уклоняться от линий рывка) и древнего рунического великана."
L["- Blitzladung: aufgeladene Kugel in der Arena -> nicht in den Blitzbereich."] = "- Заряд молнии: заряженная сфера на арене -> не заходить в зону молний."
L["- Phase 2: Thorim springt runter, Kegelblitz -> nicht vor ihm; Unausgeglichener Schlag -> Tankwechsel."] = "- Фаза 2: Торим спрыгивает, конусная молния -> не стоять перед ним; Несбалансированный удар -> смена танков."
L["Taktik: Raid teilen: Gang-Team (Tank, Heiler, DPS) läuft durch den Gang, Rest hält die Arena. Wenn Thorim springt, alle auf ihn, Tankwechsel nach Schlag."] = "Тактика: рейд разделить: команда коридора (танк, хил, ДПС) идёт через коридор, остальные держат арену. Когда Торим спрыгнет, все на него, смена танков после удара."
L["Hardmode: Thorim innerhalb des Zeitfensters erreichen, dann kämpft Sif mit."] = "Хардмод: добраться до Торима в отведённое время, тогда в бою участвует Сиф."
L["THORIM: Gang-Team los! Arena-Adds töten, Blitzfelder meiden!"] = "ТОРИМ: команда коридора — вперёд! Убивать аддов арены, избегать полей молний!"
L["P2: Nicht vor den Boss, Tankwechsel."] = "Ф2: не стоять перед боссом, смена танков."
L["XT-002 Dekonstruktor"] = "Разрушитель XT-002"
L["XT-002 Dekonstruktor + Schrottbots, Bumm-Bots, Hackbots"] = "Разрушитель XT-002 + мусороботы, взрывоботы, колотуны"
L["- Tympanischer Wutanfall: kanalisierter Raidschaden -> Raid hochheilen, Abklingzeiten."] = "- Раскаты ярости: канальный урон по рейду -> отхиливать рейд, кулдауны."
L["- Sengendes Licht / Gravitationsbombe: Debuffs auf Spielern -> Betroffene raus aus dem Raid."] = "- Опаляющий свет / Гравитационная бомба: дебаффы на игроках -> поражённые выходят из рейда."
L["- Herzphase (75/50/25 %): Herz freigelegt -> voller Schaden auf das Herz."] = "- Фаза сердца (75/50/25 %): сердце открыто -> полный урон по сердцу."
L["- Schrottbots: heilen XT -> töten, bevor sie ihn erreichen."] = "- Мусороботы: лечат XT -> убить, пока не добрались до него."
L["- Bumm-Bots: explodieren -> nicht im Nahkampf töten."] = "- Взрывоботы: взрываются -> не убивать в мили."
L["Taktik: XT mittig tanken, Fernkampf verteilt. Bomben-Ziele rausgehen, Herzphase burst, Adds vor dem Erreichen töten."] = "Тактика: XT танковать в центре, ренж рассредоточен. Цели бомб выходят, в фазу сердца бурст, аддов убивать до того, как они доберутся."
L["Hardmode: Herz töten -> XT voll geheilt und stärker."] = "Хардмод: убить сердце -> XT полностью вылечен и сильнее."
L["XT-002: Bomben-Ziele raus aus dem Raid! Herzphase burst!"] = "XT-002: цели бомб — из рейда! Фаза сердца — бурст!"
L["Schrottbots töten bevor sie heilen. Bumm-Bots weg vom Nahkampf."] = "Мусороботов убивать, пока не вылечили. Взрывоботов — подальше от мили."
L["Yogg-Saron"] = "Йогг-Сарон"
L["Yogg-Saron + Sara, Wächter, Tentakel, Gehirn"] = "Йогг-Сарон + Сара, стражи, щупальца, мозг"
L["- Phase 1 (Sara): Wächter von Yogg-Saron aus Wolken -> töten neben Sara (Schattennova schadet ihr)."] = "- Фаза 1 (Сара): стражи Йогг-Сарона из облаков -> убивать рядом с Сарой (Кольцо тьмы бьёт её)."
L["- Phase 2: Tentakel (Würger, Verderber, Zermalmer) und Portale -> Portalgruppe ins Gehirn, Einfluss-Tentakel töten, Gehirn schaden."] = "- Фаза 2: щупальца (сдавливающие, искажающие, тяжёлые) и порталы -> группа портала в мозг, убить щупальца влияния, урон по мозгу."
L["- Wahnsinn: Verstand sinkt -> Verstandsquelle (Freya) nutzen, unter 0 wird man gedankenkontrolliert."] = "- Безумие: рассудок падает -> использовать Источник рассудка (Фрейя), ниже 0 попадаешь под контроль разума."
L["- Todesstrahl: wandert -> ausweichen."] = "- Луч смерти: перемещается -> уклоняться."
L["- Phase 3: Blick des Wahnsinns -> wegsehen; Unsterbliche Wächter -> töten."] = "- Фаза 3: Взгляд безумца -> отвернуться; бессмертные стражи -> убивать."
L["Taktik: P1 Wächter zu Sara ziehen und dort töten, Wolken meiden. P2 feste Portalgruppe ins Gehirn, Rest tötet Tentakel; P3 bei Blick des Wahnsinns wegdrehen und alles auf Yogg."] = "Тактика: Ф1 стражей тянуть к Саре и убивать там, избегать облаков. Ф2 постоянная группа портала в мозг, остальные убивают щупальца; Ф3 на Взгляде безумца отвернуться и всё в Йогга."
L["Hardmode: Je weniger Hüter (Freya, Hodir, Thorim, Mimiron) helfen, desto schwerer; ohne Hüter ist es die schwerste Variante."] = "Хардмод: чем меньше хранителей (Фрейя, Ходир, Торим, Мимирон) помогает, тем сложнее; без хранителей — самый сложный вариант."
L["YOGG-SARON: Blick des Wahnsinns -> wegsehen! Verstand halten!"] = "ЙОГГ-САРОН: Взгляд безумца -> отвернуться! Держать рассудок!"
L["P2: Portalgruppe ins Gehirn, Würger-Tentakel sofort töten."] = "Ф2: группа портала в мозг, сдавливающие щупальца сразу убивать."
L["Archavons Kammer"] = "Склеп Аркавона"
L["Archavon der Steinwächter"] = "Аркавон Страж Камня"
L["- Felssplitter: Steingeschosse auf Spieler -> Fernkampf verteilt, gezielt heilen."] = "- Каменные осколки: каменные снаряды в игроков -> ренж рассредоточен, хилить прицельно."
L["- Zermalmender Sprung: springt auf einen Spieler und hinterlässt eine Erstickende Wolke -> sofort raus aus der Wolke."] = "- Сокрушительный прыжок: прыгает на игрока и оставляет удушливое облако -> сразу выйти из облака."
L["- Stampfen + Pfählen: betäubt die Nähe, danach Pfählen auf den Tank -> zweiter Tank übernimmt sofort (Tankwechsel)."] = "- Топот + Прокалывание: оглушает рядом, затем Прокалывание по танку -> второй танк сразу забирает (смена танков)."
L["- Raserei nach 5 Minuten -> reiner Schadenscheck."] = "- Бешенство через 5 минут -> чистая проверка ДПС."
L["Taktik: Zwei Tanks nebeneinander, Fernkampf verteilt. Nach Stampfen spottet der zweite Tank, Wolken meiden und vor der Raserei töten."] = "Тактика: два танка рядом, ренж рассредоточен. После Топота второй танк таунтит, избегать облаков и убить до бешенства."
L["ARCHAVON: Nach Pfählen sofort Tankwechsel! Raus aus den Wolken!"] = "АРКАВОН: после Прокалывания сразу смена танков! Из облаков выйти!"
L["Fernkampf verteilt. Raserei nach 5 Minuten."] = "Ренж рассредоточен. Бешенство через 5 минут."
L["Emalon der Sturmwächter"] = "Эмалон Страж Бури"
L["Emalon der Sturmwächter + 4 Sturmdiener"] = "Эмалон Страж Бури + 4 служителя бури"
L["- Blitznova: großer Schaden im Nahbereich -> Nahkampf rechtzeitig raus."] = "- Кольцо молний: большой урон вблизи -> мили вовремя выйти."
L["- Kettenblitz: springt zwischen Spielern -> verteilt stehen."] = "- Цепная молния: прыгает между игроками -> стоять рассредоточенно."
L["- Überladung: ein Sturmdiener wird größer und explodiert nach kurzer Zeit -> sofort töten."] = "- Перегрузка: один служитель бури растёт и вскоре взрывается -> сразу убить."
L["- Sturmdiener werden neu belebt -> getrennt tanken, Boss ist das Hauptziel."] = "- Служители бури воскрешаются -> танковать отдельно, босс — основная цель."
L["Taktik: Boss und Diener getrennt tanken, Raid verteilt. Überladenen Diener sofort töten, sonst Schaden auf Emalon."] = "Тактика: босса и служителей танковать раздельно, рейд рассредоточен. Перегруженного служителя сразу убивать, иначе урон по Эмалону."
L["EMALON: Überladenen Diener sofort töten! Blitznova -> Nahkampf raus!"] = "ЭМАЛОН: перегруженного служителя сразу убить! Кольцо молний -> мили выйти!"
L["Kettenblitz: verteilt stehen."] = "Цепная молния: стоять рассредоточенно."
L["Emalon"] = "Эмалон"
L["Die vier Sturmdiener markieren, damit der überladene schnell angesagt werden kann."] = "Пометить четырёх служителей бури, чтобы быстро объявить перегруженного."
L["Koralon der Flammenwächter"] = "Коралон Страж Огня"
L["- Meteorfäuste: Schläge werden auf nahe Ziele verteilt -> zwei Tanks nebeneinander, teilen."] = "- Метеоритные кулаки: удары делятся между ближними целями -> два танка рядом, делить."
L["- Flammende Glut: Feuerflächen am Boden -> raus."] = "- Пылающие угли: огненные зоны на полу -> выйти."
L["- Brennender Atem: Kegel nach vorne -> Raid nicht vor den Boss."] = "- Жгучее дыхание: конус вперёд -> рейд не стоит перед боссом."
L["- Brennende Wut: stapelnder Raidschaden -> Heiler steigern die Heilung, Kampf schnell beenden."] = "- Жгучая ярость: стакающийся урон по рейду -> хилы наращивают хил, бой закончить быстро."
L["Taktik: Zwei Tanks teilen die Meteorfäuste, Raid hinter dem Boss verteilt, Feuer meiden."] = "Тактика: два танка делят Метеоритные кулаки, рейд рассредоточен позади босса, избегать огня."
L["KORALON: Tanks teilen Meteorfäuste! Aus dem Feuer raus!"] = "КОРАЛОН: танки делят Метеоритные кулаки! Из огня выйти!"
L["Nicht vor den Boss. Brennende Wut stapelt -> zügig töten."] = "Не стоять перед боссом. Жгучая ярость стакается -> убить побыстрее."
L["Toravon der Eiswächter"] = "Торавон Страж Льда"
L["Toravon der Eiswächter + Gefrorene Kugeln"] = "Торавон Страж Льда + замёрзшие сферы"
L["- Gefrorene Kugel: Adds mit Frostschaden -> Offtank sammelt, Fernkampf tötet sie."] = "- Замёрзшая сфера: адды с ледяным уроном -> офф-танк собирает, ренж убивает."
L["- Gefrierender Boden: Eisflächen -> sofort raus."] = "- Замерзающая земля: ледяные зоны -> сразу выйти."
L["- Erfrierung: stapelt auf dem Tank -> Tankwechsel."] = "- Обморожение: стакается на танке -> смена танков."
L["- Weißwerden: stapelnder Raidschaden -> Heiler stark fordern, zügig töten."] = "- Белая мгла: стакающийся урон по рейду -> большая нагрузка на хилов, убить побыстрее."
L["Taktik: Zwei Tanks im Wechsel, Kugeln sammeln und töten, Eisflächen meiden."] = "Тактика: два танка по очереди, сферы собрать и убить, избегать ледяных зон."
L["TORAVON: Gefrorene Kugeln töten! Tankwechsel bei Erfrierung!"] = "ТОРАВОН: убивать замёрзшие сферы! Смена танков на Обморожении!"
L["Gefrierender Boden: sofort raus."] = "Замерзающая земля: сразу выйти."
L["Baradinfestung"] = "Крепость Барадин"
L["Argaloth"] = "Аргалот"
L["- Meteorschlag: frontaler Schaden, wird auf alle Spieler vor dem Boss aufgeteilt; Debuff erhöht den nächsten Treffer -> zwei Gruppen abwechselnd vor den Boss stellen, Tankwechsel."] = "- Метеоритный удар: фронтальный урон, делится на всех игроков перед боссом; дебафф усиливает следующий удар -> две группы по очереди встают перед боссом, смена танков."
L["- Verzehrende Dunkelheit: starker Schattenschaden über Zeit auf mehreren Spielern -> Heiler gezielt gegenheilen."] = "- Поглощающая тьма: сильный теневой урон со временем на нескольких игроках -> хилы прицельно отхиливают."
L["- Teuflischer Feuersturm (bei 66 % und 33 %): Feuerflächen am Boden -> sofort rauslaufen, Raid wird stark beschädigt."] = "- Огненная буря Скверны (на 66 % и 33 %): огненные зоны на полу -> сразу выбегать, рейд получает много урона."
L["Taktik: Zwei Gruppen teilen sich abwechselnd den Meteorschlag, Tanks wechseln mit. Bei den Feuerstürmen bewegen und Heil-Cooldowns nutzen."] = "Тактика: две группы по очереди делят Метеоритный удар, танки меняются вместе с ними. На огненных бурях двигаться и использовать хил-кулдауны."
L["ARGALOTH: Meteorschlag in zwei Gruppen abwechselnd teilen!"] = "АРГАЛОТ: Метеоритный удар делить двумя группами по очереди!"
L["Feuersturm bei 66/33 %: aus dem Feuer laufen, Heil-CDs."] = "Огненная буря на 66/33 %: выбегать из огня, хил-КД."
L["Occu'thar + Augen von Occu'thar"] = "Окутар + глаза Окутара"
L["- Sengende Schatten: starker Frontalschaden auf den Tank mit Debuff -> Tankwechsel."] = "- Обжигающие тени: сильный фронтальный урон по танку с дебаффом -> смена танков."
L["- Fokussiertes Feuer: Feuerfläche unter einem Spieler -> sofort rauslaufen."] = "- Сосредоточенный огонь: огненная зона под игроком -> сразу выбежать."
L["- Augen von Occu'thar: auf jedem Spieler erscheint ein Auge, das kanalisiert und explodiert -> zusammenstehen und die Augen schnell mit Flächenschaden töten."] = "- Глаза Окутара: на каждом игроке появляется глаз, кастует и взрывается -> стоять вместе и быстро убивать глаза АоЕ."
L["Taktik: Raid steht eng zusammen für Flächenschaden auf die Augen, Tanks wechseln bei Sengende Schatten."] = "Тактика: рейд стоит плотно вместе для АоЕ по глазам, танки меняются на Обжигающих тенях."
L["OCCU'THAR: Augen sofort mit AoE töten! Zusammen stehen."] = "ОКУТАР: глаза сразу убивать АоЕ! Стоять вместе."
L["Feuer am Boden meiden, Tankwechsel bei Sengende Schatten."] = "Избегать огня на полу, смена танков на Обжигающих тенях."
L["Alizabal, Herrin des Hasses"] = "Ализабаль, Владычица Ненависти"
L["- Aufspießen: Tank wird aufgespießt und erhält mehr Schaden durch Brodelnder Hass -> Tankwechsel."] = "- Насаживание: танка насаживают, он получает больше урона от Кипящей ненависти -> смена танков."
L["- Brodelnder Hass: Schaden auf ein Ziel, aufgeteilt auf alle in der Nähe -> Raid stellt sich zum Ziel dazu."] = "- Кипящая ненависть: урон по одной цели, делится на всех рядом -> рейд встаёт к цели."
L["- Klingentanz: Alizabal wirbelt und springt zu zufälligen Spielern -> verteilen und vom Wirbel weglaufen."] = "- Танец клинков: Ализабаль вращается и прыгает к случайным игрокам -> рассредоточиться и убегать от вихря."
L["Taktik: Normalphase: zusammen stehen für Brodelnder Hass. Klingentanz: verteilt im Raum stehen und ausweichen."] = "Тактика: обычная фаза: стоять вместе для Кипящей ненависти. Танец клинков: стоять рассредоточенно по залу и уклоняться."
L["ALIZABAL: Brodelnder Hass gemeinsam teilen, Klingentanz verteilen!"] = "АЛИЗАБАЛЬ: Кипящую ненависть делить вместе, на Танце клинков рассредоточиться!"
L["Tankwechsel bei Aufspießen."] = "Смена танков на Насаживании."
L["Die Bastion des Zwielichts"] = "Сумеречный бастион"
L["Rat der Aszendenten (Feludius, Ignacious, Arion, Terrastra, Elementiummonstrosität)"] = "Совет перерожденных (Фелудий, Игнаций, Арион, Террастра, Чудовище из элементия)"
L["- Phase 1 Feludius/Ignacious: Hydrolanze und Aufsteigende Flammen unterbrechen; Durchnässt (Wasser) löscht Feuer-Debuffs, Gefroren-Spieler befreien."] = "- Фаза 1 Фелудий/Игнаций: кикать Гидрокопьё и Восходящее пламя; Промокание (вода) гасит огненные дебаффы, освобождать замороженных игроков."
L["- Phase 2 Arion/Terrastra: Blitzableiter -> vom Raid weglaufen; vor Beben den Geerdet-Buff holen, vor Donnerschock den Wirbelwind-Buff."] = "- Фаза 2 Арион/Террастра: Громоотвод -> убегать от рейда; перед Землетрясением взять бафф Заземление, перед Громовым ударом — бафф Смерч."
L["- Feuer- und Gravitationsbrunnen am Boden: nicht hineinlaufen."] = "- Огненные и гравитационные источники на полу: не заходить."
L["- Phase 3 Elementiummonstrosität: Flüssiges Eis wächst unter dem Boss -> Tank kitet ihn am Raumrand im Kreis, Raid verteilt gegen Elektrische Instabilität."] = "- Фаза 3 Чудовище из элементия: Жидкий лёд растёт под боссом -> танк кайтит его по кругу у края зала, рейд рассредоточен против Электрической нестабильности."
L["Taktik: Phase 1+2 die Bosse getrennt tanken und Unterbrecher fest einteilen; Leben gleichmäßig senken (Phase 3 startet mit gemeinsamem Leben). Phase 3 kiten und burnen."] = "Тактика: фазы 1+2 боссов танковать раздельно и жёстко распределить кикеров; здоровье снижать равномерно (фаза 3 начинается с общим здоровьем). Фаза 3 кайтить и бурстить."
L["RAT: Unterbrechen! Blitzableiter raus, Buffs vor Beben/Donnerschock holen!"] = "СОВЕТ: кикать! Громоотвод — выйти, баффы перед Землетрясением/Громовым ударом!"
L["Phase 3: Eis kiten, verteilen, burnen."] = "Фаза 3: кайтить лёд, рассредоточиться, бурст."
L["Rat der Aszendenten"] = "Совет перерожденных"
L["Totenkopf und Kreuz auf die zwei aktiven Ratsmitglieder je Phase (Unterbrecher fest zuordnen)."] = "Череп и Крест на двух активных членов совета в каждой фазе (кикеров закрепить)."
L["Cho'gall + Anhänger und Elementare"] = "Чо'Галл + последователи и элементали"
L["- Zorn von Cho'gall: stapelnder Debuff auf dem Tank -> Tankwechsel."] = "- Ярость Чо'Галла: стакающийся дебафф на танке -> смена танков."
L["- Bekehrung: Spieler werden zu Anbetern -> sie kurz kontrollieren oder wegschlagen, bis sie frei sind."] = "- Обращение: игроки становятся поклонниками -> ненадолго контролить или выбивать, пока не освободятся."
L["- Verderbte Anhänger: verbreiten Verderbnis, Verderbtheit unterbrechen -> Anhänger sofort töten."] = "- Осквернённые последователи: распространяют порчу, кикать Осквернение -> последователей сразу убивать."
L["- Verderbnis-Leiste: steigt durch Fähigkeiten; hohe Verderbnis schwächt Spieler stark -> Flächen meiden, Verderbnis niedrig halten."] = "- Шкала порчи: растёт от способностей; высокая порча сильно ослабляет игроков -> избегать зон, держать порчу низкой."
L["- Phase 2 (25 %): Tentakel der Verderbnis erscheinen -> schnell töten, Raidschaden steigt stark."] = "- Фаза 2 (25 %): появляются щупальца порчи -> быстро убивать, урон по рейду сильно растёт."
L["Taktik: Anhänger und Elementare haben Priorität, Tanks wechseln. Ab 25 % alle Cooldowns und schnell burnen."] = "Тактика: последователи и элементали в приоритете, танки меняются. С 25 % все кулдауны и быстрый бурн."
L["CHO'GALL: Anhänger zuerst töten und unterbrechen!"] = "ЧО'ГАЛЛ: сначала последователи, убивать и кикать!"
L["Bekehrte Spieler kontrollieren. Ab 25 %: Tentakel weg, Burn!"] = "Обращённых игроков контролить. С 25 %: щупальца убрать, бурн!"
L["Cho'gall"] = "Чо'Галл"
L["Totenkopf und Kreuz auf die Verderbten Anhänger, Unterbrecher fest einteilen."] = "Череп и Крест на осквернённых последователей, кикеров закрепить."
L["Halfus Wyrmbrecher + Proto-Behemoth und Drachen"] = "Халфий Змеерез + протобегемот и драконы"
L["- Bösartige Schläge: stapelnder Heilungs-Verringerungs-Debuff auf dem Tank -> Tankwechsel."] = "- Злобные удары: стакающийся дебафф на снижение хила на танке -> смена танков."
L["- Wütendes Gebrüll: Raidschaden in Serie -> Halfus mit den Fähigkeiten befreiter Drachen stoppen bzw. Heil-CDs."] = "- Яростный рёв: серия урона по рейду -> останавливать Халфия способностями освобождённых драконов или хил-КД."
L["- Proto-Behemoth: Feuerbälle bzw. Sengendes Feuer auf den Raid -> verteilen."] = "- Протобегемот: огненные шары или Опаляющий огонь по рейду -> рассредоточиться."
L["- Drachen: jeder befreite Drache gibt Halfus einen Effekt, jeder getötete Drache schwächt ihn -> Drachen nacheinander befreien und töten."] = "- Драконы: каждый освобождённый дракон даёт Халфию эффект, каждый убитый дракон его ослабляет -> драконов освобождать и убивать по очереди."
L["Taktik: Drachen in fester Reihenfolge freilassen und töten (die aktiven Drachen wechseln wöchentlich), dann Halfus. Tanks wechseln regelmäßig."] = "Тактика: драконов освобождать и убивать в фиксированном порядке (активные драконы меняются каждую неделю), потом Халфий. Танки регулярно меняются."
L["HALFUS: Drachen nacheinander befreien und töten, dann Halfus!"] = "ХАЛФИЙ: драконов освобождать и убивать по очереди, потом Халфий!"
L["Tankwechsel bei Bösartige Schläge, verteilen gegen Feuerbälle."] = "Смена танков на Злобных ударах, рассредоточиться против огненных шаров."
L["Halfus"] = "Халфий"
L["Totenkopf, Kreuz, Viereck auf die Drachen in Tötungsreihenfolge."] = "Череп, Крест, Квадрат на драконов в порядке убийства."
L["Sinestra + Welpen und Zwielichtadds (nur Heroisch)"] = "Синестра + дракончики и сумеречные адды (только героик)"
L["- Peinigen: Debuff wird stärker und springt beim Bannen auf zwei Spieler über -> kontrolliert und fest eingeteilt bannen."] = "- Истязание: дебафф усиливается и при диспеле перескакивает на двух игроков -> диспелить контролируемо и по распределению."
L["- Flammenatem: Raidschaden -> Heil-Cooldowns."] = "- Огненное дыхание: урон по рейду -> хил-кулдауны."
L["- Zwielichtwelpen: töten; ihre Essenz erhöht den eigenen Schaden."] = "- Сумеречные дракончики: убивать; их сущность увеличивает свой урон."
L["- Phase 2: Sinestra wird immun, Zwielichtpanzer-Eier müssen fallen, während Calen den Strahl hält -> Spitecaller-Adds abfangen, Eier zerstören."] = "- Фаза 2: Синестра неуязвима, сумеречные яйца должны пасть, пока Кейлен держит луч -> перехватывать аддов-призывателей злобы, разбить яйца."
L["Taktik: Start bei 60 %. Phase 1 bis 30 % Welpen kontrolliert töten, Phase 2 Eier zerstören und Calen unterstützen, dann Sinestra burnen."] = "Тактика: старт на 60 %. Фаза 1 до 30 % контролируемо убивать дракончиков, фаза 2 разбить яйца и поддерживать Кейлена, затем бурн Синестры."
L["Nur im heroischen Modus verfügbar."] = "Доступно только в героическом режиме."
L["SINESTRA: Peinigen nur nach Plan bannen! Welpen töten."] = "СИНЕСТРА: Истязание диспелить только по плану! Убивать дракончиков."
L["Phase 2: Eier zerstören, Adds abfangen, Calen schützen."] = "Фаза 2: разбить яйца, перехватывать аддов, защищать Кейлена."
L["Sinestra"] = "Синестра"
L["Totenkopf und Kreuz auf die beiden Zwielichteier in Phase 2."] = "Череп и Крест на два сумеречных яйца в фазе 2."
L["Valiona und Theralion"] = "Валиона и Тералион"
L["- Blackout (Valiona): Debuff auf einem Spieler, Schaden wird aufgeteilt -> alle zusammenstellen, nicht bannen."] = "- Затмение (Валиона): дебафф на игроке, урон делится -> все встают вместе, не диспелить."
L["- Verschlingende Flammen (Valiona): Kegel-Feuerschaden -> aus dem Kegel hinter den Boss laufen."] = "- Пожирающее пламя (Валиона): огненный урон конусом -> выйти из конуса за босса."
L["- Einhüllende Magie (Theralion): Spieler schadet Verbündeten in der Nähe -> sofort aus dem Raid laufen."] = "- Обволакивающая магия (Тералион): игрок наносит урон союзникам рядом -> сразу выбежать из рейда."
L["- Tiefer Atem / Zwielichtmeteore in der Flugphase: Bahnen der Drachen meiden, Meteor gemeinsam teilen bzw. verteilen."] = "- Глубокий вдох / сумеречные метеоры в фазе полёта: избегать линий драконов, метеор делить вместе или рассредоточиться."
L["Taktik: Immer ein Drache am Boden, einer in der Luft; Boden-Drachen tanken und Fokus darauf, Leben beider gleichmäßig senken."] = "Тактика: всегда один дракон на земле, другой в воздухе; наземного дракона танковать и фокусить, здоровье обоих снижать равномерно."
L["VALIONA & THERALION: Blackout zusammen stehen, Einhüllende Magie raus!"] = "ВАЛИОНА И ТЕРАЛИОН: на Затмении стоять вместе, с Обволакивающей магией — выйти!"
L["Kegel hinter dem Boss meiden, Atem-Bahnen ausweichen."] = "Избегать конуса за боссом, уклоняться от линий дыхания."
L["Pechschwingenabstieg"] = "Твердыня Крыла Тьмы"
L["Atramedes"] = "Атрамед"
L["- Schall-Leiste: jeder Laut erhöht die Leiste, bei 100 % Tod -> Schallwellen und Schallpulse meiden."] = "- Шкала звука: каждый звук повышает шкалу, на 100 % смерть -> избегать звуковых волн и звуковых импульсов."
L["- Sengende Flamme: Raidschaden -> mit dem Gong (Antikes Zwergenschild) unterbrechen."] = "- Опаляющее пламя: урон по рейду -> прервать с помощью гонга (Древний щит дворфов)."
L["- Modulation: Raidschaden und Schall -> gegenheilen."] = "- Модуляция: урон по рейду и звук -> отхиливать."
L["- Flugphase: Brüllender Flammenatem verfolgt einen Spieler -> wegkiten oder per Gong befreien; Schallringe meiden."] = "- Фаза полёта: Ревущее огненное дыхание преследует игрока -> кайтить или освободиться гонгом; избегать звуковых колец."
L["Taktik: Boden: Boss ruhig tanken, Schall meiden. Flugphase: verfolgter Spieler kitet, bei Bedarf Gong schlagen. Gongs sparsam einsetzen."] = "Тактика: земля: босса спокойно танковать, избегать звука. Фаза полёта: преследуемый игрок кайтит, при необходимости бить в гонг. Гонги расходовать экономно."
L["ATRAMEDES: Schall meiden! Gong gegen Sengende Flamme nutzen."] = "АТРАМЕД: избегать звука! Гонг против Опаляющего пламени."
L["Flugphase: Verfolgter kitet den Atem, alle anderen verteilen."] = "Фаза полёта: преследуемый кайтит дыхание, все остальные рассредоточены."
L["Schimaeron + Bilotron 800"] = "Химерон + Желчетрон-800"
L["- Massaker: tödlicher Schaden auf alle; Finkles Mixtur lässt Spieler über 10.000 HP mit 1 HP überleben -> alle vorher und danach hochheilen."] = "- Бойня: смертельный урон по всем; Смесь Финкла позволяет игрокам выше 10.000 HP выжить с 1 HP -> всех отхилить до и после."
L["- Ätzender Schleim: Schaden wird aufgeteilt -> in Gruppen zusammenstehen."] = "- Едкая слизь: урон делится -> стоять вместе группами."
L["- Doppelangriff/Zerschmettern: stapelnder Debuff auf dem Tank -> Tankwechsel."] = "- Двойная атака/Сокрушение: стакающийся дебафф на танке -> смена танков."
L["- Fehde: kurz keine Heilung -> vorher volles Leben."] = "- Вражда: ненадолго нет хила -> перед этим полное здоровье."
L["- Sterblichkeit (20 %): Heilung unmöglich -> nur noch burnen."] = "- Смертность (20 %): лечение невозможно -> только бурн."
L["Taktik: Raid in feste Gruppen aufteilen, nach jedem Massaker sofort hochheilen. Ab 20 % alle Cooldowns und burnen."] = "Тактика: рейд разделить на фиксированные группы, после каждой Бойни сразу отхилить. С 20 % все кулдауны и бурн."
L["SCHIMAERON: Alle über 10k HP halten! Gruppen gegen Schleim!"] = "ХИМЕРОН: всех держать выше 10k HP! Группы против слизи!"
L["Tankwechsel. Ab 20 %: keine Heilung mehr – BURN!"] = "Смена танков. С 20 %: хила больше нет – БУРН!"
L["Omnotron-Verteidigungssystem (Arkanotron, Elektron, Magmatron, Toxitron)"] = "Система защиты Омнитрон (Чаротрон, Электрон, Магмотрон, Токситрон)"
L["- Arkanotron: Kraftumwandlung und Arkane Vernichtung -> unterbrechen."] = "- Чаротрон: Преобразование энергии и Чародейское уничтожение -> кикать."
L["- Elektron: Blitzableiter -> vom Raid weglaufen."] = "- Электрон: Громоотвод -> убегать от рейда."
L["- Magmatron: Zielerfassung/Flammenwerfer auf einen Spieler -> verteilen; während der Barriere keinen Schaden machen."] = "- Магмотрон: Захват цели/Огнемёт на игрока -> рассредоточиться; во время барьера не бить."
L["- Toxitron: Chemische Wolke und Giftbomben-Schleime -> Schleime kiten/töten, Wolke beachten."] = "- Токситрон: Химическое облако и слизни с ядовитыми бомбами -> слизней кайтить/убивать, следить за облаком."
L["Taktik: Immer zwei Golems aktiv, der Schild wechselt. Je ein Tank pro aktivem Golem, Unterbrecher für Arkanotron, Schaden auf die aktiven Golems."] = "Тактика: всегда два голема активны, щит переходит. По одному танку на каждого активного голема, кикеры на Чаротрона, урон по активным големам."
L["OMNOTRON: Arkanotron unterbrechen! Blitzableiter raus!"] = "ОМНИТРОН: кикать Чаротрона! С Громоотводом — выйти!"
L["Magmatron-Barriere nicht angreifen. Schleime kiten."] = "Барьер Магмотрона не бить. Слизней кайтить."
L["Magmaul + Lavaparasiten"] = "Магмарь + лавовые паразиты"
L["- Magmaspucke/Lavaspucke: Raidschaden -> Heil-CDs bei Lavaspucke."] = "- Плевок магмой/Плевок лавой: урон по рейду -> хил-КД на Плевке лавой."
L["- Flammensäule: Lavaparasiten schlüpfen -> töten, nicht befallen lassen."] = "- Огненный столб: вылупляются лавовые паразиты -> убивать, не давать заразить."
L["- Zermalmen: Tank wird gepackt und stark beschädigt -> Heiler fokussieren, danach Massaker meiden."] = "- Сокрушение: танка хватают и сильно бьют -> хилы фокусят, потом избегать Бойни."
L["- Aufspießen: nach Zermalmen springt ein Spieler auf die Zange und kettet den Kopf an -> Kopf ist freigelegt, Schadensfenster."] = "- Насаживание: после Сокрушения игрок прыгает на клешню и приковывает голову -> голова открыта, окно урона."
L["Taktik: Tank vor dem Boss, Raid verteilt, Parasiten schnell töten. Nach jedem Zermalmen den Kopf anketten lassen und dann mit allem Schaden auf den Kopf."] = "Тактика: танк перед боссом, рейд рассредоточен, паразитов быстро убивать. После каждого Сокрушения приковать голову и затем весь урон по голове."
L["MAGMAUL: Parasiten töten! Nach Zermalmen Kopf anketten!"] = "МАГМАРЬ: убивать паразитов! После Сокрушения приковать голову!"
L["Kopf freigelegt = volle Burst-CDs auf den Kopf."] = "Голова открыта = все бурст-КД по голове."
L["Maloriak + Aberrationen"] = "Малориак + аберрации"
L["- Rote Phiole: Versengende Explosion (Kegel) und Verzehrende Flammen -> Raid steht zusammen, Kegel vom Raid weg."] = "- Красный флакон: Обжигающий взрыв (конус) и Пожирающее пламя -> рейд стоит вместе, конус от рейда."
L["- Blaue Phiole: Beißende Kälte und Blitzgefrieren -> eingefrorene Spieler befreien, verteilen."] = "- Синий флакон: Трескучий мороз и Мгновенная заморозка -> освобождать замороженных, рассредоточиться."
L["- Grüne Phiole: Schwächender Schleim -> Schadensfenster, Aberrationen von Tank aufnehmen."] = "- Зелёный флакон: Ослабляющая слизь -> окно урона, аберраций принимает танк."
L["- Arkaner Sturm und Aberrationen freilassen: unterbrechen; Heilmittel vom Boss reinigen/stehlen."] = "- Чародейская буря и выпуск аберраций: кикать; Исцеление с босса диспелить/красть."
L["- Phase 2 (20 %): Urerschaffungen, Magmastrahlen, Absoluter Null -> burnen."] = "- Фаза 2 (20 %): первичные создания, магмовые струи, Абсолютный ноль -> бурн."
L["Taktik: Unterbrecher fest einteilen, Aberrationen gezielt freilassen und mit Flächenschaden töten. Ab 20 % Cooldowns und Boss burnen."] = "Тактика: кикеров жёстко распределить, аберраций выпускать контролируемо и убивать АоЕ. С 20 % кулдауны и бурн босса."
L["MALORIAK: Arkaner Sturm und Aberrationen unterbrechen!"] = "МАЛОРИАК: кикать Чародейскую бурю и аберраций!"
L["Phiolen beachten: Rot zusammen, Blau verteilen. 20 % Burn!"] = "Следить за флаконами: красный — вместе, синий — рассредоточиться. 20 % бурн!"
L["Maloriak"] = "Малориак"
L["Totenkopf, Kreuz, Viereck markieren die Unterbrecher-Reihenfolge am Boss."] = "Череп, Крест, Квадрат обозначают порядок кикеров на боссе."
L["Nefarian + Onyxia + Belebte Knochenkrieger"] = "Нефариан + Ониксия + оживлённые костяные воины"
L["- Phase 1: Onyxia lädt Elektrische Überladung auf -> Onyxia zuerst töten; Nefarians Elektrisieren bei jeden 10 % Leben."] = "- Фаза 1: Ониксия заряжает Электрическую перегрузку -> сначала убить Ониксию; Электризация Нефариана на каждых 10 % здоровья."
L["- Belebte Knochenkrieger: von Schattenflammenfunken wiederbelebt -> kiten, kontrollieren oder weiter tanken."] = "- Оживлённые костяные воины: воскрешаются искрами огня тьмы -> кайтить, контролить или продолжать танковать."
L["- Phase 2: Lava steigt -> auf die Säulen, Chromatische Prototypen (Druckwellennova) unterbrechen und töten."] = "- Фаза 2: лава поднимается -> на колонны, хроматических прототипов (Взрывная волна) кикать и убивать."
L["- Phase 3: Schattenflammensperrfeuer und Knochenkrieger -> verteilen, Adds wegkiten, Boss burnen."] = "- Фаза 3: Шквал огня тьмы и костяные воины -> рассредоточиться, аддов кайтить, бурн босса."
L["Taktik: P1 Onyxia und Nefarian getrennt tanken, Onyxia zuerst. P2 drei Gruppen auf den Säulen gegen die Prototypen. P3 Adds kiten, Nefarian töten."] = "Тактика: Ф1 Ониксию и Нефариана танковать раздельно, сначала Ониксия. Ф2 три группы на колоннах против прототипов. Ф3 аддов кайтить, убить Нефариана."
L["NEFARIAN: Onyxia zuerst! Phase 2 auf die Säulen!"] = "НЕФАРИАН: сначала Ониксия! Фаза 2 — на колонны!"
L["Prototypen unterbrechen. Phase 3: Knochenkrieger kiten, burnen."] = "Кикать прототипов. Фаза 3: кайтить костяных воинов, бурн."
L["Nefarian"] = "Нефариан"
L["Ein Symbol je Chromatischer Prototyp auf den Säulen (Unterbrecher-Gruppen)."] = "По одной метке на каждого хроматического прототипа на колоннах (группы кикеров)."
L["Drachenseele"] = "Душа Дракона"
L["Kriegsmeister Schwarzhorn + Goriona + Zwielichtdrachen"] = "Воевода Чёрный Рог + Гориона + сумеречные драконы"
L["- Zwielichtsperrfeuer: Geschosse auf das Schiff -> Spieler fangen sie ab, sonst nimmt das Schiff Schaden."] = "- Сумеречный обстрел: снаряды по кораблю -> игроки перехватывают, иначе корабль получает урон."
L["- Zwielichtangriff: große Einschlagzone -> mit mehreren Spielern hineinstellen, um den Schaden zu teilen."] = "- Сумеречный натиск: большая зона удара -> встать туда несколькими игроками, чтобы разделить урон."
L["- Pioniere: springen aufs Deck und explodieren -> abfangen, verlangsamen und töten."] = "- Саперы: прыгают на палубу и взрываются -> перехватывать, замедлять и убивать."
L["- Phase 2: Verwüsten (Tankwechsel), Schockwelle frontal -> nicht vor dem Boss stehen."] = "- Фаза 2: Опустошение (смена танков), Ударная волна спереди -> не стоять перед боссом."
L["Taktik: Phase 1: Drachen per Harpune runterholen und töten, Sperrfeuer abfangen. Phase 2: Schwarzhorn tanken, Goriona aufhalten, burnen."] = "Тактика: фаза 1: драконов сбивать гарпуном и убивать, перехватывать обстрел. Фаза 2: танковать Чёрного Рога, задерживать Гориону, бурн."
L["SCHWARZHORN: Sperrfeuer abfangen! Pioniere sofort töten!"] = "ЧЁРНЫЙ РОГ: перехватывать обстрел! Саперов сразу убивать!"
L["Phase 2: Tankwechsel bei Verwüsten, Schockwelle meiden."] = "Фаза 2: смена танков на Опустошении, избегать Ударной волны."
L["Schwarzhorn"] = "Чёрный Рог"
L["Totenkopf und Kreuz auf die Zwielicht-Angriffsdrachen bzw. Pioniere."] = "Череп и Крест на сумеречных штурмовых драконов или саперов."
L["Hagara die Sturmbinderin"] = "Хагара Заклинательница Бурь"
L["- Eislanze: Strahlen von Eiskugeln -> zugewiesene Spieler stellen sich in die Strahlen."] = "- Ледяное копьё: лучи от ледяных сфер -> назначенные игроки встают в лучи."
L["- Eisgrab: Spieler werden eingefroren -> Gräber schnell zerschlagen."] = "- Ледяная гробница: игроков замораживает -> быстро разбивать гробницы."
L["- Konzentrierter Angriff: schnelle frontale Angriffe -> nur der Tank steht vor dem Boss."] = "- Сосредоточенная атака: быстрые фронтальные атаки -> перед боссом стоит только танк."
L["- Frostphase: Eiswände rotieren -> ausweichen und die vier Gefrorenen Bindungskristalle zerstören."] = "- Ледяная фаза: вращаются ледяные стены -> уклоняться и разбить четыре замёрзших связующих кристалла."
L["- Blitzphase: Blitzleiter-Kette zu den vier Leitkristallen aufbauen -> danach Rückkopplung = Schadensfenster."] = "- Фаза молний: построить цепь проводников к четырём кристаллам-проводникам -> затем Обратная связь = окно урона."
L["Taktik: Normalphase Eislanze soaken und Gräber brechen. In den Spezialphasen Kristalle aktivieren/zerstören, dann während Rückkopplung burnen."] = "Тактика: обычная фаза — соакать Ледяное копьё и разбивать гробницы. В спецфазах активировать/разбить кристаллы, затем бурн во время Обратной связи."
L["HAGARA: Eislanzen soaken! Eisgräber zerschlagen!"] = "ХАГАРА: соакать Ледяные копья! Разбивать ледяные гробницы!"
L["Frostphase: Wände meiden, Kristalle. Blitzphase: Kette bilden."] = "Ледяная фаза: избегать стен, кристаллы. Фаза молний: построить цепь."
L["Wahnsinn von Todesschwinge + Gliedmaßen"] = "Безумие Смертокрыла + конечности"
L["- Gliedmaßen: an jeder Plattform eine Gliedmaße töten, bevor Kataklysmus durch ist."] = "- Конечности: на каждой платформе убить конечность, пока не завершился Катаклизм."
L["- Mutierte Verderbnis: Aufspießen -> Tankwechsel; Zermalmen meiden."] = "- Мутировавшая порча: Насаживание -> смена танков; избегать Сокрушения."
L["- Elementiumblitz: schlägt auf einer Plattform ein -> Aspekt-Hilfe nutzen (z.B. Nozdormus Zeitzone)."] = "- Взрыв элементия: падает на платформу -> использовать помощь аспекта (напр. зону времени Ноздорму)."
L["- Phase 2 (Kopf): Elementiumfragmente, Elementiumschrecken -> Adds töten, Verderbtes Blut stapelt Raidschaden."] = "- Фаза 2 (голова): осколки элементия, элементиевые ужасы -> убивать аддов, Осквернённая кровь стакает урон по рейду."
L["Taktik: Plattformen nacheinander abarbeiten und die Fähigkeit des jeweiligen Aspekts nutzen. Phase 2: Fragmente und Schrecken töten, Kopf burnen."] = "Тактика: платформы проходить по очереди и использовать способность соответствующего аспекта. Фаза 2: убивать осколки и ужасов, бурн головы."
L["TODESSCHWINGE: Gliedmaße vor Kataklysmus töten!"] = "СМЕРТОКРЫЛ: убить конечность до Катаклизма!"
L["Aspekt-Fähigkeiten nutzen. Phase 2: Adds töten, Kopf burnen."] = "Использовать способности аспектов. Фаза 2: убивать аддов, бурн головы."
L["Morchok"] = "Морхок"
L["- Stampfen: Schaden wird auf Spieler in der Nähe aufgeteilt -> Tanks und Nahkampf nah dran."] = "- Топот: урон делится между игроками рядом -> танки и мили вплотную."
L["- Resonanzkristall: explodiert, Schaden je nach Entfernung -> eingeteilte Spieler nah beim Kristall."] = "- Резонирующий кристалл: взрывается, урон зависит от расстояния -> назначенные игроки рядом с кристаллом."
L["- Erdenwirbel + Schwarzes Blut der Erde: Raid wird angezogen, dann Bodenschaden -> hinter die Felssäulen gehen."] = "- Земляной вихрь + Чёрная кровь земли: рейд притягивает, затем урон по полу -> зайти за каменные колонны."
L["- Wütend (20 %): mehr Schaden -> Cooldowns."] = "- Ярость (20 %): больше урона -> кулдауны."
L["Taktik: Zwei Tanks nah am Boss gegen Stampfen, drei Spieler soaken Kristalle. Bei Schwarzes Blut hinter die Säulen."] = "Тактика: два танка вплотную к боссу против Топота, три игрока соакают кристаллы. На Чёрной крови — за колонны."
L["Heroisch: Zwilling Kohcrom erscheint und muss getrennt getankt werden."] = "Героик: появляется близнец Кохкром, его надо танковать отдельно."
L["MORCHOK: Kristalle soaken, Stampfen mit Nahkampf teilen!"] = "МОРХОК: соакать кристаллы, Топот делить с мили!"
L["Schwarzes Blut: hinter die Felssäulen! Ab 20 % Cooldowns."] = "Чёрная кровь: за каменные колонны! С 20 % кулдауны."
L["Rückgrat von Todesschwinge + Verderbnis, Amalgamation"] = "Хребет Смертокрыла + порча, слияние"
L["- Verderbnis: Feurige Umklammerung hält Spieler -> Verderbnis-Tentakel töten bzw. Umklammerung brechen."] = "- Порча: Пламенная хватка держит игроков -> убивать щупальца порчи или разрывать хватку."
L["- Abscheuliche Amalgamation: sammelt Blut-Stapel; bei voller Ladung zu einer Panzerplatte ziehen und dort töten -> Platte wird gelöst."] = "- Отвратительное слияние: собирает стаки крови; при полном заряде подвести к бронепластине и убить там -> пластина отрывается."
L["- Brennende Sehne: nach Plattenlösen erscheint die Sehne -> sofort burnen."] = "- Пылающее сухожилие: после отрыва пластины появляется сухожилие -> сразу бурн."
L["- Rolle: Todesschwinge rollt -> Raid auf die richtige Seite verteilen, sonst fliegen alle runter."] = "- Крен: Смертокрыл переворачивается -> распределить рейд на нужную сторону, иначе все слетят."
L["- Sengendes Plasma: Heilabsorption -> Heiler gegenheilen."] = "- Опаляющая плазма: поглощение исцеления -> хилы отхиливают."
L["Taktik: Drei Panzerplatten nacheinander lösen: Amalgamation stapeln und an der Platte töten, Sehne burnen. Gewicht auf dem Rücken ausgleichen."] = "Тактика: три бронепластины снимать по очереди: стакать слияние и убивать у пластины, бурн сухожилия. Выравнивать вес на спине."
L["RÜCKGRAT: Amalgamation an der Platte töten, Sehne burnen!"] = "ХРЕБЕТ: слияние убивать у пластины, бурн сухожилия!"
L["Bei Rolle Gewicht verteilen. Verderbnis-Tentakel töten."] = "На крене распределить вес. Убивать щупальца порчи."
L["Rückgrat"] = "Хребет"
L["Ein Symbol je Verderbnis-Tentakel, Totenkopf zuerst."] = "По одной метке на каждое щупальце порчи, Череп первым."
L["Ultraxion"] = "Ультраксион"
L["- Stunde des Zwielichts: tödlicher Schaden auf den Raid -> Tank/eingeteilte Spieler nehmen ihn, alle anderen Heldenhafter Wille."] = "- Час сумерек: смертельный урон по рейду -> танк/назначенные игроки принимают его, все остальные Героическая воля."
L["- Verblassendes Licht: Debuff, beim Ablaufen tödlich -> kurz vorher Heldenhafter Wille drücken."] = "- Угасающий свет: дебафф, смертелен по истечении -> незадолго до конца нажать Героическую волю."
L["- Instabile Monstrosität: stetig steigender Raidschaden -> Heil-CDs rotieren."] = "- Нестабильное чудовище: постоянно растущий урон по рейду -> ротация хил-КД."
L["- Gaben der Aspekte: Letzter Verteidiger (Tanks), Gabe des Lebens, Quell der Magie usw. aktiv einsetzen."] = "- Дары аспектов: Последний защитник (танки), Дар жизни, Источник магии и т. д. активно использовать."
L["Taktik: Raid steht eng zusammen, Tanks wechseln über Stunde des Zwielichts. Heldenhafter Wille exakt timen, Burn vor dem Wutanfall."] = "Тактика: рейд стоит плотно вместе, танки меняются на Часе сумерек. Героическую волю точно тайминговать, бурн до берсерка."
L["ULTRAXION: Heldenhafter Wille kurz vor Ablauf drücken!"] = "УЛЬТРАКСИОН: Героическую волю нажимать перед самым концом!"
L["Stunde des Zwielichts nach Plan soaken. Gaben nutzen."] = "Час сумерек соакать по плану. Использовать дары."
L["Yor'sahj der Unermüdliche + Kügelchen"] = "Йор'садж Неспящий + шарики"
L["- Kügelchen: mehrere farbige Kugeln rollen zum Boss -> vorher zwei (heroisch drei) töten, der Rest bestimmt Yor'sahjs Fähigkeiten."] = "- Шарики: несколько цветных сфер катятся к боссу -> заранее убить две (на героике три), остальные определяют способности Йор'саджа."
L["- Grün: Säure auf Spielern -> verteilen."] = "- Зелёный: кислота на игроках -> рассредоточиться."
L["- Rot: Sengendes Blut -> zusammenstehen."] = "- Красный: Опаляющая кровь -> стоять вместе."
L["- Schwarz: Adds -> AoE. Blau: Manaleere -> töten. Lila: Heilung schadet bzw. stapelt -> Heilung zurückhalten."] = "- Чёрный: адды -> АоЕ. Синий: опустошение маны -> убить. Фиолетовый: хил вредит или стакается -> придержать хил."
L["- Leerenblitz: Tank-Stapel -> Tankwechsel."] = "- Стрела Бездны: стаки на танке -> смена танков."
L["Taktik: Feste Prioritätsliste für die Kugel-Kombinationen, Gruppen auf die Kugeln aufteilen. Danach Mechanik der verbliebenen Farbe spielen."] = "Тактика: фиксированный список приоритетов для комбинаций шариков, группы распределить по шарикам. Затем отыгрывать механику оставшегося цвета."
L["YOR'SAHJ: Kügelchen nach Priorität töten!"] = "ЙОР'САДЖ: убивать шарики по приоритету!"
L["Grün verteilen, Rot zusammen, Lila: Heilung stoppen. Tankwechsel."] = "Зелёный — рассредоточиться, красный — вместе, фиолетовый: стоп хил. Смена танков."
L["Kriegsherr Zon'ozz + Tentakel"] = "Зон'озз + щупальца"
L["- Leere des Entwerdens: Kugel prallt zwischen Raid und Boss hin und her -> Raid fängt sie gemeinsam, Stapel erhöhen Schaden auf Boss."] = "- Сфера Бездны: сфера отскакивает между рейдом и боссом -> рейд ловит её вместе, стаки увеличивают урон по боссу."
L["- Störende Schatten: Magie-Debuff mit Rückstoß beim Bannen -> erst bannen, wenn der Spieler sicher steht."] = "- Тревожные тени: магический дебафф с отталкиванием при диспеле -> диспелить, только когда игрок стоит в безопасном месте."
L["- Psychische Entziehung: frontaler Schaden auf den Tank -> nicht vor dem Boss stehen."] = "- Психическое истощение: фронтальный урон по танку -> не стоять перед боссом."
L["- Schwarzes Blut von Go'rath: Tentakel (Augen, Klaue, Peitsche) -> schnell töten, Augen mit AoE."] = "- Чёрная кровь Го'рата: щупальца (глаза, коготь, плеть) -> быстро убивать, глаза АоЕ."
L["Taktik: Raid eng zusammen, Kugel gezielt mehrfach aufprallen lassen. In der Blutphase Tentakel töten, dann Boss burnen."] = "Тактика: рейд плотно вместе, сферу целенаправленно отбивать несколько раз. В фазу крови убить щупальца, затем бурн босса."
L["ZON'OZZ: Kugel zusammen fangen! Tentakel töten!"] = "ЗОН'ОЗЗ: сферу ловить вместе! Убивать щупальца!"
L["Störende Schatten nur an sicherer Stelle bannen."] = "Тревожные тени диспелить только в безопасном месте."
L["Feuerlande"] = "Огненные Просторы"
L["Alysrazar + Druiden, Brutlinge, Lavawürmer"] = "Алисразор + друиды, птенцы, лавовые черви"
L["- Geschmolzene Federn: einsammeln, um zu fliegen -> Flieger durch Feuerringe fliegen und Schaden machen."] = "- Расплавленные перья: собирать, чтобы летать -> летуны пролетают через огненные кольца и наносят урон."
L["- Feuerbrut-Brutlinge: werden wütend, wenn nicht gefüttert -> auf Lavawürmer ziehen."] = "- Птенцы огненного выводка: впадают в ярость, если их не кормить -> подводить к лавовым червям."
L["- Druiden der Flammenkralle: Feuerspucke unterbrechen, Brennende Klaue auf Tank."] = "- Друиды Огненного Когтя: кикать Огненный плевок, Пылающий коготь по танку."
L["- Feuertornados: in Phase 2 kreisen Tornados -> ausweichen."] = "- Огненные смерчи: в фазе 2 кружат смерчи -> уклоняться."
L["- Ausbrennen: Alysrazar ist energielos -> Schadensfenster, Raidschaden beachten."] = "- Выгорание: у Алисразор нет энергии -> окно урона, следить за уроном по рейду."
L["Taktik: 1–2 Spieler fliegen, Rest am Boden gegen Brutlinge und Druiden. Tornados meiden, beim Ausbrennen alles auf den Boss."] = "Тактика: 1–2 игрока летают, остальные на земле против птенцов и друидов. Избегать смерчей, на Выгорании всё в босса."
L["ALYSRAZAR: Federn sammeln, Brutlinge tanken, Druiden unterbrechen!"] = "АЛИСРАЗОР: собирать перья, танковать птенцов, кикать друидов!"
L["Tornados ausweichen. Ausbrennen = BURN!"] = "Уклоняться от смерчей. Выгорание = БУРН!"
L["Alysrazar"] = "Алисразор"
L["Totenkopf und Kreuz auf die zwei Brutlinge."] = "Череп и Крест на двух птенцов."
L["Baloroc, der Torwächter"] = "Бейлрок, Страж Врат"
L["- Splitter der Qual: Kristall schießt auf den nächsten Spieler -> zwei Gruppen wechseln sich beim Soaken ab (Gequält-Debuff)."] = "- Осколок мучений: кристалл бьёт ближайшего игрока -> две группы по очереди соакают (дебафф Мучение)."
L["- Inferno-Klinge: hoher Feuerschaden auf Tank -> Tank-CDs."] = "- Клинок инферно: сильный огненный урон по танку -> танковые КД."
L["- Dezimierungsklinge: Treffer kosten 90 % Leben -> Tank sofort hochheilen."] = "- Клинок истребления: удары снимают 90 % здоровья -> танка сразу отхиливать."
L["- Heiler: Lebendige Funken/Flammen stapeln durch Heilung auf Zielen nahe am Kristall."] = "- Хилы: Живые искры/пламя стакаются от лечения целей рядом с кристаллом."
L["Taktik: Raid steht hinter dem Boss, Soak-Rotation fest. Tanks wechseln je nach Klinge."] = "Тактика: рейд стоит за боссом, ротация соака фиксирована. Танки меняются в зависимости от клинка."
L["BALOROC: Kristall-Rotation einhalten!"] = "БЕЙЛРОК: соблюдать ротацию кристаллов!"
L["Dezimierungsklinge: Tank sofort hochheilen."] = "Клинок истребления: танка сразу отхилить."
L["Beth'tilac + Glutnetzspinner, Drohnen, Spinnlinge"] = "Бет'тилак + прядильщики углеродной паутины, трутни, паучата"
L["- Glimmende Verwüstung: bei leerer Feuerenergie hoher Schaden auf alle oben im Netz -> Spieler oben rechtzeitig runterspringen."] = "- Тлеющее опустошение: при пустой огненной энергии сильный урон по всем наверху в паутине -> игроки наверху вовремя спрыгивают."
L["- Glutnetzspinner: hängen an Fäden -> runterziehen und töten; ihr Faden bringt Spieler nach oben ins Netz."] = "- Прядильщики: висят на нитях -> стянуть и убить; их нить поднимает игроков наверх в паутину."
L["- Glutnetzdrohnen: tanken und töten, sie füllen sonst Beth'tilacs Energie auf."] = "- Трутни: танковать и убивать, иначе они пополняют энергию Бет'тилак."
L["- Spinnlinge: krabbeln zu den Drohnen -> verlangsamen und mit AoE töten."] = "- Паучата: ползут к трутням -> замедлять и убивать АоЕ."
L["- Phase 2 (nach der 3. Verwüstung): Beth'tilac kommt runter, Witwenkuss stapelt auf dem Tank -> Tankwechsel, Raidschaden steigt."] = "- Фаза 2 (после 3-го Опустошения): Бет'тилак спускается, Поцелуй вдовы стакается на танке -> смена танков, урон по рейду растёт."
L["Taktik: Eine Gruppe (Tank + Schaden) oben am Boss, der Rest unten gegen Adds. Phase 2: alle auf den Boss, Tankwechsel, Heil-CDs."] = "Тактика: одна группа (танк + ДПС) наверху у босса, остальные внизу против аддов. Фаза 2: все на босса, смена танков, хил-КД."
L["BETH'TILAC: Oben vor der Verwüstung runterspringen!"] = "БЕТ'ТИЛАК: наверху — спрыгнуть до Опустошения!"
L["Unten: Spinner runterziehen, Drohnen tanken, Spinnlinge AoE."] = "Внизу: стягивать прядильщиков, танковать трутней, паучат АоЕ."
L["Beth'tilac"] = "Бет'тилак"
L["Totenkopf und Kreuz auf die aktuellen Drohnen (Tank und Schaden)."] = "Череп и Крест на текущих трутней (танк и ДПС)."
L["Majordomus Hirschhaupt"] = "Мажордом Олений Шлем"
L["- Katzengestalt – Springende Flammen: springt auf Spieler und hinterlässt Feuer -> verteilt stehen, Feuer meiden."] = "- Облик кошки – Прыгающее пламя: прыгает на игроков и оставляет огонь -> стоять рассредоточенно, избегать огня."
L["- Skorpiongestalt – Flammensense: frontaler Schaden, aufgeteilt auf alle Getroffenen -> ganzer Raid steht zusammen vor dem Boss."] = "- Облик скорпиона – Огненная коса: фронтальный урон, делится на всех задетых -> весь рейд стоит вместе перед боссом."
L["- Formwechsel bei voller Energie bzw. Lebensschwellen: Raid muss Aufstellung sofort wechseln."] = "- Смена облика при полной энергии или порогах здоровья: рейд должен сразу менять расстановку."
L["- Menschliche Form – Sengende Samen: explodieren nach Zeit -> verteilen. Brennende Kugeln: Spieler werden beschossen -> Kugeln abfangen/gegenheilen."] = "- Облик человека – Опаляющие семена: взрываются через время -> рассредоточиться. Горящие сферы: обстреливают игроков -> перехватывать сферы/отхиливать."
L["Taktik: Raidleiter sagt jeden Formwechsel an: Katze = verteilen, Skorpion = eng zusammen vor dem Boss. Schaden und Heilung steigen mit jedem Zyklus."] = "Тактика: РЛ объявляет каждую смену облика: кошка = рассредоточиться, скорпион = плотно вместе перед боссом. Урон и хил растут с каждым циклом."
L["HIRSCHHAUPT: Katze = VERTEILEN, Skorpion = ZUSAMMEN vor dem Boss!"] = "ОЛЕНИЙ ШЛЕМ: кошка = РАЗОЙТИСЬ, скорпион = ВМЕСТЕ перед боссом!"
L["Sengende Samen: verteilen. Formwechsel sofort umsetzen."] = "Опаляющие семена: рассредоточиться. Смену облика выполнять сразу."
L["Ragnaros + Söhne der Flamme, Lavaabkömmlinge"] = "Рагнарос + сыны пламени, лавовые отродья"
L["- Sulfurasschmettern: Lavawellen breiten sich aus -> seitlich ausweichen."] = "- Удар Сульфураса: расходятся лавовые волны -> уклоняться вбок."
L["- Magmafalle: Spieler löst die Falle aus und schleudert den Raid hoch -> eingeteilter Spieler soakt, Raid auf Schaden vorbereitet."] = "- Магмовая ловушка: игрок активирует ловушку и подбрасывает рейд -> назначенный игрок соакает, рейд готов к урону."
L["- Zorn von Ragnaros: Rückstoß auf Spieler in der Nähe -> Nahkampf nicht zu nah, nicht in die Lava fallen."] = "- Гнев Рагнароса: отталкивание игроков рядом -> мили не слишком близко, не падать в лаву."
L["- Zwischenphasen (70 % / 40 %): Söhne der Flamme laufen zu Sulfuras -> verlangsamen und töten, bevor sie ankommen."] = "- Промежуточные фазы (70 % / 40 %): сыны пламени бегут к Сульфурасу -> замедлять и убивать, пока не добрались."
L["- Phase 2: Geschmolzene Samen -> verteilen, dann weglaufen. Phase 3: Lebendiger Meteor verfolgt Spieler -> wegkiten, zurückstoßen."] = "- Фаза 2: Расплавленные семена -> рассредоточиться, затем отбежать. Фаза 3: Живой метеор преследует игроков -> кайтить, отбрасывать."
L["Taktik: Phase 1 Lavawellen und Fallen spielen, Zwischenphasen alle Söhne töten. Phase 2 Samen meiden, Phase 3 Meteore kiten und Boss burnen."] = "Тактика: фаза 1 отыгрывать лавовые волны и ловушки, в промежуточных фазах убить всех сынов. Фаза 2 избегать семян, фаза 3 кайтить метеоры и бурн босса."
L["Heroisch: zusätzliche Phase 4 mit Cenarius, Malfurion und Hamuul."] = "Героик: дополнительная фаза 4 с Кенарием, Малфурионом и Хамуулом."
L["RAGNAROS: Lavawellen ausweichen! Zwischenphase: Söhne töten!"] = "РАГНАРОС: уклоняться от лавовых волн! Промежуточная фаза: убить сынов!"
L["Samen verteilen, Meteore kiten. Nicht in die Lava!"] = "Семена — рассредоточиться, метеоры кайтить. Не в лаву!"
L["Lord Rhyolith + Fragmente und Funken"] = "Повелитель Риолит + фрагменты и искры"
L["- Steuerung: Schaden auf linkes bzw. rechtes Bein lenkt den Boss -> gezielt auf aktive Vulkane steuern."] = "- Управление: урон по левой или правой ноге направляет босса -> целенаправленно вести на активные вулканы."
L["- Obsidianrüstung: verringert erlittenen Schaden -> Rhyolith über aktive Vulkane laufen lassen, um Stapel abzubauen."] = "- Обсидиановая броня: снижает получаемый урон -> проводить Риолита по активным вулканам, чтобы снимать стаки."
L["- Magmaflüsse und Lava: Bodenschaden -> ausweichen."] = "- Потоки магмы и лава: урон по полу -> уклоняться."
L["- Fragmente von Rhyolith: schnell mit AoE töten. Funke von Rhyolith: Add weg tanken."] = "- Фрагменты Риолита: быстро убивать АоЕ. Искра Риолита: адда танковать в стороне."
L["- Phase 2 (25 %): Rhyolith ohne Rüstung, Schaden steigt -> Tank übernimmt, burnen."] = "- Фаза 2 (25 %): Риолит без брони, урон растёт -> танк забирает, бурн."
L["Taktik: Zwei Gruppen auf linkes und rechtes Bein, Raidleiter steuert. Adds schnell töten, ab 25 % alles auf den Boss."] = "Тактика: две группы на левую и правую ногу, РЛ управляет. Аддов быстро убивать, с 25 % всё в босса."
L["RHYOLITH: Beine gezielt schlagen, auf Vulkane steuern!"] = "РИОЛИТ: бить ноги прицельно, вести на вулканы!"
L["Fragmente töten. Ab 25 % Burn!"] = "Убивать фрагменты. С 25 % бурн!"
L["Shannox + Riplimb und Rageface"] = "Шэннокс + Риплимб и Рейджфейс"
L["- Riplimb: stapelnder Blutungs-Debuff auf seinem Tank; holt den geworfenen Speer zurück -> Tankwechsel bei hohen Stapeln."] = "- Риплимб: стакающийся дебафф кровотечения на его танке; приносит брошенное копьё -> смена танков на высоких стаках."
L["- Rageface: springt Spieler an und zerfleischt sie -> schwer zu treffen, schnell befreien."] = "- Рейджфейс: прыгает на игроков и терзает их -> по нему трудно попасть, быстро освобождать."
L["- Speer: Shannox wirft den Speer, um ihn entstehen Feuerflächen -> rauslaufen."] = "- Копьё: Шэннокс бросает копьё, вокруг него возникают огненные зоны -> выбегать."
L["- Kristallgefängnisfalle: hält den ersten Treffer fest -> Hunde hineinführen."] = "- Ловушка-кристальная тюрьма: удерживает первого, кто попадёт -> заводить туда собак."
L["- Hunde nicht zu weit von Shannox wegziehen, sonst werden sie stärker."] = "- Собак не уводить слишком далеко от Шэннокса, иначе они усиливаются."
L["Taktik: Shannox und die Hunde nah beieinander tanken, Hunde mit Fallen kontrollieren. Gängige Reihenfolge: Rageface zuerst, dann Shannox."] = "Тактика: Шэннокса и собак танковать рядом, собак контролить ловушками. Обычный порядок: сначала Рейджфейс, затем Шэннокс."
L["SHANNOX: Hunde in Fallen ziehen, nah am Boss tanken!"] = "ШЭННОКС: собак заводить в ловушки, танковать рядом с боссом!"
L["Feuer am Speer meiden. Rageface zuerst."] = "Избегать огня у копья. Сначала Рейджфейс."
L["Thron der Vier Winde"] = "Трон Четырёх Ветров"
L["Al'Akir + Sturmlinge"] = "Ал'акир + штормовые элементали"
L["- Böenlinie: Wand aus Tornados mit Lücke -> durch die Lücke laufen bzw. sich mitnehmen lassen."] = "- Линия шквала: стена смерчей с просветом -> пройти через просвет или дать себя увлечь."
L["- Statischer Schock / Blitzschlag: bestraft Nicht-Nahkampf am Boss -> Tank immer in Nahkampfreichweite halten."] = "- Статический шок / Удар молнии: наказывает, если у босса нет мили -> танк всегда в мили-радиусе."
L["- Phase 2 (80 %): Säureregen stapelt Raidschaden -> schnell zur Phase 3; Sturmlinge töten."] = "- Фаза 2 (80 %): Кислотный дождь стакает урон по рейду -> быстро в фазу 3; убивать штормовых элементалей."
L["- Phase 3 (25 %): alle fliegen; Blitzableiter -> verteilen, Gewitterwolken ausweichen."] = "- Фаза 3 (25 %): все летают; Громоотвод -> рассредоточиться, уклоняться от грозовых туч."
L["Taktik: Phase 1 am Boss, Böenlinien beachten. Phase 2 Sturmlinge töten und durchschieben. Phase 3 in der Luft verteilen und burnen."] = "Тактика: фаза 1 у босса, следить за линиями шквала. Фаза 2 убивать элементалей и продавливать. Фаза 3 рассредоточиться в воздухе и бурн."
L["AL'AKIR: Böenlinie – Lücke suchen! Phase 2 schnell durch!"] = "АЛ'АКИР: линия шквала – искать просвет! Фазу 2 быстро пройти!"
L["Phase 3: verteilen, Gewitterwolken meiden."] = "Фаза 3: рассредоточиться, избегать грозовых туч."
L["Konklave des Windes (Anshal, Nezir, Rohash)"] = "Конклав Ветра (Аншал, Незир, Рохаш)"
L["- Anshal: ruft Kriecher -> Kriecher töten, nicht in Beruhigende Brise stehen."] = "- Аншал: призывает ползунов -> убивать ползунов, не стоять в Успокаивающем бризе."
L["- Nezir: Windkälte stapelt auf seinem Tank -> Tank nutzt CDs, Eisflächen meiden."] = "- Незир: Ледяной ветер стакается на его танке -> танк использует КД, избегать ледяных зон."
L["- Rohash: Sturmschneide und Hurrikan -> Fernkampf auf seiner Plattform halten."] = "- Рохаш: Режущий шторм и Ураган -> ренж держать на его платформе."
L["- Ultimate bei voller Energie: Plattformen sofort verlassen."] = "- Ульта при полной энергии: сразу покинуть платформы."
L["- Alle drei müssen innerhalb kurzer Zeit fallen, sonst steht der Rest wieder auf."] = "- Все трое должны умереть за короткое время, иначе остальные поднимаются снова."
L["Taktik: Drei Gruppen auf die drei Plattformen, Schaden gleichmäßig verteilen. Bei Ultimate zurück in die Mitte."] = "Тактика: три группы на три платформы, урон распределять равномерно. На ульте назад в центр."
L["KONKLAVE: Alle drei gleichzeitig töten!"] = "КОНКЛАВ: всех троих убить одновременно!"
L["Ultimate: Plattform verlassen!"] = "Ульта: покинуть платформу!"
L["Konklave"] = "Конклав"
L["Totenkopf, Kreuz, Viereck auf Anshal, Nezir, Rohash."] = "Череп, Крест, Квадрат на Аншала, Незира, Рохаша."
L["Herz der Angst"] = "Сердце Страха"
L["Kaiserlicher Wesir Zor'lok"] = "Императорский визирь Зор'лок"
L["- Ausatmen: Kanalisierung auf einen Spieler -> Tank/Spieler stellen sich in die Linie, um den Schaden abzufangen."] = "- Выдох: поддерживаемое заклинание на игрока -> танк/игроки встают в линию, чтобы перехватить урон."
L["- Abschwächung: Schallringe laufen über den Boden -> durch die Lücken der Ringe laufen."] = "- Ослабление: звуковые кольца расходятся по полу -> проходить через бреши в кольцах."
L["- Kraft und Elan: großer Raidschaden -> in die Schallblase (Geräuschunterdrückung) stellen."] = "- Сила и мощь: сильный урон по рейду -> вставать в звуковой пузырь (Шумоподавление)."
L["- Bekehren (heroisch/später): Spieler werden gedankenkontrolliert -> kontrollieren bzw. schnell runterschaden."] = "- Обращение (героик/позже): игроки под контролем разума -> контролить или быстро сбивать."
L["- Pheromone des Eifers: Gas am Boden -> auf den Plattformen bleiben."] = "- Феромоны рвения: газ на полу -> оставаться на платформах."
L["Taktik: Der Boss wechselt Plattformen; Raid folgt geschlossen. Bei Kraft und Elan sofort in die Blasen, Ausatmen-Ziel absichern."] = "Тактика: босс меняет платформы, рейд следует за ним плотной группой. На Силе и мощи сразу в пузыри, прикрыть цель Выдоха."
L["ZOR'LOK: Bei Kraft und Elan in die Blasen! Ringe durch Lücken!"] = "ЗОР'ЛОК: на Силе и мощи в пузыри! Кольца через бреши!"
L["Ausatmen-Linie blocken, nicht ins Gas am Boden."] = "Блокировать линию Выдоха, не стоять в газе на полу."
L["Klingenfürst Ta'yak"] = "Повелитель клинков Та'як"
L["- Unsichtbarer Schlag: Ziel wird markiert -> gesamter Raid stellt sich zum Ziel, um den Schaden zu teilen."] = "- Незримый удар: цель помечается -> весь рейд встает к цели, чтобы разделить урон."
L["- Überwältigender Angriff: Tankdebuff -> Tankwechsel."] = "- Сокрушительная атака: дебафф на танке -> смена танков."
L["- Windschritt: Teleport mit Blutungen auf nahe Spieler -> Heiler bereit."] = "- Шаг ветра: телепорт с кровотечениями на ближних игроках -> хилы наготове."
L["- Sturmhieb: Wirbelstürme laufen durch den Raum -> ausweichen."] = "- Штормовой удар: смерчи идут через зал -> уворачиваться."
L["- Phase 2 (20 %): Sturm entfesselt, Boss am Ende des Korridors -> Wirbelwinden ausweichen, gegen den Wind halten."] = "- Фаза 2 (20 %): буря высвобождена, босс в конце коридора -> уворачиваться от вихрей, держаться против ветра."
L["Taktik: Raid locker hinter dem Boss, bei Unsichtbarem Schlag zum markierten Spieler. Ab 20 % mit Cooldowns zügig beenden."] = "Тактика: рейд свободно за боссом, на Незримом ударе к помеченному игроку. С 20 % быстро добить под кулдаунами."
L["TA'YAK: Bei Unsichtbarem Schlag alle zum markierten Spieler!"] = "ТА'ЯК: на Незримом ударе все к помеченному игроку!"
L["Tankwechsel nach Stapeln, Wirbelstürmen ausweichen."] = "Смена танков по стакам, уворачиваться от смерчей."
L["Garalon (Riesenkäfer mit vier Beinen)"] = "Гаралон (огромный жук на четырех ногах)"
L["- Pheromone: Träger hinterlässt eine Spur und stapelt Schaden -> Pheromone kontrolliert weitergeben, Spur meiden."] = "- Феромоны: носитель оставляет след и стакает урон -> передавать феромоны по плану, не стоять в следе."
L["- Wütender Hieb: frontaler Hieb muss mindestens zwei Spieler treffen -> Tanks zusammen vorne stehen, sonst Wut."] = "- Яростный удар: фронтальный удар должен задеть минимум двух игроков -> танки вместе спереди, иначе enrage."
L["- Zerquetschen: Garalon wirft sich auf den Boden -> unter dem Boss sofort raus."] = "- Раздавливание: Гаралон падает на пол -> сразу выйти из-под босса."
L["- Beine: zerstörte Beine machen Garalon langsamer und verwundbarer, wachsen aber nach -> Nahkampf auf Beine."] = "- Ноги: сломанные ноги замедляют Гаралона и делают его уязвимее, но отрастают -> мили бьют ноги."
L["Taktik: Nahkampf zerstört Beine, Fernkampf auf den Körper. Pheromonträger kitet am Rand entlang, Raid hält sich aus der Spur."] = "Тактика: мили ломают ноги, рдд бьют тело. Носитель феромонов кайтит по краю, рейд не стоит в следе."
L["GARALON: Nahkampf auf Beine, Fernkampf Körper! Zwei Tanks vorne!"] = "ГАРАЛОН: мили по ногам, рдд по телу! Два танка спереди!"
L["Pheromonspur meiden, bei Zerquetschen raus unter dem Boss."] = "Не стоять в следе феромонов, на Раздавливании выйти из-под босса."
L["Windfürst Mel'jarak + Klingenmeister, Bernfallensteller und Kampfheiler"] = "Повелитель ветров Мел'джарак + мастера клинка, янтарные ловцы и боевые целители"
L["- Adds in drei Gruppen: stirbt ein Add, werden die anderen seiner Art stärker -> eine Gruppe nach der anderen töten, Rest kontrollieren."] = "- Адды в трех группах: если умирает адд, остальные его типа усиливаются -> убивать группы по одной, остальных контролить."
L["- Klingenregen: Raidschaden -> Heiler-Cooldowns."] = "- Дождь клинков: урон по рейду -> кулдауны хилов."
L["- Windbombe: Bombe am Boden -> nicht hineinlaufen."] = "- Ветряная бомба: бомба на полу -> не наступать."
L["- Ätzendes Harz: Bewegung erzeugt Pfützen -> stehen bleiben bzw. kontrolliert ablegen."] = "- Едкая смола: движение оставляет лужи -> стоять на месте или сбрасывать под контролем."
L["- Bernkerker: Spieler eingeschlossen -> ein anderer Spieler befreit ihn."] = "- Янтарная темница: игрок заточен -> другой игрок его освобождает."
L["Taktik: CC zuteilen, eine Add-Gruppe gezielt töten (oft die Heiler zuerst), danach Boss. Nicht unkontrolliert AoE auf CC-Ziele."] = "Тактика: распределить СС, целенаправленно убить одну группу аддов (часто сначала хилов), затем босса. Без бесконтрольного АоЕ по целям под СС."
L["MEL'JARAK: Nur Add-Gruppe X töten, CC-Ziele nicht anfassen!"] = "МЕЛ'ДЖАРАК: убивать только группу аддов X, цели под СС не трогать!"
L["Keine AoE auf CC! Bernkerker befreien, Windbomben meiden."] = "Без АоЕ по СС! Освобождать из Янтарной темницы, обходить ветряные бомбы."
L["Mel'jarak (CC)"] = "Мел'джарак (СС)"
L["Jedes zu kontrollierende Add ein Symbol; CC-Spieler halten ihr Symbol, Stern zuerst."] = "По метке на каждого адда под контроль; игроки на СС держат свою метку, Звезда первая."
L["Bernformer Un'sok + Lebendiger Bern und Bernmonstrosität"] = "Ваятель янтаря Ун'сок + Живой янтарь и Янтарное чудовище"
L["- Leben umformen: Spieler wird zum Konstrukt -> Bernexplosionen (eigene und der Monstrosität) unterbrechen, Willenskraft beachten, rechtzeitig ausbrechen."] = "- Перековка жизни: игрок превращается в конструкт -> сбивать Янтарные взрывы (свои и чудовища), следить за волей, вовремя вырваться."
L["- Bernskalpell: Strahl folgt einem Spieler und hinterlässt Lebendigen Bern -> zum Rand führen, Adds töten."] = "- Янтарный скальпель: луч следует за игроком и оставляет Живой янтарь -> уводить к краю, убивать аддов."
L["- Parasitäres Wachstum: Heilung verstärkt den Schaden auf dem Ziel -> Ziel sparsam heilen."] = "- Паразитический рост: исцеление усиливает урон по цели -> лечить цель экономно."
L["- Phase 2: Bernmonstrosität -> Konstrukte unterbrechen ihre Explosion, Tank hält sie weg."] = "- Фаза 2: Янтарное чудовище -> конструкты сбивают его взрыв, танк держит его в стороне."
L["- Phase 3 (Konzentrierte Mutation): mehr Konstrukte, hoher Raidschaden -> schnell beenden."] = "- Фаза 3 (Концентрированная мутация): больше конструктов, сильный урон по рейду -> быстро закончить."
L["Taktik: Konstrukte schaden auf die Monstrosität/den Boss und unterbrechen; Lebendigen Bern am Rand kontrolliert töten, Pfützen nur von Konstrukten fressen lassen."] = "Тактика: конструкты бьют чудовище/босса и сбивают касты; Живой янтарь убивать под контролем у края, лужи поедают только конструкты."
L["UN'SOK: Konstrukte: Explosionen unterbrechen! Skalpell an den Rand!"] = "УН'СОК: конструкты, сбивайте взрывы! Скальпель к краю!"
L["Parasitäres Wachstum nicht überheilen. Monstrosität weg vom Raid."] = "Паразитический рост не перелечивать. Чудовище подальше от рейда."
L["Großkaiserin Shek'zeer + Kor'thik-Häscher und Set'thik-Windklingen"] = "Великая императрица Шек'зир + Кор'тикские жнецы и Сет'тикские ветрорезы"
L["- Augen der Kaiserin: Tankdebuff stapelt bis zur Gedankenkontrolle -> Tankwechsel."] = "- Глаза императрицы: дебафф на танке стакается до контроля разума -> смена танков."
L["- Schrei des Terrors: Raidschaden -> in die Dissonanzfelder stellen."] = "- Крик ужаса: урон по рейду -> вставать в поля диссонанса."
L["- Dienerin der Kaiserin: Spieler werden gedankenkontrolliert -> kontrollieren, nicht töten."] = "- Слуга императрицы: игроки под контролем разума -> контролить, не убивать."
L["- Phase 2 (Adds): Häscher in klebriges Harz/Bernfallen ziehen -> Häscher fangen, Windklingen töten; Giftbomben meiden."] = "- Фаза 2 (адды): жнецов затягивать в липкую смолу/янтарные ловушки -> ловить жнецов, убивать ветрорезов; обходить ядовитые бомбы."
L["- Phase 3 (30 %): Sha-Energie, Todesvisionen und Unheil -> verteilen und Cooldowns nutzen."] = "- Фаза 3 (30 %): энергия ша, видения смерти и Погибель -> рассредоточиться и использовать кулдауны."
L["Taktik: Phase 1 Boss mit Felder-Disziplin, Phase 2 Adds strikt nach Zuweisung, Phase 3 alle Cooldowns, Kampfrausch."] = "Тактика: фаза 1 босс с дисциплиной по полям, фаза 2 адды строго по назначению, фаза 3 все кулдауны, героизм."
L["SHEK'ZEER: Bei Schrei in die Felder! Häscher in die Harzfallen!"] = "ШЕК'ЗИР: на Крике в поля! Жнецов в смоляные ловушки!"
L["Tankwechsel bei Augen-Stapeln. Phase 3: Kampfrausch."] = "Смена танков по стакам Глаз. Фаза 3: героизм."
L["Mogu'shangewölbe"] = "Подземелья Могу'шан"
L["Die Steinwache (Jaspis-, Jade-, Kobalt- und Amethystwächter; im 10er nur 3 davon)"] = "Каменные стражи (яшмовый, нефритовый, кобальтовый и аметистовый страж; в 10-ке только 3 из них)"
L["- Energie: Wächter gewinnen Energie, besonders wenn sie nah beieinander stehen; bei 100 Energie Überladung mit Raidschaden -> Abstand der Wächter über die Tanks steuern."] = "- Энергия: стражи набирают энергию, особенно стоя рядом друг с другом; при 100 энергии перегрузка с уроном по рейду -> танки управляют расстоянием между стражами."
L["- Versteinerung: ein Element versteinert den Raid langsam (Verlangsamung bis Stillstand) -> genau den Wächter dieses Elements überladen lassen, das beendet die Versteinerung."] = "- Окаменение: одна стихия постепенно окаменяет рейд (замедление до полной остановки) -> дать перегрузиться именно стражу этой стихии, это снимает окаменение."
L["- Jaspisketten: verbinden zwei Spieler, Schaden bei Abstand -> verkettete Spieler zusammenbleiben."] = "- Яшмовые цепи: связывают двух игроков, урон при расхождении -> связанные игроки держатся вместе."
L["- Kobaltminen: wurzeln Spieler fest -> Minen meiden bzw. von Tanks gezielt auslösen lassen."] = "- Кобальтовые мины: обездвиживают игроков -> обходить мины или пусть танки подрывают их намеренно."
L["- Amethystpfützen und Jadesplitter: Bodeneffekte und Raidschaden -> Pfützen sofort verlassen, Heiler-Cooldowns auf Jade."] = "- Аметистовые лужи и нефритовые осколки: эффекты на полу и урон по рейду -> сразу выходить из луж, кулдауны хилов на нефрит."
L["Taktik: Tanks halten je einen bzw. zwei Wächter, ziehen nur den Wächter der aktiven Versteinerung zum Nachbarn, damit genau er überlädt. Wächter gleichmäßig runterschaden (geteilte Gesundheit)."] = "Тактика: танки держат по одному или два стража и подводят к соседу только стража активного окаменения, чтобы перегрузился именно он. Стражей сбивать равномерно (общее здоровье)."
L["STEINWACHE: Nur der Wächter der aktiven Versteinerung darf überladen!"] = "КАМЕННЫЕ СТРАЖИ: перегружаться может только страж активного окаменения!"
L["Kettenpartner zusammen, Pfützen und Minen meiden, Wächter gleichmäßig."] = "Партнеры по цепи вместе, обходить лужи и мины, стражей бить равномерно."
L["Steinwache"] = "Каменные стражи"
L["Je ein Symbol pro Wächter, damit die Tanks Zuweisungen und Positionen ansagen können."] = "По метке на каждого стража, чтобы танки могли объявлять назначения и позиции."
L["Feng der Verfluchte (Flamme, Blitz, Arkan; heroisch zusätzlich Schatten)"] = "Фэн Проклятый (огонь, молния, тайная магия; в героике еще тьма)"
L["- Flammenphase: Lauffeuerfunke auf Spielern -> aus dem Raid laufen und das Feuer am Rand ablegen; Flammenspeer zwingt zum Tankwechsel."] = "- Огненная фаза: Искра лесного пожара на игроках -> выбежать из рейда и сбросить огонь у края; Огненное копье вынуждает смену танков."
L["- Blitzphase: Epizentrum pulsiert großen Schaden um Feng -> weit weglaufen; Blitzfäuste frontal -> nicht vor dem Boss stehen."] = "- Фаза молний: Эпицентр пульсирует сильным уроном вокруг Фэна -> убегать далеко; Кулаки молний фронтально -> не стоять перед боссом."
L["- Arkanphase: Arkane Resonanz auf Spielern -> verteilen; Arkane Geschwindigkeit trifft nahe Spieler stärker -> Abstand halten."] = "- Тайная фаза: Чародейский резонанс на игроках -> рассредоточиться; Чародейская скорость сильнее бьет ближних игроков -> держать дистанцию."
L["- Tankdebuffs jeder Phase stapeln -> Tankwechsel nach Stapeln; Schilde/Barrieren der Phasen (Nullifizierung, Reflexion) gezielt nutzen."] = "- Дебаффы на танке в каждой фазе стакаются -> смена танков по стакам; щиты/барьеры фаз (обнуление, отражение) использовать целенаправленно."
L["Taktik: Boss mittig tanken, Fernkampf verteilt außen. Phasenwechsel bei 66 % und 33 %, die Fähigkeit (Spielerknopf) für Barriere bzw. Schild vorher an Tanks/Heiler einteilen."] = "Тактика: танковать босса по центру, рдд рассредоточены по краям. Смены фаз на 66 % и 33 %, способность (кнопку игрока) для барьера или щита заранее распределить между танками/хилами."
L["FENG: Epizentrum wegrennen, Funken nach außen tragen, in Arkan verteilen!"] = "ФЭН: от Эпицентра убегать, искры уносить наружу, на тайной фазе рассредоточиться!"
L["Tanks wechseln nach Stapeln. Barriere-Spieler auf Ansage."] = "Танки меняются по стакам. Игроки на барьере по команде."
L["Gara'jal der Geisterbinder + Geistertotems, Seelentrenner und Geister"] = "Гара'джал Заклинатель Душ + духовные тотемы, рассекатели душ и духи"
L["- Voodoopuppen: Schaden an den Puppen-Spielern wird geteilt, der Tank ist eine Puppe -> Tankwechsel nach Ansage."] = "- Куклы вуду: урон по игрокам-куклам делится, танк тоже кукла -> смена танков по команде."
L["- Geistertotem: zerstörtes Totem schickt nahe Spieler in die Geisterwelt -> dort Seelentrenner töten und die Seelen der Puppen befreien."] = "- Духовный тотем: разрушенный тотем отправляет ближних игроков в мир духов -> там убить рассекателей душ и освободить души кукол."
L["- Verbannung: Tank wird in die Geisterwelt verbannt -> Tank tötet dort sein Add schnell und kommt zurück."] = "- Изгнание: танк изгнан в мир духов -> танк быстро убивает там своего адда и возвращается."
L["- Geisterwelt erschöpft: zurückgekehrte Spieler können eine Zeit lang nicht erneut hinüber -> Gruppen rotieren."] = "- Истощение мира духов: вернувшиеся игроки некоторое время не могут уйти снова -> чередовать группы."
L["- Raserei bei 20 %: Boss wird deutlich stärker -> Cooldowns und Kampfrausch hier."] = "- Бешенство на 20 %: босс заметно сильнее -> кулдауны и героизм здесь."
L["Taktik: Zwei feste DPS-Gruppen für die Geisterwelt abwechselnd. Totems gesteuert auf 1–2 Gruppen platzieren, Bosstank wechselt nach jeder Verbannung."] = "Тактика: две фиксированные ДПС-группы по очереди в мир духов. Тотемы ставить управляемо на 1–2 группы, танк босса меняется после каждого Изгнания."
L["GARA'JAL: Totemgruppe rein, Seelentrenner töten und zurück!"] = "ГАРА'ДЖАЛ: группа тотема внутрь, убить рассекателей и назад!"
L["Tankwechsel bei Verbannung. Bei 20 % alle Cooldowns!"] = "Смена танков на Изгнании. На 20 % все кулдауны!"
L["Die Geisterkönige: Qiang, Subetai, Zian und Meng (nacheinander aktiv)"] = "Призрачные короли: Цян, Субэтай, Цзянь и Мэн (активны по очереди)"
L["- Qiang: Vernichten (gerade Linie vor ihm) -> nicht vor dem Boss stehen; Flankierende Truppen kommen von der Seite -> ausweichen."] = "- Цян: Уничтожение (прямая линия перед ним) -> не стоять перед боссом; Фланговые войска идут сбоку -> уворачиваться."
L["- Subetai: Pfeilsalven und Pfeilregen -> Bodeneffekte verlassen; Plündern springt auf Spieler -> Heiler aufpassen."] = "- Субэтай: Залпы стрел и Град стрел -> выходить из эффектов на полу; Грабеж прыгает на игроков -> хилам быть внимательными."
L["- Zian: Schattenblitze unterbrechen; Unsterbliche Schatten als Adds -> beim Tod entsteht eine Pfütze, raus da."] = "- Цзянь: сбивать Стрелы Тьмы; Бессмертные тени как адды -> при смерти оставляют лужу, выйти из нее."
L["- Meng: Feigheit wirft Schaden zurück und Wahnsinnsrufe treffen den Raid -> Schaden und Heilung nach Ansage dosieren."] = "- Мэн: Трусость отражает урон, Крики безумия бьют рейд -> дозировать урон и лечение по команде."
L["Taktik: Immer zwei Könige sind gleichzeitig aktiv (der nächste mit passiven Effekten). Nahkampf hinter dem Boss, Fernkampf verteilt, Unterbrecher für Zian fest einteilen."] = "Тактика: всегда активны два короля одновременно (следующий с пассивными эффектами). Мили за боссом, рдд рассредоточены, киков на Цзяня назначить заранее."
L["GEISTERKÖNIGE: Nicht vor Qiang stehen, Zian unterbrechen!"] = "ПРИЗРАЧНЫЕ КОРОЛИ: не стоять перед Цяном, кикать Цзяня!"
L["Pfeilregen meiden, bei Meng Schaden dosieren."] = "Обходить Град стрел, на Мэне дозировать урон."
L["Elegon + Himmlische Beschützer und Energieladungen"] = "Элегон + Небесные защитники и энергетические заряды"
L["- Überladung: Elegon stapelt ständig Raidschaden -> zügig Phasen schaffen, Heiler-Cooldowns planen."] = "- Перегрузка: Элегон постоянно стакает урон по рейду -> быстро проходить фазы, планировать кулдауны хилов."
L["- Himmlischer Beschützer: Add mit starkem Tank-Druck -> außen am Rand tanken und dort töten."] = "- Небесный защитник: адд с сильным давлением на танка -> танковать снаружи у края и там убивать."
L["- Energie entziehen (Phase 2): Energieladungen wandern zu Elegon und stärken ihn -> alle Ladungen vorher töten."] = "- Вытягивание энергии (фаза 2): энергетические заряды ползут к Элегону и усиливают его -> убивать все заряды раньше."
L["- Energiewirbel in der Mitte: wer zu nah steht, nimmt Schaden -> aus der inneren Zone raus."] = "- Энергетический вихрь в центре: кто стоит слишком близко, получает урон -> выйти из внутренней зоны."
L["- Bodenphase: der Plattformboden verschwindet zeitweise -> Fokusse/Spitzen paarweise zerstören, nicht herunterfallen."] = "- Фаза пола: пол платформы временами исчезает -> уничтожать фокусы/шпили парами, не падать."
L["Taktik: Boss und Adds getrennt tanken, DPS wechselt auf Beschützer und Ladungen. Fernkampf an den Ladungs-Laufwegen."] = "Тактика: босса и аддов танковать раздельно, ДПС переключаются на защитников и заряды. Рдд у путей движения зарядов."
L["ELEGON: Energieladungen töten, bevor sie Elegon erreichen!"] = "ЭЛЕГОН: убивать энергетические заряды, пока они не дошли до Элегона!"
L["Beschützer außen tanken. Nicht in die Mitte!"] = "Защитников танковать снаружи. Не заходить в центр!"
L["Wille des Kaisers: Jan-xi und Qin-xi + Wut, Stärke und Mut des Kaisers"] = "Воля императора: Цзань-си и Цинь-си + Ярость, Сила и Отвага императора"
L["- Verheerender Bogen / Kombo: harte Schläge der Kolosse -> nur Tanks vorne, Arme gezielt angreifen um die Kombo zu unterbrechen."] = "- Опустошающая дуга / комбо: тяжелые удары колоссов -> спереди только танки, бить по рукам, чтобы прервать комбо."
L["- Wut des Kaisers: kleine Adds, die Spieler verfolgen -> schnell aufsammeln und mit Flächenschaden töten."] = "- Ярость императора: мелкие адды, преследующие игроков -> быстро собрать и убить АоЕ."
L["- Stärke des Kaisers: schweres Add mit Stampfangriff -> Offtank hält es, nicht in den Stampfer."] = "- Сила императора: тяжелый адд с топотом -> офф-танк держит его, не стоять в топоте."
L["- Mut des Kaisers: blockt Angriffe von vorn und fixiert einen Spieler -> von hinten angreifen."] = "- Отвага императора: блокирует атаки спереди и фиксируется на игроке -> атаковать сзади."
L["- Magnetrüstung / Erdbeben: Spieler werden angezogen bzw. getroffen -> Position halten, Heilung bereit."] = "- Магнитная броня / Землетрясение: игроков притягивает или бьет -> держать позицию, хил наготове."
L["Taktik: Zwei Tanks auf Jan-xi und Qin-xi, die Adds haben Vorrang. Kolosse sind immun, bis die Kraft des Kaisers fließt – DPS dann voll auf die Bosse."] = "Тактика: два танка на Цзань-си и Цинь-си, адды в приоритете. Колоссы неуязвимы, пока не течет Сила императора, тогда ДПС полностью на боссов."
L["WILLE DES KAISERS: Adds zuerst! Mut nur von hinten angreifen!"] = "ВОЛЯ ИМПЕРАТОРА: сначала адды! Отвагу бить только сзади!"
L["Nicht vor die Kolosse, Wut-Adds sammeln und AoE."] = "Не вставать перед колоссами, адды Ярости собрать и АоЕ."
L["Wille des Kaisers"] = "Воля императора"
L["Totenkopf auf Stärke, Kreuz auf Mut, Viereck auf das nächste Wut-Add."] = "Череп на Силу, Крест на Отвагу, Квадрат на следующего адда Ярости."
L["Schlacht um Orgrimmar"] = "Осада Оргриммара"
L["Immerseus + Sha-Pfützen und Verunreinigte Pfützen"] = "Глубиний + лужи ша и оскверненные лужи"
L["- Shablitz: Wasserblasen auf Spielern -> verteilen, Pfützen meiden."] = "- Удар ша: водяные пузыри на игроках -> рассредоточиться, обходить лужи."
L["- Wirbeln: Wasserwirbel -> nicht in die Linien laufen."] = "- Вращение: водяные вихри -> не заходить в линии."
L["- Ätzender Stoß: Frontalangriff -> Tankwechsel."] = "- Едкий выброс: фронтальная атака -> смена танков."
L["- Teilung (Splitphase): Immerseus zerfällt -> DPS tötet Sha-Pfützen, Heiler heilen Verunreinigte Pfützen."] = "- Разделение (сплит-фаза): Глубиний распадается -> ДПС убивают лужи ша, хилы лечат оскверненные лужи."
L["Taktik: Je mehr Pfützen erledigt werden, desto weniger Verderbnis kehrt zurück. Phasenweise zügig wechseln."] = "Тактика: чем больше луж обработано, тем меньше порчи возвращается. Быстро менять фазы."
L["IMMERSEUS: Teilung: DPS auf Sha-Pfützen, Heiler auf Verunreinigte!"] = "ГЛУБИНИЙ: Разделение: ДПС на лужи ша, хилы на оскверненные!"
L["Wirbel meiden, Tankwechsel bei Ätzendem Stoß."] = "Обходить вихри, смена танков на Едком выбросе."
L["Die gefallenen Beschützer: Rook Steinzeh, He Sanftfuß, Sun Sanftherz"] = "Павшие защитники: Рук Каменный Палец, Хе Мягкая Стопа, Сунь Мягкое Сердце"
L["- Verzweiflungsmaßnahmen (66 % und 33 %): jeder Beschützer startet eine Sonderphase -> Mechanik schnell abarbeiten."] = "- Отчаянные меры (66 % и 33 %): каждый защитник запускает особую фазу -> быстро отработать механику."
L["- Rook: Elendverkörperung, Schwermut und Trauer -> Adds töten."] = "- Рук: воплощения страдания, уныния и скорби -> убивать аддов."
L["- He: Mal der Pein -> Kette von Spieler zu Spieler, an Tanks weitergeben."] = "- Хе: Знак мучения -> цепь от игрока к игроку, передавать танкам."
L["- Sun: Wort der Schatten: Bann -> bannen; Dunkle Meditation -> in das Feld stellen."] = "- Сунь: Слово Тьмы: Бедствие -> диспелить; Темная медитация -> вставать в поле."
L["- Erneuerung: getötete Beschützer stehen wieder auf -> alle drei möglichst gleichzeitig töten."] = "- Обновление: убитые защитники встают снова -> убить всех троих по возможности одновременно."
L["Taktik: Alle drei Bosse gleichmäßig runterschaden, gegen Ende synchron töten. Unterbrecher und Banner einteilen."] = "Тактика: всех трех боссов сбивать равномерно, под конец убить синхронно. Назначить киков и диспелеров."
L["GEFALLENE BESCHÜTZER: Gleichmäßig schaden, zeitgleich töten!"] = "ПАВШИЕ ЗАЩИТНИКИ: бить равномерно, убить одновременно!"
L["Wort der Schatten bannen, Mal der Pein an Tanks geben."] = "Слово Тьмы диспелить, Знак мучения передавать танкам."
L["Gefallene Beschützer"] = "Павшие защитники"
L["Je ein Symbol auf Rook, He und Sun für Tank- und Schadenszuteilung."] = "По метке на Рука, Хе и Суня для распределения танков и урона."
L["Norushen + Amalgam der Verderbnis"] = "Норусхен + Амальгама порчи"
L["- Blick nach innen: Spieler betreten das Reich der Verderbnis -> Prüfung (Tank, Heiler oder DPS) bestehen."] = "- Взгляд внутрь: игроки входят в Царство порчи -> пройти испытание (танк, хил или ДПС)."
L["- Verderbnis: Balken der Spieler -> Prüfungen absolvieren, um Verderbnis zu senken."] = "- Порча: полоса у игроков -> проходить испытания, чтобы снизить порчу."
L["- Blinder Hass: Strahl um den Boss -> ausweichen."] = "- Слепая ненависть: луч вокруг босса -> уворачиваться."
L["- Manifestationen der Verderbnis: Adds -> schnell töten, Rest-Verderbnis meiden."] = "- Проявления порчи: адды -> быстро убивать, обходить остаточную порчу."
L["- Phase ab 50 %: zusätzliche Adds -> Cooldowns."] = "- Фаза с 50 %: дополнительные адды -> кулдауны."
L["Taktik: Raid gestaffelt in Prüfungen schicken, Tanks wechseln über ihre eigene Prüfung. Amalgam mittig tanken."] = "Тактика: отправлять рейд на испытания по очереди, танки меняются через свое испытание. Амальгаму танковать по центру."
L["NORUSHEN: Prüfungen bestehen! Blinden Hass meiden!"] = "НОРУСХЕН: проходите испытания! Уворачиваться от Слепой ненависти!"
L["Manifestationen schnell töten. Tanks wechseln über Prüfung."] = "Проявления быстро убивать. Танки меняются через испытание."
L["Sha des Stolzes + Manifestationen des Stolzes und Reflexionen"] = "Ша Гордыни + Проявления гордыни и отражения"
L["- Stolz: Balken steigt bei vielen Fehlern -> bei 100 Stolz Kontrollverlust, also keine Fehler."] = "- Гордыня: полоса растет при многих ошибках -> при 100 гордыни потеря контроля, так что без ошибок."
L["- Gabe der Titanen: Spieler mit Gabe stellen sich zusammen -> Macht der Titanen."] = "- Дар титанов: игроки с даром встают вместе -> Сила титанов."
L["- Mal der Arroganz: Debuff bannen gibt Stolz -> sparsam bannen."] = "- Знак высокомерия: диспел дебаффа дает гордыню -> диспелить экономно."
L["- Verderbte Gefängnisse: Spieler eingesperrt -> andere befreien."] = "- Оскверненные темницы: игроки заперты -> другие освобождают."
L["- Anschwellender Stolz: Raidschaden steigt mit Stolz -> Cooldowns."] = "- Нарастающая гордыня: урон по рейду растет с гордыней -> кулдауны."
L["Taktik: Stolz der Spieler niedrig halten, Gabe-Spieler zusammen. Bei 30 % Entfesselt: Cooldowns und Kampfrausch."] = "Тактика: держать гордыню игроков низкой, игроки с даром вместе. На 30 % Высвобождение: кулдауны и героизм."
L["SHA DES STOLZES: Stolz niedrig! Gabe der Titanen zusammen!"] = "ША ГОРДЫНИ: гордыню держать низкой! Дар титанов вместе!"
L["Gefängnisse befreien, Manifestationen töten."] = "Освобождать из темниц, убивать проявления."
L["Galakras + Drachenmal-Truppen und Türme"] = "Галакрас + войска Драконьей Пасти и башни"
L["- Wellen von Adds: Fahnenträger, Knochenbrecher, Proto-Drachen -> Fahnen zuerst, Adds priorisieren."] = "- Волны аддов: знаменосцы, костоломы, протодраконы -> сначала знамена, аддов по приоритету."
L["- Türme: Gruppen erobern die Türme und töten Verteidiger -> Flugabwehrkanonen benutzen."] = "- Башни: группы захватывают башни и убивают защитников -> использовать зенитные пушки."
L["- Kanonen: Spieler schießen auf Galakras -> bis er landet."] = "- Пушки: игроки стреляют по Галакрасу -> пока он не приземлится."
L["- Phase 2: Galakras landet -> Flammen von Galakrond teilen, Tankwechsel."] = "- Фаза 2: Галакрас приземляется -> делить Пламя Галакронда, смена танков."
L["Taktik: Turmgruppen fest einteilen, Rest hält Adds unten. Ab Landung alle Cooldowns, Schadensteilung bei Flammen."] = "Тактика: группы на башни назначить заранее, остальные держат аддов внизу. С приземления все кулдауны, делить урон Пламени."
L["GALAKRAS: Turmgruppen los! Fahnenträger zuerst!"] = "ГАЛАКРАС: группы на башни, вперед! Сначала знаменосцы!"
L["Phase 2: Flammen teilen, Tankwechsel. Cooldowns!"] = "Фаза 2: делить Пламя, смена танков. Кулдауны!"
L["Eiserner Koloss (Angriffs- und Belagerungsmodus)"] = "Железный исполин (режим атаки и осадный режим)"
L["- Laserverbrennung: Tankdebuff -> Tankwechsel."] = "- Лазерный ожог: дебафф на танке -> смена танков."
L["- Krabbelminen: explodieren -> von Spielern auslösen lassen."] = "- Ползучие мины: взрываются -> пусть их подрывают игроки."
L["- Mörser und Bohrer: Bodeneffekte -> ausweichen."] = "- Минометы и буры: эффекты на полу -> уворачиваться."
L["- Belagerungsmodus: Schockimpuls (Rückstoß), Explosiver Teer, Schneidelaser -> Laser durch Teer führen."] = "- Осадный режим: Шоковый импульс (откидывание), Взрывоопасная смола, Режущий лазер -> вести лазер через смолу."
L["- Seismische Aktivität: Raidschaden -> Cooldowns."] = "- Сейсмическая активность: урон по рейду -> кулдауны."
L["Taktik: Angriffsmodus voll Schaden, Belagerungsmodus Positionen halten. Minen kontrolliert sprengen."] = "Тактика: в режиме атаки полный урон, в осадном режиме держать позиции. Мины подрывать под контролем."
L["EISERNER KOLOSS: Minen sprengen, Laser durch Teer!"] = "ЖЕЛЕЗНЫЙ ИСПОЛИН: подрывать мины, лазер через смолу!"
L["Tankwechsel bei Laserverbrennung. Rückstoß beachten."] = "Смена танков на Лазерном ожоге. Следить за откидыванием."
L["Dunkelschamanen der Kor'kron: Erdbrecher Haromm und Wellenbinderin Kardris (auf Wölfen)"] = "Темные шаманы Кор'крона: Землекрушитель Харомм и Повелительница волн Кардрис (на волках)"
L["- Gemeinsame Phasen: bei bestimmten Gesundheitswerten erhalten beide neue Fähigkeiten -> gleichmäßig schaden."] = "- Общие фазы: на определенных порогах здоровья оба получают новые способности -> бить равномерно."
L["- Giftsturm / Faulstrom: Wirbel und Strahlen -> ausweichen."] = "- Ядовитый шторм / Гнилостный поток: вихри и лучи -> уворачиваться."
L["- Aschewand: Mauer bewegt sich -> Lücke finden."] = "- Стена пепла: стена движется -> найти брешь."
L["- Eisernes Grab: Gefängnisse -> herauslaufen."] = "- Железная могила: темницы -> выбегать."
L["- Fallende Asche: großer Einschlag -> gemeinsam soaken."] = "- Падающий пепел: сильный удар -> соакать вместе."
L["Taktik: Beide Schamanen nah beieinander tanken, Spaltung durch den Raid. Wölfe nicht wegziehen."] = "Тактика: обоих шаманов танковать рядом, клив по обоим. Волков не уводить."
L["DUNKELSCHAMANEN: Gleichmäßig schaden! Fallende Asche soaken!"] = "ТЕМНЫЕ ШАМАНЫ: бить равномерно! Соакать Падающий пепел!"
L["Giftsturm und Aschewand meiden."] = "Обходить Ядовитый шторм и Стену пепла."
L["General Nazgrim + Kor'kron-Adds"] = "Генерал Назгрим + адды Кор'крона"
L["- Haltungen: Kampfhaltung, Berserkerhaltung (mehr Schaden), Verteidigungshaltung -> bei Verteidigung keine Angriffe (gibt Wut)."] = "- Стойки: боевая стойка, стойка берсерка (больше урона), оборонительная стойка -> в оборонительной не атаковать (дает ярость)."
L["- Rüstungsspaltender Schlag: Tankdebuff -> Tankwechsel."] = "- Раскалывающий удар: дебафф на танке -> смена танков."
L["- Heroische Schockwelle: Sprung -> Zone meiden."] = "- Героическая ударная волна: прыжок -> обходить зону."
L["- Kor'kron-Banner: Adds verstärkt -> Banner töten."] = "- Знамя Кор'крона: усиливает аддов -> убить знамя."
L["- Adds (Klingenträger, Bogenweber, Assassinen, Kriegsschamanen) -> Bogenweber unterbrechen, Schamanen zuerst."] = "- Адды (клинкобойцы, ткачи лука, убийцы, боевые шаманы) -> кикать ткачей лука, шаманов первыми."
L["Taktik: Adds zuerst, bei Verteidigungshaltung nur Adds angreifen. Kriegsgesang mit Cooldowns."] = "Тактика: сначала адды, в оборонительной стойке атаковать только аддов. Боевую песнь под кулдаунами."
L["NAZGRIM: Verteidigungshaltung: nicht angreifen! Adds zuerst!"] = "НАЗГРИМ: оборонительная стойка, не атаковать! Сначала адды!"
L["Banner töten, Bogenweber unterbrechen. Tankwechsel."] = "Убить знамя, кикать ткачей лука. Смена танков."
L["Nazgrim (Adds)"] = "Назгрим (адды)"
L["Totenkopf auf Kriegsschamanen, Kreuz auf Bogenweber, Viereck/Mond auf weitere Adds."] = "Череп на боевых шаманов, Крест на ткачей лука, Квадрат/Полумесяц на остальных аддов."
L["Malkorok"] = "Малкорок"
L["- Bogenschlag: drei Schläge mit Lücken -> zwischen den Bögen stehen."] = "- Дуговой удар: три удара с брешами -> стоять между дугами."
L["- Odem von Y'Shaarj: folgt Bogenschlag -> Sicherheitszonen nutzen."] = "- Дыхание И'Шаарджа: следует за Дуговым ударом -> использовать безопасные зоны."
L["- Alte Miasmen: Heilung wird zu Schild -> überheilen ist erwünscht."] = "- Древние миазмы: лечение превращается в щит -> перелечивать можно и нужно."
L["- Blutraserei: Energie freigesetzt -> wegschieben, Implosion soaken."] = "- Кровавое бешенство: высвобождение энергии -> отталкивание, соакать имплозию."
L["- Tödlicher Schlag: Tankdebuff -> Tankwechsel."] = "- Смертельный удар: дебафф на танке -> смена танков."
L["Taktik: Raid locker verteilen, Bogenzonen beachten. Heiler halten Schilde."] = "Тактика: рейд свободно рассредоточен, следить за зонами дуг. Хилы держат щиты."
L["MALKOROK: In die sicheren Zonen nach Bogenschlag!"] = "МАЛКОРОК: после Дугового удара в безопасные зоны!"
L["Tankwechsel. Implosionen soaken."] = "Смена танков. Соакать имплозии."
L["Schätze Pandarias (Kisten mit Mogu- und Mantis-Adds)"] = "Трофеи Пандарии (ящики с аддами могу и богомолов)"
L["- Kisten öffnen: kleine, mittlere, große -> Adds je nach Größe kontrolliert freisetzen."] = "- Открытие ящиков: малые, средние, большие -> выпускать аддов под контролем в зависимости от размера."
L["- Zeitlimit: Sicherheitssystem -> Fortschritt rechtzeitig erzielen."] = "- Лимит времени: система безопасности -> вовремя добиться прогресса."
L["- Mogu-Kisten: Steinstatuen und Zauberer -> unterbrechen, Bodeneffekte meiden."] = "- Ящики могу: каменные статуи и заклинатели -> кикать, обходить эффекты на полу."
L["- Mantis-Kisten: Windklingen und Bernfallen -> ausweichen, Fokus."] = "- Ящики богомолов: ветрорезы и янтарные ловушки -> уворачиваться, фокус."
L["- Sha-Gegenstände: Adds mit gefährlichen Effekten -> priorisieren."] = "- Предметы ша: адды с опасными эффектами -> в приоритете."
L["Taktik: Raid in zwei Gruppen teilen, Kisten gleichmäßig öffnen. Adds sauber nach Priorität."] = "Тактика: разделить рейд на две группы, открывать ящики равномерно. Аддов чисто по приоритету."
L["SCHÄTZE: Kisten kontrolliert öffnen, Adds nach Priorität!"] = "ТРОФЕИ: открывать ящики под контролем, аддов по приоритету!"
L["Zauber unterbrechen, Bodeneffekte meiden."] = "Кикать касты, обходить эффекты на полу."
L["Thok der Blutrünstige + Gefangene"] = "Ток Кровожадный + пленники"
L["- Furchteinflößendes Brüllen: Tankdebuff -> Tankwechsel."] = "- Устрашающий рев: дебафф на танке -> смена танков."
L["- Schwanzpeitsche: hinter Thok -> nicht dahinter stehen."] = "- Удар хвостом: за Током -> не стоять сзади."
L["- Betäubendes Kreischen: Raidschaden -> Cooldowns."] = "- Оглушающий визг: урон по рейду -> кулдауны."
L["- Blutraserei: Thok fixiert einen Spieler -> kiten."] = "- Кровавое бешенство: Ток фиксируется на игроке -> кайтить."
L["- Gefängnisschlüssel: Gefangene befreien -> Thok erhält neue Fähigkeiten."] = "- Ключ от темницы: освобождать пленников -> Ток получает новые способности."
L["Taktik: Phase 1 Schaden, Phase 2 kiten. Gefangene nach Plan befreien."] = "Тактика: фаза 1 урон, фаза 2 кайт. Пленников освобождать по плану."
L["THOK: Fixierte Spieler kiten! Nicht hinter Thok stehen!"] = "ТОК: зафиксированные игроки кайтят! Не стоять за Током!"
L["Tankwechsel bei Brüllen. Cooldowns bei Kreischen."] = "Смена танков на Реве. Кулдауны на Визг."
L["Belagerungsingenieur Rußschmied + Fließband-Waffen"] = "Инженер-конструктор Черный Запал + оружие с конвейера"
L["- Fließband: Waffen kommen auf das Band -> Spieler zerstören sie."] = "- Конвейер: оружие едет по ленте -> игроки уничтожают его."
L["- Automatisierte Schredder: Adds -> Offtank, schnell töten."] = "- Автоматические крошшеры: адды -> офф-танк, быстро убивать."
L["- Elektrostatische Ladung: Tankdebuff -> Tankwechsel."] = "- Электростатический заряд: дебафф на танке -> смена танков."
L["- Magnetzerquetschung: zieht Spieler -> Abstand halten."] = "- Магнитное сокрушение: притягивает игроков -> держать дистанцию."
L["- Laser und Minen: Bodeneffekte -> ausweichen."] = "- Лазеры и мины: эффекты на полу -> уворачиваться."
L["Taktik: Feste Fließband-Gruppe, Rest auf Boss und Schredder."] = "Тактика: фиксированная группа на конвейер, остальные на босса и крошшеры."
L["RUSSSCHMIED: Fließband-Gruppe los! Schredder töten!"] = "ЧЕРНЫЙ ЗАПАЛ: группа на конвейер, вперед! Убить крошшеры!"
L["Tankwechsel bei Ladung. Laser und Minen meiden."] = "Смена танков на Заряде. Обходить лазеры и мины."
L["Getreue der Klaxxi (9 Getreue, je 3 gleichzeitig)"] = "Идеалы клакси (9 идеалов, по 3 одновременно)"
L["- Nachfolge: stirbt ein Getreuer, kommt der nächste -> Reihenfolge festlegen."] = "- Преемство: умирает идеал, приходит следующий -> определить порядок."
L["- Essenzen: tote Getreue hinterlassen Bernstein -> Spieler übernehmen Fähigkeiten."] = "- Эссенции: мертвые идеалы оставляют янтарь -> игроки перенимают способности."
L["- Diverse Mechaniken: Kegel, Pfützen, Fixierungen -> ausweichen bzw. kiten."] = "- Разные механики: конусы, лужи, фиксации -> уворачиваться или кайтить."
L["- Tankdebuffs: Tankwechsel nach Stapeln."] = "- Дебаффы на танке: смена танков по стакам."
L["Taktik: Getreue nach Plan töten, Essenzen verteilen. Raid passt sich den aktiven Getreuen an."] = "Тактика: убивать идеалов по плану, распределить эссенции. Рейд подстраивается под активных идеалов."
L["KLAXXI: Ziel nach Symbol! Essenzen aufnehmen!"] = "КЛАКСИ: цель по метке! Подбирать эссенции!"
L["Kegeln und Pfützen ausweichen. Tankwechsel."] = "Уворачиваться от конусов и луж. Смена танков."
L["Getreue der Klaxxi"] = "Идеалы клакси"
L["Totenkopf zuerst, dann Kreuz und Viereck für die nächsten Getreuen."] = "Сначала Череп, затем Крест и Квадрат для следующих идеалов."
L["Garrosh Höllschrei + Kriegsbringer, Wolfsreiter, Belagerungsingenieure"] = "Гаррош Адский Крик + вестники войны, волчьи всадники, осадные инженеры"
L["- Phase 1: Wolfsreiter (Kettenblitz/Heilung) -> unterbrechen; Belagerungsingenieure -> Eisensterne verhindern."] = "- Фаза 1: волчьи всадники (Цепная молния/лечение) -> кикать; осадные инженеры -> не допускать Железных звезд."
L["- Entweihen: Schwert erzeugt Zone -> Schwert zerstören."] = "- Осквернение: меч создает зону -> уничтожить меч."
L["- Zwischenphase: Reich von Y'Shaarj -> Adds töten, Vernichten meiden."] = "- Промежуточная фаза: Царство И'Шаарджа -> убивать аддов, обходить Уничтожение."
L["- Phase 2: Berührung von Y'Shaarj (Gedankenkontrolle) -> kontrollieren, nicht töten."] = "- Фаза 2: Прикосновение И'Шаарджа (контроль разума) -> контролить, не убивать."
L["- Phase 3: Verstärkte Fähigkeiten -> Cooldowns."] = "- Фаза 3: усиленные способности -> кулдауны."
L["Taktik: Adds priorisieren, Wolfsreiter unterbrechen. Ab Phase 2 Gedankenkontrolle kontrollieren."] = "Тактика: аддов в приоритете, кикать волчьих всадников. С фазы 2 контролить игроков под контролем разума."
L["GARROSH: Wolfsreiter unterbrechen! Schwerter zerstören!"] = "ГАРРОШ: кикать волчьих всадников! Уничтожать мечи!"
L["Gedankenkontrolle kontrollieren. Phase 3: Cooldowns."] = "Контроль разума контролить. Фаза 3: кулдауны."
L["Garrosh (Adds)"] = "Гаррош (адды)"
L["Totenkopf/Kreuz auf Wolfsreiter, Viereck/Mond auf weitere Adds."] = "Череп/Крест на волчьих всадников, Квадрат/Полумесяц на остальных аддов."
L["Terrasse des Endlosen Frühlings"] = "Терраса Вечной Весны"
L["Beschützer des Endlosen: Beschützer Kaolan, Ältester Regail, Älteste Asani"] = "Вечные защитники: защитник Каолан, старейшина Регейл, старейшина Азани"
L["- Verderbnis: stirbt ein Beschützer, werden die anderen verderbt und stärker -> Tötungsreihenfolge festlegen."] = "- Порча: когда умирает защитник, остальные оскверняются и усиливаются -> определить порядок убийства."
L["- Regail: Blitzgefängnis auf Spielern -> verteilen; Blitzsturm als Raidschaden."] = "- Регейл: Темница молний на игроках -> рассредоточиться; Буря молний как урон по рейду."
L["- Asani: Reinigende Wasser heilen die Gegner -> Bosse aus der Pfütze ziehen; Wasserblitz unterbrechen; Sha-Kugeln töten."] = "- Азани: Очищающие воды лечат врагов -> вытаскивать боссов из лужи; кикать Водяную стрелу; убивать сферы ша."
L["- Kaolan: Berührung des Sha (Schaden auf Spielern) und verderbter Boden -> Heilung halten, aus dem Boden raus."] = "- Каолан: Прикосновение ша (урон по игрокам) и оскверненная земля -> держать хил, выйти с земли."
L["Taktik: Bosse getrennt tanken, Fokus auf das Ziel der Reihenfolge, Unterbrecher auf Asani. Nach jedem Tod Cooldowns für die stärkeren Restbosse."] = "Тактика: боссов танковать раздельно, фокус на цель по порядку, киков на Азани. После каждой смерти кулдауны на усилившихся оставшихся боссов."
L["BESCHÜTZER: Fokusziel nach Symbol! Asani unterbrechen, aus Wasser ziehen!"] = "ЗАЩИТНИКИ: фокус по метке! Кикать Азани, тащить из воды!"
L["Bei Blitzgefängnis verteilen, verderbten Boden verlassen."] = "На Темнице молний рассредоточиться, уходить с оскверненной земли."
L["Beschützer des Endlosen"] = "Вечные защитники"
L["Totenkopf zuerst, Kreuz als Zweites, Viereck zuletzt (Reihenfolge der Beschützer)."] = "Сначала Череп, вторым Крест, последним Квадрат (порядок защитников)."
L["Tsulong (Nacht feindlich, Tag freundlich)"] = "Цулон (ночью враждебен, днем дружелюбен)"
L["- Nacht: Schattenodem auf den Tank -> Tankwechsel; Albträume als Bodeneffekte -> ausweichen."] = "- Ночь: Дыхание Тьмы на танка -> смена танков; Кошмары как эффекты на полу -> уворачиваться."
L["- Tag: Tsulong wird freundlich -> Heiler heilen Tsulong hoch, DPS auf Adds."] = "- День: Цулон становится дружелюбным -> хилы лечат Цулона, ДПС на аддов."
L["- Verkörperter Schrecken und Schreckensbrut (Tag): Adds -> zügig töten."] = "- Воплощенный ужас и Порождения ужаса (день): адды -> быстро убивать."
L["- Instabiler Sha: Adds laufen zu Tsulong und heilen/stärken ihn -> abfangen und töten."] = "- Нестабильный ша: адды идут к Цулону и лечат/усиливают его -> перехватывать и убивать."
L["- Sonnenstrahl: entfernt Schreckensdebuffs -> bei Bedarf hineinstellen."] = "- Солнечный луч: снимает дебаффы ужаса -> при необходимости вставать в него."
L["Taktik: Nacht = Boss schaden, Tag = Tsulong heilen und Adds töten. Der Kampf endet, wenn Tsulong geheilt bzw. die Sha-Kraft gebrochen ist."] = "Тактика: ночь = бить босса, день = лечить Цулона и убивать аддов. Бой заканчивается, когда Цулон вылечен и сила ша сломлена."
L["TSULONG: Nacht Schaden, Tag heilen! Instabile Sha abfangen!"] = "ЦУЛОН: ночью урон, днем хил! Перехватывать Нестабильных ша!"
L["Tankwechsel bei Schattenodem, Sonnenstrahl gegen Schrecken."] = "Смена танков на Дыхании Тьмы, Солнечный луч против ужаса."
L["Lei Shi + Belebte Beschützer"] = "Лэй Ши + Оживленные защитники"
L["- Sprühen: stapelnder Frostschaden auf dem Tank -> Tankwechsel."] = "- Брызги: стакающийся урон от льда на танке -> смена танков."
L["- Verschwindet!: Lei Shi stößt alle zurück -> gegen den Wind zu ihr laufen, nicht vom Rand fallen."] = "- Прочь!: Лэй Ши отталкивает всех -> бежать к ней против ветра, не падать с края."
L["- Beschützen (bei 80/60/40/20 %): Belebte Beschützer + Schild -> Adds töten."] = "- Защита (на 80/60/40/20 %): Оживленные защитники + щит -> убивать аддов."
L["- Verstecken: Lei Shi wird unsichtbar -> mit Flächenschaden finden und angreifen."] = "- Укрытие: Лэй Ши становится невидимой -> найти АоЕ-уроном и атаковать."
L["Taktik: Boss mittig, Raid nah dran, Adds schnell töten. Bei Verstecken AoE, bis sie auftaucht."] = "Тактика: босс по центру, рейд рядом, аддов быстро убивать. На Укрытии АоЕ, пока она не появится."
L["LEI SHI: Adds bei Beschützen sofort töten! Bei Verstecken AoE!"] = "ЛЭЙ ШИ: на Защите сразу убивать аддов! На Укрытии АоЕ!"
L["Gegen den Rückstoß anlaufen. Tankwechsel nach Sprühen."] = "Бежать против отбрасывания. Смена танков по Брызгам."
L["Sha der Angst + Schreckensbrut und Wächter auf den äußeren Plattformen"] = "Ша Страха + Порождения ужаса и стражи на внешних платформах"
L["- Odem der Angst: Furcht für alle außerhalb des Lichts -> in der Lichtmauer des Champions stehen."] = "- Дыхание страха: страх на всех вне света -> стоять в Стене света чемпиона."
L["- Ominöses Gackern: schleudert Spieler auf äußere Plattformen -> dort Wächter besiegen und zurück."] = "- Зловещий смех: забрасывает игроков на внешние платформы -> там победить стража и вернуться."
L["- Dreschen: hoher Tankschaden -> Tanks mit Cooldowns und Heilfokus."] = "- Молотьба: сильный урон по танку -> танки с кулдаунами и фокус хила."
L["- Champion des Lichts: Spieler mit Licht-Buff hält die Lichtmauer -> Buff nicht verlieren."] = "- Чемпион Света: игрок с баффом Света держит Стену света -> не терять бафф."
L["Taktik: Raid in der Lichtmauer vor dem Boss stapeln; Gruppen auf den äußeren Plattformen erledigen ihren Wächter und kehren zurück."] = "Тактика: рейд стакается в Стене света перед боссом; группы на внешних платформах убивают своего стража и возвращаются."
L["Heroisch: Phase 2 mit Furchtsaat, Umgekehrten Schatten und Aufteilung auf Plattformen."] = "Героик: фаза 2 с Семенами страха, Обращенными тенями и разделением по платформам."
L["SHA DER ANGST: Im Licht bleiben! Plattform-Gruppen Wächter töten!"] = "ША СТРАХА: оставаться в свете! Группы на платформах убивают стражей!"
L["Tanks Cooldowns bei Dreschen. Champion hält die Lichtmauer."] = "Танкам кулдауны на Молотьбу. Чемпион держит Стену света."
L["Thron des Donners"] = "Престол Гроз"
L["Jin'rokh der Zerstörer"] = "Джин'рок Разрушитель"
L["- Statischer Ausbruch: Tankdebuff -> Tankwechsel."] = "- Статический взрыв: дебафф на танке -> смена танков."
L["- Fokussierter Blitz: Kugel verfolgt einen Spieler -> wegkiten, nicht durch Wasser führen."] = "- Сфокусированная молния: шар преследует игрока -> кайтить, не вести через воду."
L["- Donnernder Wurf: Tank wird auf eine Statue geworfen, es entsteht leitfähiges Wasser -> Wasser gibt Buff, aber bei Blitzsturm wird es elektrisiert."] = "- Громовой бросок: танка бросает на статую, появляется проводящая вода -> вода дает бафф, но во время Бури молний она электризуется."
L["- Blitzsturm: Raidschaden -> aus dem elektrisierten Wasser raus, Heiler-Cooldowns."] = "- Буря молний: урон по рейду -> выйти из наэлектризованной воды, кулдауны хилов."
L["- Ionisierung (heroisch): Debuff verteilt Schaden -> vor Ablauf weit verteilen."] = "- Ионизация (героик): дебафф распределяет урон -> до окончания широко рассредоточиться."
L["Taktik: Boss nacheinander bei den Statuen tanken, damit Pfützen nicht den ganzen Raum füllen. Fokus-Blitz-Ziel kitet."] = "Тактика: танковать босса поочередно у статуй, чтобы лужи не заполнили весь зал. Цель Сфокусированной молнии кайтит."
L["JIN'ROKH: Blitzkugel wegkiten! Raus aus elektrisiertem Wasser!"] = "ДЖИН'РОК: шар молнии кайтить! Из наэлектризованной воды!"
L["Tankwechsel bei Statischem Ausbruch. Wasser nur gezielt nutzen."] = "Смена танков на Статическом взрыве. Воду использовать только по делу."
L["Horridon + Stämme (Farraki, Gurubashi, Drakkari, Amani) und Kriegsgott Jalak"] = "Хорридон + племена (Фарраки, Гурубаши, Драккари, Амани) и боевой бог Джалак"
L["- Dreifacher Stich: Tankdebuff -> Tankwechsel."] = "- Тройной укол: дебафф на танке -> смена танков."
L["- Ansturm + Doppelter Hieb: Horridon stürmt auf einen Spieler -> Spieler weicht aus, Raid nicht vor/hinter ihm stehen."] = "- Рывок + Двойной удар: Хорридон бросается на игрока -> игрок уворачивается, рейд не стоит перед/за ним."
L["- Dinomant pro Tor: hinterlässt eine Kugel der Kontrolle -> anklicken, um Horridon zu betäuben (Schadensfenster)."] = "- Диномант у каждых ворот: оставляет Сферу контроля -> кликнуть, чтобы оглушить Хорридона (окно урона)."
L["- Stammes-Adds: Steinblick-Basilisken (Betäubung), Giftpriester, Amani-Schamanen -> Zauber unterbrechen, Verhexungen bannen."] = "- Адды племен: василиски-окаменители (оглушение), жрецы яда, шаманы Амани -> кикать касты, диспелить сглазы."
L["- Phase 2: Kriegsgott Jalak springt in den Kampf -> Jalak schnell töten, Horridon wird sonst wütend."] = "- Фаза 2: боевой бог Джалак вступает в бой -> быстро убить Джалака, иначе Хорридон впадает в ярость."
L["Taktik: Boss mittig, Adds an den Toren abfangen und töten; feste Unterbrecher, Dinomant priorisieren und Kugel nutzen."] = "Тактика: босс по центру, аддов перехватывать и убивать у ворот; фиксированные кики, диноманта в приоритете и использовать сферу."
L["HORRIDON: Dinomant töten und Kugel klicken! Adds unterbrechen!"] = "ХОРРИДОН: убить диноманта и кликнуть сферу! Кикать аддов!"
L["Ansturm ausweichen, Tankwechsel. Phase 2: Jalak zuerst!"] = "Уворачиваться от Рывка, смена танков. Фаза 2: сначала Джалак!"
L["Horridon (Unterbrechen)"] = "Хорридон (кики)"
L["Totenkopf auf den Dinomanten, Kreuz/Viereck/Mond auf Zauberer-Adds für feste Unterbrecher."] = "Череп на диноманта, Крест/Квадрат/Полумесяц на аддов-кастеров для фиксированных киков."
L["Ältestenrat: Frostkönig Malakk, Kazra'jin, Sul der Sandkriecher, Hohepriesterin Mar'li"] = "Совет старейшин: король мороза Малакк, Каз'ра'джин, Сул Песчаный Скиталец, верховная жрица Мар'ли"
L["- Gara'jals Geist besetzt einen Ältesten: er lädt Dunkle Macht auf und verstärkt sich -> Besessenen bevorzugt angreifen, nach Schaden wechselt der Geist."] = "- Дух Гара'джала вселяется в старейшину: тот копит Темную силу и усиливается -> в первую очередь бить одержимого, после урона дух переходит."
L["- Malakk: Frostbiss/Beißende Kälte -> Spieler verteilen bzw. Frostbiss-Stapel teilen; Tankwechsel bei Frostigem Angriff."] = "- Малакк: Обморожение/Пронизывающий холод -> рассредоточиться или делить стаки Обморожения; смена танков на Морозной атаке."
L["- Sul: Treibsand -> nicht hineinlaufen; Sandsturm verbindet Treibsand zu Adds -> Adds töten."] = "- Сул: Зыбучие пески -> не заходить; Песчаная буря соединяет пески в аддов -> убивать аддов."
L["- Mar'li: Loa-Geister wandern zu Spielern bzw. zum Rat -> Geister schnell töten."] = "- Мар'ли: духи лоа идут к игрокам или к совету -> быстро убивать духов."
L["- Kazra'jin: Rücksichtsloser Sturmangriff -> Aufprallzone meiden."] = "- Каз'ра'джин: Безрассудный рывок -> обходить зону удара."
L["Taktik: Tanks halten Malakk und Kazra'jin nahe beieinander, AoE-Spaltung möglich. Tötungsreihenfolge festlegen, Dunkle Macht nie zu hoch werden lassen."] = "Тактика: танки держат Малакка и Каз'ра'джина рядом, можно кливать АоЕ. Определить порядок убийства, Темную силу никогда не давать набрать слишком много."
L["ÄLTESTENRAT: Besessenen Ältesten angreifen! Loa-Geister töten!"] = "СОВЕТ СТАРЕЙШИН: бить одержимого старейшину! Убивать духов лоа!"
L["Treibsand meiden, bei Beißender Kälte verteilen."] = "Обходить Зыбучие пески, на Пронизывающем холоде рассредоточиться."
L["Ältestenrat"] = "Совет старейшин"
L["Totenkopf auf das erste Ziel der Reihenfolge, dann Kreuz, Viereck, Mond für die übrigen Ältesten."] = "Череп на первую цель по порядку, затем Крест, Квадрат, Полумесяц на остальных старейшин."
L["Tortos + Wirbelschildkröten und Vampirhöhlenfledermäuse"] = "Тортос + Вихревые черепахи и вампирические пещерные летучие мыши"
L["- Wütender Steinatem: großer Raidschaden -> mit einem getretenen Panzer unterbrechen."] = "- Яростное каменное дыхание: сильный урон по рейду -> прервать пинком панциря."
L["- Wirbelschildkröten: getötet werden sie zu Panzern -> Panzer in Tortos treten (Panzer treten), wenn der Steinatem kommt."] = "- Вихревые черепахи: убитые становятся панцирями -> пинать панцирь в Тортоса (Пинок панциря), когда идет Каменное дыхание."
L["- Bebenstampfer: Raidschaden und herabfallende Steine -> Steinen ausweichen, Heiler-Cooldowns."] = "- Сотрясающий топот: урон по рейду и падающие камни -> уворачиваться от камней, кулдауны хилов."
L["- Fledermäuse: saugen Leben -> Offtank sammelt, AoE."] = "- Летучие мыши: высасывают жизнь -> офф-танк собирает, АоЕ."
L["- Zuschnappender Biss: Tankschaden -> Tankwechsel nach Bedarf."] = "- Хищный укус: урон по танку -> смена танков по необходимости."
L["Taktik: Schildkröten kontrolliert töten, immer einen Panzer für den nächsten Atem bereit. Fledermäuse beim Offtank stapeln."] = "Тактика: черепах убивать под контролем, всегда держать панцирь наготове для следующего дыхания. Мышей стакать на офф-танке."
L["TORTOS: Panzer in Tortos treten, wenn der Steinatem kommt!"] = "ТОРТОС: пинать панцирь в Тортоса, когда идет Каменное дыхание!"
L["Fledermäuse zum Offtank, AoE. Fallenden Steinen ausweichen."] = "Мыши к офф-танку, АоЕ. Уворачиваться от падающих камней."
L["Megaera (Hydra mit Flammen-, Frost-, Gift- und heroisch Arkankopf)"] = "Мегера (гидра с огненной, ледяной, ядовитой и в героике тайной головой)"
L["- Kopftod: nach jedem getöteten Kopf Raserei mit hohem Raidschaden und neuen Köpfen -> Heiler-Cooldowns pro Raserei."] = "- Смерть головы: после каждой убитой головы бешенство с сильным уроном по рейду и новые головы -> кулдауны хилов на каждое бешенство."
L["- Flammenkopf (Asche): Debuff -> abseits des Raids bannen, Feuerpfütze bleibt liegen."] = "- Огненная голова (Пепел): дебафф -> диспелить в стороне от рейда, огненная лужа остается."
L["- Frostkopf (Eisstrom): Strahl verfolgt einen Spieler -> an den Rand kiten."] = "- Ледяная голова (Ледяной поток): луч преследует игрока -> кайтить к краю."
L["- Giftkopf (Säureregen): Pfützen im Raid -> verteilen und ausweichen."] = "- Ядовитая голова (Кислотный дождь): лужи в рейде -> рассредоточиться и уворачиваться."
L["- Tankdebuffs der Köpfe: Tankwechsel zwischen den aktiven Köpfen."] = "- Дебаффы голов на танке: смена танков между активными головами."
L["Taktik: Köpfe gezielt nacheinander töten; nach jeder Raserei neue Kopf-Kombination beachten. Ausreichend Platz für Pfützen lassen."] = "Тактика: убивать головы целенаправленно по очереди; после каждого бешенства учитывать новую комбинацию голов. Оставлять достаточно места для луж."
L["MEGAERA: Asche abseits bannen, Eisstrom an den Rand kiten!"] = "МЕГЕРА: Пепел диспелить в стороне, Ледяной поток кайтить к краю!"
L["Nach Kopftod Raserei: Cooldowns! Säureregen ausweichen."] = "После смерти головы бешенство: кулдауны! Уворачиваться от Кислотного дождя."
L["Ji-Kun + Nester mit Jungvögeln"] = "Цзи-Кунь + гнезда с птенцами"
L["- Nester: Eier und Jungvögel schlüpfen -> Nestgruppen fliegen hin und töten sie."] = "- Гнезда: вылупляются яйца и птенцы -> группы на гнезда летят туда и убивают их."
L["- Krallenhieb: Tankdebuff -> Tankwechsel."] = "- Удар когтями: дебафф на танке -> смена танков."
L["- Abwind: Ji-Kun drückt Spieler weg -> gegen den Wind laufen, nicht von der Plattform fallen."] = "- Нисходящий поток: Цзи-Кунь сдувает игроков -> бежать против ветра, не падать с платформы."
L["- Federkiele: Raidschaden -> Heiler-Cooldowns."] = "- Колючие перья: урон по рейду -> кулдауны хилов."
L["- Fütterung: grüne Bälle fallen -> Spieler fangen sie, damit sie nicht die Jungen nähren."] = "- Кормление: падают зеленые шары -> игроки ловят их, чтобы они не кормили птенцов."
L["Taktik: Feste Nestgruppen (unten und oben) per Federn hinfliegen lassen. Auf der Plattform zusammen bleiben und bei Abwind laufen."] = "Тактика: фиксированные группы на гнезда (нижние и верхние) летят туда на перьях. На платформе держаться вместе и бежать на Нисходящем потоке."
L["JI-KUN: Nestgruppe rein, Jungvögel töten! Bei Abwind dagegen laufen!"] = "ЦЗИ-КУНЬ: группа на гнездо, убить птенцов! На потоке бежать против!"
L["Tankwechsel bei Krallenhieb. Federkiele: Cooldowns."] = "Смена танков на Ударе когтями. Колючие перья: кулдауны."
L["Durumu der Vergessene + Nebel (Purpur, Azur, Bernstein)"] = "Дуруму Позабытый + туманы (багровый, лазурный, янтарный)"
L["- Lichtspektrum: Strahlen (gelb, blau, rot) decken versteckte Nebel auf -> Strahlenträger laufen langsam zu den Nebeln, Raid tötet sie."] = "- Спектр света: лучи (желтый, синий, красный) выявляют скрытые туманы -> носители лучей медленно идут к туманам, рейд их убивает."
L["- Lebensentzug: Strahl auf einen Spieler -> andere Spieler stellen sich in die Linie, um zu teilen."] = "- Похищение жизни: луч на игрока -> другие игроки встают в линию, чтобы разделить."
L["- Desintegrationsstrahl: Labyrinth aus Augen am Boden -> Strahl folgt, den Lücken folgen."] = "- Луч дезинтеграции: лабиринт из глаз на полу -> луч движется, следовать по брешам."
L["- Kraft des Willens: Rückstoß -> aus der Kegelrichtung laufen."] = "- Сила воли: отбрасывание -> уходить из направления конуса."
L["- Verweilender Blick: Kreise am Boden -> herauslaufen."] = "- Пристальный взгляд: круги на полу -> выбегать."
L["Taktik: Aufgabenverteilung bei Farbstrahlen vorher festlegen. Im Labyrinth eng zusammen der Lücke folgen."] = "Тактика: распределение задач на цветные лучи заранее. В лабиринте плотно вместе идти по бреши."
L["DURUMU: Farbstrahlen zu den Nebeln, Nebel töten! Labyrinth folgen!"] = "ДУРУМУ: цветные лучи к туманам, убить туманы! Следовать лабиринту!"
L["Lebensentzug teilen, Kraft des Willens ausweichen."] = "Делить Похищение жизни, уворачиваться от Силы воли."
L["Primordius + Lebendige Flüssigkeiten"] = "Изначалий + Живые жидкости"
L["- Lebendige Flüssigkeit: Pfützen geben Mutationen -> zugeteilte Spieler sammeln positive Mutationen."] = "- Живая жидкость: лужи дают мутации -> назначенные игроки собирают положительные мутации."
L["- Schlechte Mutationen: Stapel schwächen Spieler -> nicht zu viele aufnehmen."] = "- Плохие мутации: стаки ослабляют игроков -> не набирать слишком много."
L["- Volle Mutation: genug positive Stapel -> großer Bonus, Schaden auf den Boss erhöhen."] = "- Полная мутация: достаточно положительных стаков -> большой бонус, увеличить урон по боссу."
L["- Primordialer Schlag / Fehlgebildetes Blut: Tankdebuff -> Tankwechsel."] = "- Изначальный удар / Искаженная кровь: дебафф на танке -> смена танков."
L["- Evolution: Boss erhält zusätzliche Fähigkeiten -> Raid passt sich an, Cooldowns."] = "- Эволюция: босс получает дополнительные способности -> рейд подстраивается, кулдауны."
L["Taktik: Feste Sammelgruppe für Pfützen, Rest auf den Boss. Viskose Schrecken (heroisch) separat tanken."] = "Тактика: фиксированная группа сборщиков на лужи, остальные на босса. Вязких ужасов (героик) танковать отдельно."
L["PRIMORDIUS: Sammler nehmen positive Mutationen, keine schlechten!"] = "ИЗНАЧАЛИЙ: сборщики берут положительные мутации, без плохих!"
L["Tankwechsel bei Schlag. Evolution beachten."] = "Смена танков на Ударе. Следить за Эволюцией."
L["Dunkler Animus + Animagolems (klein, mittel, groß)"] = "Темный Анимус + анима-големы (малые, средние, большие)"
L["- Anima-Golems: beim Tod springt ihre Anima auf andere -> kontrolliert töten, nicht wahllos AoE."] = "- Анима-големы: при смерти их анима перепрыгивает на других -> убивать под контролем, без бездумного АоЕ."
L["- Animaring: Kugeln um Spieler -> ausweichen bzw. soaken."] = "- Кольцо анимы: сферы вокруг игроков -> уворачиваться или соакать."
L["- Unterbrechender Ruck: Zauberer werden unterbrochen -> rechtzeitig Zaubern stoppen."] = "- Прерывающий рывок: кастеры прерываются -> вовремя прекратить каст."
L["- Materietausch: tauscht Spieler -> bannen bzw. Heilung bereit."] = "- Обмен материей: меняет игроков местами -> диспелить или хил наготове."
L["- Explosiver Hieb: Tankschaden -> Tankwechsel."] = "- Взрывной удар: урон по танку -> смена танков."
L["Taktik: Golems in fester Reihenfolge, Animus spät aktivieren. Animus wird mit Anima immer stärker – zügig beenden."] = "Тактика: големов в фиксированном порядке, Анимуса активировать поздно. Анимус с анимой становится все сильнее, быстро закончить."
L["DUNKLER ANIMUS: Golems kontrolliert, kein wildes AoE!"] = "ТЕМНЫЙ АНИМУС: големов под контролем, без дикого АоЕ!"
L["Bei Unterbrechendem Ruck Zaubern stoppen. Animaring ausweichen."] = "На Прерывающем рывке прекратить каст. Уворачиваться от Кольца анимы."
L["Eiserner Qon + Quilen Ro'shak (Feuer), Quet'zal (Sturm), Dam'ren (Frost)"] = "Железный Кон + цийлини Ро'шак (огонь), Квет'зал (буря), Дам'рен (лед)"
L["- Aufspießen: Tankdebuff -> Tankwechsel."] = "- Пронзание: дебафф на танке -> смена танков."
L["- Ro'shak: Entfesselte Flamme trifft nahe Spieler -> Gruppen teilen den Schaden; brennende Asche meiden."] = "- Ро'шак: Высвобожденное пламя бьет ближних игроков -> группы делят урон; обходить горящий пепел."
L["- Quet'zal: Blitzsturm -> verteilen; Windsturm mit Rückstoß -> Positionen halten."] = "- Квет'зал: Буря молний -> рассредоточиться; Ураган с отбрасыванием -> держать позиции."
L["- Dam'ren: Tote Zone und Gefrorenes Blut -> nur von den offenen Seiten angreifen, Eispfützen meiden."] = "- Дам'рен: Мертвая зона и Замерзшая кровь -> атаковать только с открытых сторон, обходить ледяные лужи."
L["- Phase 4: Qon kämpft selbst (Faustschlag) -> Cooldowns."] = "- Фаза 4: Кон сражается сам (удар кулаком) -> кулдауны."
L["Taktik: Quilen nacheinander töten, Qon begleitet die Phasen mit Speerwürfen. Feuerpfützen klein halten, Raidwechsel zügig."] = "Тактика: цийлиней убивать по очереди, Кон сопровождает фазы бросками копья. Огненные лужи держать маленькими, рейд быстро перемещается."
L["EISERNER QON: Ro'shak teilen, Quet'zal verteilen, Dam'ren nur offene Seiten!"] = "ЖЕЛЕЗНЫЙ КОН: на Ро'шаке делить, на Квет'зале рассредоточиться, Дам'рена только с открытых сторон!"
L["Tankwechsel bei Aufspießen. Feuerpfützen meiden."] = "Смена танков на Пронзании. Обходить огненные лужи."
L["Zwillingsgemahlinnen: Lu'lin (Mond) und Suen (Sonne)"] = "Наложницы-близнецы: Лу'линь (луна) и Сюэнь (солнце)"
L["- Nacht: Lu'lin aktiv, Bestien der Albträume und kosmischer Beschuss -> Spieler verteilen, Bestien tanken."] = "- Ночь: активна Лу'линь, звери из кошмаров и космический обстрел -> игроки рассредоточены, зверей танковать."
L["- Tag: Suen aktiv, Fächer der Flammen auf Tank -> Tankwechsel; Flammen der Leidenschaft meiden."] = "- День: активна Сюэнь, Веер пламени на танке -> смена танков; обходить Пламя страсти."
L["- Dämmerung: beide aktiv -> Fähigkeiten beider beachten."] = "- Сумерки: активны обе -> учитывать способности обеих."
L["- Eiskomet: erzeugt Eis -> zum Löschen von Feuer nutzen."] = "- Ледяная комета: создает лед -> использовать для тушения огня."
L["- Himmelsgestalt/Sterne: Raidschaden -> Cooldowns."] = "- Небесный облик/звезды: урон по рейду -> кулдауны."
L["Taktik: Schaden phasenweise auf die aktive Gemahlin, beide Bosse gleichmäßig senken. Nachts Tank für Bestie, tags Tankwechsel."] = "Тактика: урон по фазам на активную наложницу, обоих боссов снижать равномерно. Ночью танк на зверя, днем смена танков."
L["ZWILLINGSGEMAHLINNEN: Nachts verteilen, Tags Tankwechsel!"] = "НАЛОЖНИЦЫ-БЛИЗНЕЦЫ: ночью рассредоточиться, днем смена танков!"
L["Eiskomet zum Löschen nutzen. Dämmerung: beide aktiv."] = "Ледяную комету для тушения. Сумерки: активны обе."
L["Lei Shen + Leitungen (4 Quadranten)"] = "Лэй Шэнь + проводники (4 квадранта)"
L["- Statischer Schock: Schaden auf ein Ziel -> mitstapeln, um zu teilen."] = "- Статический шок: урон на одну цель -> стакаться вместе, чтобы разделить."
L["- Diffusionskette: springt zwischen Spielern -> verteilen."] = "- Диффузная цепь: перескакивает между игроками -> рассредоточиться."
L["- Überladung: Ring um das Ziel -> weg vom Ziel."] = "- Перегрузка: кольцо вокруг цели -> отойти от цели."
L["- Springender Blitz: Kugeln landen im Raid -> soaken."] = "- Скачущая молния: шары падают в рейд -> соакать."
L["- Enthaupten / Donnerschlag: Tankdebuff bzw. Speer -> Tankwechsel, Speer-Zone verlassen."] = "- Обезглавливание / Громовой удар: дебафф на танке или копье -> смена танков, выйти из зоны копья."
L["Taktik: Boss in einem Quadranten tanken, um die Leitung zu stärken bzw. deaktivieren; Phasen bei 65 % und 30 %. Ab Phase 3 Peitschen und Winde beachten."] = "Тактика: танковать босса в одном квадранте, чтобы усилить или отключить проводник; фазы на 65 % и 30 %. С фазы 3 следить за плетями и ветрами."
L["Heroisch: Leitungen bleiben aktiv, Aufteilung entscheidend."] = "Героик: проводники остаются активными, распределение решает все."
L["LEI SHEN: Schock teilen, Diffusion verteilen, Überladung weg!"] = "ЛЭЙ ШЭНЬ: Шок делить, на Диффузии рассредоточиться, от Перегрузки отойти!"
L["Tankwechsel bei Enthaupten. Kugeln soaken, Speer-Zone meiden."] = "Смена танков на Обезглавливании. Шары соакать, обходить зону копья."
L["Ra-den (nur heroisch) + Anima und Vita"] = "Ра-ден (только героик) + Анима и Вита"
L["- Materialien der Schöpfung: Ra-den wählt Anima oder Vita -> Anima-Kugeln töten oder soaken, Vita trifft den fernsten Spieler."] = "- Материалы творения: Ра-ден выбирает Аниму или Виту -> сферы анимы убивать или соакать, Вита бьет самого дальнего игрока."
L["- Instabile Vita: springt zum entferntesten Spieler -> Abstände gezielt einteilen."] = "- Нестабильная вита: прыгает на самого дальнего игрока -> расстояния распределить заранее."
L["- Instabile Anima: Schaden auf nahe Spieler -> verteilen."] = "- Нестабильная анима: урон по ближним игрокам -> рассредоточиться."
L["- Verderbte Kugeln: stärken Ra-den, wenn sie ihn erreichen -> abfangen und töten."] = "- Оскверненные сферы: усиливают Ра-дена, если доходят до него -> перехватывать и убивать."
L["- Phase 2 (40 %): Ruin und Katastrophe -> starker Raidschaden, schnell beenden."] = "- Фаза 2 (40 %): Разорение и Катастрофа -> сильный урон по рейду, быстро закончить."
L["Taktik: Ra-den gilt als härtester Boss des Raids. Kugeln konsequent abfangen, Vita-Rotation planen."] = "Тактика: Ра-ден считается самым сложным боссом рейда. Сферы последовательно перехватывать, ротацию Виты спланировать."
L["RA-DEN: Kugeln abfangen! Vita-Rotation einhalten!"] = "РА-ДЕН: перехватывать сферы! Соблюдать ротацию Виты!"
L["Phase 2: Katastrophe, alle Cooldowns."] = "Фаза 2: Катастрофа, все кулдауны."
L["Schwarzfelsgießerei"] = "Литейная клана Черной горы"
L["Gruul"] = "Груул"
L["- Infernoschnitt: frontaler Kegel, Schaden wird auf alle Getroffenen aufgeteilt -> zwei feste Soak-Gruppen im Wechsel vor den Tank stellen."] = "- Адский разрез: фронтальный конус, урон делится на всех задетых -> две фиксированные соак-группы поочередно встают перед танком."
L["- Überwältigende Schläge: stapelnder Tank-Debuff -> Tankwechsel nach Ansage."] = "- Сокрушительные удары: стакающийся дебафф на танке -> смена танков по команде."
L["- Versteinernder Hieb: Spieler werden nach kurzer Zeit zu Stein und treffen Umstehende -> sofort verteilen."] = "- Окаменяющий удар: игроки через короткое время каменеют и бьют стоящих рядом -> сразу рассредоточиться."
L["- Wüten (Raserei-Phase): Gruul stürmt durch den Raum und lässt Felsen fallen -> Boden beachten, Abstand halten."] = "- Неистовство (фаза бешенства): Груул носится по залу и роняет камни -> следить за полом, держать дистанцию."
L["- Einsturz: Felsbrocken fallen auf Spieler -> nicht in markierten Bereichen stehen."] = "- Обвал: валуны падают на игроков -> не стоять в отмеченных зонах."
L["Taktik: Gruul mittig tanken, Soak-Gruppen für den Infernoschnitt fest einteilen und abwechseln; bei Versteinerung immer verteilen."] = "Тактика: Груула танковать по центру, соак-группы на Адский разрез назначить заранее и чередовать; при окаменении всегда рассредоточиться."
L["GRUUL: Schnitt-Gruppen abwechselnd soaken! Bei Versteinern verteilen!"] = "ГРУУЛ: группы на разрез соакают по очереди! На окаменении рассредоточиться!"
L["Tankwechsel nach Stapeln. Bei Wüten Felsen ausweichen."] = "Смена танков по стакам. На Неистовстве уворачиваться от камней."
L["Erzfresser"] = "Рудожор"
L["- Säureschwall: frontaler Strahl auf den Tank -> zweiter Tank steht direkt dahinter und teilt den Schaden."] = "- Кислотный поток: фронтальный луч на танка -> второй танк стоит прямо за ним и делит урон."
L["- Säureschlund: stapelnder Tank-Debuff -> Tankwechsel."] = "- Кислотная пасть: стакающийся дебафф на танке -> смена танков."
L["- Ausgewürgter Schwarzfels: Brocken hinterlassen Flächen -> sofort raus, Boss aus den Pfützen ziehen."] = "- Изрыгнутый черный камень: глыбы оставляют зоны -> сразу выйти, вытащить босса из луж."
L["- Explosive Splitter: Splitter explodieren nach kurzer Zeit -> wegbewegen (Nahkampf beachten)."] = "- Взрывные осколки: осколки взрываются через короткое время -> отойти (мили, внимание)."
L["- Phase 2 (Energie leer): Erzfresser rollt durch das Labyrinth und frisst Erz -> nicht überrollen lassen, Erz selbst zerstören/nicht ihm überlassen."] = "- Фаза 2 (энергия на нуле): Рудожор катится по лабиринту и поедает руду -> не попадать под него, руду уничтожать самим, не оставлять ему."
L["Taktik: Phase 1 Boss am Rand tanken, Tanks teilen den Säureschwall; in Phase 2 im Labyrinth nicht überrollen lassen, danach wieder sammeln."] = "Тактика: фаза 1 босса танковать у края, танки делят Кислотный поток; в фазе 2 в лабиринте не попадать под каток, потом снова собраться."
L["ERZFRESSER: Zweiter Tank hinter den Tank (Säureschwall)! Aus Pfützen raus!"] = "РУДОЖОР: второй танк за танком (Кислотный поток)! Из луж выходить!"
L["Phase 2: Rollendem Boss im Labyrinth ausweichen."] = "Фаза 2: уворачиваться от катящегося босса в лабиринте."
L["Hochofen + Ingenieure, Blasebalgbediener, Ursprüngliche Elementaristen, Schlackeelementare"] = "Доменная печь + инженеры, мехоноши, изначальные элементалисты, шлаковые элементали"
L["- Ingenieure: reparieren die Hitzeregulatoren und lassen Bomben fallen -> töten, Bomben aufnehmen und auf die Regulatoren werfen."] = "- Инженеры: чинят регуляторы жара и роняют бомбы -> убивать, подбирать бомбы и бросать в регуляторы."
L["- Blasebalgbediener: erhöhen die Hitze -> schnell töten."] = "- Мехоноши: повышают жар -> быстро убивать."
L["- Phase 2: Ursprüngliche Elementaristen sind geschützt -> Schlackeelementare (fixieren Spieler) beim Elementaristen sterben lassen, um den Schild zu brechen."] = "- Фаза 2: изначальные элементалисты под защитой -> шлаковых элементалей (фиксируются на игроках) убивать у элементалиста, чтобы сломать щит."
L["- Feuerrufer / Flüchtiges Feuer: Spieler explodieren -> raus aus dem Raid laufen."] = "- Огнезов / Нестабильный огонь: игроки взрываются -> выбежать из рейда."
L["- Phase 3 (Herz des Berges): Explosion trifft den Raid mit wachsender Stärke -> Defensivfähigkeiten, Herz schnell töten."] = "- Фаза 3 (Сердце Горы): взрыв бьет рейд с нарастающей силой -> дефы, быстро убить Сердце."
L["Taktik: Phase 1 beide Hitzeregulatoren gleichmäßig zerstören, Phase 2 die vier Elementaristen nacheinander, Phase 3 alles auf das Herz."] = "Тактика: фаза 1 оба регулятора жара разрушать равномерно, фаза 2 четырех элементалистов по очереди, фаза 3 все в Сердце."
L["HOCHOFEN: Bomben aufheben und auf Regulatoren werfen! Ingenieure töten!"] = "ДОМЕННАЯ ПЕЧЬ: подбирать бомбы и бросать в регуляторы! Убивать инженеров!"
L["P2: Schlackeelementare zum Elementaristen ziehen. P3: alles aufs Herz."] = "Ф2: шлаковых элементалей тащить к элементалисту. Ф3: все в Сердце."
L["Hochofen (Elementaristen)"] = "Доменная печь (элементалисты)"
L["Ein Symbol je Elementarist, Tötungsreihenfolge Totenkopf, Kreuz, Viereck, Mond."] = "По метке на каждого элементалиста, порядок убийства Череп, Крест, Квадрат, Полумесяц."
L["Hans'gar und Franzok"] = "Ханс'гар и Франзок"
L["- Lähmender Suplex: ein Bruder packt einen Tank und schleudert ihn -> zweiter Tank steht nahe, Heiler vorbereiten."] = "- Калечащий суплекс: один из братьев хватает танка и швыряет его -> второй танк стоит рядом, хилы готовы."
L["- Zerschmetterte Wirbel: Tank-Debuff -> Tankwechsel zwischen den Brüdern."] = "- Раздробленные позвонки: дебафф на танке -> смена танков между братьями."
L["- Störendes Gebrüll: unterbricht Zauber in der Nähe -> rechtzeitig Zauber abbrechen."] = "- Оглушительный рев: прерывает касты рядом -> вовремя прервать каст."
L["- Stampfpressen (bei ca. 85/55/30 %): Brüder springen auf die Fließbänder -> auf die Bänder wechseln und den Pressen ausweichen."] = "- Штамповочные прессы (примерно на 85/55/30 %): братья запрыгивают на конвейеры -> переходить на ленты и уворачиваться от прессов."
L["- Sengende Platten: Bodenplatten werden heiß -> nicht auf glühenden Platten stehen."] = "- Раскаленные плиты: плиты пола нагреваются -> не стоять на раскаленных плитах."
L["Taktik: Brüder getrennt tanken, Tanks tauschen nach Debuff; in den Pressen-Phasen den Pressen auf den Fließbändern ausweichen."] = "Тактика: братьев танковать раздельно, танки меняются по дебаффу; в фазах с прессами уворачиваться от прессов на конвейерах."
L["HANS'GAR & FRANZOK: In Pressen-Phase auf die Bänder, Pressen ausweichen!"] = "ХАНС'ГАР И ФРАНЗОК: в фазе прессов на ленты, уворачиваться от прессов!"
L["Gebrüll: Zauber stoppen. Tankwechsel nach Wirbel-Debuff."] = "Рев: прекратить каст. Смена танков по дебаффу на позвонки."
L["Flammenbändigerin Ka'graz + Aknor Stahlbringer, Glutwölfe"] = "Повелительница огня Ка'граз + Акнор Стальной Вестник, огненные волки"
L["- Glutwölfe: fixieren Spieler und überhitzen -> fixierte Spieler kiten, Wölfe von Tanks aufnehmen lassen."] = "- Огненные волки: фиксируются на игроках и перегреваются -> цели фиксации кайтят, волков подбирают танки."
L["- Geschmolzener Strom: großer Feuerball auf einen Spieler -> mit einer Gruppe zusammen soaken."] = "- Поток расплава: большой огненный шар на игрока -> соакать вместе группой."
L["- Lavaschnitt: Linie aus Lava -> ausweichen."] = "- Лавовый разрез: линия лавы -> уворачиваться."
L["- Steigende Flammen: stapelnder Tank-Debuff -> Tankwechsel."] = "- Нарастающее пламя: стакающийся дебафф на танке -> смена танков."
L["- Feuersturm (100 Energie): starker Raid-Schaden -> Heiler-Defensivfähigkeiten, Wölfe danach wieder aufnehmen."] = "- Огненная буря (100 энергии): сильный урон по рейду -> дефы хилов, потом снова подобрать волков."
L["Taktik: Aknor zuerst töten, Wölfe abseits halten und gesammelt umhauen; Feuersturm mit Cooldowns überstehen."] = "Тактика: сначала убить Акнора, волков держать в стороне и сносить собранными; Огненную бурю пережить под кулдаунами."
L["KA'GRAZ: Aknor zuerst! Fixierte Spieler Wölfe kiten!"] = "КА'ГРАЗ: сначала Акнор! Цели фиксации кайтят волков!"
L["Geschmolzenen Strom zusammen soaken. Feuersturm: Cooldowns."] = "Поток расплава соакать вместе. Огненная буря: кулдауны."
L["Kromog"] = "Кромог"
L["- Runen der Greifenden Erde: Hände packen alle -> vorher auf eine Rune stellen, je Spieler eine Rune, dann Hände zerstören."] = "- Руны хватающей земли: руки хватают всех -> заранее встать на руну, по одной руне на игрока, затем разбить руки."
L["- Donnernde Schläge: Raid wird weggestoßen -> auf einer Rune stehen, um festgehalten zu werden."] = "- Громовые удары: рейд отбрасывает -> стоять на руне, чтобы удержаться."
L["- Nachhall: Wellen durch den Raum -> ausweichen."] = "- Отзвук: волны по залу -> уворачиваться."
L["- Steinatem: starker Raid-Schaden über Zeit -> Heiler-Cooldowns."] = "- Каменное дыхание: сильный урон по рейду со временем -> кулдауны хилов."
L["- Hieb / Verzogene Rüstung: Tank-Debuff -> Tankwechsel."] = "- Удар / Искореженная броня: дебафф на танке -> смена танков."
L["Taktik: Boss stationär tanken, bei Greifender Erde schnell eigene Rune einnehmen und Hände wegschießen, sonst ausweichen."] = "Тактика: босса танковать на месте, на Хватающей земле быстро занять свою руну и сбить руки, в остальное время уворачиваться."
L["KROMOG: Bei Greifender Erde auf eine Rune! Hände sofort zerstören!"] = "КРОМОГ: на Хватающей земле на руну! Руки сразу разбить!"
L["Nachhall ausweichen. Tankwechsel nach Debuff."] = "Уворачиваться от Отзвука. Смена танков по дебаффу."
L["Bestienlord Darmac + Bestien (Wolf, Wyrm, Elekk)"] = "Повелитель зверей Дармак + звери (волк, змей, элекк)"
L["- Speere / Festnageln: Speere nageln Spieler fest -> Speer zerstören, Betroffene befreien."] = "- Копья / Пригвождение: копья пригвождают игроков -> уничтожить копье, освободить пострадавших."
L["- Wolf: Reißen und Zerren auf den Tank, Wildes Heulen (Wutanfall) -> beruhigen bzw. Tank-Cooldown."] = "- Волк: Разрывание и Терзание на танке, Дикий вой (исступление) -> успокоить или кулдаун танка."
L["- Wyrm: Feuer-Debuffs auf Spieler -> bannen bzw. vom Raid weggehen."] = "- Змей: огненные дебаффы на игроках -> диспелить или отойти от рейда."
L["- Elekk: Ansturm durch den Raid -> Laufwege freihalten, ausweichen."] = "- Элекк: рывок сквозь рейд -> держать пути свободными, уворачиваться."
L["- Darmac reitet bei ca. 85/65/45 % auf eine Bestie auf und erhält deren Fähigkeiten -> Bestien vorher getrennt töten."] = "- Дармак примерно на 85/65/45 % садится на зверя и получает его способности -> зверей заранее убивать раздельно."
L["Taktik: Darmac und die Bestien getrennt tanken, Bestien in fester Reihenfolge töten; Fähigkeiten des Reittiers gehen auf Darmac über."] = "Тактика: Дармака и зверей танковать раздельно, зверей убивать в фиксированном порядке; способности маунта переходят к Дармаку."
L["DARMAC: Speere zerstören, Festgenagelte befreien!"] = "ДАРМАК: уничтожать копья, освобождать пригвожденных!"
L["Bestien getrennt tanken, Wutanfall beruhigen."] = "Зверей танковать раздельно, исступление успокаивать."
L["Maschinist Thogar + Zug-Adds (Feuerheiler, Eisenräuber, Grom'kar)"] = "Машинист Тогар + адды из поездов (огненные целители, железные налетчики, гром'кары)"
L["- Züge: fahren auf vier Gleisen ein -> nie auf aktivem Gleis stehen, Ansagen (DBM) beachten."] = "- Поезда: приезжают по четырем путям -> никогда не стоять на активном пути, следить за оповещениями (DBM)."
L["- Grom'kar-Feuerheiler: heilt Adds -> unterbrechen und zuerst töten."] = "- Гром'карский огненный целитель: лечит аддов -> кикать и убивать первым."
L["- Entfachen: Tank-Debuff -> Tankwechsel."] = "- Воспламенение: дебафф на танке -> смена танков."
L["- Prototyp-Impulsgranate: Feuerflächen -> Boss herausziehen, nicht reinstehen."] = "- Опытная импульсная граната: огненные зоны -> вытащить босса, не стоять в них."
L["- Verzögerte Belagerungsbombe: Spieler explodieren -> vom Raid weggehen."] = "- Осадная бомба замедленного действия: игроки взрываются -> отойти от рейда."
L["Taktik: Feste Laufwege zwischen den Gleisen, Adds aus den Zügen schnell töten (Heiler zuerst unterbrechen), Boss abseits tanken."] = "Тактика: фиксированные пути между рельсами, аддов из поездов быстро убивать (хилов кикать первыми), босса танковать в стороне."
L["THOGAR: Nie auf aktiven Gleisen stehen! Feuerheiler unterbrechen!"] = "ТОГАР: никогда не стоять на активных путях! Кикать огненных целителей!"
L["Adds aus den Zügen zuerst. Bomben vom Raid weg."] = "Сначала адды из поездов. Бомбы подальше от рейда."
L["Thogar"] = "Тогар"
L["Totenkopf auf den Feuerheiler (unterbrechen), Kreuz auf das nächste Add."] = "Череп на огненного целителя (кикать), Крест на следующего адда."
L["Admiralin Gar'an, Marak die Blutige, Vollstreckerin Sorka"] = "Адмирал Гар'ан, Марак Кровавая, вершительница Сорка"
L["- Bei 100 Energie springt eine Jungfer auf das Schiff -> Bootsgruppe fährt hinauf und erledigt die Aufgabe dort, der Rest kämpft unten weiter."] = "- При 100 энергии одна из дев прыгает на корабль -> группа на лодку поднимается и выполняет там задачу, остальные продолжают бой внизу."
L["- Gar'an - Schnellfeuer: verfolgt einen Spieler -> aus dem Raid kiten."] = "- Гар'ан - Беглый огонь: преследует игрока -> уводить кайтом из рейда."
L["- Gar'an - Durchdringender Schuss: Linie -> mehrere Spieler stellen sich in die Linie und teilen den Schaden."] = "- Гар'ан - Пробивающий выстрел: линия -> несколько игроков встают в линию и делят урон."
L["- Marak - Blutgetränkter Herzsucher: springt zwischen markierten Spielern -> vom Raid weg, Heiler fokussieren."] = "- Марак - Окровавленный сердцеискатель: прыгает между отмеченными игроками -> подальше от рейда, хилы фокусят."
L["- Sorka - Klingensturm und Krampfartige Schatten -> ausweichen bzw. Debuff mit Bedacht bannen."] = "- Сорка - Вихрь клинков и Судорожные тени -> уворачиваться или диспелить дебафф с умом."
L["Taktik: Jungfern gemeinsam tanken und Schaden gleichmäßig verteilen; Bootsgruppe vorher einteilen."] = "Тактика: дев танковать вместе и распределять урон равномерно; группу на лодку назначить заранее."
L["EISERNE JUNGFERN: Bootsgruppe bei 100 Energie aufs Schiff!"] = "ЖЕЛЕЗНЫЕ ДЕВЫ: группа на лодку при 100 энергии на корабль!"
L["Schnellfeuer weg vom Raid kiten. Durchdringender Schuss soaken."] = "Беглый огонь кайтить подальше от рейда. Пробивающий выстрел соакать."
L["Schwarzfaust"] = "Черная Рука"
L["- Phase 1 - Zum Tode verurteilt: markierte Spieler werden mit Durchbohrendem Wurf getroffen -> Wurf durch herabgefallene Trümmer leiten."] = "- Фаза 1 - Приговорен к смерти: отмеченных игроков бьет Пронзающий бросок -> направлять бросок через упавшие обломки."
L["- Zerschmetternder Hieb: Raid-Schaden, wird auf Nahestehende geteilt -> sammeln, außer markierte Spieler."] = "- Сокрушающий удар: урон по рейду, делится на стоящих рядом -> собраться, кроме отмеченных игроков."
L["- Phase 2 - Belagerungsmaschinen: fixieren Spieler und feuern Mörser -> wegkiten, Maschinen zerstören."] = "- Фаза 2 - осадные машины: фиксируются на игроках и стреляют из минометов -> кайтить, уничтожать машины."
L["- Phase 3 - Schlackebomben: Bomben am Tank explodieren -> Tank weg vom Raid, nach Explosion Tankwechsel."] = "- Фаза 3 - шлаковые бомбы: бомбы взрываются у танка -> танк подальше от рейда, после взрыва смена танков."
L["- Gewaltiger Zerschmetternder Hieb (P3): stößt alle zurück -> nahe am Boss stehen, nicht von der Plattform fallen."] = "- Мощный сокрушающий удар (Ф3): отбрасывает всех -> стоять близко к боссу, не падать с платформы."
L["Taktik: Drei Phasen auf zwei Ebenen: Trümmer in P1 nutzen, in P2 Maschinen zerstören, in P3 dicht stehen und Schlacke ausweichen."] = "Тактика: три фазы на двух уровнях: в Ф1 использовать обломки, в Ф2 уничтожать машины, в Ф3 стоять плотно и уворачиваться от шлака."
L["SCHWARZFAUST: Markierte durch Trümmer werfen lassen, sonst sammeln!"] = "ЧЕРНАЯ РУКА: отмеченные пусть бросок идет через обломки, остальные собраться!"
L["P2 Maschinen zerstören. P3 nah am Boss bleiben, nicht runterfallen."] = "Ф2 уничтожать машины. Ф3 держаться у босса, не падать."
L["Höllenfeuerzitadelle"] = "Цитадель Адского Пламени"
L["Belagerungsmeisterin Mar'tak + Belagerungsfahrzeuge und Adds"] = "Осадный мастер Мар'так + осадные машины и адды"
L["- Belagerungsfahrzeuge: greifen das Tor an -> priorisiert zerstören, bevor sie es erreichen."] = "- Осадные машины: атакуют ворота -> уничтожать в приоритете, пока не доехали."
L["- Teufelsfeuermunition: von zerstörten Fahrzeugen -> aufheben und zu den Kanonen bringen."] = "- Снаряды Скверны: из уничтоженных машин -> подбирать и нести к пушкам."
L["- Gorebound-Teufelszauberer und Ingenieure: Zauber/Reparaturen -> unterbrechen."] = "- Чародеи Скверны и инженеры Кровавых Оков: касты/ремонт -> кикать."
L["- Mar'tak - Heulende Axt und Schockwelle -> markierte Spieler raus, Frontal meiden."] = "- Мар'так - Воющий топор и Ударная волна -> отмеченные игроки наружу, обходить фронтал."
L["Taktik: Raid in Gruppen aufteilen: Fahrzeuge zuerst, Adds unterbrechen und töten, Mar'tak nebenbei tanken."] = "Тактика: разделить рейд на группы: сначала машины, аддов кикать и убивать, Мар'так танковать попутно."
L["HÖLLENFEUERANGRIFF: Fahrzeuge zuerst! Zauberer unterbrechen!"] = "ШТУРМ ЦИТАДЕЛИ: сначала машины! Кикать чародеев!"
L["Munition zu den Kanonen bringen. Axt-Ziele raus."] = "Снаряды нести к пушкам. Цели топора наружу."
L["Eiserner Häscher"] = "Железный разрушитель"
L["- Artillerie: Debuff, explodiert nach Ablauf -> mit Debuff vom Raid weglaufen."] = "- Артобстрел: дебафф, взрывается по окончании -> с дебаффом убегать от рейда."
L["- Sperrfeuer: Frontalkegel -> nur der Tank vorne."] = "- Заградительный огонь: фронтальный конус -> спереди только танк."
L["- Instabile Kugel: Schaden um Fernkämpfer -> verteilen."] = "- Нестабильная сфера: урон вокруг рдд -> рассредоточиться."
L["- Blitz: schnelle Ansturmlinien -> ausweichen."] = "- Блиц: быстрые линии рывков -> уворачиваться."
L["- Luftphase: Feuerbomben fallen -> Bomben zerstören, bevor sie explodieren, Raid-Cooldowns."] = "- Воздушная фаза: падают огненные бомбы -> уничтожать бомбы до взрыва, рейдовые кулдауны."
L["Taktik: Fernkampf verteilt, Artillerie-Ziele raus; in der Luftphase Bomben nach Art priorisiert zerstören."] = "Тактика: рдд рассредоточены, цели Артобстрела наружу; в воздушной фазе уничтожать бомбы по приоритету типа."
L["EISERNER HÄSCHER: Artillerie-Ziele raus aus dem Raid!"] = "ЖЕЛЕЗНЫЙ РАЗРУШИТЕЛЬ: цели Артобстрела вон из рейда!"
L["Luftphase: Bomben sofort zerstören. Blitz ausweichen."] = "Воздушная фаза: бомбы сразу уничтожать. Уворачиваться от Блица."
L["Kormrok"] = "Кормрок"
L["- Runen (Explosiv, Faulig, Schatten): Kormrok taucht in Pfützen und verstärkt die nächste Fähigkeit -> Pfützenfarbe beachten."] = "- Руны (взрывная, гнилостная, теневая): Кормрок ныряет в лужи и усиливает следующую способность -> следить за цветом лужи."
L["- Greifende Hände: Hände packen Spieler -> Hände schnell töten bzw. soaken."] = "- Хватающие руки: руки хватают игроков -> быстро убивать руки или соакать."
L["- Teufelsausbruch: Wellen durch den Raum -> in Lücken bewegen."] = "- Выброс Скверны: волны по залу -> перемещаться в бреши."
L["- Schlag / Explosiver Ausbruch: Tank-Debuff -> Tankwechsel, Raid bei Explosionen sammeln."] = "- Удар / Взрывной выброс: дебафф на танке -> смена танков, рейду собраться на взрывах."
L["- Hämmern: Raid-Schaden über Zeit -> sammeln für Heilung."] = "- Сокрушение: урон по рейду со временем -> собраться для хила."
L["Taktik: Kormrok nahe der jeweiligen Pfütze tanken, Mechanik je Pfützenfarbe vorher absprechen."] = "Тактика: Кормрока танковать рядом с нужной лужей, механику для каждого цвета лужи обговорить заранее."
L["KORMROK: Wellen ausweichen, Hände sofort töten!"] = "КОРМРОК: уворачиваться от волн, руки сразу убивать!"
L["Tankwechsel nach Schlag. Pfützenfarbe ansagen."] = "Смена танков после Удара. Объявлять цвет лужи."
L["Dia Dunkelflüster, Gurtogg Siedeblut, Klingenmeister Jubei'thos"] = "Диа Темный Шепот, Гуртогг Кипящая Кровь, мастер клинка Джубей'тос"
L["- Dia - Ernten: Schatten-AoE -> verteilen; Albtraumgestalt -> Tankwechsel."] = "- Диа - Жатва: теневое АоЕ -> рассредоточиться; Облик кошмара -> смена танков."
L["- Jubei'thos - Spiegelbilder: erzeugt Kopien -> schnell töten bzw. Flächenschaden."] = "- Джубей'тос - Зеркальные отражения: создает копии -> быстро убивать или АоЕ."
L["- Gurtogg - Teufelswut / Blutsieden: fixiert Spieler -> fixierte Spieler kiten, Blutsieden auf Nahkampf rotieren."] = "- Гуртогг - Ярость Скверны / Кипение крови: фиксируется на игроках -> цели фиксации кайтят, Кипение крови ротировать по мили."
L["- Stirbt ein Ratsmitglied, verstärken sich die anderen -> Leben ausgleichen bzw. feste Reihenfolge."] = "- Когда умирает член совета, остальные усиливаются -> выравнивать здоровье или фиксированный порядок."
L["Taktik: Feste Tötungsreihenfolge (meist Dia zuerst), Mitglieder getrennt tanken, auf Spiegelbilder und Fixierung reagieren."] = "Тактика: фиксированный порядок убийства (обычно сначала Диа), членов совета танковать раздельно, реагировать на отражения и фиксацию."
L["HOHER RAT: Dia zuerst! Bei Ernten verteilen!"] = "СОВЕТ ЦИТАДЕЛИ: сначала Диа! На Жатве рассредоточиться!"
L["Spiegelbilder töten. Gurtoggs Fixierung kiten."] = "Убивать отражения. Фиксацию Гуртогга кайтить."
L["Hoher Rat"] = "Совет Цитадели"
L["Totenkopf Dia, Kreuz Gurtogg, Viereck Jubei'thos (Tötungsreihenfolge)."] = "Череп Диа, Крест Гуртогг, Квадрат Джубей'тос (порядок убийства)."
L["Kilrogg Totauge + Blutdürster-Adds, Terrorwachen"] = "Килрогг Мертвый Глаз + адды-кровопийцы, стражи ужаса"
L["- Herzsucher: Spieler hinterlassen Blutpfützen -> am Rand ablegen."] = "- Сердцеискатель: игроки оставляют кровавые лужи -> сбрасывать у края."
L["- Todesvision: Spieler betreten Visionen und kehren mit Schutz-Buff zurück -> eingeteilte Spieler rein."] = "- Видение смерти: игроки входят в видения и возвращаются с защитным баффом -> назначенные игроки заходят."
L["- Speichelnde Blutdürster: laufen zu Kilrogg -> töten, bevor sie ihn erreichen."] = "- Слюнявые кровопийцы: бегут к Килроггу -> убить, пока не добежали."
L["- Panzerzerreißen: stapelnder Tank-Debuff -> Tankwechsel."] = "- Разрыв брони: стакающийся дебафф на танке -> смена танков."
L["- Todeszuckungen: Raid-Schaden -> Defensivfähigkeiten, verteilt stehen."] = "- Предсмертные судороги: урон по рейду -> дефы, стоять рассредоточенно."
L["Taktik: Boss mittig tanken, Pfützen außen ablegen, Blutdürster vor Erreichen des Bosses töten, Visionen rotieren."] = "Тактика: босса танковать по центру, лужи сбрасывать снаружи, кровопийц убивать до того, как дойдут до босса, видения ротировать."
L["KILROGG: Blutdürster töten, bevor sie den Boss erreichen!"] = "КИЛРОГГ: убивать кровопийц, пока не дошли до босса!"
L["Pfützen am Rand ablegen. Tankwechsel nach Stapeln."] = "Лужи сбрасывать у края. Смена танков по стакам."
L["Blutschatten"] = "Кровожад"
L["- Berührung der Verdammnis: explodiert am Spieler -> raus aus dem Raid."] = "- Прикосновение погибели: взрывается на игроке -> вон из рейда."
L["- Schatten des Todes: Spieler landen im Magen -> dort Adds töten und rechtzeitig wieder hinaus."] = "- Тень смерти: игроки попадают в желудок -> там убить аддов и вовремя выйти."
L["- Geteiltes Schicksal: verbindet Spieler -> zusammenlaufen, um sich zu befreien."] = "- Общая судьба: связывает игроков -> сбежаться вместе, чтобы освободиться."
L["- Blutschatten-Geister: laufen zum Boss -> verlangsamen und töten."] = "- Духи Кровожада: идут к боссу -> замедлять и убивать."
L["- Seelenfest (100 Energie): Raid-Schaden -> Cooldowns."] = "- Пир душ (100 энергии): урон по рейду -> кулдауны."
L["Taktik: Magen-Gruppen festlegen, Geister nicht zum Boss lassen; Seelenfest mit Raid-Cooldowns heilen."] = "Тактика: определить группы в желудок, духов к боссу не пускать; Пир душ отхиливать рейдовыми кулдаунами."
L["BLUTSCHATTEN: Geister nicht zum Boss lassen! Verdammnis raus!"] = "КРОВОЖАД: не пускать духов к боссу! С Погибелью вон!"
L["Magen: Adds töten und wieder raus. Geteiltes Schicksal zusammen."] = "Желудок: убить аддов и назад. Общая судьба вместе."
L["Schattenfürst Iskar + Zwischenphasen-Adds"] = "Повелитель теней Искар + адды промежуточных фаз"
L["- Auge von Anzu: wird zwischen Spielern weitergegeben -> nur der Träger kann bestimmte Debuffs bannen."] = "- Глаз Анзу: передается между игроками -> только носитель может диспелить определенные дебаффы."
L["- Phantomwinde: wehen Spieler von der Plattform -> Auge an Betroffene geben."] = "- Призрачные ветра: сдувают игроков с платформы -> передать Глаз пострадавшим."
L["- Teufelschakram: springt zwischen Spielern -> verteilen."] = "- Чакрам Скверны: прыгает между игроками -> рассредоточиться."
L["- Adds in den Zwischenphasen: töten, Zauber unterbrechen."] = "- Адды в промежуточных фазах: убивать, кикать касты."
L["Taktik: Auge gezielt weitergeben, Adds schnell töten, verteilt stehen gegen Chakram."] = "Тактика: Глаз передавать целенаправленно, аддов быстро убивать, против чакрама стоять рассредоточенно."
L["ISKAR: Auge weitergeben! Phantomwinde: Auge an Betroffene!"] = "ИСКАР: передавать Глаз! Призрачные ветра: Глаз пострадавшим!"
L["Adds in Zwischenphase töten. Gegen Chakram verteilen."] = "Аддов в промежуточной фазе убивать. Против чакрама рассредоточиться."
L["Iskar"] = "Искар"
L["Totenkopf, Kreuz, Viereck auf die Zwischenphasen-Adds (Tötungsreihenfolge)."] = "Череп, Крест, Квадрат на аддов промежуточной фазы (порядок убийства)."
L["Socrethar der Ewige + Seelengebundenes Konstrukt"] = "Сокретар Вечный + Конструкт, связанный душой"
L["- Seelengebundenes Konstrukt: ein Spieler übernimmt das Konstrukt -> Konstrukt gegen Socrethar einsetzen."] = "- Конструкт, связанный душой: игрок берет под управление конструкт -> использовать его против Сокретара."
L["- Sargerei-Dominatoren: Gabe der Man'ari / Herrschaft -> unterbrechen und schnell töten."] = "- Доминаторы Саргерай: Дар ман'ари / Господство -> кикать и быстро убивать."
L["- Spukende Seelen: zahlreiche Adds -> Flächenschaden."] = "- Призрачные души: многочисленные адды -> АоЕ."
L["- Überladung / Raidschaden: Konstrukt-Fähigkeiten -> Raid-Cooldowns."] = "- Перегрузка / урон по рейду: способности конструкта -> рейдовые кулдауны."
L["Taktik: Konstrukt von einem festen Spieler steuern lassen, Dominatoren priorisieren, Adds zusammenziehen."] = "Тактика: конструктом управляет фиксированный игрок, доминаторы в приоритете, аддов стягивать вместе."
L["SOCRETHAR: Dominatoren unterbrechen und zuerst töten!"] = "СОКРЕТАР: доминаторов кикать и убивать первыми!"
L["Konstrukt-Pilot einsetzen. Seelen mit AoE wegräumen."] = "Пилота конструкта в дело. Души зачищать АоЕ."
L["Socrethar"] = "Сокретар"
L["Totenkopf und Kreuz auf die Dominatoren."] = "Череп и Крест на доминаторов."
L["Tyrannin Velhari + Uralter Vollstrecker, Uralter Herold, Uralter Herrscher"] = "Тиран Велари + древний вершитель, древний глашатай, древний властитель"
L["- Aura der Unterdrückung (P1): Bewegung verursacht Schaden -> nur wenig bewegen."] = "- Аура подавления (Ф1): движение наносит урон -> двигаться поменьше."
L["- Aura der Verachtung (P2): senkt die Heilung -> Heiler-Cooldowns."] = "- Аура презрения (Ф2): снижает исцеление -> кулдауны хилов."
L["- Aura der Bösartigkeit (P3): Schaden bei Heilung -> Raid-Cooldowns."] = "- Аура злобы (Ф3): урон при исцелении -> рейдовые кулдауны."
L["- Uralter Herold: heilt -> unterbrechen und schnell töten."] = "- Древний глашатай: лечит -> кикать и быстро убивать."
L["- Edikt der Verurteilung: Schaden wird geteilt -> markierte Spieler zusammenbringen."] = "- Эдикт осуждения: урон делится -> отмеченных игроков свести вместе."
L["Taktik: Adds je Phase zuerst töten, Herold unterbrechen, Velhari danach; Auren mit Cooldowns überstehen."] = "Тактика: в каждой фазе сначала адды, глашатая кикать, потом Велари; ауры переживать под кулдаунами."
L["VELHARI: Adds zuerst! Herold unterbrechen!"] = "ВЕЛАРИ: сначала адды! Кикать глашатая!"
L["Unterdrückung: wenig bewegen. Edikt zusammen teilen."] = "Подавление: мало двигаться. Эдикт делить вместе."
L["Velhari"] = "Велари"
L["Totenkopf auf das aktuelle Add, Kreuz auf den Herold (unterbrechen)."] = "Череп на текущего адда, Крест на глашатая (кикать)."
L["Teufelsfürst Zakuun"] = "Лорд Скверны Закуун"
L["- Samen der Zerstörung: Spieler explodieren -> an festgelegten Punkten ablegen."] = "- Семя разрушения: игроки взрываются -> сбрасывать в заданных точках."
L["- Entwaffnet: Boss wirft Waffen und erzeugt Spalten -> Spalten mit Befleckt-Debuff schließen."] = "- Обезоружен: босс бросает оружие и создает разломы -> закрывать разломы с дебаффом Скверна."
L["- Befleckt: Heilabsorb -> Spieler mit Debuff gehen in Spalten."] = "- Скверна: поглощение исцеления -> игроки с дебаффом идут в разломы."
L["- Kavitation: Wellen -> ausweichen."] = "- Кавитация: волны -> уворачиваться."
L["- Schwer bewaffnet: Tank-Schaden -> Cooldowns, Tankwechsel."] = "- Тяжеловооруженный: урон по танку -> кулдауны, смена танков."
L["Taktik: Samen an feste Positionen tragen, Spalten von Befleckten schließen lassen, Wellen ausweichen."] = "Тактика: семена нести на фиксированные позиции, разломы закрывают игроки со Скверной, от волн уворачиваться."
L["ZAKUUN: Samen an Positionen tragen! Befleckte in die Spalten!"] = "ЗАКУУН: семена на позиции! Игроки со Скверной в разломы!"
L["Kavitation ausweichen. Tankwechsel nach Ansage."] = "Уворачиваться от Кавитации. Смена танков по команде."
L["Xhul'horac + Teufelswichtel, Vanguard Akkelion, Omnus"] = "Зул'хорак + бесы Скверны, Авангард Аккелион, Омнус"
L["- Teufels- und Leerenschlag: Tank-Debuffs -> Tankwechsel nach Combo."] = "- Удар Скверны и Удар Бездны: дебаффы на танке -> смена танков после комбо."
L["- Teufelswichtel: Debuff-bringende Adds -> schnell töten."] = "- Бесы Скверны: адды, накладывающие дебаффы -> быстро убивать."
L["- Pfützen (Teufel/Leere): bilden Flächen -> herausziehen."] = "- Лужи (Скверна/Бездна): создают зоны -> вытаскивать босса."
L["- Schwarzes Loch: zieht Spieler an -> ausweichen bzw. soaken."] = "- Черная дыра: притягивает игроков -> уворачиваться или соакать."
L["- Akkelion und Omnus: Adds je Phase -> tanken und töten."] = "- Аккелион и Омнус: адды в каждой фазе -> танковать и убивать."
L["Taktik: Boss getrennt von Adds tanken, Wichtel priorisieren, Pfützen am Rand ablegen."] = "Тактика: босса танковать отдельно от аддов, бесов в приоритете, лужи сбрасывать у края."
L["XHUL'HORAC: Wichtel sofort töten! Tankwechsel nach Combo!"] = "ЗУЛ'ХОРАК: бесов сразу убивать! Смена танков после комбо!"
L["Pfützen am Rand ablegen. Schwarzes Loch meiden."] = "Лужи сбрасывать у края. Обходить Черную дыру."
L["Xhul'horac"] = "Зул'хорак"
L["Totenkopf und Kreuz auf die Wichtel bzw. Vanguard-Adds."] = "Череп и Крест на бесов или аддов Авангарда."
L["Mannoroth + Teufelswichtel, Verdammnislords, Höllenbestien, Beschwörer"] = "Маннорот + бесы Скверны, повелители ужаса, инферналы, призыватели"
L["- Beschwörer (P1): drei Beschwörer erzeugen Adds -> töten, um Mannoroth zu befreien."] = "- Призыватели (Ф1): три призывателя вызывают аддов -> убить, чтобы освободить Маннорота."
L["- Fluch der Legion: Debuff spawnt Verdammnislord -> bannen, Lord töten."] = "- Проклятие Легиона: дебафф вызывает повелителя ужаса -> диспелить, убить повелителя."
L["- Mal der Verdammnis: Explosion -> verteilen."] = "- Метка погибели: взрыв -> рассредоточиться."
L["- Schattenblitzsalve (Verdammnislords): -> unterbrechen."] = "- Залп стрел Тьмы (повелители ужаса): -> кикать."
L["- Gleve-Combo / Gewaltige Explosion: Tank-Mechanik -> Tankwechsel."] = "- Комбо глефы / Мощный взрыв: механика танков -> смена танков."
L["Taktik: P1 Beschwörer und Adds, dann Mannoroth; ab P2 verstärkt er sich mit Teufelsstrahlen, Raid-Cooldowns einplanen."] = "Тактика: Ф1 призыватели и адды, затем Маннорот; с Ф2 он усиливается лучами Скверны, запланировать рейдовые кулдауны."
L["MANNOROTH: Beschwörer zuerst! Verdammnislords unterbrechen!"] = "МАННОРОТ: сначала призыватели! Кикать повелителей ужаса!"
L["Mal der Verdammnis: verteilen. Tankwechsel nach Combo."] = "Метка погибели: рассредоточиться. Смена танков после комбо."
L["Mannoroth"] = "Маннорот"
L["Ein Symbol je Beschwörer bzw. Verdammnislord, Totenkopf zuerst."] = "По метке на каждого призывателя или повелителя ужаса, Череп первым."
L["Archimonde + Teufelsgeborene Übeldämonen, Verdammnisfeuergeister"] = "Архимонд + рожденные Скверной злодеи, духи пламени Скверны"
L["- Verdammnisfeuer: Geister hinterlassen wachsende Feuerspuren -> Feuer nicht durch den Raid ziehen, nicht reinstehen."] = "- Пламя погибели: духи оставляют растущие огненные следы -> не тащить огонь через рейд, не стоять в нем."
L["- Gefesselte Qual: Spieler sind angekettet -> nacheinander aus dem Kreis laufen, um die Kette zu brechen (Schaden für den Raid)."] = "- Скованная пытка: игроки прикованы цепью -> по очереди выбегать из круга, чтобы разорвать цепь (урон по рейду)."
L["- Todesbrandmal: starker Tank-Treffer und Add-Spawn -> Tankwechsel, Add schnell töten."] = "- Клеймо смерти: сильный удар по танку и появление адда -> смена танков, адда быстро убить."
L["- Geschmiedetes Chaos: verbundene Spieler feuern Strahlen aufeinander -> Strahlen vom Raid weg ausrichten."] = "- Кованый хаос: связанные игроки стреляют лучами друг в друга -> направлять лучи от рейда."
L["- Mal der Legion: mehrere Spieler explodieren nacheinander -> in feste Ecken laufen."] = "- Метка Легиона: несколько игроков взрываются по очереди -> бежать в назначенные углы."
L["- Netherverbannung (P3): Gruppe wird in den Wirbelnden Nether verbannt -> dort Adds töten und zurückkehren."] = "- Изгнание в Пустоверть (Ф3): группу изгоняют в Круговерть Пустоты -> там убить аддов и вернуться."
L["Taktik: Drei Phasen: Feuer am Rand ablegen und Ketten kontrolliert brechen, in P2 Strahlen und Male sauber, in P3 Nether-Gruppen rotieren."] = "Тактика: три фазы: огонь сбрасывать у края и цепи рвать под контролем, в Ф2 чисто отработать лучи и метки, в Ф3 ротировать группы в Пустоверть."
L["Mythisch: eigene Phase im Wirbelnden Nether mit stark veränderten Mechaniken."] = "Эпохальный режим: отдельная фаза в Круговерти Пустоты с сильно измененными механиками."
L["ARCHIMONDE: Feuer am Rand ablegen! Ketten nacheinander brechen!"] = "АРХИМОНД: огонь сбрасывать у края! Цепи рвать по очереди!"
L["Strahlen vom Raid weg. Mal der Legion: in die Ecken."] = "Лучи от рейда. Метка Легиона: в углы."
L["Hochfels"] = "Верховный Молот"
L["Kargath Messerfaust + Tribünen-Adds"] = "Каргат Острорук + адды на трибунах"
L["- Durchbohren: Tank-Debuff mit Schaden über Zeit -> Tankwechsel."] = "- Пронзание: дебафф на танке с уроном со временем -> смена танков."
L["- Berserkeransturm: verfolgt einen Spieler mit steigendem Schaden -> kiten und Kargath durch eine Flammensäule führen."] = "- Рывок берсерка: преследует игрока с нарастающим уроном -> кайтить и провести Каргата через огненный столп."
L["- Kettenwurf: schleudert die nächsten Spieler auf die Tribüne -> dort Adds töten und wieder hinunterspringen."] = "- Бросок цепи: забрасывает ближайших игроков на трибуны -> там убить аддов и спрыгнуть обратно."
L["- Klingentanz: Sprünge zwischen Spielern mit Flächenschaden -> verteilt stehen."] = "- Танец клинков: прыжки между игроками с АоЕ-уроном -> стоять рассредоточенно."
L["- Flammensäulen und Tiger in der Arena -> Feuer und Tiger meiden, Tiger ggf. abfangen."] = "- Огненные столпы и тигры на арене -> обходить огонь и тигров, при необходимости перехватывать тигров."
L["Taktik: Kargath zentral tanken, feste Kettenwurf-Gruppe neben dem Boss; Berserkeransturm immer in eine Flammensäule leiten."] = "Тактика: Каргата танковать по центру, фиксированная группа на Бросок цепи рядом с боссом; Рывок берсерка всегда вести в огненный столп."
L["KARGATH: Berserkeransturm in Flammensäule führen!"] = "КАРГАТ: Рывок берсерка вести в огненный столп!"
L["Kettenwurf-Gruppe: Tribünen-Adds töten. Tankwechsel nach Durchbohren."] = "Группа на Бросок цепи: убить аддов на трибунах. Смена танков после Пронзания."
L["Der Schlachter"] = "Мясник"
L["- Spalten: Schaden wird auf alle Nahestehenden aufgeteilt -> Nahkampf und Fernkampf in zwei engen Gruppen stapeln."] = "- Рассечение: урон делится на всех стоящих рядом -> мили и рдд стакаются в две плотные группы."
L["- Spalter / Fleischklopfer: Tank-Debuffs -> Tankwechsel nach Ansage."] = "- Тесак / Отбивной молот: дебаффы на танке -> смена танков по команде."
L["- Klaffende Wunden: Stapel durch Spalten -> Spieler mit vielen Stapeln kurz aus der Gruppe."] = "- Зияющие раны: стаки от Рассечения -> игроки с большим числом стаков ненадолго выходят из группы."
L["- Raserei (unter 30 %): Schaden und Tempo steigen -> Cooldowns, Burn-Phase."] = "- Бешенство (ниже 30 %): урон и скорость растут -> кулдауны, бёрн-фаза."
L["- Fleischige Brocken (Heroisch): Adds aus Schlachtresten -> töten bzw. nicht ignorieren."] = "- Мясистые куски (героик): адды из остатков бойни -> убивать, не игнорировать."
L["Taktik: Reiner Schadens-Check: dicht stapeln, Tanks wechseln, Heiler-Cooldowns auf die Raserei sparen."] = "Тактика: чистая проверка урона: плотно стакаться, танки меняются, кулдауны хилов беречь на бешенство."
L["SCHLACHTER: Eng stapeln, Spalten teilen! Tankwechsel nach Ansage!"] = "МЯСНИК: плотно стакаться, делить Рассечение! Смена танков по команде!"
L["Unter 30 %: Raserei, Cooldowns zünden!"] = "Ниже 30 %: бешенство, жмите кулдауны!"
L["Tectus + Splitter von Tectus, Bröckchen von Tectus"] = "Тектус + осколки Тектуса, обломки Тектуса"
L["- Tektonischer Umbruch: Tectus teilt sich beim 'Tod' in Splitter, diese wiederum in Bröckchen -> gleichmäßig runterschaden."] = "- Тектонический сдвиг: при «смерти» Тектус делится на осколки, они в свою очередь на обломки -> сбивать равномерно."
L["- Kristallines Sperrfeuer: Kristallspur folgt einem Spieler -> vom Raid weglaufen."] = "- Кристаллический обстрел: кристаллический след следует за игроком -> убегать от рейда."
L["- Erdsäulen: erscheinen unter Spielern -> rechtzeitig rausgehen."] = "- Земляные столпы: появляются под игроками -> вовремя выйти."
L["- Brechen: Fläche auf zufälligen Spielern -> ausweichen."] = "- Раскол: зона на случайных игроках -> уворачиваться."
L["- Akkretion / Energie: bei voller Energie starker Raid-Schaden -> Splitter nicht zu lange leben lassen."] = "- Аккреция / энергия: при полной энергии сильный урон по рейду -> не давать осколкам жить слишком долго."
L["Taktik: Tectus, dann zwei Splitter, dann Bröckchen jeweils möglichst gleichzeitig töten; Tanks übernehmen je einen Splitter."] = "Тактика: Тектуса, затем два осколка, затем обломки убивать по возможности одновременно; танки берут по одному осколку."
L["TECTUS: Splitter gleichmäßig runterschaden! Sperrfeuer vom Raid weg!"] = "ТЕКТУС: осколки сбивать равномерно! Обстрел подальше от рейда!"
L["Erdsäulen ausweichen. Bröckchen am Ende gemeinsam töten."] = "Уворачиваться от земляных столпов. Обломки в конце убивать вместе."
L["Tectus (Splitter)"] = "Тектус (осколки)"
L["Totenkopf und Kreuz auf die zwei Splitter, je ein Tank pro Symbol."] = "Череп и Крест на два осколка, по одному танку на метку."
L["Brackenspore + Pilz-Adds"] = "Гнилобрюх + грибные адды"
L["- Nekrotischer Atem: frontaler Kegel -> nur der Tank vorne, Rest seitlich."] = "- Некротическое дыхание: фронтальный конус -> спереди только танк, остальные сбоку."
L["- Fäulnis: stapelnder Tank-Debuff -> Tankwechsel."] = "- Гниль: стакающийся дебафф на танке -> смена танков."
L["- Kriechendes Moos: heilt Boss und Adds -> mit den Flammenwerfern am Rand wegbrennen."] = "- Ползучий мох: лечит босса и аддов -> выжигать огнеметами у края."
L["- Pilzfleischfresser: Zerfall-Zauber -> unterbrechen und zuerst töten."] = "- Грибной плотоед: каст Распада -> кикать и убивать первым."
L["- Befallende Sporen (100 Energie): Raid-Schaden -> Flammenwerfer bzw. Raid-Cooldowns, Heilpilze nutzen."] = "- Заражающие споры (100 энергии): урон по рейду -> огнеметы или рейдовые кулдауны, использовать лечебные грибы."
L["Taktik: Boss langsam durch den Raum tanken, Spieler an den Flammenwerfern einteilen, Fleischfresser unterbrechen und töten."] = "Тактика: босса медленно протанковывать по залу, распределить игроков на огнеметы, плотоедов кикать и убивать."
L["BRACKENSPORE: Fleischfresser unterbrechen und töten! Moos wegbrennen!"] = "ГНИЛОБРЮХ: плотоедов кикать и убивать! Мох выжигать!"
L["Atem nur auf den Tank. Tankwechsel nach Fäulnis."] = "Дыхание только на танка. Смена танков после Гнили."
L["Brackenspore"] = "Гнилобрюх"
L["Totenkopf auf den aktuellen Pilzfleischfresser (unterbrechen und töten)."] = "Череп на текущего грибного плотоеда (кикать и убить)."
L["Phemos und Pol"] = "Фемос и Пол"
L["- Pol - Schildansturm: stürmt in einer Linie auf einen Spieler -> aus der Laufbahn gehen."] = "- Пол - Рывок со щитом: бросается по линии на игрока -> уйти с пути."
L["- Pol - Unterbrechender Schrei: unterbricht alle Zauber in Reichweite -> kurz vorher Zauber abbrechen."] = "- Пол - Прерывающий крик: прерывает все касты в радиусе -> незадолго до этого прервать каст."
L["- Pol - Zermalmen: Flächen um Spieler -> verteilen und Steinen ausweichen."] = "- Пол - Сокрушение: зоны вокруг игроков -> рассредоточиться и уворачиваться от камней."
L["- Phemos - Wirbelwind: hoher Nahkampfschaden und Feuerflächen -> Nahkampf vorsichtig, aus Feuer raus."] = "- Фемос - Вихрь: сильный урон в ближнем бою и огненные зоны -> мили осторожно, из огня выходить."
L["- Phemos - Schwächendes Gebrüll: Schaden wird auf alle Getroffenen geteilt -> eng zusammen stapeln."] = "- Фемос - Ослабляющий рев: урон делится на всех задетых -> плотно стакаться."
L["Taktik: Beide Ogron nahe beieinander, aber Rücken zum Raid tanken; Fähigkeiten kommen nach Energiestand, Ansagen beachten und gleichmäßig Schaden machen."] = "Тактика: обоих огронов танковать рядом, но спиной к рейду; способности идут по уровню энергии, следить за оповещениями и бить равномерно."
L["Mythisch: zusätzlich Arkane Volatilität (Spieler explodieren) -> stärker verteilen."] = "Эпохальный режим: дополнительно Чародейская нестабильность (игроки взрываются) -> рассредоточиться сильнее."
L["ZWILLINGSOGRON: Schildansturm ausweichen! Beim Schrei Zauber stoppen!"] = "ОГРОНЫ-БЛИЗНЕЦЫ: уворачиваться от Рывка со щитом! На Крике прервать каст!"
L["Gebrüll: eng stapeln. Wirbelwind: aus Feuer raus."] = "Рев: плотно стакаться. Вихрь: из огня выходить."
L["Ko'ragh"] = "Ко'раг"
L["- Barriere der Annullierung: Schild absorbiert Magieschaden -> mit körperlichem Schaden brechen, danach kanalisiert Ko'ragh und erhält Schadensbonus."] = "- Барьер аннулирования: щит поглощает магический урон -> сбивать физическим уроном, после этого Ко'раг поддерживает каст и получает бонус к урону."
L["- Überfließende Energie: Kugeln fallen auf den Boden -> von eingeteilten Spielern abfangen lassen, sonst Raid-Schaden."] = "- Переполняющая энергия: сферы падают на пол -> пусть их перехватывают назначенные игроки, иначе урон по рейду."
L["- Magie ausstoßen - Feuer: Explosion um den Spieler -> Raid teilt den Schaden durch Stapeln, Ziel bleibt stehen."] = "- Выброс магии - огонь: взрыв вокруг игрока -> рейд делит урон, стакаясь, цель стоит на месте."
L["- Magie ausstoßen - Arkan / Frost / Schatten: Tank-Debuff, verlangsamende Frostkugel, Heilabsorb -> Tank raus, Kugel ausweichen, gezielt heilen."] = "- Выброс магии - тайная магия / лед / тьма: дебафф на танке, замедляющая ледяная сфера, поглощение исцеления -> танк выходит, уворачиваться от сферы, лечить целенаправленно."
L["- Unterdrückungsfeld: Fläche auf Spielern -> sofort verlassen."] = "- Поле подавления: зона на игроках -> сразу покинуть."
L["Taktik: Ko'ragh mittig tanken, Fänger für die Energiekugeln fest einteilen, Barriere schnell brechen und Ausstoßen-Mechanik je Element ansagen."] = "Тактика: Ко'рага танковать по центру, ловцов энергетических сфер назначить заранее, барьер быстро ломать и объявлять механику Выброса по стихии."
L["KO'RAGH: Energiekugeln fangen! Barriere schnell brechen!"] = "КО'РАГ: ловить энергетические сферы! Барьер быстро ломать!"
L["Feuer: stapeln. Arkan: Tank raus. Frostkugel ausweichen."] = "Огонь: стакаться. Тайная магия: танк выходит. От ледяной сферы уворачиваться."
L["Imperator Mar'gok + Arkane Aberrationen, Gorische Adds"] = "Император Мар'гок + чародейские аберрации, горианские адды"
L["- Mal des Chaos: Tank-Debuff, explodiert -> Tank raus, Tankwechsel."] = "- Знак хаоса: дебафф на танке, взрывается -> танк выходит, смена танков."
L["- Zerstörerische Resonanz: Minen -> ausweichen."] = "- Разрушительный резонанс: мины -> уворачиваться."
L["- Arkaner Zorn: springt zwischen Spielern -> verteilen."] = "- Чародейский гнев: прыгает между игроками -> рассредоточиться."
L["- Arkane Aberrationen: Adds -> töten, Rückstoß beim Tod beachten."] = "- Чародейские аберрации: адды -> убивать, учитывать отбрасывание при смерти."
L["- Zwischenphasen: Gorische Adds -> unterbrechen und töten."] = "- Промежуточные фазы: горианские адды -> кикать и убивать."
L["Taktik: Vier Phasen mit Runen (Verdrängung, Befestigung, Replikation), Adds zuerst."] = "Тактика: четыре фазы с рунами (смещение, укрепление, репликация), сначала адды."
L["Mythisch: zusätzliche Phase mit Cho'gall."] = "Эпохальный режим: дополнительная фаза с Чо'Галлом."
L["MAR'GOK: Mal des Chaos - Tank raus! Minen ausweichen!"] = "МАР'ГОК: Знак хаоса - танк выходит! Уворачиваться от мин!"
L["Adds zuerst. Zwischenphase: unterbrechen."] = "Сначала адды. Промежуточная фаза: кикать."
L["Mar'gok"] = "Мар'гок"
L["Totenkopf und Kreuz auf die Zwischenphasen-Adds."] = "Череп и Крест на аддов промежуточной фазы."
L["Antorus, der Brennende Thron"] = "Анторус, Пылающий Трон"
L["Garothi Weltenbrecher + Dezimator- und Annihilatorkanone"] = "Гароти Разрушитель Миров + пушки «Дециматор» и «Аннигилятор»"
L["- Dezimierung: markierte Spieler bekommen einen Treffer mit Flächenschaden -> markierte Spieler laufen vom Raid weg an den Rand."] = "- Децимация: отмеченные игроки получают удар с АоЕ-уроном -> отмеченные убегают от рейда к краю."
L["- Annihilation: Einschlagzonen auf dem Boden -> jede Zone mit mehreren Spielern soaken, sonst trifft es den ganzen Raid."] = "- Аннигиляция: зоны падения на полу -> каждую зону соакают несколько игроков, иначе бьет весь рейд."
L["- Teufelsbombardement: Tank-Debuff, hinterlässt Feuer -> Tank läuft aus dem Raid, Tankwechsel."] = "- Бомбардировка Скверны: дебафф на танке, оставляет огонь -> танк выходит из рейда, смена танков."
L["- Ausrottung (bei ca. 65 % und 35 %): starker Schaden je nach Nähe -> alle weit vom Boss weglaufen."] = "- Искоренение (примерно на 65 % и 35 %): сильный урон в зависимости от близости -> все убегают далеко от босса."
L["- Gemetzel (zwischen den Phasen): Raidschaden -> Heiler-Cooldowns bereithalten."] = "- Резня (между фазами): урон по рейду -> держать кулдауны хилов наготове."
L["Taktik: Fernkampf locker verteilt hinter dem Boss, Soak-Gruppen für Annihilation fest einteilen. Bei den Phasenwechseln die Kanone zerstören, deren Mechanik für den Raid unangenehmer ist."] = "Тактика: рдд свободно рассредоточены за боссом, соак-группы на Аннигиляцию назначить заранее. На сменах фаз уничтожать ту пушку, чья механика неприятнее для рейда."
L["GAROTHI: Annihilation-Zonen soaken, Dezimierung raus an den Rand!"] = "ГАРОТИ: соакать зоны Аннигиляции, с Децимацией к краю!"
L["Bei Ausrottung alle weg vom Boss. Tankwechsel nach Bombardement."] = "На Искоренении все от босса. Смена танков после Бомбардировки."
L["F'harg + Shatug (zwei Teufelshunde)"] = "Ф'арг + Шатуг (две гончие Скверны)"
L["- Getrennte Hunde: F'harg (Feuer) und Shatug (Schatten) teilen Stärkungen, wenn sie zu nahe beieinander stehen -> Hunde weit auseinander tanken."] = "- Разделенные гончие: Ф'арг (огонь) и Шатуг (тьма) делятся усилениями, если стоят слишком близко -> танковать гончих далеко друг от друга."
L["- Entflammte Verderbnis (F'harg): Spieler mit Debuff explodieren -> verteilt stehen, Feuerkreise am Rand ablegen."] = "- Воспламененная порча (Ф'арг): игроки с дебаффом взрываются -> стоять рассредоточенно, огненные круги сбрасывать у края."
L["- Verschlingende Sphäre (Shatug): Sphäre zieht Spieler an -> von der Sphäre weglaufen, nicht hineinziehen lassen."] = "- Поглощающая сфера (Шатуг): сфера притягивает игроков -> убегать от сферы, не давать затянуть себя."
L["- Trostloser Blick: markierte Spieler werden mit Linien verbunden -> sich so stellen, dass niemand sonst getroffen wird."] = "- Безутешный взгляд: отмеченных игроков соединяют линии -> встать так, чтобы никого больше не задело."
L["- Tank-Debuffs (Geschmolzene Berührung / Verderbender Biss) -> Tankwechsel nach Ansage."] = "- Дебаффы на танке (Расплавленное касание / Оскверняющий укус) -> смена танков по команде."
L["Taktik: Ein Tank pro Hund, Hunde an gegenüberliegenden Seiten, Raid in der Mitte. Schaden gleichmäßig verteilen, damit beide Hunde etwa gleichzeitig sterben."] = "Тактика: по танку на гончую, гончие на противоположных сторонах, рейд посередине. Урон распределять равномерно, чтобы обе гончие умерли примерно одновременно."
L["HUNDE: F'harg und Shatug weit auseinander tanken! Gleichmäßig schaden!"] = "ГОНЧИЕ: Ф'арга и Шатуга танковать далеко друг от друга! Бить равномерно!"
L["Debuff-Spieler raus aus dem Raid, von Sphären weg. Tankwechsel nach Ansage."] = "Игроки с дебаффом вон из рейда, подальше от сфер. Смена танков по команде."
L["Teufelshunde"] = "Гончие Скверны"
L["Totenkopf auf F'harg, Kreuz auf Shatug."] = "Череп на Ф'арга, Крест на Шатуга."
L["Admiral Svirax + Chefingenieur Ishkar + General Erodus + Adds"] = "Адмирал Свиракс + главный инженер Ишкар + генерал Эрод + адды"
L["- Kommandokapseln: ein aktiver Offizier kämpft, die anderen sitzen in Kapseln -> Spieler nutzen freie Kapseln für zusätzliche Fähigkeiten (z. B. Schild gegen Salve)."] = "- Командные капсулы: сражается один активный офицер, остальные сидят в капсулах -> игроки используют свободные капсулы для дополнительных способностей (например, щит против Залпа)."
L["- Salve (Svirax): hoher Raidschaden -> Raid stellt sich in den Schild des Kapselspielers oder nutzt Cooldowns."] = "- Залп (Свиракс): сильный урон по рейду -> рейд встает в щит игрока из капсулы или использует кулдауны."
L["- Entropische Minen (Ishkar): Minen am Boden -> nicht hineinlaufen, gezielt räumen."] = "- Энтропические мины (Ишкар): мины на полу -> не наступать, зачищать целенаправленно."
L["- Verstärkung (Erodus): Teufelsklingen-Stoßtruppler und Pyromanten -> Adds schnell töten, Zauber unterbrechen."] = "- Подкрепление (Эрод): штурмовики Пылающего Клинка и пироманты -> аддов быстро убивать, кикать касты."
L["- Schwäche ausnutzen: Tank-Debuff -> Tankwechsel nach Stapeln."] = "- Использование слабости: дебафф на танке -> смена танков по стакам."
L["Taktik: Aktiven Offizier fokussieren, Adds sofort umschalten. Kapselspieler fest einteilen und ihre Fähigkeiten auf Ansage nutzen."] = "Тактика: фокус на активного офицера, на аддов переключаться сразу. Игроков в капсулы назначить заранее и использовать их способности по команде."
L["OBERKOMMANDO: Adds sofort töten, bei Salve in den Schild!"] = "ВЕРХОВНОЕ КОМАНДОВАНИЕ: аддов сразу убивать, на Залпе в щит!"
L["Kapselspieler nach Plan, Minen meiden. Tankwechsel nach Stapeln."] = "Игроки в капсулах по плану, обходить мины. Смена танков по стакам."
L["Oberkommando"] = "Верховное командование"
L["Totenkopf auf den aktiven Offizier, Kreuz und Viereck auf die Adds in Tötungsreihenfolge."] = "Череп на активного офицера, Крест и Квадрат на аддов в порядке убийства."
L["Portalhüterin Hasabel + Portalwelten (Xoroth, Rancora, Nathreza)"] = "Хранительница порталов Азабель + миры порталов (Зорот, Ранкора, Натреза)"
L["- Riss in der Realität: Tank-Debuff -> Tankwechsel nach Stapeln."] = "- Разрыв реальности: дебафф на танке -> смена танков по стакам."
L["- Zusammenbrechende Welt: Einschlagzone vor dem Boss -> herauslaufen."] = "- Разрушающийся мир: зона удара перед боссом -> выбегать."
L["- Teufelssturm-Sperrfeuer: Linien quer durch den Raum -> ausweichen."] = "- Шквал бури Скверны: линии через весь зал -> уворачиваться."
L["- Portale: Hasabel öffnet Portale zu drei Welten, deren Wächter Adds herüberschicken -> Portal-Teams gehen hinein, töten den Wächter und schließen das Portal."] = "- Порталы: Азабель открывает порталы в три мира, их стражи присылают аддов -> команды на порталы заходят, убивают стража и закрывают портал."
L["- Adds der Welten (z. B. Wichtel, Vulkanare): gefährliche Fähigkeiten -> unterbrechen und schnell töten."] = "- Адды миров (например, бесы, вулканары): опасные способности -> кикать и быстро убивать."
L["Taktik: Kleine Teams (meist 3-5 Spieler mit Heiler) für die Portale einteilen, der Rest bleibt am Boss. Portale zügig schließen, sonst steigt der Raidschaden stark an."] = "Тактика: назначить маленькие команды (обычно 3-5 игроков с хилом) на порталы, остальные остаются на боссе. Порталы закрывать быстро, иначе урон по рейду сильно растет."
L["HASABEL: Portal-Teams rein, Wächter töten, Portal schließen!"] = "АЗАБЕЛЬ: команды в порталы, убить стража, закрыть портал!"
L["Linien ausweichen, Adds unterbrechen. Tankwechsel nach Riss."] = "Уворачиваться от линий, кикать аддов. Смена танков после Разрыва."
L["Hasabel (Portale)"] = "Азабель (порталы)"
L["Totenkopf, Kreuz und Viereck markieren die drei Portale (Xoroth, Rancora, Nathreza) für die Teams."] = "Череп, Крест и Квадрат отмечают три портала (Зорот, Ранкора, Натреза) для команд."
L["Essenz von Eonar + Wellen der Legion"] = "Сущность Эонар + волны Легиона"
L["- Essenz von Eonar: muss überleben -> Heiler heilen die Essenz, Adds dürfen sie nicht erreichen."] = "- Сущность Эонар: должна выжить -> хилы лечат сущность, адды не должны до нее дойти."
L["- Drei Wege (oben, Mitte, unten): Adds kommen über verschiedene Pfade -> Gruppen fest auf die Wege verteilen."] = "- Три пути (верх, середина, низ): адды идут разными путями -> группы закрепить за путями."
L["- Teufelszerstörer und Verhüller: starke Adds mit Schilden/Unsichtbarkeit -> priorisiert töten."] = "- Разрушители Скверны и маскировщики: сильные адды со щитами/невидимостью -> убивать в приоритете."
L["- Läuterer: Adds, die die Essenz angreifen -> sofort töten."] = "- Очистители: адды, атакующие сущность -> убивать сразу."
L["- Paraxis-Beschuss (Regen des Teufels, Speer der Verdammnis): Einschläge und Linien -> ausweichen."] = "- Обстрел Паракса (Дождь Скверны, Копье погибели): падения и линии -> уворачиваться."
L["Taktik: Raid in Teams aufteilen und mit den Sprungfeldern zu den Wegen wechseln. Heiler halten die Essenz hoch und kümmern sich zusätzlich um den Raid."] = "Тактика: разделить рейд на команды и перемещаться к путям через прыжковые площадки. Хилы держат сущность и вдобавок лечат рейд."
L["Mythisch: Paraxis muss zusätzlich beschädigt werden (Spieler fliegen hoch), dafür eigenes Team einteilen."] = "Эпохальный режим: дополнительно нужно бить Паракс (игроки взлетают наверх), для этого назначить отдельную команду."
L["EONAR: Adds auf allen Wegen töten, Essenz am Leben halten!"] = "ЭОНАР: убивать аддов на всех путях, держать сущность живой!"
L["Teams auf ihre Wege, Läuterer sofort töten. Einschlägen ausweichen."] = "Команды на свои пути, очистителей убивать сразу. Уворачиваться от падений."
L["Imonar der Seelenjäger"] = "Имонар Охотник за Душами"
L["- Schocklanze: Tank-Debuff -> Tankwechsel nach Stapeln."] = "- Шоковое копье: дебафф на танке -> смена танков по стакам."
L["- Schlafkanister: Spieler schläft ein -> nicht in der Nähe anderer stehen, Heiler bannen erst, wenn der Spieler allein steht."] = "- Снотворный баллон: игрок засыпает -> не стоять рядом с другими, хилы диспелят, только когда игрок стоит один."
L["- Pulsgranate: Flächenschaden an markierter Stelle -> ausweichen."] = "- Импульсная граната: АоЕ-урон в отмеченном месте -> уворачиваться."
L["- Zwischenphasen: Imonar flieht über die Brücke und legt Fallen -> Fallen ausweichen und ihm folgen."] = "- Промежуточные фазы: Имонар убегает по мосту и ставит ловушки -> обходить ловушки и следовать за ним."
L["- Spätere Phasen: Sprengsprengladungen und Feuer -> sauber laufen, Raidschaden steigt."] = "- Поздние фазы: подрывные заряды и огонь -> чисто перемещаться, урон по рейду растет."
L["Taktik: Boss am Rand der Plattform tanken, Raid locker verteilt. In den Zwischenphasen gemeinsam über die Brücke laufen und Fallen meiden."] = "Тактика: босса танковать у края платформы, рейд свободно рассредоточен. В промежуточных фазах вместе бежать по мосту и обходить ловушки."
L["IMONAR: Schlafende Spieler weg vom Raid, dann bannen!"] = "ИМОНАР: спящих игроков подальше от рейда, потом диспелить!"
L["Zwischenphase: Fallen ausweichen, Boss folgen. Tankwechsel nach Schocklanze."] = "Промежуточная фаза: обходить ловушки, следовать за боссом. Смена танков после Шокового копья."
L["Kin'garoth + Konstrukte"] = "Кин'гарот + конструкты"
L["- Verheerer: Strahl fegt über die Plattform -> ausweichen."] = "- Опустошитель: луч проходит по платформе -> уворачиваться."
L["- Diabolische Bombe: Bomben müssen gesoakt werden -> mehrere Spieler pro Bombe."] = "- Дьявольская бомба: бомбы нужно соакать -> несколько игроков на бомбу."
L["- Schmiedeschlag / Widerhallender Schlag: starke Tank-Treffer -> Tankwechsel."] = "- Удар кузни / Отражающийся удар: сильные удары по танку -> смена танков."
L["- Abriss: markierte Spieler -> gemeinsam soaken lassen, nicht weglaufen."] = "- Снос: отмеченные игроки -> соакать вместе, не убегать."
L["- Initialisierungsphase: Konstrukte (Dezimator, Annihilator, Abrissmaschine) werden gebaut -> vorher Schaden aufbauen, Konstrukte schnell zerstören."] = "- Фаза инициализации: строятся конструкты (Дециматор, Аннигилятор, Разрушитель) -> заранее накопить урон, конструкты быстро уничтожать."
L["Taktik: In der Initialisierungsphase die Konstrukte fokussieren, in der Angriffsphase Bomben soaken und Verheerer ausweichen. Tanks wechseln nach jedem schweren Schlag."] = "Тактика: в фазе инициализации фокусить конструкты, в фазе атаки соакать бомбы и уворачиваться от Опустошителя. Танки меняются после каждого тяжелого удара."
L["KIN'GAROTH: Konstrukte schnell zerstören, Bomben soaken!"] = "КИН'ГАРОТ: конструкты быстро уничтожать, бомбы соакать!"
L["Verheerer ausweichen. Tankwechsel nach Schlag."] = "Уворачиваться от Опустошителя. Смена танков после Удара."
L["Kin'garoth"] = "Кин'гарот"
L["Totenkopf, Kreuz und Viereck auf die Konstrukte in Tötungsreihenfolge."] = "Череп, Крест и Квадрат на конструкты в порядке убийства."
L["Varimathras"] = "Вариматрас"
L["- Qualen (Flammen, Frost, Teufel, Schatten): wechselnde Umgebungsgefahr -> auf die jeweilige Mechanik achten (z. B. Feuer am Boden, Frost-Zonen)."] = "- Пытки (огнем, льдом, Скверной, тьмой): меняющаяся угроза окружения -> следить за текущей механикой (например, огонь на полу, ледяные зоны)."
L["- Elend: Spieler werden getroffen -> nicht in andere Spieler hineinlaufen."] = "- Страдание: игроков бьет -> не забегать в других игроков."
L["- Dunkle Spalte: Flächen am Boden -> herausgehen."] = "- Темный разлом: зоны на полу -> выходить."
L["- Nekrotische Umarmung: Debuff springt auf nahe Spieler -> Spieler mit Debuff steht allein am Rand."] = "- Некротические объятия: дебафф перескакивает на ближних игроков -> игрок с дебаффом стоит один у края."
L["- Tank-Mechanik (Schattenstoß / Allein in der Finsternis): Tanks müssen nahe beieinander stehen -> Tankwechsel nach Ansage."] = "- Механика танков (Теневой удар / Один во тьме): танкам нужно стоять рядом -> смена танков по команде."
L["Taktik: Boss in der Mitte tanken, Raid verteilt. Debuff-Spieler sofort raus, Heiler-Cooldowns für die späten Qualen planen."] = "Тактика: босса танковать в центре, рейд рассредоточен. Игроки с дебаффом сразу наружу, кулдауны хилов спланировать на поздние пытки."
L["VARIMATHRAS: Nekrotische Umarmung sofort weg vom Raid!"] = "ВАРИМАТРАС: с Некротическими объятиями сразу от рейда!"
L["Spalten meiden, Tanks nah zusammen. Auf aktuelle Qual achten."] = "Обходить разломы, танки рядом. Следить за текущей пыткой."
L["Asara + Noura + Diima + Thu'raya (Zirkel der Shivarra)"] = "Азара + Нура + Диима + Ту'рая (Ковен шиварр)"
L["- Qualen der Titanen: Geister von Aman'Thul, Khaz'goroth, Golganneth und Norgannon greifen nacheinander an -> je nach Titan Linien, Kugeln oder Stürmen ausweichen."] = "- Пытки титанов: духи Аман'Тула, Каз'горота, Голганнета и Норганнона атакуют по очереди -> в зависимости от титана уворачиваться от линий, сфер или бурь."
L["- Wirbelnder Säbel / Feuriger Schlag: Tank-Fähigkeiten -> Tankwechsel."] = "- Вращающаяся сабля / Огненный удар: способности против танка -> смена танков."
L["- Explodierender Puls (Noura): Spieler explodieren -> verteilt stehen."] = "- Взрывной импульс (Нура): игроки взрываются -> стоять рассредоточенно."
L["- Gekühltes Blut (Diima): Heilabsorption -> gezielt wegheilen."] = "- Охлажденная кровь (Диима): поглощение исцеления -> целенаправленно отхиливать."
L["- Sturm der Dunkelheit (Asara): Raidschaden -> im Schutzbereich stehen."] = "- Буря тьмы (Азара): урон по рейду -> стоять в защитной зоне."
L["Taktik: Immer nur die aktiven Schwestern angreifen, Schaden auf die gefährlichste fokussieren. Raid verteilt, Heiler priorisieren Gekühltes Blut."] = "Тактика: атаковать только активных сестер, урон фокусить на самую опасную. Рейд рассредоточен, хилы в приоритете снимают Охлажденную кровь."
L["ZIRKEL: Titan-Geistern ausweichen, Gekühltes Blut wegheilen!"] = "КОВЕН: уворачиваться от духов титанов, Охлажденную кровь отхиливать!"
L["Verteilt stehen. Tankwechsel nach Ansage."] = "Стоять рассредоточенно. Смена танков по команде."
L["Zirkel der Shivarra"] = "Ковен шиварр"
L["Je ein Symbol pro Schwester (Totenkopf Asara, Kreuz Noura, Viereck Diima, Mond Thu'raya)."] = "По метке на каждую сестру (Череп Азара, Крест Нура, Квадрат Диима, Полумесяц Ту'рая)."
L["Aggramar + Glut von Taeshalach"] = "Агграмар + Угли Тайшалака"
L["- Taeshalachs Reichweite: stapelnder Tank-Debuff -> Tankwechsel."] = "- Досягаемость Тайшалака: стакающийся дебафф на танке -> смена танков."
L["- Taeshalachs Technik: Kombo aus Flammenriss (Soak vor dem Boss), Tempest/Feuerwellen und Wuchtschlag -> Ansage folgen, Flammenriss mit vielen Spielern soaken."] = "- Техника Тайшалака: комбо из Огненного разрыва (соак перед боссом), Бури/огненных волн и Мощного удара -> следовать оповещениям, Огненный разрыв соакать большим числом игроков."
L["- Sengende Flammen: Feuerflächen -> herauslaufen."] = "- Опаляющее пламя: огненные зоны -> выбегать."
L["- Zwischenphasen (80 % / 40 %): Glut von Taeshalach erscheint -> Glut töten, bevor sie den Boss erreicht."] = "- Промежуточные фазы (80 % / 40 %): появляются Угли Тайшалака -> убить угли, пока не дошли до босса."
L["- Wogende Flammen: Linien am Boden -> ausweichen."] = "- Бушующее пламя: линии на полу -> уворачиваться."
L["Taktik: Raid hinter dem Boss, Nahkampf/Fernkampf soaken die Flammenrisse nach Einteilung. In den Zwischenphasen alle Gluten verlangsamen und töten."] = "Тактика: рейд за боссом, мили/рдд соакают Огненные разрывы по распределению. В промежуточных фазах замедлять и убивать все угли."
L["AGGRAMAR: Flammenriss soaken, in Zwischenphasen Glut töten!"] = "АГГРАМАР: соакать Огненный разрыв, в промежуточных фазах убивать угли!"
L["Feuerlinien ausweichen. Tankwechsel nach Stapeln."] = "Уворачиваться от огненных линий. Смена танков по стакам."
L["Argus der Zerrütter + Konstellare und Adds"] = "Аргус Порабощенный + созвездники и адды"
L["- Schwungvolle Sense: stapelnder Tank-Debuff -> Tankwechsel."] = "- Размашистая коса: стакающийся дебафф на танке -> смена танков."
L["- Seelenfäule: Spieler mit Debuff -> raus aus dem Raid, Kugeln nicht treffen lassen."] = "- Гниль души: игрок с дебаффом -> вон из рейда, сферы никого не должны задеть."
L["- Geschenk des Himmels / des Meeres: Spieler mit diesen Buffs -> getrennt voneinander stehen, Rest verteilt."] = "- Дар небес / моря: игроки с этими баффами -> стоять отдельно друг от друга, остальные рассредоточены."
L["- Seelenbombe / Seelenexplosion (Phase 2): markierte Spieler -> nach Plan weglaufen bzw. sammeln."] = "- Бомба души / Взрыв души (фаза 2): отмеченные игроки -> по плану убегать или собираться."
L["- Phase 3: Pantheon-Konstellaren und Module -> Adds töten, Seelen der Pantheon nutzen."] = "- Фаза 3: созвездники Пантеона и модули -> убивать аддов, использовать души Пантеона."
L["Taktik: Mehrphasiger Endkampf mit Tankwechseln und vielen Positionen; Debuff-Spieler laufen vor dem Ablauf raus. Raid-Cooldowns für die Phasenübergänge planen."] = "Тактика: многофазный финальный бой со сменами танков и множеством позиций; игроки с дебаффом выбегают до окончания. Рейдовые кулдауны спланировать на переходы фаз."
L["ARGUS: Debuff-Spieler raus, Himmel und Meer getrennt!"] = "АРГУС: игроки с дебаффом наружу, небо и море раздельно!"
L["Phasen nach Plan, Adds schnell töten. Tankwechsel nach Sense."] = "Фазы по плану, аддов быстро убивать. Смена танков после Косы."
L["Der Smaragdgrüne Albtraum"] = "Изумрудный Кошмар"
L["Nythendra"] = "Нитендра"
L["- Befallener Atem: Kegelangriff -> nicht vor dem Boss stehen."] = "- Зараженное дыхание: конусная атака -> не стоять перед боссом."
L["- Fäulnis: Spieler mit Debuff hinterlassen Gift am Boden -> an den Rand laufen und dort ablegen."] = "- Гниль: игроки с дебаффом оставляют яд на полу -> бежать к краю и сбрасывать там."
L["- Instabile Fäulnis: Tank-Debuff explodiert -> Tankwechsel, Tank läuft kurz vor Ablauf weg."] = "- Нестабильная гниль: дебафф на танке взрывается -> смена танков, танк отходит незадолго до окончания."
L["- Herz des Schwarms: Nythendra zieht sich zurück, Käfer aus den Giftflächen -> Flächen meiden, Käfer schnell töten."] = "- Сердце роя: Нитендра отступает, жуки вылезают из ядовитых зон -> обходить зоны, жуков быстро убивать."
L["Taktik: Raid verteilt hinter dem Boss, Giftflächen nur am Rand ablegen, damit die Mitte frei bleibt."] = "Тактика: рейд рассредоточен за боссом, ядовитые зоны сбрасывать только у края, чтобы центр оставался свободным."
L["NYTHENDRA: Fäulnis am Rand ablegen, nicht vor den Boss!"] = "НИТЕНДРА: Гниль сбрасывать у края, не вставать перед боссом!"
L["Käfer beim Herz des Schwarms töten. Tankwechsel nach Instabiler Fäulnis."] = "Жуков на Сердце роя убивать. Смена танков после Нестабильной гнили."
L["Auge von Il'gynoth + Tentakel + Albtraumichor"] = "Глаз Ил'гинота + щупальца + ихор кошмара"
L["- Albtraumichor: Adds explodieren beim Tod -> am Auge töten, damit die Explosion das Auge beschädigt; Spieler stehen nicht in der Explosion."] = "- Ихор кошмара: адды взрываются при смерти -> убивать у Глаза, чтобы взрыв ранил Глаз; игроки не стоят во взрыве."
L["- Todesstarrtentakel: wirken Gedankenschinden -> unterbrechen."] = "- Щупальца смертельного взгляда: кастуют Пытку разума -> кикать."
L["- Herrschertentakel: Tank-Adds -> von Tanks abholen lassen."] = "- Щупальца-властители: танковые адды -> пусть их забирают танки."
L["- Verderbertentakel: spucken Verderbnis -> Spieler mit Debuff aus dem Raid."] = "- Оскверняющие щупальца: плюются порчей -> игроки с дебаффом вон из рейда."
L["- Herzphase: Ist das Auge tot, geht der Raid ins Innere und beschädigt das Herz -> Schaden-Cooldowns hier nutzen."] = "- Фаза сердца: когда Глаз мертв, рейд заходит внутрь и бьет Сердце -> здесь использовать кулдауны на урон."
L["Taktik: Außen Adds kontrollieren, Ichor am Auge töten. In der Herzphase alle Cooldowns, dann wiederholt sich der Zyklus."] = "Тактика: снаружи контролировать аддов, ихор убивать у Глаза. В фазе сердца все кулдауны, затем цикл повторяется."
L["IL'GYNOTH: Ichor am Auge töten, Tentakel unterbrechen!"] = "ИЛ'ГИНОТ: ихор убивать у Глаза, щупальца кикать!"
L["Herzphase: alle Cooldowns aufs Herz."] = "Фаза сердца: все кулдауны в Сердце."
L["Il'gynoth"] = "Ил'гинот"
L["Totenkopf und Kreuz auf Todesstarrtentakel (Unterbrecher), Viereck und Mond auf Herrschertentakel."] = "Череп и Крест на щупальца смертельного взгляда (кики), Квадрат и Полумесяц на щупальца-властители."
L["Elerethe Renferal + Spinnlinge"] = "Элерета Дикая Лань + паучата"
L["- Spinnenform - Nekrotisches Gift: Spieler hinterlassen Giftflächen -> am Rand ablegen."] = "- Облик паука - Некротический яд: игроки оставляют ядовитые зоны -> сбрасывать у края."
L["- Spinnenform - Netz des Schmerzes: zwei Spieler teilen Schaden -> Partner nicht trennen."] = "- Облик паука - Сеть боли: два игрока делят урон -> партнеров не разлучать."
L["- Spinnenform - Wirbelnde Schatten: Einschläge -> ausweichen."] = "- Облик паука - Кружащиеся тени: падения -> уворачиваться."
L["- Rabenform - Rasierflügel: Linienangriff -> ausweichen."] = "- Облик ворона - Острые крылья: линейная атака -> уворачиваться."
L["- Rabenform - Sich sammelnde Wolken / Dunkler Sturm: Schaden durch Wolken -> im Auge des Sturms stehen."] = "- Облик ворона - Собирающиеся тучи / Темная буря: урон от туч -> стоять в оке бури."
L["- Spinnlinge (Adds): -> töten, Netzwege zur Plattform nutzen."] = "- Паучата (адды): -> убивать, использовать пути по паутине к платформе."
L["Taktik: Spinnenform: verteilt stehen, Gift am Rand. Rabenform: Linien ausweichen und gemeinsam im Sturm stehen."] = "Тактика: облик паука: стоять рассредоточенно, яд у края. Облик ворона: уворачиваться от линий и вместе стоять в буре."
L["RENFERAL: Gift am Rand ablegen, Rasierflügel ausweichen!"] = "ЭЛЕРЕТА: яд сбрасывать у края, уворачиваться от Острых крыльев!"
L["Rabenphase: in den Dunklen Sturm stellen."] = "Фаза ворона: встать в Темную бурю."
L["Ursoc"] = "Урсок"
L["- Überwältigen / Fleisch zerfetzen: stapelnde Tank-Debuffs -> Tankwechsel."] = "- Подавление / Разрывание плоти: стакающиеся дебаффы на танке -> смена танков."
L["- Fokussierter Blick: Ursoc stürmt zu markiertem Spieler -> Soak-Gruppe stellt sich in Linie zwischen Boss und Ziel."] = "- Сосредоточенный взгляд: Урсок бросается к отмеченному игроку -> соак-группа встает в линию между боссом и целью."
L["- Schwung: Soaker bekommen Debuff -> zwei Soak-Gruppen abwechseln."] = "- Инерция: соакеры получают дебафф -> две соак-группы чередуются."
L["- Brüllende Kakophonie: Raidschaden + Albtraumbilder (Adds) -> Adds töten/kontrollieren."] = "- Ревущая какофония: урон по рейду + кошмарные образы (адды) -> убивать/контролить аддов."
L["- Raserei (bei 30 %): mehr Schaden -> Heiler- und Tank-Cooldowns."] = "- Бешенство (на 30 %): больше урона -> кулдауны хилов и танков."
L["Taktik: Zwei feste Soak-Gruppen für Fokussierten Blick einteilen, Raid hinter dem Ziel. Ab 30 % alles reinwerfen."] = "Тактика: назначить две фиксированные соак-группы на Сосредоточенный взгляд, рейд за целью. С 30 % вкладывать все."
L["URSOC: Fokussierter Blick soaken, Gruppen abwechseln!"] = "УРСОК: соакать Сосредоточенный взгляд, группы чередуются!"
L["Tankwechsel nach Stapeln. Ab 30 % Raserei: Cooldowns."] = "Смена танков по стакам. С 30 % бешенство: кулдауны."
L["Ysondre + Emeriss + Lethon + Taerar (Drachen des Albtraums)"] = "Исондра + Эмерисс + Летон + Таэрар (Драконы Кошмара)"
L["- Zwei bis drei Drachen gleichzeitig, Ysondre immer dabei -> Drachen getrennt tanken, Drachenmale verhindern Tankwechsel auf denselben Drachen."] = "- Два-три дракона одновременно, Исондра всегда в бою -> драконов танковать раздельно, драконьи метки не дают взять того же дракона после смены танков."
L["- Emeriss: Flüchtige Infektion -> verteilt stehen; Essenz der Verderbnis (Adds) -> unterbrechen/töten."] = "- Эмерисс: Летучая инфекция -> стоять рассредоточенно; Сущность порчи (адды) -> кикать/убивать."
L["- Lethon: Geist absaugen -> Schattengeister erreichen den Drachen, schnell töten."] = "- Летон: Вытягивание духа -> духи тьмы идут к дракону, быстро убивать."
L["- Taerar: Schatten von Taerar (Adds) und Brüllendes Gebrüll (Furcht) -> Adds töten, Furcht-Schutz."] = "- Таэрар: Тени Таэрара (адды) и Ревущий рык (страх) -> убивать аддов, защита от страха."
L["- Albtraumfelder / Atem: -> nicht vor die Drachen stellen, Felder meiden."] = "- Поля кошмара / дыхание: -> не вставать перед драконами, обходить поля."
L["Taktik: Drachen an verschiedenen Stellen tanken, Ysondre und den aktiven Zweitdrachen gleichmäßig senken. Adds je nach Drache priorisieren."] = "Тактика: драконов танковать в разных местах, Исондру и активного второго дракона сбивать равномерно. Аддов в приоритете в зависимости от дракона."
L["DRACHEN: Getrennt tanken, Adds der Drachen sofort töten!"] = "ДРАКОНЫ: танковать раздельно, аддов драконов сразу убивать!"
L["Nicht vor die Köpfe, bei Emeriss verteilen."] = "Не стоять перед головами, на Эмериссе рассредоточиться."
L["Drachen des Albtraums"] = "Драконы Кошмара"
L["Ein Symbol pro aktivem Drachen (Totenkopf Ysondre), damit Tanks und Schadensverteilung klar sind."] = "По метке на каждого активного дракона (Череп Исондра), чтобы танки и распределение урона были ясны."
L["Cenarius + Kräfte des Albtraums"] = "Кенарий + силы Кошмара"
L["- Kräfte des Albtraums: Adds (Irrwische, Drachen, Uralte, Verdrehte Schwestern) -> töten oder durch Heilung auf Gereinigtem Boden bekehren."] = "- Силы Кошмара: адды (огоньки, драконы, древни, искаженные сестры) -> убивать или обращать лечением на очищенной земле."
L["- Kriechende Albträume: stapelnder Debuff -> auf gereinigten Boden gehen, um ihn zu senken."] = "- Ползучие кошмары: стакающийся дебафф -> идти на очищенную землю, чтобы его снизить."
L["- Albtraumdornen: Ranken verfolgen einen Spieler -> Spieler zieht sie weg vom Raid."] = "- Кошмарные шипы: лозы преследуют игрока -> игрок уводит их подальше от рейда."
L["- Tank-Debuffs: -> Tankwechsel nach Stapeln."] = "- Дебаффы на танке: -> смена танков по стакам."
L["- Späte Phase: mehr Adds und Raidschaden -> Heiler-Cooldowns, Fokus auf den Boss."] = "- Поздняя фаза: больше аддов и урона по рейду -> кулдауны хилов, фокус на босса."
L["Taktik: Gereinigte Adds helfen dem Raid, verdorbene Drachen und Uralte priorisieren. Debuffs auf gereinigtem Boden abbauen."] = "Тактика: очищенные адды помогают рейду, оскверненных драконов и древней в приоритете. Дебаффы сбрасывать на очищенной земле."
L["CENARIUS: Adds kontrollieren, Stapel auf gereinigtem Boden abbauen!"] = "КЕНАРИЙ: аддов контролировать, стаки сбрасывать на очищенной земле!"
L["Ranken weg vom Raid ziehen. Tankwechsel nach Ansage."] = "Лозы уводить подальше от рейда. Смена танков по команде."
L["Xavius + Albtraumadds"] = "Ксавий + адды Кошмара"
L["- Verderbnis-Leiste: steigt durch Mechaniken -> niedrig halten, bei 100 übernimmt Xavius den Spieler."] = "- Полоса порчи: растет от механик -> держать низкой, при 100 Ксавий подчиняет игрока."
L["- Albtraumklingen: Klingen zwischen Spielern -> nicht in den Linien stehen."] = "- Кошмарные клинки: клинки между игроками -> не стоять на линиях."
L["- Verdunkelnde Seele: Magie-Debuff, beim Bannen entsteht eine Fläche -> nur am Rand bannen."] = "- Помрачение души: магический дебафф, при диспеле появляется зона -> диспелить только у края."
L["- Fesseln des Schreckens (Phase 2): zwei Spieler verbunden -> zusammenlaufen."] = "- Оковы ужаса (фаза 2): два игрока связаны -> сбежаться вместе."
L["- Verderbnis-Schrecken (Add) -> von einem Tank übernehmen, Schaden darauf."] = "- Ужас порчи (адд) -> забирает один из танков, урон на него."
L["- Traumsimulakrum: bei tödlichem Schaden fallen Spieler in den Traum -> zurückkehren, solange möglich."] = "- Симулякр сна: при смертельном уроне игроки падают в Сон -> возвращаться, пока возможно."
L["Taktik: Verderbnis bewusst klein halten, Bannflächen am Rand. In Phase 3 Tentakel und Boss gleichzeitig kontrollieren."] = "Тактика: порчу сознательно держать малой, зоны от диспела у края. В фазе 3 одновременно контролировать щупальца и босса."
L["XAVIUS: Verderbnis niedrig halten, nur am Rand bannen!"] = "КСАВИЙ: порчу держать низкой, диспелить только у края!"
L["Verbundene Spieler zusammen. Schrecken-Add vom Tank holen."] = "Связанные игроки вместе. Адда Ужаса забирает танк."
L["Die Nachtfestung"] = "Цитадель Ночи"
L["Skorpyron + Kristall-, Säure- und Instabile Skorpide"] = "Скорпирон + кристаллические, кислотные и нестабильные скорпиды"
L["- Arkanhieb: Tank-Kombo -> Tankwechsel nach jeder Kombo."] = "- Чародейский удар: комбо по танку -> смена танков после каждого комбо."
L["- Schockwelle: tödlicher Raidschaden -> hinter einem abgefallenen blauen Kristallsplitter verstecken."] = "- Ударная волна: смертельный урон по рейду -> прятаться за отвалившимся синим кристаллическим осколком."
L["- Kristallsplitter: fallen vom Boss -> nicht zerstören, solange sie als Deckung gebraucht werden."] = "- Кристаллические осколки: отваливаются от босса -> не разрушать, пока нужны как укрытие."
L["- Skorpid-Adds: kristallin, säurehaltig, instabil -> mit Flächenschaden töten, instabile Adds nicht im Raid platzen lassen."] = "- Адды-скорпиды: кристаллические, кислотные, нестабильные -> убивать АоЕ, нестабильным не давать лопаться в рейде."
L["Taktik: Raid hinter dem Boss, vor jeder Schockwelle zu den Splittern laufen. Adds zusammen ziehen und mit AoE töten."] = "Тактика: рейд за боссом, перед каждой Ударной волной бежать к осколкам. Аддов стягивать вместе и убивать АоЕ."
L["SKORPYRON: Bei Schockwelle hinter Kristallsplitter!"] = "СКОРПИРОН: на Ударной волне за кристаллический осколок!"
L["Tankwechsel nach Arkanhieb. Adds mit AoE töten."] = "Смена танков после Чародейского удара. Аддов убивать АоЕ."
L["Chronomatische Anomalie + Zeitpartikel"] = "Хрономатическая аномалия + частицы времени"
L["- Zeitgeschwindigkeit wechselt (normal, schnell, langsam) -> Fähigkeiten kommen je nach Phase schneller oder langsamer."] = "- Скорость времени меняется (нормальная, быстрая, медленная) -> способности идут быстрее или медленнее в зависимости от фазы."
L["- Zeitfreisetzung: Heilabsorption, die beim Ablauf explodiert -> vor dem Ablauf komplett wegheilen."] = "- Высвобождение времени: поглощение исцеления, взрывающееся по окончании -> полностью отхилить до окончания."
L["- Zeitbombe: Spieler explodiert -> rechtzeitig aus dem Raid laufen."] = "- Бомба времени: игрок взрывается -> вовремя выбежать из рейда."
L["- Schwindendes Zeitpartikel (Add): explodiert bei Tod oder Ablauf -> kontrolliert töten, Heiler bereit."] = "- Угасающая частица времени (адд): взрывается при смерти или по окончании -> убивать под контролем, хилы наготове."
L["- Kraft überwältigt: Tank-Stapel -> Tankwechsel."] = "- Подавляющая сила: стаки на танке -> смена танков."
L["Taktik: Phasenablauf kennen und Cooldowns auf die schnellen Abschnitte legen. Heiler priorisieren Zeitfreisetzung."] = "Тактика: знать порядок фаз и класть кулдауны на быстрые отрезки. Хилы в приоритете снимают Высвобождение времени."
L["ANOMALIE: Zeitfreisetzung wegheilen, Zeitbomben raus!"] = "АНОМАЛИЯ: Высвобождение времени отхиливать, с Бомбами времени наружу!"
L["Partikel kontrolliert töten. Tankwechsel nach Stapeln."] = "Частицы убивать под контролем. Смена танков по стакам."
L["Trilliax + Putzroboter"] = "Триллиакс + роботы-уборщики"
L["- Modi wechseln (Reiniger, Wahnsinniger, Hausmeister) -> Mechanik jedes Modus kennen."] = "- Смена режимов (Очиститель, Маньяк, Смотритель) -> знать механику каждого режима."
L["- Wahnsinniger: Arkane Fesseln verbinden Spieler -> Verbundene stehen zusammen, Verbindungen nicht durch andere ziehen."] = "- Маньяк: Чародейские узы связывают игроков -> связанные стоят вместе, не протягивать связи через других."
L["- Hausmeister: Kuchen/Giftige Stücke liegen herum -> nach Einteilung essen, giftige Stücke nicht zu oft."] = "- Смотритель: повсюду лежат торты/ядовитые куски -> есть по распределению, ядовитые куски не слишком часто."
L["- Reiniger: Putzroboter erscheinen -> schnell töten."] = "- Очиститель: появляются роботы-уборщики -> быстро убивать."
L["- Vernichtung: starker Raidschaden -> Cooldowns."] = "- Уничтожение: сильный урон по рейду -> кулдауны."
L["Taktik: Boss in der Mitte, Raid verteilt. Kuchen-Esser und Add-Gruppe fest einteilen."] = "Тактика: босс в центре, рейд рассредоточен. Едоков тортов и группу на аддов назначить заранее."
L["TRILLIAX: Verbundene zusammen, Kuchen nach Einteilung essen!"] = "ТРИЛЛИАКС: связанные вместе, торты есть по распределению!"
L["Putzroboter schnell töten. Cooldowns für Vernichtung."] = "Роботов-уборщиков быстро убивать. Кулдауны на Уничтожение."
L["Aluriel die Zauberklinge + Verzauberungen (Adds)"] = "Заклинательница клинков Алуриэль + чары (адды)"
L["- Vernichten: großer Tank-Treffer -> Tankwechsel nach jedem Vernichten."] = "- Уничтожение: сильный удар по танку -> смена танков после каждого Уничтожения."
L["- Frostphase - Frostmal: Spieler springen ab und hinterlassen Flächen -> verteilt stehen, Flächen am Rand ablegen."] = "- Ледяная фаза - Ледяная метка: игроки отпрыгивают и оставляют зоны -> стоять рассредоточенно, зоны сбрасывать у края."
L["- Feuerphase - Sengendes Brandmal: markierte Spieler explodieren -> verteilt stehen, Feuerverzauberungs-Add töten."] = "- Огненная фаза - Опаляющее клеймо: отмеченные игроки взрываются -> стоять рассредоточенно, убить адда огненных чар."
L["- Arkanphase - Arkane Kugeln und Verzauberungen -> Adds schnell töten, Kugeln ausweichen."] = "- Тайная фаза - чародейские сферы и чары -> аддов быстро убивать, уворачиваться от сфер."
L["- Verzauberungs-Adds nach jeder Phase -> unterbrechen und töten."] = "- Адды-чары после каждой фазы -> кикать и убивать."
L["Taktik: Raid verteilt, Mechanik je nach Schule spielen. Adds haben Vorrang vor dem Boss."] = "Тактика: рейд рассредоточен, механику играть по школе магии. Адды в приоритете перед боссом."
L["ALURIEL: Adds zuerst! Frostflächen am Rand, Brandmal verteilt!"] = "АЛУРИЭЛЬ: сначала адды! Ледяные зоны у края, на Клейме рассредоточиться!"
L["Tankwechsel nach Vernichten."] = "Смена танков после Уничтожения."
L["Aluriel (Adds)"] = "Алуриэль (адды)"
L["Totenkopf, Kreuz und Viereck auf die Verzauberungs-Adds in Tötungsreihenfolge."] = "Череп, Крест и Квадрат на аддов-чар в порядке убийства."
L["Tichondrius + Fledermäuse"] = "Тихондрий + летучие мыши"
L["- Aaspest: stapelnder Debuff auf Spielern -> Spieler mit Pest verteilt stehen."] = "- Чума падали: стакающийся дебафф на игроках -> игроки с чумой стоят рассредоточенно."
L["- Sucherschwarm: trifft alle Spieler mit Aaspest in Linie -> nicht in der Linie zwischen Boss und Ziel stehen."] = "- Рой-искатель: бьет всех игроков с Чумой падали на линии -> не стоять на линии между боссом и целью."
L["- Mal von Argus: markierte Spieler explodieren bei Nähe -> weit auseinander."] = "- Метка Аргуса: отмеченные игроки взрываются при сближении -> далеко друг от друга."
L["- Echos der Leere: starker Schaden -> hinter Säulen/Deckung gehen."] = "- Отголоски Бездны: сильный урон -> уходить за колонны/укрытие."
L["- Illusionäre Nacht: Fledermäuse -> töten, Essenz der Nacht sammeln."] = "- Иллюзорная ночь: летучие мыши -> убивать, собирать Сущность ночи."
L["Taktik: Raid verteilt um den Boss, Positionen für Mal von Argus festlegen. In Illusionärer Nacht Adds schnell weg."] = "Тактика: рейд рассредоточен вокруг босса, позиции на Метку Аргуса определить заранее. В Иллюзорной ночи аддов быстро убрать."
L["TICHONDRIUS: Mal von Argus weit auseinander!"] = "ТИХОНДРИЙ: с Меткой Аргуса далеко друг от друга!"
L["Bei Echos hinter Deckung. Fledermäuse töten."] = "На Отголосках за укрытие. Убивать летучих мышей."
L["Krosus"] = "Крос"
L["- Zerschmettern: Krosus zerstört Brückenteile -> Raid rechtzeitig auf intakte Teile laufen."] = "- Сокрушение: Крос разрушает части моста -> рейд вовремя переходит на целые части."
L["- Brennendes Pech: Pfützen -> soaken bzw. ausweichen nach Ansage."] = "- Горящая смола: лужи -> соакать или уворачиваться по команде."
L["- Kugel der Zerstörung: markierter Spieler -> weit weg vom Raid laufen."] = "- Сфера разрушения: отмеченный игрок -> убегать далеко от рейда."
L["- Teufelsstrahl: Strahl über die Brücke -> ausweichen."] = "- Луч Скверны: луч вдоль моста -> уворачиваться."
L["- Brennende Glut (Adds) -> schnell töten."] = "- Горящие угли (адды) -> быстро убивать."
L["Taktik: Raid in der Brückenmitte, Kugel-Spieler an die Kanten. Plattform schrumpft, also Laufwege vorher absprechen."] = "Тактика: рейд в середине моста, игроки со сферой к краям. Платформа уменьшается, так что пути отхода обговорить заранее."
L["KROSUS: Kugel weg vom Raid, Strahl ausweichen!"] = "КРОС: сферу подальше от рейда, от луча уворачиваться!"
L["Auf die Brücke achten, Glut-Adds töten."] = "Следить за мостом, аддов-угли убивать."
L["Hochbotaniker Tel'arn (teilt sich in drei Formen)"] = "Верховный ботаник Тел'арн (делится на три формы)"
L["- Aufteilung: Tel'arn teilt sich in Naturalist, Arkanist und Solarist -> alle Formen gleichzeitig töten, sonst stehen sie wieder auf."] = "- Разделение: Тел'арн делится на натуралиста, чародея и солнцеведа -> все формы убить одновременно, иначе они воскреснут."
L["- Zusammenbruch der Nacht: Soak-Zone -> mit mehreren Spielern soaken."] = "- Наступление ночи: соак-зона -> соакать несколькими игроками."
L["- Parasitäre Fessel: Debuff -> beim Bannen entstehen Adds, Bannen nach Plan."] = "- Паразитические оковы: дебафф -> при диспеле появляются адды, диспелить по плану."
L["- Kontrolliertes Chaos: Ringe -> Lücken nutzen."] = "- Управляемый хаос: кольца -> использовать бреши."
L["- Plasmasphären (Solarist): -> gleichzeitig töten."] = "- Плазменные сферы (солнцевед): -> убивать одновременно."
L["Taktik: Schaden gleichmäßig auf alle Formen verteilen. Soak-Gruppen und Banner fest einteilen."] = "Тактика: урон распределять равномерно на все формы. Соак-группы и диспелеров назначить заранее."
L["TEL'ARN: Alle Formen gleichzeitig töten!"] = "ТЕЛ'АРН: все формы убить одновременно!"
L["Soaks nach Plan, Fessel kontrolliert bannen."] = "Соаки по плану, оковы диспелить под контролем."
L["Tel'arn"] = "Тел'арн"
L["Ein Symbol pro Form (Naturalist, Arkanist, Solarist) für die Schadensverteilung."] = "По метке на каждую форму (натуралист, чародей, солнцевед) для распределения урона."
L["Sterndeuter Etraeus"] = "Звездный авгур Этрей"
L["- Große Konjunktion: Spieler bekommen Sternzeichen -> Spieler mit gleichem Zeichen stehen zusammen."] = "- Великое соединение: игроки получают знаки зодиака -> игроки с одинаковым знаком стоят вместе."
L["- Eis-, Teufels-, Leere-Phasen: wechselnde Debuffs -> Debuffs am Rand ablegen."] = "- Ледяная, Скверны, Бездны фазы: меняющиеся дебаффы -> дебаффы сбрасывать у края."
L["- Absoluter Nullpunkt: Spieler eingefroren -> Spieler soaken / Raid hilft."] = "- Абсолютный ноль: игрок заморожен -> соакать игрока / рейд помогает."
L["- Gravitationszug: Tank-Debuff -> Tankwechsel."] = "- Гравитационное притяжение: дебафф на танке -> смена танков."
L["- Leere-Phase: Leerling-Adds -> schnell töten."] = "- Фаза Бездны: адды-послушники Бездны -> быстро убивать."
L["Taktik: Raid um den Boss verteilt, Konjunktionsgruppen schnell bilden. Phasenwechsel bei 90/60/30 % mit Cooldowns begleiten."] = "Тактика: рейд рассредоточен вокруг босса, группы соединения собирать быстро. Смены фаз на 90/60/30 % сопровождать кулдаунами."
L["ETRAEUS: Gleiche Sternzeichen zusammen!"] = "ЭТРЕЙ: одинаковые знаки зодиака вместе!"
L["Debuffs am Rand ablegen. Tankwechsel nach Gravitation."] = "Дебаффы сбрасывать у края. Смена танков после Гравитации."
L["Großmagistrix Elisande + Rekursive und Zweckdienliche Elementare"] = "Великий магистр Элисанда + рекурсивные и ускоряющие элементали"
L["- Rekursives Elementar: erzeugt beim Tod eine Zone der verlangsamten Zeit -> für Ringe/Kugeln nutzen."] = "- Рекурсивный элементаль: при смерти создает зону замедленного времени -> использовать для колец/сфер."
L["- Zweckdienliches Elementar: erzeugt beim Tod eine Zone der beschleunigten Zeit -> für Schaden nutzen, Zauber unterbrechen."] = "- Ускоряющий элементаль: при смерти создает зону ускоренного времени -> использовать для урона, кикать касты."
L["- Arkanetischer Ring: Ring rollt auf den Raid zu -> durch eine Lücke gehen oder verlangsamt durchlaufen."] = "- Чародейское кольцо: кольцо катится на рейд -> пройти через брешь или пройти сквозь в замедлении."
L["- Epochenkugel: fällt herab -> soaken."] = "- Сфера эпох: падает сверху -> соакать."
L["- Zeitwiederholung: Elisande setzt die Zeit zurück -> Mechaniken wiederholen sich als Echos."] = "- Повторение времени: Элисанда отматывает время назад -> механики повторяются как эхо."
L["Taktik: Elementare an sinnvollen Stellen töten, um Zeitblasen zu nutzen. Kugeln soaken, Ringe sauber durchlaufen."] = "Тактика: элементалей убивать в удобных местах, чтобы использовать пузыри времени. Сферы соакать, кольца проходить чисто."
L["ELISANDE: Ringe durch Lücken, Kugeln soaken!"] = "ЭЛИСАНДА: кольца через бреши, сферы соакать!"
L["Elementare gezielt töten, Zeitblasen nutzen."] = "Элементалей убивать прицельно, использовать пузыри времени."
L["Elisande (Elementare)"] = "Элисанда (элементали)"
L["Totenkopf auf Zweckdienliches, Kreuz auf Rekursives Elementar."] = "Череп на ускоряющего, Крест на рекурсивного элементаля."
L["Gul'dan + Inquisitor Vethriz, Teufelslord Kuraz, D'zorykx der Fallensteller"] = "Гул'дан + инквизитор Ветриз, лорд Скверны Кураз, Д'зорикс Ловец"
L["- Phase 1: drei Dämonen-Adds unter Gul'dans Schild -> nacheinander töten, ihre Augen von Aman'Thul geben Buffs."] = "- Фаза 1: три демона-адда под щитом Гул'дана -> убивать по очереди, их Глаза Аман'Тула дают баффы."
L["- Flüssiges Höllenfeuer: Einschläge -> ausweichen."] = "- Жидкое адское пламя: падения -> уворачиваться."
L["- Teufelsfesseln (Phase 2): Spieler gekettet -> weg vom Raid."] = "- Оковы Скверны (фаза 2): игроки скованы -> подальше от рейда."
L["- Auge von Gul'dan: Augen-Adds -> töten, bevor sie sich teilen."] = "- Глаз Гул'дана: адды-глаза -> убивать, пока не разделились."
L["- Phase 3 (Sturm des Zerstörers, Schwarze Ernte): Raidschaden und Flächen -> Cooldowns, Flächen ausweichen."] = "- Фаза 3 (Буря Разрушителя, Черная жатва): урон по рейду и зоны -> кулдауны, уворачиваться от зон."
L["Taktik: Phase 1 Adds nach Reihenfolge töten, danach Gul'dan mit Fokus auf Augen-Adds. Heiler-Cooldowns für Phase 3 planen."] = "Тактика: в фазе 1 аддов убивать по порядку, затем Гул'дан с фокусом на аддов-глаза. Кулдауны хилов спланировать на фазу 3."
L["Mythisch: zusätzliche Illidan-Phase."] = "Эпохальный режим: дополнительная фаза с Иллиданом."
L["GUL'DAN: Adds nach Reihenfolge, Augen schnell töten!"] = "ГУЛ'ДАН: аддов по порядку, глаза быстро убивать!"
L["Feuer ausweichen. Gekettete Spieler weg vom Raid."] = "Уворачиваться от огня. Скованные игроки подальше от рейда."
L["Gul'dan"] = "Гул'дан"
L["Totenkopf, Kreuz und Viereck auf die drei Dämonen in Phase 1 in Tötungsreihenfolge."] = "Череп, Крест и Квадрат на трех демонов в фазе 1 в порядке убийства."
L["Grabmal des Sargeras"] = "Гробница Саргераса"
L["Goroth"] = "Горот"
L["- Brennende Rüstung: Tank-Debuff explodiert -> Tank läuft raus, Tankwechsel."] = "- Горящая броня: дебафф на танке взрывается -> танк выбегает, смена танков."
L["- Höllische Stacheln: Stacheln erscheinen auf dem Boden -> als Deckung nutzen."] = "- Адские шипы: на полу появляются шипы -> использовать как укрытие."
L["- Höllisches Brennen: tödlicher Raidschaden -> hinter einem Stachel verstecken."] = "- Адское горение: смертельный урон по рейду -> прятаться за шипом."
L["- Zerschmetternder Stern: markierter Spieler -> Linie so durch die Stacheln ziehen, dass sie zerstört werden."] = "- Сокрушающая звезда: отмеченный игрок -> вести линию через шипы так, чтобы они разрушились."
L["- Krachender Komet: Kometen auf Spielern -> verteilt stehen, Raid nicht treffen."] = "- Рушащаяся комета: кометы на игроках -> стоять рассредоточенно, не задевать рейд."
L["Taktik: Raid locker verteilt, vor Höllischem Brennen hinter Stacheln. Stacheln mit Zerschmetterndem Stern gezielt abbauen."] = "Тактика: рейд свободно рассредоточен, перед Адским горением за шипы. Шипы целенаправленно убирать Сокрушающей звездой."
L["GOROTH: Bei Höllischem Brennen hinter Stachel!"] = "ГОРОТ: на Адском горении за шип!"
L["Kometen verteilt. Tankwechsel nach Brennender Rüstung."] = "Кометы рассредоточенно. Смена танков после Горящей брони."
L["Atrigan + Belac (Dämonische Inquisition)"] = "Атриган + Белак (Демоническая инквизиция)"
L["- Qual-Leiste: steigt ständig -> niedrig halten, bei hoher Qual Gequälte Seele/Seelenreich nutzen."] = "- Полоса мучения: постоянно растет -> держать низкой, при высоком мучении использовать Измученную душу/Царство душ."
L["- Knochensäge (Atrigan): wirbelnder Nahkampfschaden -> Nahkampf und Raid gehen auf Abstand."] = "- Костяная пила (Атриган): вращающийся урон в ближнем бою -> мили и рейд держат дистанцию."
L["- Verkalkte Stacheln: Ziel-Spieler -> ausweichen."] = "- Обызвествленные шипы: цель-игрок -> уворачиваться."
L["- Erstickende Dunkelheit / Teufelsbö (Belac): Flächen und Schaden -> ausweichen."] = "- Удушающая тьма / Порыв Скверны (Белак): зоны и урон -> уворачиваться."
L["- Seelenreich: Spieler kehren zurück, indem sie Seelen töten/unterbrechen -> Schmerzen der Schuld unterbrechen."] = "- Царство душ: игроки возвращаются, убивая/прерывая души -> кикать Муки вины."
L["Taktik: Beide Bosse gemeinsam tanken. Spieler mit hoher Qual gehen gezielt ins Seelenreich, um die Leiste zurückzusetzen."] = "Тактика: обоих боссов танковать вместе. Игроки с высоким мучением целенаправленно уходят в Царство душ, чтобы сбросить полосу."
L["INQUISITION: Qual niedrig halten! Knochensäge weg!"] = "ИНКВИЗИЦИЯ: мучение держать низким! От Костяной пилы подальше!"
L["Im Seelenreich Schuld unterbrechen."] = "В Царстве душ кикать Вину."
L["Harjatan + Klauenkiefer-Adds"] = "Харджатан + адды-когтечелюсты"
L["- Ungezügelte Wut: Kegel vor dem Boss -> mit möglichst vielen Spielern soaken."] = "- Необузданная ярость: конус перед боссом -> соакать как можно большим числом игроков."
L["- Eisige Schläge: stapelnder Tank-Debuff -> Tankwechsel."] = "- Ледяные удары: стакающийся дебафф на танке -> смена танков."
L["- Gebieterisches Gebrüll: ruft Klauenkiefer-Adds -> Adds fixieren Spieler, schnell töten."] = "- Властный рев: призывает аддов-когтечелюстов -> адды фиксируются на игроках, быстро убивать."
L["- Durchnässt / Wasserflächen -> nicht in Flächen stehen."] = "- Промокание / водяные зоны -> не стоять в зонах."
L["- Heroisch: Eier schlüpfen -> Adds zusätzlich töten."] = "- Героик: вылупляются яйца -> дополнительно убивать аддов."
L["Taktik: Raid sammelt sich vor dem Boss für die Wut, Adds sofort abfangen und töten."] = "Тактика: рейд собирается перед боссом на Ярость, аддов сразу перехватывать и убивать."
L["HARJATAN: Ungezügelte Wut gemeinsam soaken!"] = "ХАРДЖАТАН: Необузданную ярость соакать вместе!"
L["Adds schnell töten. Tankwechsel nach Stapeln."] = "Аддов быстро убивать. Смена танков по стакам."
L["Jägerin Kasparian + Hauptmann Yathae Mondsturm + Priesterin Lunaspyre"] = "Охотница Каспариан + капитан Ятея Лунная Буря + жрица Луноспира"
L["- Nur eine Schwester kämpft pro Phase -> Wechsel bei Gesundheitsschwellen."] = "- В каждой фазе сражается только одна сестра -> смена на порогах здоровья."
L["- Mondgleve / Zwielichtgleve (Kasparian): Linien durch den Raid -> ausweichen bzw. nach Plan soaken."] = "- Лунная глефа / Сумеречная глефа (Каспариан): линии через рейд -> уворачиваться или соакать по плану."
L["- Astrales und Umbrales Licht: Raid in Licht- und Schattenseite -> Seite gezielt wechseln, um Stapel zu senken."] = "- Астральный и Теневой свет: рейд на стороне света и тени -> целенаправленно менять сторону, чтобы снизить стаки."
L["- Mondbrand / Mondfeuer (Lunaspyre): Debuffs -> bannen nach Plan."] = "- Лунный ожог / Лунный огонь (Луноспира): дебаффы -> диспелить по плану."
L["- Mondleuchtfeuer: Spieler mit Mondstrahl -> aus dem Raid laufen."] = "- Лунный маяк: игрок с лунным лучом -> выбежать из рейда."
L["Taktik: Raid auf Licht/Schatten verteilen, Tank holt die aktive Schwester. Debuffs auf Ansage bannen."] = "Тактика: рейд распределить на свет/тень, танк забирает активную сестру. Дебаффы диспелить по команде."
L["SCHWESTERN: Gleven ausweichen, Licht/Schatten-Stapel managen!"] = "СЕСТРЫ: уворачиваться от глеф, следить за стаками света/тени!"
L["Mondleuchtfeuer raus, Bannen auf Ansage."] = "С Лунным маяком наружу, диспел по команде."
L["Herrin Sassz'ine + Abyssale Adds"] = "Госпожа Сашж'ин + адды из бездны"
L["- Hydraschuss: Pfeile auf Spieler -> von zugewiesenen Spielern soaken lassen."] = "- Выстрел гидры: стрелы в игроков -> пусть соакают назначенные игроки."
L["- Bürde der Schmerzen: Tank-Debuff -> Tankwechsel."] = "- Бремя боли: дебафф на танке -> смена танков."
L["- Donnernder Schock (Aale): Linien -> ausweichen."] = "- Громовой шок (угри): линии -> уворачиваться."
L["- Phase 2/3 (Tinte, Schreckenshaie): -> Mechanik nach Ansage spielen, Haien ausweichen."] = "- Фаза 2/3 (чернила, жуткие акулы): -> механику играть по команде, уворачиваться от акул."
L["- Schneidender Tornado: -> ausweichen."] = "- Режущий смерч: -> уворачиваться."
L["Taktik: Soak-Gruppen für Hydraschuss festlegen, Tanks wechseln regelmäßig. In späteren Phasen gemeinsam ausweichen."] = "Тактика: соак-группы на Выстрел гидры определить заранее, танки регулярно меняются. В поздних фазах уворачиваться вместе."
L["SASSZ'INE: Hydraschüsse soaken nach Plan!"] = "САШЖ'ИН: Выстрелы гидры соакать по плану!"
L["Aale und Tornados ausweichen. Tankwechsel nach Bürde."] = "Уворачиваться от угрей и смерчей. Смена танков после Бремени."
L["Die trostlose Heerschar (Seelenkönigin Dejahna + Maschine der Seelen + Adds)"] = "Сонм страданий (королева душ Деяна + машина душ + адды)"
L["- Zwei Welten (Körperlich / Geisterwelt): Raid aufteilen -> jede Gruppe kümmert sich um ihre Adds."] = "- Два мира (телесный / мир духов): разделить рейд -> каждая группа занимается своими аддами."
L["- Seelenbindung: zwei Spieler verbunden -> zusammen bleiben oder Bindung nach Plan brechen."] = "- Связь душ: два игрока связаны -> держаться вместе или рвать связь по плану."
L["- Verdorrender Untergang / Untergang des Zerreißens: Soak-Zonen -> mit Spielern aus der richtigen Welt soaken."] = "- Иссушающая погибель / Разрывающая погибель: соак-зоны -> соакать игроками из правильного мира."
L["- Gequälte Schreie: Raidschaden -> Cooldowns."] = "- Мучительные крики: урон по рейду -> кулдауны."
L["- Adds (Tempelritter, Knochenwächter, Gefallene Priesterin) -> schnell töten, Zauber unterbrechen."] = "- Адды (храмовники, костяные стражи, падшая жрица) -> быстро убивать, кикать касты."
L["Taktik: Teams für beide Welten einteilen, Adds priorisieren, Soaks sauber teilen. Phase 2 mit Raid-Cooldowns."] = "Тактика: назначить команды на оба мира, аддов в приоритете, соаки делить чисто. Фаза 2 под рейдовыми кулдаунами."
L["HEERSCHAR: Welten nach Plan, Soaks richtig teilen!"] = "СОНМ: миры по плану, соаки делить правильно!"
L["Adds töten, Seelenbindung nach Plan."] = "Аддов убивать, Связь душ по плану."
L["Wachsame Maid"] = "Бдительная дева"
L["- Licht- und Teufelsinfusion: Raid in zwei Farben -> Spieler gleicher Farbe zusammen, Farbe nicht falsch mischen."] = "- Вливание Света и Скверны: рейд в двух цветах -> игроки одного цвета вместе, цвета не путать."
L["- Hammer der Schöpfung / Auslöschung: Tank-Treffer -> Tankwechsel, Farbe beachten."] = "- Молот созидания / уничтожения: удары по танку -> смена танков, следить за цветом."
L["- Fragmente: Kugeln in Licht/Teufel -> mit eigener Farbe fangen."] = "- Фрагменты: сферы Света/Скверны -> ловить своим цветом."
L["- Instabile Seele: Debuff -> in das Loch in der Mitte springen."] = "- Нестабильная душа: дебафф -> прыгать в дыру в центре."
L["- Zorn der Schöpfer: Schild auf der Maid -> mit Titanessenz brechen, Raidschaden."] = "- Гнев Творцов: щит на деве -> ломать сущностью титанов, урон по рейду."
L["Taktik: Raid in Licht- und Teufelshälfte, Kugeln mit passender Farbe fangen. Instabile Seele rechtzeitig ins Loch."] = "Тактика: рейд на половины Света и Скверны, сферы ловить подходящим цветом. С Нестабильной душой вовремя в дыру."
L["MAID: Licht und Teufel getrennt, Kugeln richtig fangen!"] = "ДЕВА: Свет и Скверна раздельно, сферы ловить правильно!"
L["Instabile Seele ins Loch. Tankwechsel nach Hammer."] = "С Нестабильной душой в дыру. Смена танков после Молота."
L["Gefallener Avatar + Wachsame Maid"] = "Падший аватар + Бдительная дева"
L["- Schwere Tank-Treffer: -> Tankwechsel nach Ansage."] = "- Тяжелые удары по танку: -> смена танков по команде."
L["- Berührung des Sargeras: Soak-Zonen -> mit Spielern soaken."] = "- Прикосновение Саргераса: соак-зоны -> соакать игроками."
L["- Realitäten zerreißen: Flächenschaden -> rauslaufen."] = "- Разрыв реальности: АоЕ-урон -> выбегать."
L["- Verdorbene Matrix: Strahl -> in den Strahl stellen, damit die Maid nicht getroffen wird."] = "- Оскверненная матрица: луч -> встать в луч, чтобы он не попал в деву."
L["- Phase 2: Boden zerbricht, Dunkle Male -> verteilt stehen, Cooldowns."] = "- Фаза 2: пол разрушается, Темные метки -> стоять рассредоточенно, кулдауны."
L["Taktik: Matrix-Soaker einteilen, Raid hinter dem Boss. Phase 2 mit Raid-Cooldowns."] = "Тактика: назначить соакеров матрицы, рейд за боссом. Фаза 2 под рейдовыми кулдаунами."
L["AVATAR: Matrix-Strahl soaken, Berührung soaken!"] = "АВАТАР: соакать луч матрицы, соакать Прикосновение!"
L["Phase 2: verteilt. Tankwechsel nach Ansage."] = "Фаза 2: рассредоточиться. Смена танков по команде."
L["- Teufelsklauen: Tank-Kombo -> Tankwechsel."] = "- Когти Скверны: комбо по танку -> смена танков."
L["- Zerreißende Singularität: Rückstoß -> Position so wählen, dass niemand von der Plattform fliegt."] = "- Разрывающая сингулярность: отбрасывание -> выбирать позицию так, чтобы никто не слетел с платформы."
L["- Armageddon: Meteore -> soaken."] = "- Армагеддон: метеоры -> соакать."
L["- Schattenspiegelung: Spieler erzeugen Adds -> Adds töten."] = "- Теневое отражение: игроки создают аддов -> убивать аддов."
L["- Zwischenphase: Dunkelheit - Illidans Licht folgen."] = "- Промежуточная фаза: тьма - следовать за светом Иллидана."
L["Taktik: Raid verteilt, Positionen gegen Rückstoß absichern. Zwischenphasen mit Illidan, Phase 3 Raid-Cooldowns."] = "Тактика: рейд рассредоточен, позиции страховать от отбрасывания. Промежуточные фазы с Иллиданом, фаза 3 под рейдовыми кулдаунами."
L["KIL'JAEDEN: Singularität beachten, nicht runterfallen!"] = "КИЛ'ДЖЕДЕН: следить за Сингулярностью, не падать!"
L["Armageddon soaken, Schatten-Adds töten. Tankwechsel."] = "Соакать Армагеддон, убивать теневых аддов. Смена танков."
L["Prüfung der Tapferkeit"] = "Испытание доблести"
L["Odyn + Hymdall + Hyrja"] = "Один + Химдалль + Хирья"
L["- Phase 1: Hymdall und Hyrja -> beide gleichmäßig senken."] = "- Фаза 1: Химдалль и Хирья -> обоих снижать равномерно."
L["- Hyrja - Schild des Lichts: Strahl auf Spieler -> mit mehreren Spielern soaken."] = "- Хирья - Щит Света: луч на игрока -> соакать несколькими игроками."
L["- Hymdall - Tanzende Klinge: Wirbel -> ausweichen."] = "- Химдалль - Танцующий клинок: вихрь -> уворачиваться."
L["- Phase 2/3: Runenbrandmal -> Spieler mit Rune auf die passende Plattform."] = "- Фаза 2/3: Рунное клеймо -> игроки с руной на соответствующую платформу."
L["- Speer des Lichts / Gleißende Hiebe: -> ausweichen."] = "- Копье Света / Сияющие удары: -> уворачиваться."
L["Taktik: Phase 1 beide Adds gleichzeitig senken. Runen-Spieler zügig auf ihre Plattform, Tanks wechseln."] = "Тактика: в фазе 1 обоих аддов снижать одновременно. Игроки с рунами быстро на свою платформу, танки меняются."
L["ODYN: Runen-Spieler auf passende Plattform!"] = "ОДИН: игроки с рунами на соответствующую платформу!"
L["Phase 1: Hymdall und Hyrja gleichmäßig senken."] = "Фаза 1: Химдалля и Хирью снижать равномерно."
L["Guarm"] = "Гарм"
L["- Atem (Feuer, Frost, Schatten): Kegel vor dem Boss -> mit passend markierten Spielern soaken."] = "- Дыхание (огонь, лед, тьма): конус перед боссом -> соакать игроками с подходящей меткой."
L["- Flüchtiger Schaum: Debuffs in drei Farben -> mit dem passenden Atem entfernen."] = "- Летучая пена: дебаффы трех цветов -> снимать подходящим дыханием."
L["- Lecken (Flamme, Frost, Schatten): Tank-Debuffs -> Tankwechsel."] = "- Облизывание (огнем, льдом, тьмой): дебаффы на танке -> смена танков."
L["- Kopfloser Ansturm / Brüllender Sprung: Raid verteilt sich danach -> Positionen halten."] = "- Безоглядный рывок / Ревущий прыжок: рейд после этого рассредоточивается -> держать позиции."
L["Taktik: Raid vor dem Boss für Atem-Soaks, Schaum-Farben genau zuweisen."] = "Тактика: рейд перед боссом для соака дыханий, цвета пены распределять точно."
L["GUARM: Atem soaken, Schaum mit richtiger Farbe entfernen!"] = "ГАРМ: соакать дыхание, пену снимать правильным цветом!"
L["Tankwechsel nach Lecken."] = "Смена танков после Облизывания."
L["Helya + Tentakel + Adds"] = "Хелия + щупальца + адды"
L["- Kugel der Verderbnis: markierte Spieler -> an den Rand laufen."] = "- Сфера порчи: отмеченные игроки -> бежать к краю."
L["- Makel des Meeres: Debuff -> am Rand bannen."] = "- Порча моря: дебафф -> диспелить у края."
L["- Gallwasseratem: Tank-Kegel, Schleim-Adds -> Adds schnell töten."] = "- Дыхание горькой воды: конус по танку, слизневые адды -> аддов быстро убивать."
L["- Tentakelschlag: Soak-Zone -> soaken."] = "- Удар щупальца: соак-зона -> соакать."
L["- Phase 2 (65 %): Adds (Matrosen, Schleimfürsten) -> töten/unterbrechen."] = "- Фаза 2 (65 %): адды (матросы, повелители слизи) -> убивать/кикать."
L["Taktik: Kugeln und Debuffs am Rand ablegen, Tentakelschläge soaken. Phase 2 Adds priorisieren."] = "Тактика: сферы и дебаффы сбрасывать у края, удары щупалец соакать. В фазе 2 аддов в приоритете."
L["HELYA: Kugeln an den Rand, Tentakel soaken!"] = "ХЕЛИЯ: сферы к краю, щупальца соакать!"
L["Phase 2: Adds schnell töten."] = "Фаза 2: аддов быстро убивать."
L["Aktueller Raid"] = "Текущий рейд"
L["Boss-Infos"] = "Инфо о боссе"
L["Erweiterung wählen."] = "Выберите дополнение."
L["Für diesen Boss gibt es noch keine Taktik."] = "Для этого босса пока нет тактики."
L["Für diesen Raid sind keine Bosse hinterlegt. Bosse werden beim ersten Kill automatisch erkannt."] = "Для этого рейда не добавлены боссы. Боссы определяются автоматически при первом убийстве."
L["Raid wählen. Im Raid wird er automatisch vorausgewählt."] = "Выберите рейд. В рейде он выбирается автоматически."
L["Springt zum Raid, in dem du gerade bist."] = "Переход к рейду, в котором вы сейчас находитесь."
L["Vorlage beim Bosskampf automatisch wählen"] = "Автоматически выбирать шаблон в бою с боссом"
L["Classic"] = "Classic"
L["The Burning Crusade"] = "The Burning Crusade"
L["Wrath of the Lich King"] = "Wrath of the Lich King"
L["Cataclysm"] = "Cataclysm"
L["Mists of Pandaria"] = "Mists of Pandaria"
L["Warlords of Draenor"] = "Warlords of Draenor"
L["Legion"] = "Legion"
L["Battle for Azeroth"] = "Battle for Azeroth"
L["Shadowlands"] = "Shadowlands"
L["Dragonflight"] = "Dragonflight"
L["The War Within"] = "The War Within"
L["Midnight"] = "Midnight"
L["Schlacht um Dazar'alor"] = "Битва за Дазар'алор"
L["Champion des Lichts + Adds (Allianz: Frida Eisenbalg / Horde: Ra'wani Kanae)"] = "Воитель Света + адды (Альянс: Фрида Железные Мехи / Орда: Ра'вани Канаэ)"
L["- Adds (Priester/Paladine): heilen und stärken den Boss -> unterbrechen, Adds schnell töten."] = "- Адды (жрецы/паладины): лечат и усиливают босса -> прерывать, аддов быстро убивать."
L["- Weihe-Flächen: Boss und Adds stehen darin verstärkt -> Boss und Adds aus den Flächen ziehen."] = "- Зоны Освящения: босс и адды в них усилены -> выводить босса и аддов из зон."
L["- Blendender Glaube: grelles Licht vom Boss -> rechtzeitig vom Boss wegdrehen."] = "- Ослепляющая вера: яркий свет от босса -> вовремя отвернуться от босса."
L["- Tankfähigkeit mit Stapel-Debuff -> Tankwechsel bei hohen Stapeln."] = "- Танковая способность со стакающимся дебаффом -> смена танков на высоких стаках."
L["Taktik: Boss und Adds gemeinsam aus den Weihe-Flächen tanken, Kickrotation auf die Adds, Adds mit Priorität töten."] = "Тактика: Босса и аддов вместе выводить из зон Освящения, ротация киков на аддов, аддов убивать в приоритете."
L["CHAMPION: Adds kicken und zuerst töten! Boss aus Weihe ziehen!"] = "ВОИТЕЛЬ: Кикать аддов и убивать первыми! Выводить босса из Освящения!"
L["Bei Blendendem Glauben wegdrehen. Tankwechsel bei Stapeln."] = "На Ослепляющей вере отвернуться. Смена танков на стаках."
L["Champion des Lichts"] = "Воитель Света"
L["Totenkopf, Kreuz und Viereck auf die Adds, Kickgruppen je Symbol."] = "Череп, крест и квадрат на аддов, группы киков на каждую метку."
L["Jadefeuermeister (zwei Mönche: Allianz-/Horde-Version je nach Fraktion)"] = "Мастера Нефритового Огня (два монаха: версия Альянса/Орды в зависимости от фракции)"
L["- Vielseitiger Schlag: kegelförmiger Mehrfachangriff -> mehrere Spieler stellen sich zum Aufteilen vor den Boss."] = "- Многосторонний удар: конусная атака по нескольким целям -> несколько игроков встают перед боссом, чтобы разделить урон."
L["- Feuer-Debuffs auf Spielern hinterlassen Flammen -> an den Rand laufen, Flammen nicht im Raid ablegen."] = "- Огненные дебаффы на игроках оставляют пламя -> бежать к краю, не оставлять пламя в рейде."
L["- Magmafallen/Feuerflächen am Boden -> nicht hineinlaufen."] = "- Магмовые ловушки/огненные зоны на полу -> не заходить."
L["- Aufsteigende Flammen: stapelnder Feuerschaden auf Tanks -> Tankwechsel."] = "- Восходящее пламя: стакающийся огненный урон по танкам -> смена танков."
L["- Chi-Welle und Energiefähigkeiten der Mönche -> Heiler-Cooldowns einteilen."] = "- Волна ци и энергетические способности монахов -> распределить кулдауны хилов."
L["Taktik: Beide Mönche getrennt tanken und gleichmäßig herunterschlagen, Soak-Gruppe für den Mehrfachangriff fest einteilen, Feuer an den Rand legen."] = "Тактика: Обоих монахов танковать раздельно и сбивать равномерно, жестко назначить группу соака для многосторонней атаки, огонь выносить к краю."
L["JADEFEUERMEISTER: Soaker vor den Boss! Feuer an den Rand legen!"] = "МАСТЕРА НЕФРИТОВОГО ОГНЯ: Соакеры перед боссом! Огонь к краю!"
L["Nicht in Magmafallen laufen. Tankwechsel bei Aufsteigenden Flammen."] = "Не заходить в магмовые ловушки. Смена танков на Восходящем пламени."
L["Grong (Allianz: Grong der Wiedergänger / Horde: Grong der Dschungelherr)"] = "Гронг (Альянс: Гронг Возрожденный / Орда: Гронг Повелитель Джунглей)"
L["- Combo-Angriff auf den Tank: mehrere schwere Schläge mit Stapel-Debuff -> Tankwechsel nach jeder Combo."] = "- Комбо-атака по танку: несколько тяжелых ударов со стакающимся дебаффом -> смена танков после каждого комбо."
L["- Energie-Fähigkeit (bei 100 Energie): Flächenschlag/Gebrüll auf den Raid -> Heiler-Cooldowns vorbereiten."] = "- Способность за энергию (на 100 энергии): АоЕ-удар/рев по рейду -> подготовить кулдауны хилов."
L["- Geschleuderte Fässer/Kugeln: müssen von Spielern abgefangen bzw. getroffen werden -> eingeteilte Spieler fangen sie ab."] = "- Брошенные бочки/шары: игроки должны их перехватывать или попадать по ним -> назначенные игроки перехватывают."
L["- Frontaler Angriff des Bosses -> nie vor dem Boss stehen (außer Tank)."] = "- Фронтальная атака босса -> никогда не стоять перед боссом (кроме танка)."
L["- Bodeneffekte nach Einschlägen -> sofort verlassen."] = "- Эффекты на полу после ударов -> сразу выходить."
L["Taktik: Boss in der Mitte tanken, Raid seitlich/hinten, Tankwechsel nach jeder Combo; Energie-Phasen mit Raid-Cooldowns abfangen."] = "Тактика: Босса танковать в центре, рейд сбоку/сзади, смена танков после каждого комбо; фазы энергии перекрывать рейдовыми кулдаунами."
L["GRONG: Tankwechsel nach jeder Combo! Nicht vor dem Boss stehen!"] = "ГРОНГ: Смена танков после каждого комбо! Не стоять перед боссом!"
L["Geworfene Objekte abfangen. Heiler-CDs bei 100 Energie."] = "Перехватывать брошенные объекты. Кулдауны хилов на 100 энергии."
L["Opulenz (Phase 1: zwei Schatzwächter, Phase 2: Opulenz)"] = "Богатство (фаза 1: два стража сокровищ, фаза 2: Богатство)"
L["- Phase 1: Zwei Wächter in getrennten Räumen mit Fallen -> Raid teilt sich auf, beide Wächter möglichst gleichzeitig töten."] = "- Фаза 1: два стража в разных залах с ловушками -> рейд делится, обоих стражей убить по возможности одновременно."
L["- Juwelen (Rubin, Topas, Opal, Smaragd, Amethyst, Diamant): geben Trägern starke Effekte -> fest zugewiesene Spieler nehmen und weitergeben."] = "- Самоцветы (рубин, топаз, опал, изумруд, аметист, алмаз): дают носителям сильные эффекты -> закрепленные игроки берут и передают."
L["- Münzregen: muss von Spielern abgefangen werden -> eingeteilte Soaker stellen sich darunter."] = "- Дождь монет: игроки должны его перехватывать -> назначенные соакеры встают под него."
L["- Flüssiges Gold / Goldflächen am Boden -> nicht hineinlaufen, Debuff-Träger an den Rand."] = "- Жидкое золото / золотые зоны на полу -> не заходить, носителей дебаффа к краю."
L["- Tankfähigkeiten mit Stapel-Debuff -> Tankwechsel."] = "- Танковые способности со стакающимся дебаффом -> смена танков."
L["Taktik: Phase 1 im Split mit gleichmäßigem Schaden, Phase 2 Juwelen fest einteilen und Soaks koordinieren, Raid-Cooldowns für die Schadensspitzen."] = "Тактика: Фаза 1 в сплите с равномерным уроном, фаза 2 жестко распределить самоцветы и координировать соаки, рейдовые кулдауны на пики урона."
L["OPULENZ: Juwelen nur durch Eingeteilte! Münzregen soaken!"] = "БОГАТСТВО: Самоцветы берут только назначенные! Соакать дождь монет!"
L["Nicht im Gold stehen. Tankwechsel bei Stapeln."] = "Не стоять в золоте. Смена танков на стаках."
L["Konklave der Auserwählten (Loa-Avatare: Pa'ku, Gonk, Kimbul, Akunda)"] = "Конклав Избранных (аватары лоа: Па'ку, Гонк, Кимбул, Акунда)"
L["- Pa'kus Zorn: Pa'ku fliegt ein -> alle laufen zu Pa'ku, sonst massiver Raidschaden."] = "- Гнев Па'ку: Па'ку прилетает -> все бегут к Па'ку, иначе огромный урон по рейду."
L["- Gonks Raptoren: Adds tauchen auf -> schnell töten (Fernkampf), nicht auf Heiler laufen lassen."] = "- Ящеры Гонка: появляются адды -> быстро убивать (РДД), не подпускать к хилам."
L["- Kimbuls Zorn / Blutungen: springt auf Spieler -> Debuff-Träger heilen, Abstand halten."] = "- Гнев Кимбула / кровотечения: прыгает на игроков -> хилить носителей дебаффа, держать дистанцию."
L["- Akundas Zorn: Blitz-Debuff -> verteilen, Debuff-Träger aus dem Raid laufen."] = "- Гнев Акунды: дебафф молнии -> рассредоточиться, носители дебаффа выбегают из рейда."
L["- Avatar des Loa: bei Erscheinen verstärkt er sich -> Avatare abwechselnd und gezielt töten."] = "- Аватар лоа: при появлении усиливается -> аватаров убивать поочередно и прицельно."
L["Taktik: Loa-Avatare nacheinander fokussieren (übliche Reihenfolge nach Gruppe absprechen), Raptoren sofort töten, bei Pa'ku sammeln."] = "Тактика: Фокусить аватаров лоа по очереди (обычный порядок обсудить с группой), ящеров убивать сразу, собираться у Па'ку."
L["KONKLAVE: Bei Pa'ku sofort hinlaufen! Raptoren sofort töten!"] = "КОНКЛАВ: На Па'ку сразу бежать к нему! Ящеров убивать сразу!"
L["Akunda-Debuff aus dem Raid tragen. Fokusziel beachten."] = "Дебафф Акунды выносить из рейда. Следить за фокус-целью."
L["Totenkopf auf den aktuellen Fokus-Avatar, Kreuz auf den nächsten, Viereck/Mond auf Raptoren."] = "Череп на текущего фокус-аватара, крест на следующего, квадрат/луна на ящеров."
L["König Rastakhan + Belagerungsbrecher Roka'mon / Prälat Za'lan, später Bwonsamdi"] = "Король Растахан + Рушитель стен Рока'мон / Прелат За'лан, позже Бвонсамди"
L["- Krötenplage: Kröten laufen über den Boden -> ausweichen, Berührung explodiert."] = "- Жабья напасть: жабы бегут по полу -> уклоняться, при касании взрываются."
L["- Sengende Detonation: Debuff explodiert nach kurzer Zeit -> Träger läuft aus dem Raid."] = "- Обжигающая детонация: дебафф взрывается через короткое время -> носитель выбегает из рейда."
L["- Meteorsprung (Roka'mon): Landeflächen müssen von mehreren Spielern geteilt werden -> soaken."] = "- Прыжок метеора (Рока'мон): места приземления должны делить несколько игроков -> соакать."
L["- Todesreich: Teil des Raids wird ins Reich des Todes geschickt -> dort Phantome töten und zurück."] = "- Царство смерти: часть рейда отправляется в царство смерти -> там убить фантомов и вернуться."
L["- Phase 3: Bwonsamdi greift ein, Todesbereich und schwere Raidschläge -> Raid-Cooldowns, Abstände halten."] = "- Фаза 3: вмешивается Бвонсамди, зона смерти и тяжелые удары по рейду -> рейдовые кулдауны, держать дистанцию."
L["Taktik: Phase 1 erst die Helfer töten, danach Rastakhan; Todesreich-Gruppe fest einteilen; Phase 3 Bwonsamdi aus dem Raid halten und Boss burnen."] = "Тактика: Фаза 1 сначала убить помощников, затем Растахана; жестко назначить группу в царство смерти; фаза 3 держать Бвонсамди вне рейда и сжигать босса."
L["RASTAKHAN: Kröten ausweichen! Meteorsprung soaken!"] = "РАСТАХАН: Уклоняться от жаб! Соакать прыжок метеора!"
L["Detonation aus dem Raid tragen. Todesreich-Gruppe bereit."] = "Детонацию выносить из рейда. Группа в царство смерти, готовность."
L["Rastakhan"] = "Растахан"
L["Totenkopf auf Roka'mon bzw. Za'lan, Kreuz auf das nächste Add."] = "Череп на Рока'мона или За'лана, крест на следующего адда."
L["Hochtüftler Mekkadrill + Funkenbots"] = "Верховный механик Меггакрут + искроботы"
L["- Gigavoltladung: Bombe auf Spielern -> an den Rand laufen, nicht im Raid explodieren."] = "- Гигавольтный заряд: бомба на игроках -> бежать к краю, не взрываться в рейде."
L["- Durchbrecherkanone: frontaler Strahl -> nicht vor dem Boss stehen."] = "- Пушка-пробойник: фронтальный луч -> не стоять перед боссом."
L["- Schrumpfstrahl: geschrumpfte Spieler steigen in Gnomroboter und deaktivieren sie mit dem richtigen Code."] = "- Уменьшающий луч: уменьшенные игроки залезают в гномских роботов и отключают их правильным кодом."
L["- Funkenbots: laufen durch den Raum -> betäuben/töten, nicht berühren."] = "- Искроботы: бегают по залу -> оглушать/убивать, не касаться."
L["- Explosive Schafe / Wurmloch-Generator: schwere Flächen -> ausweichen und Kontrolle zurückgewinnen."] = "- Взрывные овцы / генератор червоточин: опасные зоны -> уклоняться и вернуть контроль."
L["Taktik: Boss mittig tanken, Bombenträger fest an Randpositionen, Schrumpfspieler lösen die Roboter, Funkenbots kontrollieren."] = "Тактика: Босса танковать в центре, носители бомб на закрепленных позициях у края, уменьшенные игроки отключают роботов, искроботов контролировать."
L["MEKKADRILL: Bomben an den Rand! Nicht vor die Kanone!"] = "МЕГГАКРУТ: Бомбы к краю! Не стоять перед пушкой!"
L["Geschrumpfte: Roboter deaktivieren. Funkenbots stoppen."] = "Уменьшенные: отключить роботов. Остановить искроботов."
L["Sturmwallblockade (Schwester Katherine, Bruder Joseph, später Laminaria)"] = "Блокада Штормовой Стены (Сестра Катерина, Брат Джозеф, позже Ламинария)"
L["- Zwei Geschwister auf getrennten Schiffen -> Raid teilt sich auf beide Boote auf."] = "- Брат и сестра на разных кораблях -> рейд делится на обе лодки."
L["- Meeressturm / Wirbel auf dem Wasser -> Bewegung beachten, nicht ins Wasser gespült werden."] = "- Морской шторм / водовороты на воде -> следить за движением, не дать смыть себя в воду."
L["- Spannungsblitz / Knisternde Blitze: Debuff springt über -> verteilt stehen."] = "- Разряд напряжения / потрескивающие молнии: дебафф перескакивает -> стоять рассредоточенно."
L["- Gezeitenhülle: Schild auf einem Boss -> wegschlagen oder unterbrechen."] = "- Покров приливов: щит на одном из боссов -> сбить или прервать."
L["- Phase 2 Laminaria: Seetang-Stapel und Fluten -> Raid zusammen, Heiler-Cooldowns, Tankwechsel."] = "- Фаза 2 Ламинария: стаки водорослей и потопы -> рейд вместе, кулдауны хилов, смена танков."
L["Taktik: Geschwister gleichmäßig herunterschlagen, damit sie nah beieinander sterben; danach Laminaria im zweiten Teil mit Raid-Cooldowns legen."] = "Тактика: Брата и сестру сбивать равномерно, чтобы они умерли почти одновременно; затем во второй части убить Ламинарию с рейдовыми кулдаунами."
L["STURMWALL: Raid auf beide Schiffe aufteilen! Verteilt stehen!"] = "ШТОРМОВАЯ СТЕНА: Рейд делится на оба корабля! Стоять рассредоточенно!"
L["Schilde sofort wegmachen. P2: Heiler-CDs auf Laminaria."] = "Щиты снимать сразу. Ф2: кулдауны хилов на Ламинарию."
L["Lady Jaina Prachtmeer + Kul Tiras-Marine"] = "Леди Джайна Праудмур + флот Кул-Тираса"
L["- Eiseskälte/Unterkühlung: stapelnde Kälte -> an Feuerflächen bzw. Wärmequellen aufwärmen."] = "- Ледяной холод/переохлаждение: стакающийся холод -> греться у огненных зон или источников тепла."
L["- Lawine: schwerer Tankangriff -> Tankwechsel."] = "- Лавина: тяжелая атака по танку -> смена танков."
L["- Eisring / Frostflächen: Spieler werden eingefroren -> rechtzeitig herauslaufen."] = "- Ледяное кольцо / ледяные зоны: игроков замораживает -> вовремя выбегать."
L["- Zwischenphasen: Jaina im Eisblock -> Kanonen/Feuer nutzen, Block brechen, Adds töten."] = "- Промежуточные фазы: Джайна в ледяной глыбе -> использовать пушки/огонь, разбить глыбу, убить аддов."
L["- Phase 3: Breitseite und Eiswände -> Positionen absprechen, Wasserblitz-Salven unterbrechen."] = "- Фаза 3: бортовой залп и ледяные стены -> обговорить позиции, прерывать залпы Ледяной стрелы."
L["Taktik: Kälte-Stapel konsequent abbauen, Adds schnell töten, Zwischenphasen sauber spielen; Phase 3 mit allen Raid-Cooldowns."] = "Тактика: Стаки холода последовательно сбрасывать, аддов быстро убивать, промежуточные фазы играть чисто; фаза 3 со всеми рейдовыми кулдаунами."
L["JAINA: Kälte-Stapel aufwärmen! Eisring sofort verlassen!"] = "ДЖАЙНА: Стаки холода — греться! Из ледяного кольца сразу выходить!"
L["Adds töten, Salven kicken. Tankwechsel bei Lawine."] = "Убивать аддов, кикать залпы. Смена танков на Лавине."
L["Jaina"] = "Джайна"
L["Totenkopf und Kreuz auf die Adds mit Zaubern (Kickziele)."] = "Череп и крест на аддов-кастеров (цели для киков)."
L["Tiegel der Stürme"] = "Горнило Штормов"
L["Die Rastlose Kabale (Zaxasj der Sprecher, Fa'thuul der Gefürchtete)"] = "Неугомонный совет (Закзаш Глашатай, Фа'тул Ужасный)"
L["- Reliquien (Sturmrufer / Leerenstein): Spieler tragen sie und erhalten Fähigkeiten -> fest einteilen, rechtzeitig weitergeben."] = "- Реликвии (Призыватель бури / Камень Бездны): игроки носят их и получают способности -> жестко назначить, вовремя передавать."
L["- Verdunkelung/Wahnsinn: Spieler verlieren Kontrolle -> Ziele überwachen, kontrollierte Spieler nicht angreifen."] = "- Затмение/безумие: игроки теряют контроль -> следить за целями, не атаковать контролируемых игроков."
L["- Abyssalkollaps: großer Einschlag -> mit mehreren Spielern teilen."] = "- Коллапс Бездны: мощный удар -> делить с несколькими игроками."
L["- Gesicht aus dem Jenseits: Add -> schnell töten."] = "- Лик из-за грани: адд -> быстро убивать."
L["Taktik: Beide Bosse getrennt tanken, Reliquienträger einteilen, Soaks und Adds koordinieren."] = "Тактика: Обоих боссов танковать раздельно, назначить носителей реликвий, координировать соаки и аддов."
L["KABALE: Reliquien nur durch Eingeteilte! Einschläge soaken!"] = "СОВЕТ: Реликвии только назначенным! Соакать удары!"
L["Adds schnell töten. Tankwechsel bei Stapeln."] = "Аддов быстро убивать. Смена танков на стаках."
L["Kabale"] = "Совет"
L["Totenkopf und Kreuz auf die beschworenen Adds."] = "Череп и крест на призванных аддов."
L["Uu'nat, Vorbote der Leere + Urtümliche Gedankenbeuger"] = "Уу'нат, Предвестник Бездны + первобытные сокрушители разума"
L["- Drei Reliquien (Sturmrufer, Ozeanrune, Leerenstein): Träger nutzen sie gegen Mechaniken -> fest einteilen."] = "- Три реликвии (Призыватель бури, Руна океана, Камень Бездны): носители используют их против механик -> жестко назначить."
L["- Berührung des Endes: schwerer Tank-Debuff -> Tankwechsel."] = "- Касание конца: тяжелый дебафф на танке -> смена танков."
L["- Unergründlicher Schrecken: Furchteffekt -> rechtzeitig vom Boss wegdrehen."] = "- Непостижимый ужас: эффект страха -> вовремя отвернуться от босса."
L["- Gedankenbeuger-Adds: zaubern -> unterbrechen und töten."] = "- Адды-сокрушители разума: кастуют -> прерывать и убивать."
L["- Leerenrisse/Flächen -> nicht hineinlaufen."] = "- Разломы Бездны/зоны -> не заходить."
L["Taktik: Reliquien rotieren lassen, Adds kicken und töten, bei Schrecken wegdrehen; Phase 3 mit Raid-Cooldowns."] = "Тактика: Реликвии ротировать, аддов кикать и убивать, на ужасе отворачиваться; фаза 3 с рейдовыми кулдаунами."
L["UU'NAT: Reliquien-Träger bereit! Bei Schrecken wegdrehen!"] = "УУ'НАТ: Носители реликвий, готовность! На ужасе отвернуться!"
L["Gedankenbeuger kicken und töten. Tankwechsel."] = "Сокрушителей разума кикать и убивать. Смена танков."
L["Uu'nat"] = "Уу'нат"
L["Je ein Symbol auf die Gedankenbeuger, Kickgruppen pro Symbol."] = "По одной метке на каждого сокрушителя разума, группы киков на каждую метку."
L["Der Ewige Palast"] = "Вечный дворец"
L["Abyssische Kommandantin Sivara"] = "Командир глубин Сивара"
L["- Chimärische Male (Frost und Gift): Spieler erhalten eins von zwei Malen -> nach Mal-Farbe gruppiert stehen."] = "- Химерные метки (лед и яд): игроки получают одну из двух меток -> стоять группами по цвету метки."
L["- Umkehrung: Male tauschen -> Gruppen neu sortieren."] = "- Инверсия: метки меняются -> перестроить группы."
L["- Frost-/Giftpfeile und Linien am Boden -> ausweichen."] = "- Ледяные/ядовитые стрелы и линии на полу -> уклоняться."
L["- Tankangriffe mit Frost-/Gift-Stapeln -> Tankwechsel."] = "- Атаки по танку со стаками льда/яда -> смена танков."
L["- Sturzflut/Überschwemmung -> Heiler-Cooldowns."] = "- Ливень/наводнение -> кулдауны хилов."
L["Taktik: Zwei feste Lager für Frost und Gift, beim Umkehren sauber wechseln; Tankwechsel nach Stapeln."] = "Тактика: Два постоянных лагеря для льда и яда, при инверсии чисто меняться; смена танков после стаков."
L["SIVARA: Nach Mal-Farbe aufstellen! Bei Umkehrung wechseln!"] = "СИВАРА: Строиться по цвету метки! При инверсии меняться!"
L["Linien ausweichen. Tankwechsel bei Stapeln."] = "Уклоняться от линий. Смена танков на стаках."
L["Schwarzwasserbehemoth (Unterwasserkampf)"] = "Чудище Черноводья (бой под водой)"
L["- Biolumineszenz: leuchtende Wolken einsammeln -> schützt vor Dunkelheit, Stapel halten."] = "- Биолюминесценция: собирать светящиеся облака -> защищают от тьмы, держать стаки."
L["- Fressrausch: stapelnder Tank-Debuff -> Tankwechsel."] = "- Пищевое бешенство: стакающийся дебафф на танке -> смена танков."
L["- Fischschwärme / Kavitation: große Flächen -> rechtzeitig ausweichen."] = "- Косяки рыб / кавитация: большие зоны -> вовремя уклоняться."
L["- Abstieg in tiefere Ebenen: Kampf wandert nach unten -> zusammenbleiben."] = "- Спуск на нижние уровни: бой смещается вниз -> держаться вместе."
L["Taktik: Raid nah beim Boss, Biolumineszenz aktiv sammeln, Tankwechsel nach Stapeln, beim Abtauchen gemeinsam folgen."] = "Тактика: Рейд близко к боссу, активно собирать биолюминесценцию, смена танков после стаков, при погружении следовать вместе."
L["BEHEMOTH: Leuchtwolken sammeln! Schwärmen ausweichen!"] = "ЧУДИЩЕ: Собирать светящиеся облака! Уклоняться от косяков!"
L["Tankwechsel bei Fressrausch. Gemeinsam abtauchen."] = "Смена танков на Пищевом бешенстве. Погружаться вместе."
L["Glanz von Azshara + Uralte Stürme"] = "Сияние Азшары + древние бури"
L["- Arkanados / Sturmwirbel: wandernde Tornados -> ausweichen."] = "- Чародейский ураган / вихрь бури: блуждающие торнадо -> уклоняться."
L["- Gezeitenfaust: schwerer Tankschlag -> Tankwechsel."] = "- Кулак прилива: тяжелый удар по танку -> смена танков."
L["- Arkane Bomben: Debuff-Träger -> an den Rand und auseinander."] = "- Чародейские бомбы: носители дебаффа -> к краю и врозь."
L["- Zwischenphase: Raid läuft die Rampen hoch, Uralte Stürme -> gemeinsam laufen, Schäden heilen."] = "- Промежуточная фаза: рейд бежит вверх по рампам, древние бури -> бежать вместе, отхиливать урон."
L["Taktik: Boss mittig, Bomben nach außen, Tornados beachten; Zwischenphase zügig zusammen hochlaufen."] = "Тактика: Босс в центре, бомбы наружу, следить за торнадо; в промежуточной фазе быстро бежать наверх вместе."
L["GLANZ: Tornados ausweichen! Bomben nach außen!"] = "СИЯНИЕ: Уклоняться от торнадо! Бомбы наружу!"
L["Tankwechsel nach Gezeitenfaust. Zwischenphase gemeinsam laufen."] = "Смена танков после Кулака прилива. Промежуточная фаза — бежать вместе."
L["Lady Ashvane"] = "Леди Эшвейн"
L["- Schild auf Lady Ashvane: macht sie nahezu unverwundbar -> nach Raidplan über die Kampfmechanik brechen."] = "- Щит на леди Эшвейн: делает ее почти неуязвимой -> снимать по рейдовому плану через механику боя."
L["- Muschelhieb: schwerer Tankangriff -> Tankwechsel."] = "- Удар раковиной: тяжелая атака по танку -> смена танков."
L["- Bogen-Azerit: verbundene Spieler -> nach Anweisung positionieren, damit Linien keine anderen treffen."] = "- Дуговой азерит: связанные игроки -> вставать по указанию, чтобы линии не задевали других."
L["- Salzblasen: Spieler eingeschlossen -> freischlagen/heilen."] = "- Соляные пузыри: игрок заключен внутри -> выбивать/хилить."
L["- Wachsende Korallen am Boden -> nicht im Weg stehen, Raum freihalten."] = "- Растущие кораллы на полу -> не стоять на пути, держать место свободным."
L["Taktik: Boss so bewegen, dass der Schild gebrochen wird, Azerit-Linien sauber legen, Tankwechsel."] = "Тактика: Двигать босса так, чтобы щит ломался, азеритовые линии класть чисто, смена танков."
L["ASHVANE: Schild brechen! Azerit-Linien sauber legen!"] = "ЭШВЕЙН: Ломать щит! Азеритовые линии класть чисто!"
L["Blasen freischlagen. Tankwechsel nach Muschelhieb."] = "Выбивать из пузырей. Смена танков после Удара раковиной."
L["Orgozoa + Brut"] = "Оргозоа + выводок"
L["- Brut/Inkubationsadds: schlüpfen aus Eiern -> schnell töten, unterbrechen."] = "- Выводок/адды-инкубанты: вылупляются из яиц -> быстро убивать, прерывать."
L["- Betäubender Stachel: stapelnder Tank-Debuff -> Tankwechsel."] = "- Оглушающее жало: стакающийся дебафф на танке -> смена танков."
L["- Bogenstrom / Elektro-Effekte -> verteilt stehen."] = "- Дуговой ток / электрические эффекты -> стоять рассредоточенно."
L["- Inkubationsflüssigkeit: Debuff -> Abstand zu anderen Trägern."] = "- Инкубационная жидкость: дебафф -> держать дистанцию от других носителей."
L["Taktik: Adds mit Priorität töten, Kicks einteilen, Boss stationär; Phase 2 mit Raid-Cooldowns."] = "Тактика: Аддов убивать в приоритете, распределить кики, босс на месте; фаза 2 с рейдовыми кулдаунами."
L["ORGOZOA: Adds schnell töten! Kicks einteilen!"] = "ОРГОЗОА: Аддов быстро убивать! Распределить кики!"
L["Verteilt stehen. Tankwechsel bei Stachel-Stapeln."] = "Стоять рассредоточенно. Смена танков на стаках жала."
L["Orgozoa"] = "Оргозоа"
L["Symbole auf die zaubernden Adds, Kickgruppen pro Symbol."] = "Метки на аддов-кастеров, группы киков на каждую метку."
L["Der Hof der Königin (Silivaz die Eifrige, Pashmar die Fanatische)"] = "Двор королевы (Силиваз Ревностная, Пашмар Фанатичная)"
L["- Erlasse der Königin: wechselnde Befehle (allein stehen, zusammen stehen, wiederholen, nicht bewegen) -> exakt befolgen."] = "- Указы королевы: меняющиеся приказы (стоять одному, стоять вместе, повторять, не двигаться) -> выполнять точно."
L["- Fanatisches Urteil: Flächen -> herauslaufen."] = "- Фанатичный приговор: зоны -> выбегать."
L["- Mächtiger Funke: Adds -> töten, nicht zu nah an Bosse."] = "- Мощная искра: адды -> убивать, не подводить близко к боссам."
L["- Beide Bosse verstärken sich gegenseitig -> abwechselnd schlagen, Bosse getrennt halten."] = "- Оба босса усиливают друг друга -> бить поочередно, держать боссов раздельно."
L["Taktik: Erlasse des Hofes genau ansagen und befolgen, Bosse auseinander, Adds töten."] = "Тактика: Указы двора четко объявлять и выполнять, боссов развести, аддов убивать."
L["HOF: Erlasse exakt befolgen! Bosse getrennt halten!"] = "ДВОР: Указы выполнять точно! Боссов держать раздельно!"
L["Adds töten, aus Flächen raus."] = "Убивать аддов, выходить из зон."
L["Za'qul, Vorbote von Ny'alotha + Schreckensbeschwörer"] = "За'кул, Предвестник Ни'алоты + призыватели ужаса"
L["- Wahnsinnsreich: Spieler werden ins Delirium versetzt -> dort Mechaniken lösen und zurückkehren."] = "- Царство безумия: игроков погружает в бред -> там решить механики и вернуться."
L["- Dunkler Puls / Kugeln: schwere Effekte -> ausweichen oder nach Plan absorbieren."] = "- Темный импульс / сферы: опасные эффекты -> уклоняться или поглощать по плану."
L["- Gedankenverbindung: Tank-Mechanik -> Tankwechsel."] = "- Связь разума: танковая механика -> смена танков."
L["- Zermalmender Griff: Tentakel-Einschläge -> ausweichen."] = "- Сокрушительная хватка: удары щупалец -> уклоняться."
L["- Adds (Schreckensbeschwörer) -> unterbrechen und schnell töten."] = "- Адды (призыватели ужаса) -> прерывать и быстро убивать."
L["Taktik: Phasen bei 90/70/40 % vorbereiten, Delirium-Wechsel koordinieren, Adds zuerst."] = "Тактика: Готовиться к фазам на 90/70/40 %, координировать смены в бреду, сначала адды."
L["ZA'QUL: Adds zuerst! Tentakeln ausweichen!"] = "ЗА'КУЛ: Сначала адды! Уклоняться от щупалец!"
L["Delirium-Spieler zurückbringen. Tankwechsel beachten."] = "Возвращать игроков из бреда. Следить за сменой танков."
L["Za'qul"] = "За'кул"
